import{t as n}from"./contentLive-U71wAU_x.js";var t=await n("b:lib/minna-curriculum.js#MINNA_LESSONS","5d21d3afe20b3905fdd9",[{bai:1,level:"N5",kanji:"私",reading:"わたし",romaji:"Watashi",titleVi:"Giới thiệu bản thân",titleJp:"〜は〜です／じゃありません",descVi:"Câu cơ bản NはNです — học cách tự giới thiệu và xưng hô.",selfCheckGoals:["Tự giới thiệu tên, quốc tịch, nghề nghiệp.","Hỏi danh tính người khác bằng NはNですか.","Phủ định bằng じゃありません / ではありません.",'Dùng も để nói "cũng vậy".',"Dùng の để chỉ sở hữu và thuộc về."],readingPassage:{title:"初めまして",titleVi:"Lần đầu gặp nhau",japanese:"はじめまして。私はミラーです。アメリカ人です。学生ではありません。会社員です。田中さんも会社員ですか。いいえ、田中さんは先生です。これは私の名刺です。どうぞよろしくお願いします。",vietnamese:"Xin chào, rất vui được gặp. Tôi là Miller. Tôi là người Mỹ. Tôi không phải sinh viên. Tôi là nhân viên công ty. Anh Tanaka cũng là nhân viên công ty à? Không, anh Tanaka là giáo viên. Đây là danh thiếp của tôi. Rất mong được giúp đỡ.",highlights:[{excerpt:"私はミラーです",label:"NはNです"},{excerpt:"学生ではありません",label:"NはNではありません"},{excerpt:"田中さんも会社員ですか",label:"Nも"},{excerpt:"私の名刺",label:"NのN (sở hữu)"}],questions:[{q:"ミラーさんは何ですか。",options:["学生です","先生です","会社員です","アメリカ人ではありません"],answer:2},{q:"田中さんは何ですか。",options:["会社員です","先生です","学生です","アメリカ人です"],answer:1}]},patterns:[{pattern:"NはNです",meaning:"N là N (khẳng định)",priority:"core",explanation:'Cấu trúc câu cơ bản nhất trong tiếng Nhật. は (đọc là "wa") là trợ từ chủ đề, です là trợ động từ lịch sự cuối câu.',examples:[{sentence:"私は田中です。",translation:"Tôi là Tanaka."},{sentence:"あの人は先生です。",translation:"Người kia là giáo viên."},{sentence:"私はベトナム人です。",translation:"Tôi là người Việt Nam."},{sentence:"これは私のかばんです。",translation:"Cái này là túi của tôi."}],note:'は trong vai trò trợ từ đọc là "wa", không phải "ha".',dialogue:{title:"Lần đầu gặp ở công ty",lines:[{speaker:"A",text:"初めまして。リンです。よろしくお願いします。",translation:"Rất vui được gặp. Tôi là Linh. Mong được anh chỉ giáo."},{speaker:"B",text:"初めまして。田中です。リンさんはベトナム人ですか。",translation:"Rất vui được gặp. Tôi là Tanaka. Linh-san là người Việt Nam à?"},{speaker:"A",text:"はい、ベトナム人です。エンジニアです。",translation:"Vâng, tôi là người Việt. Tôi là kỹ sư."}]},commonMistake:{wrong:"私　学生です。",correct:"私は学生です。",why:'Không được thiếu trợ từ は giữa chủ đề và vị ngữ. Trong tiếng Việt không có "thì/là" rõ ràng nên người Việt hay quên は.'},related:["minna-1:NはNではありません","minna-2:NのN","minna-8:NはAいです"],kitsuPrompt:"Hãy luyện tự giới thiệu với tôi bằng NはNです: tên, quốc tịch, nghề nghiệp."},{pattern:"NはNではありません",meaning:"N không phải là N",priority:"core",explanation:"Phủ định của NはNです. Trong hội thoại thân mật thường dùng じゃありません thay vì ではありません.",examples:[{sentence:"私は学生ではありません。",translation:"Tôi không phải là sinh viên."},{sentence:"田中さんは先生じゃありません。",translation:"Anh Tanaka không phải là giáo viên."},{sentence:"これは私の本じゃありません。",translation:"Đây không phải sách của tôi."},{sentence:"あれは病院ではありません。",translation:"Kia không phải là bệnh viện."}],note:"じゃありません = ではありません nhưng thân mật hơn, dùng trong hội thoại hàng ngày.",dialogue:{title:"Đính chính thông tin",lines:[{speaker:"A",text:"すみません、田中さんは先生ですか。",translation:"Xin lỗi, anh Tanaka có phải là giáo viên không?"},{speaker:"B",text:"いいえ、田中さんは先生じゃありません。会社員ですよ。",translation:"Không, anh Tanaka không phải là giáo viên. Là nhân viên công ty đấy."},{speaker:"A",text:"あ、そうですか。失礼しました。",translation:"À, vậy à. Tôi xin lỗi."}]},commonMistake:{wrong:"私は学生じゃないです。",correct:"私は学生じゃありません。",why:"じゃないです là dạng nói thân mật rút gọn. Trong văn cảnh lịch sự (sách giáo khoa, công sở) nên dùng じゃありません hoặc ではありません."},related:["minna-1:NはNです","minna-1:NはNですか"],kitsuPrompt:"Tôi sẽ đoán nghề nghiệp/quốc tịch của bạn, bạn hãy phủ định bằng じゃありません."},{pattern:"NはNですか",meaning:"Có phải N là N không?",priority:"core",explanation:"Câu hỏi Yes/No: thêm か vào cuối câu khẳng định. Trả lời: はい、そうです (vâng) hoặc いいえ、ちがいます (không).",examples:[{sentence:"あなたは学生ですか。",translation:"Bạn có phải là sinh viên không?"},{sentence:"これは日本語の本ですか。",translation:"Đây có phải là sách tiếng Nhật không?"},{sentence:"田中さんは会社員ですか。",translation:"Anh Tanaka có phải là nhân viên công ty không?"}],note:"Tiếng Nhật không đảo trật tự câu hỏi — chỉ thêm か vào cuối và lên giọng.",dialogue:{title:"Hỏi tên ở quầy lễ tân",lines:[{speaker:"A",text:"すみません、田中さんですか。",translation:"Xin lỗi, có phải anh Tanaka không?"},{speaker:"B",text:"はい、田中です。",translation:"Vâng, tôi là Tanaka."},{speaker:"A",text:"会議室はあちらです。どうぞ。",translation:"Phòng họp ở phía kia. Mời anh."}]},commonMistake:{wrong:"あなたは学生？",correct:"あなたは学生ですか。",why:"Trong văn cảnh lịch sự bắt buộc phải có ですか. Bỏ か và chỉ lên giọng là dạng cực kỳ thân mật/cộc lốc."},related:["minna-1:NはNです","minna-3:NはNですか、Nですか"],kitsuPrompt:"Bạn hãy phỏng vấn tôi bằng 5 câu NはNですか về tôi, tôi sẽ trả lời."},{pattern:"Nも",meaning:"N cũng",priority:"common",explanation:'Trợ từ も có nghĩa "cũng". Thay thế trực tiếp cho は hoặc が, không dùng cùng lúc với chúng.',examples:[{sentence:"リーさんも学生です。",translation:"Bạn Lee cũng là sinh viên."},{sentence:"私も日本語を勉強します。",translation:"Tôi cũng học tiếng Nhật."},{sentence:"これも私のです。",translation:"Cái này cũng là của tôi."},{sentence:"スミスさんもアメリカ人ですか。",translation:"Anh Smith cũng là người Mỹ à?"}],note:"Sai: 私はも学生です → Đúng: 私も学生です (も thay thế は, không đứng sau).",dialogue:{title:"Trùng quốc tịch ở lớp",lines:[{speaker:"A",text:"私はベトナム人です。",translation:"Tôi là người Việt Nam."},{speaker:"B",text:"あ、私もベトナム人です！どこから来ましたか。",translation:"Ồ, tôi cũng là người Việt! Bạn đến từ đâu?"},{speaker:"A",text:"ハノイから来ました。",translation:"Tôi đến từ Hà Nội."}]},commonMistake:{wrong:"私はもベトナム人です。",correct:"私もベトナム人です。",why:'も và は là hai trợ từ "cạnh tranh" cùng vị trí — chỉ dùng một trong hai, không được dùng cả hai.'},related:["minna-1:NはNです"],kitsuPrompt:"Tôi sẽ nói thông tin về tôi, bạn hãy đáp lại bằng 私も〜です nếu trùng, hoặc 私は〜です nếu khác."},{pattern:"NのN",meaning:"N của N / N thuộc N",priority:"core",explanation:"Trợ từ の nối hai danh từ: N1 bổ nghĩa cho N2. Dùng để chỉ sở hữu, thuộc về, hoặc phân loại.",examples:[{sentence:"これは私の本です。",translation:"Đây là sách của tôi."},{sentence:"田中さんの車はあれです。",translation:"Xe của anh Tanaka là chiếc kia."},{sentence:"日本語の先生",translation:"giáo viên tiếng Nhật"},{sentence:"これは誰のかばんですか。",translation:"Đây là túi của ai?"}],note:"の cũng thay thế danh từ khi đã rõ nghĩa: これは私のです (cái này là của tôi).",dialogue:{title:"Tìm chủ nhân của vật để quên",lines:[{speaker:"A",text:"これは誰のかばんですか。",translation:"Đây là túi của ai vậy?"},{speaker:"B",text:"あ、田中さんのです。",translation:"À, là của anh Tanaka đấy."},{speaker:"A",text:"そうですか。じゃあ、田中さんに渡します。",translation:"Vậy à. Vậy tôi đưa cho anh Tanaka nhé."}]},commonMistake:{wrong:"私本",correct:"私の本",why:"Khác tiếng Việt, tiếng Nhật bắt buộc phải có の giữa hai danh từ khi muốn chỉ sở hữu. Không thể ghép trực tiếp."},related:["minna-2:NのN (sở hữu)","minna-22:Vる + N"],kitsuPrompt:'Hãy hỏi tôi 5 câu "Đây là cái gì của ai?" và tôi trả lời bằng NのN.'}]},{bai:2,level:"N5",kanji:"本",reading:"ほん",romaji:"Hon",titleVi:"Đại từ chỉ thị",titleJp:"指示詞 + のN",descVi:"Dùng これ・それ・あれ chỉ đồ vật gần, vừa xa và rất xa.",selfCheckGoals:["Phân biệt và dùng đúng これ/それ/あれ theo vị trí của người nói và người nghe.","Biết khi nào dùng これ vs この.","Trả lời câu hỏi bằng はい、そうです / いいえ、ちがいます.","Hỏi giá/tên/chủ sở hữu của một đồ vật cụ thể."],readingPassage:{title:"デパートでのショッピング",titleVi:"Mua sắm ở bách hóa",japanese:"すみません、これは何ですか。これはカメラです。そうですか。あれも田中さんのカメラですか。いいえ、あれはカメラではありません。あれは田中さんの双眼鏡です。このカメラはいくらですか。このカメラは三万円です。",vietnamese:"Xin lỗi, cái này là gì vậy? Cái này là máy ảnh. Thế à. Cái kia cũng là máy ảnh của anh Tanaka à? Không, cái đó không phải máy ảnh. Cái đó là ống nhòm của anh Tanaka. Cái máy ảnh này bao nhiêu tiền? Cái máy ảnh này 30.000 yên.",highlights:[{excerpt:"これは何ですか",label:"これ"},{excerpt:"あれも田中さんのカメラですか",label:"あれ / Nも"},{excerpt:"あれはカメラではありません",label:"そうではありません"},{excerpt:"田中さんの双眼鏡",label:"NのN (sở hữu)"},{excerpt:"このカメラはいくらですか",label:"このN"}],questions:[{q:"あれは何ですか。",options:["カメラです","テレビです","双眼鏡です","時計です"],answer:2},{q:"このカメラはいくらですか。",options:["一万円","二万円","三万円","四万円"],answer:2}]},patterns:[{pattern:"これ／それ／あれ",meaning:"cái này / cái đó / cái kia",priority:"core",explanation:"Đại từ chỉ thị độc lập: これ (gần người nói), それ (gần người nghe), あれ (xa cả hai). Dùng làm chủ ngữ hoặc tân ngữ.",examples:[{sentence:"これは本です。",translation:"Cái này là sách."},{sentence:"それは何ですか。",translation:"Cái đó là gì vậy?"},{sentence:"あれは富士山です。",translation:"Kia là núi Fuji."},{sentence:"これはいくらですか。",translation:"Cái này giá bao nhiêu?"}],note:"これ/それ/あれ đứng độc lập (không đi kèm danh từ). Khi đi kèm danh từ dùng この/その/あの.",dialogue:{title:"Mua đồ ở cửa hàng",lines:[{speaker:"Khách",text:"すみません、これは何ですか。",translation:"Xin lỗi, cái này là gì vậy?"},{speaker:"NV",text:"それはお茶のクッキーです。",translation:"Cái đó là bánh quy vị trà ạ."},{speaker:"Khách",text:"おいしいですか。じゃあ、これをください。",translation:"Có ngon không? Vậy cho tôi cái này."}]},commonMistake:{wrong:"これ本です。",correct:"これは本です。",why:"これ là đại từ độc lập, vẫn cần は để đánh dấu chủ đề. Không được nối thẳng これ + danh từ + です."},related:["minna-2:この／その／あのN","minna-3:ここ／そこ／あそこ"],kitsuPrompt:'Hãy đố tôi 5 lần "これは何ですか", mỗi lần thay đổi vật tưởng tượng, tôi sẽ đoán.'},{pattern:"この／その／あのN",meaning:"N này / N đó / N kia",priority:"core",explanation:"Tính từ chỉ thị đứng trước danh từ: この (N này), その (N đó), あの (N kia xa cả hai). Khác với これ/それ/あれ ở chỗ bắt buộc có danh từ theo sau.",examples:[{sentence:"この本は面白いです。",translation:"Cuốn sách này thú vị."},{sentence:"その鞄はいくらですか。",translation:"Cái túi đó giá bao nhiêu?"},{sentence:"あの人は誰ですか。",translation:"Người kia là ai?"},{sentence:"このラーメンはおいしいですね。",translation:"Tô mì ramen này ngon nhỉ."}],note:"あの cũng dùng khi cả hai người cùng biết đối tượng đó: あの映画、見ましたか (bộ phim đó bạn xem chưa)?",dialogue:{title:"Bàn luận về một người trong văn phòng",lines:[{speaker:"A",text:"あの人は誰ですか。",translation:"Người kia là ai vậy?"},{speaker:"B",text:"あの人は新しい部長の山田さんですよ。",translation:"Người kia là trưởng phòng mới — anh Yamada đấy."},{speaker:"A",text:"え、あの若い人が部長ですか？",translation:"Hả, người trẻ kia mà là trưởng phòng à?"}]},commonMistake:{wrong:"これ本は私のです。",correct:"この本は私のです。",why:"Khi đứng trước danh từ phải dùng この (không phải これ). これ/それ/あれ chỉ đứng độc lập, không kèm danh từ."},related:["minna-2:これ／それ／あれ","minna-22:Vる + N"],kitsuPrompt:'Bạn hãy giả vờ đang ở quán cà phê và hỏi tôi về "あの人" (người kia là ai/làm gì).'},{pattern:"そうです／そうではありません",meaning:"đúng vậy / không phải vậy",priority:"common",explanation:'Dùng để xác nhận hoặc phủ nhận nội dung câu hỏi mà không lặp lại toàn bộ câu. そうです = "đúng vậy", そうではありません / そうじゃありません = "không phải vậy".',examples:[{sentence:"A: これは田中さんのですか。B: はい、そうです。",translation:"A: Cái này của anh Tanaka à? B: Vâng, đúng vậy."},{sentence:"A: あなたは学生ですか。B: いいえ、そうじゃありません。",translation:"A: Bạn là sinh viên à? B: Không, không phải vậy."},{sentence:"そうですか。",translation:"Vậy à / Thế à. (phản ứng khi nghe thông tin)"}],note:'そうですか (giọng xuống) = "Vậy à" thể hiện sự tiếp nhận thông tin, không phải câu hỏi.',dialogue:{title:"Xác nhận thông tin qua điện thoại",lines:[{speaker:"A",text:"もしもし、田中さんですか。",translation:"Alo, anh Tanaka phải không ạ?"},{speaker:"B",text:"はい、そうです。",translation:"Vâng, đúng vậy."},{speaker:"A",text:"A社のリンです。明日の会議のことで…",translation:"Tôi là Linh ở công ty A. Về cuộc họp ngày mai..."}]},commonMistake:{wrong:"A: あなたは先生ですか。B: はい、そうです。 (khi thực ra mình là sinh viên)",correct:"A: あなたは先生ですか。B: いいえ、違います。学生です。",why:"そうです chỉ dùng khi xác nhận điều đúng. Khi phủ định và đính chính thông tin, dùng 違います (chigaimasu) + thông tin đúng."},related:["minna-1:NはNですか","minna-1:NはNではありません"],kitsuPrompt:"Tôi sẽ hỏi bạn 5 câu Yes/No về sở thích. Hãy trả lời đầy đủ bằng はい、そうです / いいえ、ちがいます."},{pattern:"NのN (sở hữu)",meaning:"N của N",priority:"core",explanation:"Khi người sở hữu là đại từ hoặc tên người, の đứng giữa để chỉ sở hữu. Danh từ sau の là vật được sở hữu.",examples:[{sentence:"これは私の傘です。",translation:"Cái này là ô của tôi."},{sentence:"それはマリアさんの自転車ですか。",translation:"Cái đó có phải xe đạp của Maria không?"},{sentence:"田中さんの電話番号は何番ですか。",translation:"Số điện thoại của anh Tanaka là số mấy?"}],note:"Khi danh từ đã rõ từ ngữ cảnh, có thể bỏ danh từ sau の: これは私のです.",dialogue:{title:"Trả lại đồ để quên",lines:[{speaker:"A",text:"すみません、この傘は誰のですか。",translation:"Xin lỗi, cái ô này là của ai vậy?"},{speaker:"B",text:"あ、私のです！ありがとうございます。",translation:"Ồ, là của tôi đấy! Cảm ơn anh nhiều."},{speaker:"A",text:"いえいえ、どういたしまして。",translation:"Không có gì đâu."}]},commonMistake:{wrong:"私かばん",correct:"私のかばん",why:"Khác tiếng Việt, tiếng Nhật bắt buộc phải có の giữa hai danh từ khi muốn chỉ sở hữu — không thể ghép trực tiếp."},related:["minna-1:NのN","minna-22:Vる + N"],kitsuPrompt:'Hãy hỏi tôi 5 lần "これは誰のNですか" và tôi sẽ trả lời sở hữu chủ.'}]},{bai:3,level:"N5",kanji:"所",reading:"ところ",romaji:"Tokoro",titleVi:"Vị trí & địa điểm",titleJp:"場所指示詞",descVi:"Nói về vị trí không gian với ここ・そこ・あそこ và trợ từ に.",selfCheckGoals:['Hỏi và chỉ vị trí: "Nhà vệ sinh ở đâu?", "Phòng học ở đây".',"Dùng こちら trong tình huống lịch sự (cửa hàng, công sở).","Phân biệt あります (vật) vs います (người/động vật).","Đặt câu hỏi lựa chọn AですかBですか."],readingPassage:{title:"ホテルのフロントで",titleVi:"Tại quầy lễ tân khách sạn",japanese:"すみません、エレベーターはどこですか。エレベーターはあそこにあります。レストランはどこですか。レストランはこちらです。レストランは２階ですか、３階ですか。２階です。田中さんは今どこにいますか。田中さんはロビーにいます。",vietnamese:"Xin lỗi, thang máy ở đâu vậy? Thang máy ở đằng kia. Nhà hàng ở đâu? Nhà hàng ở phía này. Nhà hàng ở tầng 2 hay tầng 3? Tầng 2. Anh Tanaka hiện đang ở đâu? Anh Tanaka đang ở sảnh.",highlights:[{excerpt:"エレベーターはあそこにあります",label:"NはNにあります"},{excerpt:"レストランはこちらです",label:"こちら"},{excerpt:"レストランは２階ですか、３階ですか",label:"NはAですか、Bですか"},{excerpt:"田中さんはロビーにいます",label:"NはNにいます"}],questions:[{q:"エレベーターはどこにありますか。",options:["こちら","そこ","あそこ","ロビー"],answer:2},{q:"レストランは何階ですか。",options:["１階","２階","３階","４階"],answer:1}]},patterns:[{pattern:"ここ／そこ／あそこ",meaning:"ở đây / ở đó / ở kia",priority:"core",explanation:"Đại từ chỉ nơi chốn: ここ (nơi gần người nói), そこ (nơi gần người nghe), あそこ (nơi xa cả hai). Dùng làm chủ ngữ hoặc bổ ngữ chỉ nơi chốn.",examples:[{sentence:"ここは教室です。",translation:"Đây là phòng học."},{sentence:"すみません、お手洗いはどこですか。そこです。",translation:"Xin lỗi, nhà vệ sinh ở đâu? — Ở đó kìa."},{sentence:"あそこに本屋があります。",translation:"Ở kia có một hiệu sách."},{sentence:"ここで写真を撮ってもいいですか。",translation:"Tôi có thể chụp ảnh ở đây không?"}],note:'ここ/そこ/あそこ chỉ vị trí; どこ là dạng câu hỏi "ở đâu?".',dialogue:{title:"Hỏi đường trong tòa nhà",lines:[{speaker:"A",text:"すみません、エレベーターはどこですか。",translation:"Xin lỗi, thang máy ở đâu?"},{speaker:"B",text:"エレベーターはあそこです。",translation:"Thang máy ở đằng kia."},{speaker:"A",text:"ありがとうございます。",translation:"Cảm ơn anh."}]},commonMistake:{wrong:"ここ教室です。",correct:"ここは教室です。",why:"Vẫn cần は sau ここ để đánh dấu chủ đề. ここ là đại từ, không phải vị ngữ."},related:["minna-2:これ／それ／あれ","minna-3:こちら／そちら／あちら"],kitsuPrompt:'Bạn hãy hỏi tôi 5 lần "Nơi X ở đâu?" và tôi sẽ trả lời với ここ/そこ/あそこ.'},{pattern:"こちら／そちら／あちら",meaning:"phía này / phía đó / phía kia (lịch sự)",priority:"common",explanation:"Dạng lịch sự hơn của ここ/そこ/あそこ, thường dùng trong môi trường công việc, cửa hàng. Cũng dùng để giới thiệu người một cách lịch sự.",examples:[{sentence:"お手洗いはこちらです。",translation:"Nhà vệ sinh ở phía này ạ."},{sentence:"こちらは田中部長です。",translation:"Đây là Trưởng phòng Tanaka."},{sentence:"レジはあちらになります。",translation:"Quầy thanh toán ở phía kia ạ."}],note:"こちらは〜です cũng dùng để tự giới thiệu hoặc giới thiệu người khác trong ngữ cảnh lịch sự.",dialogue:{title:"Giới thiệu khách quan trọng",lines:[{speaker:"A",text:"社長、こちらはA社のリンさんです。",translation:"Thưa giám đốc, đây là chị Linh của công ty A."},{speaker:"B",text:"リンさん、初めまして。鈴木です。",translation:"Chị Linh, rất hân hạnh. Tôi là Suzuki."},{speaker:"A",text:"こちらへどうぞ。",translation:"Xin mời chị qua đây."}]},commonMistake:{wrong:"ここは田中部長です。",correct:"こちらは田中部長です。",why:"Khi giới thiệu người, đặc biệt người trên/khách quan trọng, phải dùng こちら (lịch sự). ここ dùng cho người sẽ thấy thô lỗ."},related:["minna-3:ここ／そこ／あそこ","minna-49:尊敬語"],kitsuPrompt:"Hãy đóng vai khách quan trọng đến công ty tôi, tôi sẽ giới thiệu sếp bằng こちら."},{pattern:"NはNにあります／います",meaning:"N ở vị trí N",priority:"core",explanation:"Diễn tả vị trí của vật hoặc người. あります cho vật vô tri, います cho người và động vật. に chỉ nơi chốn tồn tại.",examples:[{sentence:"本は机の上にあります。",translation:"Sách ở trên bàn."},{sentence:"田中さんは事務所にいます。",translation:"Anh Tanaka đang ở văn phòng."},{sentence:"コンビニは駅の前にあります。",translation:"Cửa hàng tiện lợi ở trước ga."},{sentence:"猫はソファの下にいます。",translation:"Con mèo đang ở dưới ghế sofa."}],note:"Từ chỉ vị trí: 上(うえ)trên, 下(した)dưới, 前(まえ)trước, 後ろ(うしろ)sau, 隣(となり)bên cạnh, 中(なか)trong.",dialogue:{title:"Hỏi chìa khóa ở đâu",lines:[{speaker:"A",text:"あれ、私の鍵はどこにありますか。",translation:"Ơ, chìa khóa của tôi đâu rồi nhỉ?"},{speaker:"B",text:"テーブルの上にありますよ。",translation:"Ở trên bàn đấy."},{speaker:"A",text:"あ、本当だ！ありがとう。",translation:"À, đúng rồi! Cảm ơn."}]},commonMistake:{wrong:"田中さんは事務所にあります。",correct:"田中さんは事務所にいます。",why:'Người dùng います, không phải あります. Sai này rất phổ biến với người Việt vì tiếng Việt chỉ có "ở/có" chung.'},related:["minna-10:NがNにあります","minna-10:NがNにいます"],kitsuPrompt:"Bạn hãy hỏi tôi vị trí 5 đồ vật trong phòng, tôi trả lời với cấu trúc 〜は〜にあります."},{pattern:"NはAですか、Bですか",meaning:"N là A hay B? (câu hỏi lựa chọn)",priority:"common",explanation:"Câu hỏi lựa chọn: đưa ra hai phương án A hoặc B. Người trả lời chọn một trong hai, không trả lời はい/いいえ.",examples:[{sentence:"エレベーターは1階ですか、2階ですか。",translation:"Thang máy ở tầng 1 hay tầng 2?"},{sentence:"田中さんは日本人ですか、中国人ですか。",translation:"Anh Tanaka là người Nhật hay người Trung Quốc?"},{sentence:"お支払いは現金ですか、カードですか。",translation:"Bạn thanh toán tiền mặt hay thẻ?"}],note:"Không trả lời はい/いいえ với câu hỏi lựa chọn — trả lời thẳng bằng phương án được chọn.",dialogue:{title:"Order ở quán cà phê",lines:[{speaker:"NV",text:"お飲み物はコーヒーですか、紅茶ですか。",translation:"Đồ uống của anh là cà phê hay trà đen?"},{speaker:"Khách",text:"コーヒーをお願いします。",translation:"Cho tôi cà phê."},{speaker:"NV",text:"ホットですか、アイスですか。",translation:"Nóng hay đá ạ?"}]},commonMistake:{wrong:"A: コーヒーですか、紅茶ですか。 B: はい。",correct:"A: コーヒーですか、紅茶ですか。 B: コーヒーです。",why:"Câu hỏi lựa chọn không trả lời Yes/No, phải chọn một trong hai phương án."},related:["minna-6:NかN","minna-1:NはNですか"],kitsuPrompt:"Tôi giả vờ là khách ở nhà hàng, bạn hãy hỏi tôi 5 lựa chọn (món ăn, đồ uống) bằng AですかBですか."}]},{bai:4,level:"N5",kanji:"時",reading:"じ",romaji:"Ji",titleVi:"Giờ giấc & thời gian",titleJp:"時間・から〜まで",descVi:"Biểu đạt giờ phút, từ〜đến〜 và các hoạt động trong ngày.",selfCheckGoals:["Nói giờ phút chính xác bằng 〜時〜分.","Phân biệt dạng ます (hiện tại/tương lai) và dạng ました (quá khứ).",'Diễn tả khoảng thời gian "từ A đến B" với から〜まで.','Nói "cùng với ai" bằng Nと.'],readingPassage:{title:"ミラーさんの昨日",titleVi:"Hôm qua của Miller",japanese:"昨日、ミラーさんは朝７時に起きました。８時から９時まで日本語を勉強しました。それから、田中さんと図書館へ行きました。お昼ごはんは食べませんでした。夜は家で本を読みました。",vietnamese:"Hôm qua, anh Miller thức dậy lúc 7 giờ sáng. Từ 8 giờ đến 9 giờ học tiếng Nhật. Sau đó đi thư viện với anh Tanaka. Bữa trưa anh không ăn. Tối đọc sách ở nhà.",highlights:[{excerpt:"朝７時に起きました",label:"〜時に"},{excerpt:"８時から９時まで",label:"NからNまで"},{excerpt:"田中さんと図書館へ行きました",label:"Nと"},{excerpt:"食べませんでした",label:"Vませんでした"}],questions:[{q:"ミラーさんは何時に起きましたか。",options:["６時","７時","８時","９時"],answer:1},{q:"ミラーさんは昨日誰と図書館へ行きましたか。",options:["マリアさん","キムさん","田中さん","一人で"],answer:2}]},patterns:[{pattern:"〜時／〜分",meaning:"giờ / phút",priority:"core",explanation:"Cách nói giờ trong tiếng Nhật: số + 時(じ) cho giờ, số + 分(ふん/ぷん) cho phút. Một số cách đọc phút đặc biệt cần chú ý.",examples:[{sentence:"今、9時15分です。",translation:"Bây giờ là 9 giờ 15 phút."},{sentence:"会議は3時半に始まります。",translation:"Cuộc họp bắt đầu lúc 3 giờ rưỡi."},{sentence:"授業は何時から何時までですか。",translation:"Lớp học từ mấy giờ đến mấy giờ?"},{sentence:"今何時ですか。",translation:"Bây giờ là mấy giờ?"}],note:"4分=よんぷん, 1分=いっぷん, 6分=ろっぷん, 8分=はっぷん, 10分=じゅっぷん — có biến âm.",commonMistake:{wrong:"今、4時（しじ）15分（ふん）です。",correct:"今、4時（よじ）15分（ぷん）です。",why:"Giờ có cách đọc đặc biệt: 4時=よじ (không phải しじ), 7時=しちじ, 9時=くじ (không phải きゅうじ). Phút cũng biến âm: 15分=じゅうごふん nhưng 1分=いっぷん, 4分=よんぷん, 10分=じゅっぷん — phải thuộc từng cách đọc, không suy từ số đếm thường."}},{pattern:"Vます／Vません",meaning:"làm / không làm (hiện tại/tương lai lịch sự)",explanation:"Dạng ます là dạng lịch sự của động từ, dùng trong hội thoại với người không thân. Vます = khẳng định, Vません = phủ định.",examples:[{sentence:"毎日日本語を勉強します。",translation:"Tôi học tiếng Nhật mỗi ngày."},{sentence:"週末は働きません。",translation:"Cuối tuần tôi không làm việc."},{sentence:"朝ごはんを食べますか。",translation:"Bạn có ăn sáng không?"},{sentence:"私はお酒を飲みません。",translation:"Tôi không uống rượu."}],note:"Dạng ます cũng dùng cho tương lai: 明日行きます (Tôi sẽ đi ngày mai).",priority:"core",dialogue:{title:"Hỏi lịch học",lines:[{speaker:"A",text:"毎日日本語を勉強しますか。",translation:"Bạn có học tiếng Nhật mỗi ngày không?"},{speaker:"B",text:"はい、毎日勉強します。週末も勉強します。",translation:"Có, tôi học mỗi ngày. Cuối tuần cũng học."},{speaker:"A",text:"すごいですね！",translation:"Cừ thật nhỉ!"}]},commonMistake:{wrong:"昨日勉強します。",correct:"昨日勉強しました。",why:"ます-form chỉ dùng cho hiện tại/tương lai. Với quá khứ phải đổi thành ました."},related:["minna-4:Vました／Vませんでした","minna-20:V/A/NAの普通形"],kitsuPrompt:"Bạn hãy hỏi tôi 5 câu về thói quen hàng ngày bằng dạng ます, tôi sẽ trả lời."},{pattern:"Vました／Vませんでした",meaning:"đã làm / đã không làm (quá khứ)",priority:"core",explanation:"Dạng quá khứ lịch sự: ました = đã làm, ませんでした = đã không làm. Thường đi kèm các từ chỉ quá khứ như 昨日, 先週, さっき.",examples:[{sentence:"昨日映画を見ました。",translation:"Hôm qua tôi đã xem phim."},{sentence:"先週は忙しくて、全然勉強しませんでした。",translation:"Tuần trước bận quá, tôi đã không học chút nào."},{sentence:"もう昼ごはんを食べましたか。",translation:"Bạn đã ăn trưa chưa?"},{sentence:"昨日はどこへ行きましたか。",translation:"Hôm qua bạn đã đi đâu?"}],note:"もう + Vました = đã làm rồi. まだ + Vていません = chưa làm (học sau).",dialogue:{title:"Hỏi về cuối tuần",lines:[{speaker:"A",text:"週末、何をしましたか。",translation:"Cuối tuần bạn đã làm gì?"},{speaker:"B",text:"友だちと映画を見ました。リンさんは？",translation:"Tôi đi xem phim với bạn. Còn Linh?"},{speaker:"A",text:"私は何もしませんでした。ずっと寝ていました。",translation:"Tôi chẳng làm gì. Ngủ suốt thôi."}]},commonMistake:{wrong:"昨日勉強しませんです。",correct:"昨日勉強しませんでした。",why:"Phủ định quá khứ là ませんでした (một từ), không phải ません + でした. Phải đổi nguyên cụm."},related:["minna-4:Vます／Vません","minna-19:Vたことがあります"],kitsuPrompt:"Hãy hỏi tôi 5 câu về việc tôi đã làm hôm qua/tuần trước, dùng Vました/ませんでした."},{pattern:"NからNまで",meaning:"từ N đến N",priority:"core",explanation:"から chỉ điểm xuất phát (thời gian hoặc không gian), まで chỉ điểm kết thúc. Có thể dùng một mình hoặc kết hợp.",examples:[{sentence:"仕事は9時から6時までです。",translation:"Công việc từ 9 giờ đến 6 giờ."},{sentence:"月曜日から金曜日まで働きます。",translation:"Tôi làm việc từ thứ Hai đến thứ Sáu."},{sentence:"東京から大阪まで新幹線で2時間かかります。",translation:"Từ Tokyo đến Osaka mất 2 tiếng bằng tàu cao tốc."},{sentence:"9時から勉強します。",translation:"Tôi học từ 9 giờ."}],note:"から và まで có thể dùng riêng lẻ: 9時から (từ 9 giờ), 5時まで (đến 5 giờ).",dialogue:{title:"Hỏi giờ mở cửa",lines:[{speaker:"Khách",text:"すみません、お店は何時から何時までですか。",translation:"Xin lỗi, quán mở từ mấy giờ đến mấy giờ?"},{speaker:"NV",text:"11時から夜10時までです。",translation:"Từ 11 giờ trưa đến 10 giờ tối ạ."},{speaker:"Khách",text:"日曜日もやっていますか。",translation:"Chủ nhật cũng mở chứ ạ?"}]},commonMistake:{wrong:"9時から5時にまで",correct:"9時から5時まで",why:"まで không kết hợp với に. Cấu trúc cố định: から...まで, không thêm trợ từ ở giữa."},related:["minna-17:Nまでに"],kitsuPrompt:"Hãy hỏi tôi giờ giấc 3 hoạt động hàng ngày, tôi trả lời bằng từ A時からB時まで."},{pattern:"Nと",meaning:"cùng với ai / và N",priority:"common",explanation:'と có hai nghĩa: (1) cùng với ai đó thực hiện hành động, (2) liệt kê danh từ (A và B). Ở bài này học nghĩa "cùng với người".',examples:[{sentence:"友だちと映画を見ました。",translation:"Tôi đã xem phim cùng với bạn."},{sentence:"家族と旅行します。",translation:"Tôi đi du lịch cùng gia đình."},{sentence:"誰と行きましたか。",translation:"Bạn đã đi cùng ai?"},{sentence:"一人で行きます。",translation:"Tôi tự đi một mình."}],note:'一人で (một mình) là cách nói ngược lại với 〜と. Chú ý: と chỉ "cùng với người/sinh vật", không dùng cho phương tiện (dùng で).',dialogue:{title:"Lên kế hoạch ăn tối",lines:[{speaker:"A",text:"今夜、誰と晩ご飯を食べますか。",translation:"Tối nay bạn ăn tối với ai?"},{speaker:"B",text:"同僚と食べます。リンさんも一緒にどうですか。",translation:"Tôi ăn với đồng nghiệp. Linh đi cùng không?"},{speaker:"A",text:"いいですね、行きます！",translation:"Tốt quá, tôi đi nhé!"}]},commonMistake:{wrong:"電車と行きます。",correct:"電車で行きます。",why:'と dùng cho "cùng với người"; phương tiện thì dùng で. Người Việt hay nhầm vì tiếng Việt "đi với" dùng cho cả hai.'},related:["minna-5:NとVます","minna-6:NかN"],kitsuPrompt:'Hãy hỏi tôi "cuối tuần đi đâu với ai" và tôi trả lời bằng Nと.'}]},{bai:5,level:"N5",kanji:"行",reading:"いく",romaji:"Iku",titleVi:"Di chuyển & phương tiện",titleJp:"移動の表現",descVi:"Nói đi đâu, bằng phương tiện gì và đi cùng ai.",selfCheckGoals:["Nói đến đâu bằng trợ từ へ (N5) hay に (đích cụ thể).","Dùng đúng で cho phương tiện và と cho người đồng hành.",'Hỏi "khi nào" bằng いつ và trả lời với thời gian.',"Kết hợp: 誰と・何で・どこへ trong một câu hoàn chỉnh."],readingPassage:{title:"休みの計画",titleVi:"Kế hoạch ngày nghỉ",japanese:"ミラーさんは来週京都へ行きます。新幹線で行きます。マリアさんも一緒に行きます。京都でお寺を見ます。有名なレストランで食事をします。いつ京都へ行きますか。来週の土曜日に行きます。",vietnamese:"Tuần tới anh Miller đi Kyoto. Đi bằng tàu shinkansen. Chị Maria cũng đi cùng. Ở Kyoto sẽ xem chùa. Ăn ở nhà hàng nổi tiếng. Khi nào đi Kyoto? Đi thứ 7 tuần tới.",highlights:[{excerpt:"来週京都へ行きます",label:"NへVます"},{excerpt:"新幹線で行きます",label:"NでVます"},{excerpt:"マリアさんも一緒に行きます",label:"NとVます"},{excerpt:"いつ京都へ行きますか",label:"いつVますか"}],questions:[{q:"ミラーさんはどうやって京都へ行きますか。",options:["飛行機で","バスで","新幹線で","電車で"],answer:2},{q:"いつ京都へ行きますか。",options:["今週土曜日","来週土曜日","来週日曜日","再来週"],answer:1}]},patterns:[{pattern:"NへVます",meaning:"đi đến N (hướng di chuyển)",priority:"core",explanation:'へ (đọc là "e") chỉ hướng hoặc điểm đến của chuyển động. Thường dùng với động từ di chuyển: 行く, 来る, 帰る. へ và に có thể thay nhau nhưng へ nhấn mạnh hướng đi hơn.',examples:[{sentence:"来月、日本へ行きます。",translation:"Tháng sau tôi sẽ đi Nhật."},{sentence:"週末は図書館へ行きました。",translation:"Cuối tuần tôi đã đến thư viện."},{sentence:"何時に家へ帰りますか。",translation:"Bạn về nhà lúc mấy giờ?"},{sentence:"明日、友だちの家へ遊びに行きます。",translation:"Ngày mai tôi sẽ đến nhà bạn chơi."}],note:"Điểm đến cụ thể và mục đích rõ ràng → dùng に; nhấn mạnh hướng di chuyển → dùng へ.",dialogue:{title:"Hỏi kế hoạch cuối tuần",lines:[{speaker:"A",text:"週末、どこへ行きますか。",translation:"Cuối tuần bạn sẽ đi đâu?"},{speaker:"B",text:"京都へ行きます。初めてです。",translation:"Tôi sẽ đi Kyoto. Lần đầu đấy."},{speaker:"A",text:"いいですね！楽しんできてください。",translation:"Tốt quá! Chúc bạn vui nhé."}]},commonMistake:{wrong:"学校に行きます。(khi muốn nhấn hướng đi)",correct:"学校へ行きます。",why:'Cả hai đều đúng nhưng へ nhấn mạnh quá trình di chuyển về hướng đó, còn に nhấn mạnh đích đến cụ thể. Với hành động đơn thuần "đi đến", に phổ biến hơn trong hội thoại.'},related:["minna-5:NでVます","minna-5:いつVますか","minna-22:VにNへ行きます"],kitsuPrompt:"Hỏi tôi kế hoạch cuối tuần đi đâu và tôi sẽ trả lời với NへVます."},{pattern:"NでVます",meaning:"bằng / bởi phương tiện N",priority:"core",explanation:"で chỉ phương tiện di chuyển hoặc công cụ. Đây là một trong những nghĩa của で — ở bài này tập trung vào phương tiện giao thông.",examples:[{sentence:"電車で会社へ行きます。",translation:"Tôi đi làm bằng tàu điện."},{sentence:"バスで学校へ来ましたか。",translation:"Bạn đến trường bằng xe buýt à?"},{sentence:"歩いて駅まで行きます。",translation:"Tôi đi bộ đến ga."},{sentence:"飛行機で東京から大阪へ行きました。",translation:"Tôi đã bay từ Tokyo đến Osaka."}],note:'歩いて (đi bộ) không dùng で vì "đi bộ" dùng て-form như một trạng ngữ cách thức.',dialogue:{title:"Hỏi đường đi làm",lines:[{speaker:"A",text:"毎日、何で会社へ行きますか。",translation:"Mỗi ngày bạn đi làm bằng gì?"},{speaker:"B",text:"電車で行きます。でも雨の日はバスです。",translation:"Tôi đi bằng tàu điện. Nhưng hôm mưa thì đi xe buýt."},{speaker:"A",text:"駅まで歩きますか。",translation:"Bạn đi bộ đến ga à?"}]},commonMistake:{wrong:"電車と会社へ行きます。",correct:"電車で会社へ行きます。",why:'と dùng cho "đi cùng người", で dùng cho "bằng phương tiện". Hai trợ từ hoàn toàn khác nhau dù cùng ý "đi với/bằng" trong tiếng Việt.'},related:["minna-5:NとVます","minna-7:NでNをVます"],kitsuPrompt:"Hỏi tôi đi đến 3 địa điểm khác nhau bằng phương tiện gì, tôi trả lời với で."},{pattern:"NとVます",meaning:"cùng với N làm gì",priority:"common",explanation:"と chỉ người cùng thực hiện hành động. Khác với phương tiện (で): bạn đi cùng người (と), đi bằng phương tiện (で).",examples:[{sentence:"家族と旅行します。",translation:"Tôi đi du lịch cùng gia đình."},{sentence:"誰と日本へ行きましたか。",translation:"Bạn đã đi Nhật cùng với ai?"},{sentence:"一人でレストランへ行きました。",translation:"Tôi đã đi nhà hàng một mình."}],note:"誰と (cùng ai?) là câu hỏi cặp đôi với Nと. 一人で = một mình (không có と).",dialogue:{title:"Rủ bạn đi du lịch",lines:[{speaker:"A",text:"来月、沖縄へ旅行します。",translation:"Tháng sau tôi đi du lịch Okinawa."},{speaker:"B",text:"誰と行きますか。",translation:"Bạn đi cùng ai?"},{speaker:"A",text:"彼女と行きます。一緒にどうですか。",translation:"Tôi đi cùng bạn gái. Bạn có muốn đi cùng không?"}]},commonMistake:{wrong:"私は友だちと電車と行きました。",correct:"私は友だちと電車で行きました。",why:"Một câu có thể có cả と (người đi cùng) và で (phương tiện), nhưng phương tiện phải là で, không phải と thứ hai."},related:["minna-4:Nと","minna-5:NでVます"],kitsuPrompt:"Hỏi tôi 3 hoạt động cuối tuần vừa rồi đi cùng ai, tôi trả lời với Nと."},{pattern:"いつVますか",meaning:"khi nào làm?",priority:"common",explanation:'いつ là từ hỏi về thời gian "khi nào / lúc nào". Dùng thay cho từ chỉ thời gian trong câu và không cần trợ từ に.',examples:[{sentence:"いつ日本へ来ましたか。",translation:"Bạn đến Nhật khi nào?"},{sentence:"次の試験はいつですか。",translation:"Kỳ thi tiếp theo là khi nào?"},{sentence:"いつ帰りますか。— 来週帰ります。",translation:"Khi nào bạn về? — Tôi về tuần sau."}],note:"いつ không cần に sau nó, nhưng thời gian cụ thể thì cần: 月曜日に行きます (đi vào thứ Hai).",dialogue:{title:"Hỏi ngày về nước",lines:[{speaker:"A",text:"いつベトナムへ帰りますか。",translation:"Khi nào bạn về Việt Nam?"},{speaker:"B",text:"来月の15日に帰ります。",translation:"Tôi về ngày 15 tháng sau."},{speaker:"A",text:"そうですか。寂しくなりますね。",translation:"Vậy à. Sẽ nhớ bạn đấy."}]},commonMistake:{wrong:"いつに行きますか。",correct:"いつ行きますか。",why:"いつ không kết hợp với に. Nhưng khi nói thời gian cụ thể thì cần に: 月曜日に行きます (vào thứ Hai)."},related:["minna-4:〜時／〜分","minna-5:NへVます"],kitsuPrompt:"Hỏi tôi 5 sự kiện sắp tới của tôi bằng いつ、tôi sẽ trả lời thời gian cụ thể."}]},{bai:6,level:"N5",kanji:"食",reading:"たべる",romaji:"Taberu",titleVi:"Tân ngữ & tha động từ",titleJp:"他動詞・を",descVi:"Dùng を chỉ tân ngữ — nói ăn gì, làm gì và rủ ai cùng làm.",selfCheckGoals:["Dùng を đúng chỗ với tha động từ.",'Hỏi "ăn/uống/làm gì" bằng 何を〜ますか.',"Tạo động từ suru từ danh từ gốc Hán.","Rủ bạn cùng làm gì đó bằng 〜ませんか / 〜ましょう.","Phân biệt か (lựa chọn trong câu) với か (câu hỏi cuối câu)."],readingPassage:{title:"週末の過ごし方",titleVi:"Cách sống cuối tuần",japanese:"「週末、何をしますか。」「映画を見ます。それからショッピングをします。」「映画ですか。何の映画を見ますか。」「日本映画かアニメを見ます。」「一人で行きますか。」「いいえ、友達を呼びます。」",vietnamese:'"Cuối tuần bạn làm gì?" "Tôi xem phim. Sau đó đi mua sắm." "Phim à. Xem phim gì?" "Xem phim Nhật hoặc anime." "Đi một mình à?" "Không, tôi gọi bạn cùng đi."',highlights:[{excerpt:"映画を見ます",label:"NをVます"},{excerpt:"ショッピングをします",label:"NをNします"},{excerpt:"何をしますか",label:"何をVますか"},{excerpt:"日本映画かアニメを見ます",label:"NかN"}],questions:[{q:"週末に何をしますか。（２つ）",options:["買い物と料理","映画とショッピング","勉強と運動","映画と料理"],answer:1},{q:"どんな映画を見ますか。",options:["アメリカ映画","フランス映画","日本映画かアニメ","ホラー映画"],answer:2}]},patterns:[{pattern:"NをVます",meaning:"làm gì với N (tân ngữ trực tiếp)",priority:"core",explanation:"を là trợ từ đánh dấu tân ngữ trực tiếp của tha động từ — vật/người chịu tác động của hành động. を không có nghĩa riêng, chỉ có chức năng ngữ pháp.",examples:[{sentence:"毎朝コーヒーを飲みます。",translation:"Mỗi sáng tôi uống cà phê."},{sentence:"昨日、映画を見ました。",translation:"Hôm qua tôi đã xem phim."},{sentence:"日本語を勉強しています。",translation:"Tôi đang học tiếng Nhật."},{sentence:"何を食べましたか。",translation:"Bạn đã ăn gì?"}],note:"を chỉ dùng với tha động từ (có tân ngữ). Tự động từ như あります, います không dùng を.",dialogue:{title:"Bữa trưa ở căng-tin",lines:[{speaker:"A",text:"昼ごはんに何を食べましたか。",translation:"Bạn đã ăn gì vào bữa trưa?"},{speaker:"B",text:"ラーメンを食べました。Aさんは？",translation:"Tôi ăn ramen. Còn anh A?"},{speaker:"A",text:"私はサラダとサンドイッチを食べました。",translation:"Tôi ăn salad và sandwich."}]},commonMistake:{wrong:"映画が見ます。",correct:"映画を見ます。",why:"が và を không thay nhau với tha động từ. が đánh dấu chủ thể; を đánh dấu tân ngữ. 映画を見ます = xem phim (を cho đối tượng hành động)."},related:["minna-6:何をVますか","minna-9:NはNが好きです（が thay を）"],kitsuPrompt:"Hỏi tôi ăn gì, uống gì, và làm gì mỗi ngày, tôi trả lời với NをVます."},{pattern:"NをNします",meaning:"làm N (suru-động từ)",priority:"common",explanation:"Danh từ gốc Hán (or ngoại lai) + します tạo thành động từ. Đây là nhóm động từ suru rất phổ biến trong tiếng Nhật hiện đại.",examples:[{sentence:"毎日運動します。",translation:"Mỗi ngày tôi tập thể dục."},{sentence:"週末は買い物をします。",translation:"Cuối tuần tôi đi mua sắm."},{sentence:"友だちに電話します。",translation:"Tôi gọi điện cho bạn."},{sentence:"明日、予約をします。",translation:"Ngày mai tôi sẽ đặt chỗ."}],note:"Danh từ + をします hoặc viết liền thành 1 động từ: 勉強をします = 勉強します. Cả hai đều đúng.",dialogue:{title:"Hỏi thói quen tập thể dục",lines:[{speaker:"A",text:"毎日運動しますか。",translation:"Bạn có tập thể dục mỗi ngày không?"},{speaker:"B",text:"はい、朝ジョギングをします。Aさんは？",translation:"Có, buổi sáng tôi chạy bộ. Còn anh A?"},{speaker:"A",text:"私はジムで筋トレをします。",translation:"Tôi tập tạ ở phòng gym."}]},commonMistake:{wrong:"勉強するをします。",correct:"勉強します。",why:"Suru-verb đã là động từ, không cần をします thêm vào. 勉強する = 勉強します (dạng lịch sự)."},related:["minna-6:NをVます","minna-26:Vること"],kitsuPrompt:"Hỏi tôi về 3 thói quen hàng ngày, tôi sẽ trả lời bằng suru-verb (勉強、運動、仕事...)."},{pattern:"何をVますか",meaning:"làm gì?",priority:"core",explanation:'何(なに/なん) là từ hỏi "gì / cái gì". Khi làm tân ngữ đi với を: 何を〜. Khi đứng trước danh từ: 何の〜.',examples:[{sentence:"昼ごはんに何を食べましたか。",translation:"Bạn đã ăn gì vào bữa trưa?"},{sentence:"週末に何をしますか。",translation:"Cuối tuần bạn làm gì?"},{sentence:"何を飲みますか。— コーヒーをお願いします。",translation:"Bạn uống gì? — Cho tôi cà phê."}],note:'何 trước âm t, d, n đọc là "nan": 何時(なんじ), 何番(なんばん), 何人(なんにん).',dialogue:{title:"Hỏi sở thích cuối tuần",lines:[{speaker:"A",text:"週末はいつも何をしますか。",translation:"Cuối tuần bạn thường làm gì?"},{speaker:"B",text:"映画を見たり、料理をしたりします。",translation:"Tôi vừa xem phim vừa nấu ăn (và những thứ khác)."},{speaker:"A",text:"料理は何を作りますか。",translation:"Bạn nấu món gì?"}]},commonMistake:{wrong:"何が食べましたか。",correct:"何を食べましたか。",why:"Tân ngữ của tha động từ dùng を, không phải が. が dùng cho chủ thể hoặc đối tượng của cảm xúc/trạng thái."},related:["minna-6:NをVます","minna-9:どうしてVますか"],kitsuPrompt:"Bạn hãy phỏng vấn tôi về thói quen sáng/trưa/tối bằng 何をVますか, tôi trả lời."},{pattern:"NかN",meaning:"N hay N (liệt kê lựa chọn)",priority:"common",explanation:'か nối các danh từ để đưa ra lựa chọn "A hay B". Khác với や (liệt kê không đầy đủ) — か mang tính lựa chọn/phân vân.',examples:[{sentence:"コーヒーか紅茶、どちらにしますか。",translation:"Cà phê hay trà, bạn chọn gì?"},{sentence:"土曜日か日曜日に行きます。",translation:"Tôi sẽ đi vào thứ Bảy hoặc Chủ nhật."},{sentence:"電車かバスで来てください。",translation:"Bạn hãy đi bằng tàu hoặc xe buýt."}],note:'か ở giữa câu = "hay/hoặc"; か cuối câu = dấu hỏi. Hai cách dùng hoàn toàn khác nhau.',dialogue:{title:"Đặt đồ uống",lines:[{speaker:"NV",text:"お飲み物はコーヒーか紅茶、どちらがよろしいですか。",translation:"Đồ uống cà phê hay trà, anh muốn gì ạ?"},{speaker:"Khách",text:"コーヒーをお願いします。",translation:"Cho tôi cà phê."},{speaker:"NV",text:"ホットかアイス、どちらになさいますか。",translation:"Nóng hay lạnh, anh chọn gì ạ?"}]},commonMistake:{wrong:"コーヒーやお茶、どちらがいいですか。",correct:"コーヒーかお茶、どちらがいいですか。",why:"や dùng để liệt kê không đầy đủ (còn nhiều thứ khác); か dùng khi đưa ra lựa chọn cụ thể A hoặc B."},related:["minna-3:NはAですか、Bですか","minna-10:NやN"],kitsuPrompt:"Bạn hỏi tôi lựa chọn 5 thứ khác nhau bằng AかB、どちらがいいですか, tôi trả lời."},{pattern:"いっしょにVませんか／Vましょう",meaning:"cùng làm nhé? / hãy cùng làm",priority:"core",explanation:"Vませんか = lời mời (bạn không muốn ... cùng nhau không?); Vましょう = đề nghị cùng làm (chắc hơn, cả hai cùng đồng ý).",examples:[{sentence:"いっしょに昼ごはんを食べませんか。",translation:"Chúng ta cùng ăn trưa không?"},{sentence:"映画を見ましょう！",translation:"Hãy xem phim thôi!"},{sentence:"そろそろ帰りましょうか。",translation:"Chúng ta về thôi nhỉ?"},{sentence:"カラオケに行きませんか。",translation:"Bạn có muốn đi hát karaoke không?"}],note:"Vませんか nghe lịch sự, bày tỏ đề nghị. Vましょう mạnh hơn, phù hợp khi cả hai đã muốn làm.",dialogue:{title:"Rủ đồng nghiệp ăn trưa",lines:[{speaker:"A",text:"もうお昼ですね。いっしょに食べませんか。",translation:"Đã đến trưa rồi nhỉ. Chúng ta cùng ăn không?"},{speaker:"B",text:"いいですね！どこへ行きますか。",translation:"Hay đấy! Mình đi đâu?"},{speaker:"A",text:"駅前のラーメン屋に行きましょう。",translation:"Hãy đến quán ramen trước ga nhé."}]},commonMistake:{wrong:"いっしょに行きましょうか (khi muốn hỏi ý kiến người kia)",correct:"いっしょに行きませんか (lịch sự hơn khi đề nghị)",why:'ましょうか nghe như "mình nên đi không nhỉ?" — phù hợp khi chưa chắc. ませんか = "bạn có muốn đi cùng không?" — lịch sự và phổ biến hơn khi mời.'},related:["minna-5:NとVます","minna-14:〜てください"],kitsuPrompt:"Rủ tôi tham gia 3 hoạt động khác nhau bằng 〜ませんか, tôi sẽ nhận lời hoặc từ chối."}]},{bai:7,level:"N5",kanji:"友",reading:"とも",romaji:"Tomo",titleVi:"Cho & nhận đồ vật",titleJp:"やりもらい (物)",descVi:"Phân biệt あげます・もらいます khi trao và nhận đồ vật cho ai.",selfCheckGoals:["Dùng あげます/もらいます đúng hướng trao-nhận.","Dùng で cho công cụ và ngôn ngữ.",'Hỏi "tặng ai/nhận từ ai" với に.',"Tránh nhầm あげます khi người nhận là bản thân."],readingPassage:{title:"誕生日プレゼント",titleVi:"Quà sinh nhật",japanese:"今日は田中さんの誕生日です。ミラーさんは田中さんに花をあげます。マリアさんも田中さんにケーキをあげます。田中さんはミラーさんに素敵な本をもらいました。一緒にレストランで食事をしましょう。夜、みんなで公園を散歩しませんか。",vietnamese:"Hôm nay là sinh nhật anh Tanaka. Anh Miller tặng hoa cho anh Tanaka. Chị Maria cũng tặng bánh kem cho anh Tanaka. Anh Tanaka nhận được một cuốn sách hay từ anh Miller. Hãy cùng nhau ăn ở nhà hàng. Tối nay cùng đi dạo trong công viên nhé?",highlights:[{excerpt:"田中さんに花をあげます",label:"NにNをあげます"},{excerpt:"ミラーさんに素敵な本をもらいました",label:"NにNをもらいます"},{excerpt:"レストランで食事をしましょう",label:"Vましょう"},{excerpt:"公園を散歩しませんか",label:"Vませんか"}],questions:[{q:"ミラーさんは田中さんに何をあげますか。",options:["ケーキ","本","花","手紙"],answer:2},{q:"田中さんはミラーさんに何をもらいましたか。",options:["花","素敵な本","ケーキ","プレゼント"],answer:1}]},patterns:[{pattern:"NでNをVます",meaning:"bằng công cụ N, làm gì",priority:"core",explanation:'で ở đây chỉ công cụ hoặc phương tiện thực hiện hành động. Công cụ = vật bạn "dùng" để làm gì đó.',examples:[{sentence:"はしでごはんを食べます。",translation:"Tôi ăn cơm bằng đũa."},{sentence:"ボールペンで名前を書いてください。",translation:"Hãy viết tên bằng bút bi."},{sentence:"スマホで写真を撮りました。",translation:"Tôi đã chụp ảnh bằng điện thoại."},{sentence:"日本語で話しましょう。",translation:"Hãy nói chuyện bằng tiếng Nhật."}],note:"で chỉ cả phương tiện di chuyển (電車で) lẫn công cụ (はしで) — cùng một trợ từ, hai ngữ cảnh.",dialogue:{title:"Thực hành ăn bằng đũa",lines:[{speaker:"A",text:"はしが使えますか。",translation:"Bạn có dùng được đũa không?"},{speaker:"B",text:"はい、でもまだ上手じゃないです。フォークで食べてもいいですか。",translation:"Được, nhưng vẫn chưa giỏi. Tôi ăn bằng dĩa được không?"},{speaker:"A",text:"もちろんです！練習しましょう。",translation:"Dĩ nhiên! Hãy cùng luyện tập nhé."}]},commonMistake:{wrong:"はしをごはんを食べます。",correct:"はしでごはんを食べます。",why:"Công cụ/phương tiện dùng で, không phải を. を chỉ đánh dấu tân ngữ trực tiếp (ở đây là ごはん)."},related:["minna-5:NでVます","minna-7:Nで（ngôn ngữ）"],kitsuPrompt:"Hỏi tôi dùng công cụ gì cho 5 hoạt động hàng ngày, tôi trả lời với Nで."},{pattern:"NにNをあげます",meaning:"cho N (đồ vật) cho ai",priority:"core",explanation:'あげます = "cho" — người nói (hoặc người khác, ngoại trừ người nghe) cho đồ vật đến người nhận. Hướng cho: mình → người khác.',examples:[{sentence:"田中さんに本をあげました。",translation:"Tôi đã tặng sách cho anh Tanaka."},{sentence:"彼女に花をあげます。",translation:"Tôi sẽ tặng hoa cho bạn gái."},{sentence:"子どもにお菓子をあげました。",translation:"Tôi đã cho kẹo cho đứa trẻ."},{sentence:"誕生日に何をあげましたか。",translation:"Bạn đã tặng gì vào ngày sinh nhật?"}],note:"Không dùng あげます khi người nhận là người nói — dùng もらいます. Cũng tránh dùng あげます cho người bề trên (dùng さしあげます).",dialogue:{title:"Hỏi về quà sinh nhật",lines:[{speaker:"A",text:"田中さんの誕生日に何をあげましたか。",translation:"Bạn đã tặng gì cho anh Tanaka nhân dịp sinh nhật?"},{speaker:"B",text:"本をあげました。日本語の勉強の本です。",translation:"Tôi tặng sách. Sách học tiếng Nhật."},{speaker:"A",text:"いいプレゼントですね！",translation:"Quà hay đấy!"}]},commonMistake:{wrong:'田中さんは私に本をあげました。(khi muốn nói "nhận từ Tanaka")',correct:"田中さんに本をもらいました。",why:'あげます: tôi → người khác. もらいます: tôi ← người khác. Người Việt hay nhầm hướng. Chú ý: chủ ngữ "tôi" không cần nói ra trong もらいます.'},related:["minna-7:NにNをもらいます","minna-24:VてあげますVてもらいます"],kitsuPrompt:"Hỏi tôi đã tặng gì cho ai trong các dịp đặc biệt, tôi trả lời với NにNをあげます."},{pattern:"NにNをもらいます",meaning:"nhận N từ ai",priority:"core",explanation:'もらいます = "nhận" — người nói nhận đồ vật từ ai đó. Hướng nhận: người khác → mình. に chỉ người cho, を chỉ vật được nhận.',examples:[{sentence:"友だちにプレゼントをもらいました。",translation:"Tôi đã nhận quà từ bạn."},{sentence:"先生に本をもらいました。",translation:"Tôi đã nhận sách từ thầy giáo."},{sentence:"誰にもらいましたか。",translation:"Bạn nhận từ ai vậy?"},{sentence:"親に時計をもらいました。",translation:"Tôi đã nhận đồng hồ từ bố mẹ."}],note:'から cũng có thể thay に với もらいます: 友だちからもらいました. から nhấn mạnh "xuất phát từ" hơn.',dialogue:{title:"Khoe quà nhận được",lines:[{speaker:"A",text:"素敵な時計ですね！どうしたんですか。",translation:"Chiếc đồng hồ đẹp quá! Bạn có từ đâu vậy?"},{speaker:"B",text:"彼氏にもらいました。誕生日プレゼントです。",translation:"Bạn trai tặng tôi. Quà sinh nhật đấy."},{speaker:"A",text:"いいですね、うらやましい！",translation:"Tốt quá, ghen tị với bạn!"}]},commonMistake:{wrong:"友だちからをもらいました。",correct:"友だちからもらいました。/ 友だちにもらいました。",why:"から và に đều chỉ người cho với もらいます, nhưng không dùng をから cùng lúc. Nếu dùng から, chỉ cần: 友だちからもらいました."},related:["minna-7:NにNをあげます","minna-24:VてもらいますVてあげます"],kitsuPrompt:"Hỏi tôi đã nhận quà gì từ ai trong năm qua, tôi trả lời với NにNをもらいました."},{pattern:"Nで (ngôn ngữ／phương tiện)",meaning:"bằng tiếng N / bằng N",priority:"common",explanation:"Mở rộng của で chỉ phương tiện: dùng để nói bằng ngôn ngữ nào. Cũng áp dụng cho phương thức liên lạc.",examples:[{sentence:"日本語で話してください。",translation:"Hãy nói bằng tiếng Nhật."},{sentence:"メールで連絡します。",translation:"Tôi sẽ liên lạc qua email."},{sentence:"英語でも話せますか。",translation:"Bạn có thể nói bằng tiếng Anh không?"},{sentence:"日本語で書いた手紙",translation:"bức thư viết bằng tiếng Nhật"}],note:"で chỉ phương tiện/công cụ/ngôn ngữ — một trợ từ đa năng, gặp lại nhiều ở các bài sau.",dialogue:{title:"Họp quốc tế",lines:[{speaker:"A",text:"会議は何語でしますか。",translation:"Cuộc họp dùng ngôn ngữ gì?"},{speaker:"B",text:"英語でします。でも資料は日本語で書きます。",translation:"Họp bằng tiếng Anh. Nhưng tài liệu viết bằng tiếng Nhật."},{speaker:"A",text:"わかりました。日本語でメールを送ります。",translation:"Tôi hiểu. Tôi sẽ gửi email bằng tiếng Nhật."}]},commonMistake:{wrong:"日本語に話してください。",correct:"日本語で話してください。",why:"Ngôn ngữ dùng で (phương tiện giao tiếp). に ở đây không phù hợp — に chỉ điểm đến hoặc người nhận, không chỉ ngôn ngữ."},related:["minna-7:NでNをVます","minna-5:NでVます"],kitsuPrompt:"Hỏi tôi dùng ngôn ngữ nào cho 3 tình huống khác nhau (họp, chat, viết thư), tôi trả lời với Nで."}]},{bai:8,level:"N5",kanji:"美",reading:"うつくしい",romaji:"Utsukushii",titleVi:"Tính từ い & な",titleJp:"形容詞の基本",descVi:"Mô tả sự vật và nơi chốn bằng い-adj và な-adj.",selfCheckGoals:["Chia đúng tính từ い: khẳng định/phủ định/quá khứ.","Biết khi nào tính từ な cần/không cần な.","Hỏi mô tả bằng どんな và trả lời mô tả đầy đủ.","Dùng とても và あまり〜ない đúng với câu khẳng định/phủ định.","Nhớ ngoại lệ いい → よかった (quá khứ)."],readingPassage:{title:"アパート探し",titleVi:"Tìm căn hộ",japanese:"ミラーさんは新しいアパートを探しています。どんなアパートがいいですか。静かできれいなアパートがいいです。駅から遠くないアパートがほしいです。この部屋は広いですが、ちょっと古いです。あの部屋はとても明るくて、便利です。でも、家賃があまり安くないです。",vietnamese:"Anh Miller đang tìm căn hộ mới. Muốn căn hộ như thế nào? Muốn căn hộ yên tĩnh và sạch sẽ. Muốn căn hộ không xa ga. Phòng này rộng nhưng hơi cũ. Phòng đó rất sáng và tiện lợi. Nhưng tiền thuê không rẻ lắm.",highlights:[{excerpt:"静かできれいなアパート",label:"NAなN"},{excerpt:"広いですが、ちょっと古いです",label:"NはAいです"},{excerpt:"とても明るくて",label:"とても〜"},{excerpt:"家賃があまり安くないです",label:"あまり〜ない"}],questions:[{q:"ミラーさんはどんなアパートがいいですか。",options:["広くて新しい","静かできれい","安くて便利","駅から近い"],answer:1},{q:"あの部屋の家賃はどうですか。",options:["とても安い","あまり安くない","とても高い","ただ"],answer:1}]},patterns:[{pattern:"NはAいです／Aくないです",meaning:"N thì tính từ い (khẳng định / phủ định)",priority:"core",explanation:"Tính từ đuôi い chia: khẳng định = い + です; phủ định = い → くない + です. Tính từ い hoạt động như vị ngữ trực tiếp mà không cần な.",examples:[{sentence:"この本はおもしろいです。",translation:"Cuốn sách này thú vị."},{sentence:"今日は寒くないです。",translation:"Hôm nay không lạnh."},{sentence:"このラーメンはおいしいですが、高いです。",translation:"Tô ramen này ngon nhưng đắt."},{sentence:"昨日の試験は難しかったです。",translation:"Bài thi hôm qua khó."}],note:"Quá khứ tính từ い: い → かった + です (おいしかった). いい → よかった (không phải いかった).",dialogue:{title:"Đánh giá nhà hàng mới",lines:[{speaker:"A",text:"昨日の新しいレストラン、どうでしたか。",translation:"Nhà hàng mới hôm qua thế nào?"},{speaker:"B",text:"料理はおいしかったですが、ちょっと高かったです。",translation:"Đồ ăn ngon nhưng hơi đắt."},{speaker:"A",text:"お店はきれいでしたか。",translation:"Quán sạch không?"},{speaker:"B",text:"はい、とてもきれいで、静かでした。",translation:"Có, rất sạch và yên tĩnh."}]},commonMistake:{wrong:"今日は寒いくないです。",correct:"今日は寒くないです。",why:"Phủ định tính từ い: bỏ い, thêm くない. Không thêm くない vào sau い — phải thay い bằng くない."},related:["minna-8:とても／あまり〜ない","minna-12:NはNより〜です"],kitsuPrompt:"Hỏi tôi đánh giá 5 thứ khác nhau (đồ ăn, phim, trường học...) và tôi trả lời với tính từ い."},{pattern:"NAなN",meaning:"N na-adj (bổ nghĩa trước danh từ)",priority:"core",explanation:"Tính từ な đứng trước danh từ phải có な ở giữa. Khi đứng làm vị ngữ (sau は) thì bỏ な: きれいな町 → この町はきれいです.",examples:[{sentence:"きれいな街ですね。",translation:"Thành phố đẹp nhỉ."},{sentence:"静かな部屋が好きです。",translation:"Tôi thích phòng yên tĩnh."},{sentence:"有名なレストランに行きました。",translation:"Tôi đã đến một nhà hàng nổi tiếng."},{sentence:"便利なアプリを使っています。",translation:"Tôi đang dùng một ứng dụng tiện lợi."}],note:"Tính từ な khi làm vị ngữ: この町はきれいです (không cần な). Khi bổ nghĩa danh từ: きれいな町.",dialogue:{title:"Giới thiệu thành phố quê hương",lines:[{speaker:"A",text:"ハノイはどんな町ですか。",translation:"Hà Nội là thành phố như thế nào?"},{speaker:"B",text:"とてもにぎやかな町です。歴史的な場所もたくさんあります。",translation:"Là một thành phố rất nhộn nhịp. Cũng có nhiều địa điểm lịch sử."},{speaker:"A",text:"いいですね。静かな場所もありますか。",translation:"Tốt quá. Có chỗ nào yên tĩnh không?"}]},commonMistake:{wrong:"きれいい部屋",correct:"きれいな部屋",why:"きれい trông như tính từ い nhưng thực ra là tính từ な (い cuối không phải đuôi chia). Luôn dùng きれいな khi bổ nghĩa danh từ."},related:["minna-8:NはNAです","minna-8:どんなNですか"],kitsuPrompt:"Hỏi tôi mô tả thành phố quê hương, tôi sẽ dùng 3 tính từ な trong câu trả lời."},{pattern:"NはNAです／NAじゃありません",meaning:"N thì na-adj / N không na-adj",priority:"core",explanation:"Tính từ な làm vị ngữ: khẳng định = NA + です; phủ định = NA + じゃありません / ではありません. Không cần な khi là vị ngữ.",examples:[{sentence:"この町はにぎやかです。",translation:"Thành phố này nhộn nhịp."},{sentence:"私の部屋はあまりきれいじゃありません。",translation:"Phòng tôi không được sạch lắm."},{sentence:"田中さんは親切な人です。",translation:"Anh Tanaka là người tốt bụng."},{sentence:"日本語の勉強は大変ですが、楽しいです。",translation:"Học tiếng Nhật vất vả nhưng vui."}],note:"Quá khứ tính từ な: NAでした (khẳng định), NAじゃありませんでした (phủ định).",dialogue:{title:"Nói về căn phòng mới",lines:[{speaker:"A",text:"新しい部屋はどうですか。きれいですか。",translation:"Phòng mới thế nào? Sạch không?"},{speaker:"B",text:"きれいですが、あまり広くないです。でも静かです。",translation:"Sạch nhưng không rộng lắm. Nhưng yên tĩnh."},{speaker:"A",text:"駅から便利ですか。",translation:"Có thuận tiện từ ga không?"}]},commonMistake:{wrong:"この町はにぎやかなです。",correct:"この町はにぎやかです。",why:"Tính từ な khi đứng làm vị ngữ (sau は) thì BỎ な, chỉ cần +です. Chỉ dùng な khi đứng TRƯỚC danh từ: にぎやかな町."},related:["minna-8:NAなN","minna-1:NはNではありません"],kitsuPrompt:"Hỏi tôi đặc điểm tính cách của bạn tôi, tôi mô tả bằng tính từ な dạng vị ngữ."},{pattern:"どんなNですか",meaning:"N như thế nào? / N loại gì?",priority:"common",explanation:"どんな hỏi về đặc điểm hoặc tính chất của N. Trả lời mô tả bằng tính từ い hoặc な.",examples:[{sentence:"日本はどんな国ですか。",translation:"Nhật Bản là đất nước như thế nào?"},{sentence:"どんな音楽が好きですか。",translation:"Bạn thích nhạc loại gì?"},{sentence:"彼はどんな人ですか。",translation:"Anh ấy là người như thế nào?"},{sentence:"新しい仕事はどんな仕事ですか。",translation:"Công việc mới là công việc như thế nào?"}],note:"どんな (loại gì, như thế nào) khác với どう (= như thế nào về cách thức/cảm nhận): どうでしたか (Bạn cảm thấy thế nào?).",dialogue:{title:"Hỏi về công việc mới",lines:[{speaker:"A",text:"新しい会社はどんな会社ですか。",translation:"Công ty mới là công ty như thế nào?"},{speaker:"B",text:"IT系の会社です。とても忙しいですが、仕事がおもしろいです。",translation:"Là công ty IT. Rất bận nhưng công việc thú vị."},{speaker:"A",text:"上司はどんな人ですか。",translation:"Sếp là người thế nào?"}]},commonMistake:{wrong:"A: 日本はどんな国ですか。B: はい、いい国です。",correct:"A: 日本はどんな国ですか。B: きれいで、安全な国です。",why:"どんな hỏi mô tả, không trả lời はい/いいえ. Phải mô tả bằng tính từ hoặc đặc điểm cụ thể."},related:["minna-8:NはAいです","minna-8:NAなN"],kitsuPrompt:'Hỏi tôi "どんな〜が好きですか" về 4 chủ đề: âm nhạc, phim, sách, thức ăn.'},{pattern:"とても／あまり〜ない",meaning:"rất ~ / không ~ lắm",priority:"common",explanation:"Trạng từ bổ nghĩa mức độ: とても (rất) dùng với câu khẳng định; あまり (không... lắm) chỉ dùng với câu phủ định.",examples:[{sentence:"このケーキはとてもおいしいです。",translation:"Cái bánh này rất ngon."},{sentence:"日本語はあまり難しくないです。",translation:"Tiếng Nhật không khó lắm."},{sentence:"その映画はあまり面白くありませんでした。",translation:"Bộ phim đó không thú vị lắm."},{sentence:"今日はとても暑いですね。",translation:"Hôm nay nóng quá nhỉ."}],note:"あまり luôn đi với phủ định: あまり〜ない / あまり〜ません. Sai: あまりおいしいです.",dialogue:{title:"Bình luận thời tiết",lines:[{speaker:"A",text:"今日はとても暑いですね。",translation:"Hôm nay nóng quá nhỉ."},{speaker:"B",text:"そうですね。でも昨日はあまり暑くなかったです。",translation:"Đúng vậy. Nhưng hôm qua không nóng lắm."},{speaker:"A",text:"明日はどうでしょうか。",translation:"Ngày mai thế nào nhỉ?"}]},commonMistake:{wrong:"あまりおいしいです。",correct:"あまりおいしくないです。/ あまりおいしくありません。",why:'あまり bắt buộc phải đi với phủ định. Nếu muốn nói "rất ngon" thì dùng とても.'},related:["minna-8:NはAいです","minna-9:NはNが好きです"],kitsuPrompt:"Hỏi tôi đánh giá 5 thứ (đồ ăn, phim, thời tiết...) và tôi dùng とても hoặc あまり〜ない."}]},{bai:9,level:"N5",kanji:"好",reading:"すき",romaji:"Suki",titleVi:"Sở thích & năng lực",titleJp:"好き・嫌い・上手・下手",descVi:"Nói thích/ghét, giỏi/kém và đưa ra lý do bằng から.",selfCheckGoals:["Nói sở thích và mức độ (大好き/好き/あまり好きじゃない/嫌い).","Khen người khác giỏi bằng 上手 và tự nói về kỹ năng mình bằng 得意/苦手.","Dùng わかります/できます với が đúng chỗ.","Giải thích lý do bằng 〜から.","Hỏi lý do với どうして và trả lời đầy đủ."],readingPassage:{title:"趣味と得意なこと",titleVi:"Sở thích và điểm mạnh",japanese:"マリアさんは料理が大好きです。特に日本料理が好きです。日本語もよくわかります。どうして日本語を勉強しますか。日本のアニメが好きだから、勉強します。ギターも弾きます。でも、歌はあまり上手じゃありません。",vietnamese:"Chị Maria rất thích nấu ăn. Đặc biệt thích ẩm thực Nhật. Tiếng Nhật cũng hiểu tốt. Tại sao học tiếng Nhật? Vì thích anime Nhật nên học. Cũng chơi guitar. Nhưng hát không giỏi lắm.",highlights:[{excerpt:"料理が大好きです",label:"NはNが好きです"},{excerpt:"日本語もよくわかります",label:"NがわかりますN"},{excerpt:"どうして日本語を勉強しますか",label:"どうして〜か"},{excerpt:"アニメが好きだから",label:"〜から (lý do)"},{excerpt:"歌はあまり上手じゃありません",label:"上手/下手"}],questions:[{q:"マリアさんは何が好きですか。",options:["スポーツ","料理","音楽","旅行"],answer:1},{q:"どうして日本語を勉強しますか。",options:["仕事があるから","日本に住むから","アニメが好きだから","友達がいるから"],answer:2}]},patterns:[{pattern:"NはNが好きです／嫌いです",meaning:"N thích / ghét N",priority:"core",explanation:"Cấu trúc đặc biệt: đối tượng yêu thích dùng が chứ không dùng を. が đánh dấu đối tượng của cảm xúc (thích/ghét/sợ/muốn).",examples:[{sentence:"私は寿司が大好きです。",translation:"Tôi rất thích sushi."},{sentence:"子どもの頃、野菜が嫌いでした。",translation:"Hồi nhỏ tôi ghét rau."},{sentence:"どんな音楽が好きですか。",translation:"Bạn thích nhạc gì?"},{sentence:"私はコーヒーが好きですが、お茶はあまり好きじゃないです。",translation:"Tôi thích cà phê nhưng không thích trà lắm."}],note:"Mức độ: 大好き (rất thích) > 好き (thích) > まあまあ (tạm) > あまり好きじゃない (không thích lắm) > 嫌い (ghét) > 大嫌い (rất ghét).",dialogue:{title:"Làm quen sở thích",lines:[{speaker:"A",text:"どんな食べ物が好きですか。",translation:"Bạn thích món ăn gì?"},{speaker:"B",text:"寿司が大好きです！でも辛い食べ物は嫌いです。Aさんは？",translation:"Tôi rất thích sushi! Nhưng ghét đồ cay. Còn anh A?"},{speaker:"A",text:"私は何でも食べます。特に辛い料理が好きです。",translation:"Tôi ăn được gì cũng được. Đặc biệt thích đồ cay."}]},commonMistake:{wrong:"私は寿司を好きです。",correct:"私は寿司が好きです。",why:"Với 好き/嫌い/上手/下手/わかる/できる — đối tượng dùng が, không phải を. Đây là nhóm từ đặc biệt trong tiếng Nhật."},related:["minna-9:NはNが上手です","minna-9:NはNがわかります"],kitsuPrompt:"Hỏi tôi sở thích về 5 chủ đề (ăn, âm nhạc, thể thao, phim, địa điểm), tôi trả lời với が好き/嫌い."},{pattern:"NはNが上手です／下手です",meaning:"N giỏi / kém về N",priority:"common",explanation:"Tương tự 好き/嫌い, kỹ năng (giỏi/kém) dùng が cho đối tượng. 上手 (じょうず) = giỏi, 下手 (へた) = kém. Tự nói về mình giỏi nghe kiêu ngạo — nên dùng 得意 hoặc 好きです.",examples:[{sentence:"田中さんは料理が上手です。",translation:"Anh Tanaka nấu ăn giỏi."},{sentence:"私はピアノが下手です。",translation:"Tôi chơi đàn piano kém."},{sentence:"日本語の発音が苦手です。",translation:"Tôi yếu về phát âm tiếng Nhật."},{sentence:"スポーツが得意ですか。",translation:"Bạn giỏi thể thao không?"}],note:"自分について: 上手 nghe kiêu → dùng 得意(とくい) hoặc まあまあです. Nói về người khác thì 上手 bình thường.",dialogue:{title:"Hỏi về kỹ năng",lines:[{speaker:"A",text:"田中さんは料理が上手ですね。どんな料理が得意ですか。",translation:"Anh Tanaka nấu ăn giỏi nhỉ. Anh giỏi nấu món gì nhất?"},{speaker:"B",text:"ありがとうございます。イタリア料理が好きで、パスタが得意です。",translation:"Cảm ơn. Tôi thích ẩm thực Ý và giỏi làm pasta."},{speaker:"A",text:"私は料理が下手ですから、教えてください。",translation:"Tôi nấu ăn kém, xin anh dạy tôi với."}]},commonMistake:{wrong:"私は料理が上手です。(tự nói về mình)",correct:"私は料理が得意です。/ 料理が好きです。",why:'上手 khi tự nói về mình nghe kiêu ngạo trong văn hóa Nhật. Nên dùng 得意(とくい) = "sở trường" hay まあまあです = "tạm được" thay thế.'},related:["minna-9:NはNが好きです","minna-9:〜から（lý do）"],kitsuPrompt:"Hỏi tôi về 3 kỹ năng của mình (nấu ăn, thể thao, ngôn ngữ...) và tôi trả lời với 上手/下手/得意/苦手."},{pattern:"NはNがわかります",meaning:"N hiểu / biết N",priority:"common",explanation:'わかります (hiểu, biết) và あります (có/tồn tại — khả năng) dùng が cho đối tượng. Đây là nhóm động từ "cảm nhận/nhận thức" dùng が thay vì を.',examples:[{sentence:"日本語が少しわかります。",translation:"Tôi hiểu tiếng Nhật một chút."},{sentence:"この問題の意味がわかりません。",translation:"Tôi không hiểu nghĩa của câu hỏi này."},{sentence:"時間がありますか。",translation:"Bạn có thời gian không?"},{sentence:"お金が少しあります。",translation:"Tôi có một ít tiền."}],note:"わかる, できる, ある, いる (khi = có) — nhóm động từ dùng が cho đối tượng chứ không phải を.",dialogue:{title:"Hỏi thăm sau giờ học",lines:[{speaker:"Teacher",text:"今日の文法、わかりましたか。",translation:"Ngữ pháp hôm nay, các em hiểu chưa?"},{speaker:"Sinh viên",text:"〜てformはわかりますが、〜ているはまだよくわかりません。",translation:"て-form thì em hiểu, nhưng 〜ている thì em vẫn chưa hiểu lắm."},{speaker:"Teacher",text:"じゃあ、もう一度説明します。",translation:"Vậy thầy giải thích lại một lần nữa."}]},commonMistake:{wrong:"日本語をわかります。",correct:"日本語がわかります。",why:'わかります thuộc nhóm động từ "cảm nhận" dùng が cho đối tượng, không phải を. Nhớ: わかる/できる/好き/嫌い → tất cả dùng が.'},related:["minna-9:NはNが好きです","minna-18:Vことができます"],kitsuPrompt:"Hỏi tôi hiểu/biết gì về tiếng Nhật, tôi trả lời với 〜がわかります/わかりません."},{pattern:"〜から (lý do)",meaning:"vì ~ nên ~ (giải thích lý do)",priority:"core",explanation:"Câu lý do đứng trước から, kết quả đứng sau. Cấu trúc: [lý do]から、[kết quả]. から ở đây khác với から chỉ điểm xuất phát.",examples:[{sentence:"忙しいですから、行きません。",translation:"Vì bận nên tôi không đi."},{sentence:"明日試験がありますから、今日は勉強します。",translation:"Vì ngày mai có thi nên hôm nay tôi học."},{sentence:"雨が降っていますから、傘を持って行きます。",translation:"Vì trời đang mưa nên tôi mang ô đi."},{sentence:"どうして日本語を勉強しますか。仕事で使いますから。",translation:"Tại sao bạn học tiếng Nhật? Vì dùng trong công việc."}],note:"Trong văn nói, から thường đứng cuối câu khi giải thích: 忙しいですから。(nghe tự nhiên hơn khi trả lời).",dialogue:{title:"Từ chối lời mời",lines:[{speaker:"A",text:"今夜、飲み会に来ませんか。",translation:"Tối nay bạn có muốn đến tiệc uống không?"},{speaker:"B",text:"すみません、明日朝早い会議がありますから、今日は無理です。",translation:"Xin lỗi, vì ngày mai có cuộc họp sớm nên hôm nay không được."},{speaker:"A",text:"そうですか、残念ですね。また今度ぜひ！",translation:"Vậy à, tiếc quá. Lần sau nhất định nhé!"}]},commonMistake:{wrong:"忙しいから、が行きません。",correct:"忙しいですから、行きません。",why:"から chỉ nối hai vế câu, không thêm が vào vế sau. Vế sau là câu bình thường, không cần thêm trợ từ nào."},related:["minna-9:どうしてVますか","minna-16:〜て、〜（nguyên nhân-kết quả）"],kitsuPrompt:"Hỏi tôi tại sao làm 3 việc (học tiếng Nhật, đến Nhật, ăn chay...) và tôi giải thích với 〜から."},{pattern:"どうしてVますか",meaning:"Tại sao làm vậy? / Vì sao?",priority:"common",explanation:'どうして là từ hỏi lý do "tại sao". Tương tự なぜ (văn viết, trang trọng hơn). Câu trả lời thường kết thúc bằng から.',examples:[{sentence:"どうして日本語を勉強しますか。",translation:"Tại sao bạn học tiếng Nhật?"},{sentence:"どうして来なかったんですか。",translation:"Tại sao bạn không đến?"},{sentence:"どうしたんですか。(= どうしましたか)",translation:"Bạn làm sao vậy? / Có chuyện gì không?"}],note:"どうして ≈ なぜ ≈ なんで. なんで thân mật hơn, なぜ trang trọng/văn viết hơn, どうして trung tính.",dialogue:{title:"Hỏi lý do học tiếng Nhật",lines:[{speaker:"A",text:"どうして日本語を勉強していますか。",translation:"Tại sao bạn học tiếng Nhật?"},{speaker:"B",text:"日本のアニメが好きですから、日本語がわかりたいです。",translation:"Vì tôi thích anime Nhật, tôi muốn hiểu tiếng Nhật."},{speaker:"A",text:"将来、日本で働きたいですか。",translation:"Tương lai bạn muốn làm việc ở Nhật không?"}]},commonMistake:{wrong:"A: どうして来ませんでしたか。B: 私は忙しい。",correct:"A: どうして来ませんでしたか。B: 忙しかったですから。",why:"Câu trả lời cho どうして phải kết thúc bằng から (lý do). Dạng lịch sự cần chia đúng thì: 忙しかった (quá khứ) + ですから."},related:["minna-9:〜から（lý do）","minna-26:〜のに、〜ので"],kitsuPrompt:'Hỏi tôi "どうして〜ですか" về 3 lựa chọn trong cuộc sống, tôi trả lời với から.'}]},{bai:10,level:"N5",kanji:"在",reading:"ある",romaji:"Aru",titleVi:"Sự tồn tại",titleJp:"存在表現",descVi:"Phân biệt あります (vật) và います (người) để nói vị trí có mặt.",selfCheckGoals:["Dùng đúng あります (vật) vs います (người/động vật).","Phân biệt NがNに vs NはNに khi hỏi và khi mô tả.",'Dùng や để liệt kê không đầy đủ và など để ngụ ý "còn nhiều hơn".',"Mô tả vị trí đồ vật trong phòng/nhà đầy đủ."],readingPassage:{title:"私の町",titleVi:"Thị trấn của tôi",japanese:"私の町には公園や図書館などがあります。駅の近くに大きいスーパーがあります。公園に子どもや老人がいます。図書館は駅の前にあります。私の家は駅から歩いて５分のところにあります。とても便利な町です。",vietnamese:"Ở thị trấn của tôi có công viên, thư viện, v.v. Gần ga có siêu thị lớn. Trong công viên có trẻ em và người già. Thư viện ở trước ga. Nhà tôi cách ga đi bộ 5 phút. Là thị trấn rất tiện lợi.",highlights:[{excerpt:"公園や図書館などがあります",label:"NやN(など)"},{excerpt:"大きいスーパーがあります",label:"NがNにあります"},{excerpt:"公園に子どもや老人がいます",label:"NがNにいます"}],questions:[{q:"図書館はどこにありますか。",options:["公園の中","駅の前","家の近く","スーパーの隣"],answer:1},{q:"公園に誰がいますか。",options:["学生","子どもと老人","犬と猫","会社員"],answer:1}]},patterns:[{pattern:"NがNにあります",meaning:"N (vật vô tri) ở N (nơi)",priority:"core",explanation:"あります diễn tả sự tồn tại của vật không sống hoặc thực thể trừu tượng. が đánh dấu chủ thể tồn tại, に chỉ nơi tồn tại.",examples:[{sentence:"机の上に本があります。",translation:"Trên bàn có sách."},{sentence:"駅の近くにコンビニがあります。",translation:"Gần ga có cửa hàng tiện lợi."},{sentence:"明日、会議があります。",translation:"Ngày mai có cuộc họp."},{sentence:"冷蔵庫にビールはありません。",translation:"Trong tủ lạnh không có bia."}],note:"あります cũng dùng với sự kiện trừu tượng: 授業があります (có buổi học), 時間があります (có thời gian).",dialogue:{title:"Tìm chìa khóa",lines:[{speaker:"A",text:"あれ？鍵がない！どこにありますか。",translation:"Ơ? Chìa khóa đâu rồi! Ở đâu nhỉ?"},{speaker:"B",text:"テーブルの上にありますよ。ほら！",translation:"Ở trên bàn đấy. Kìa!"},{speaker:"A",text:"あ、本当だ。ありがとう！",translation:"À đúng rồi. Cảm ơn!"}]},commonMistake:{wrong:"田中さんは会議室にあります。",correct:"田中さんは会議室にいます。",why:'Người dùng います, vật dùng あります. Người Việt hay nhầm vì tiếng Việt chỉ có "ở" cho cả hai.'},related:["minna-10:NがNにいます","minna-10:NはNにあります"],kitsuPrompt:"Tôi mô tả căn phòng của mình bằng NがNにあります, bạn hỏi thêm về những đồ vật khác."},{pattern:"NがNにいます",meaning:"N (người/sinh vật) ở N (nơi)",priority:"core",explanation:"います diễn tả sự hiện diện của người hoặc sinh vật. Quy tắc: vật = あります, người/động vật = います.",examples:[{sentence:"庭に犬がいます。",translation:"Trong sân có chó."},{sentence:"田中さんは今、会議室にいます。",translation:"Anh Tanaka đang ở phòng họp."},{sentence:"教室に学生が20人います。",translation:"Trong lớp có 20 sinh viên."},{sentence:"今、誰かいますか。",translation:"Bây giờ có ai ở đó không?"}],note:'Robot, búp bê, nhân vật truyện — dùng あります (vật vô tri) hay います (có "sự sống" trong tưởng tượng) tùy ngữ cảnh.',dialogue:{title:"Hỏi thăm người trong văn phòng",lines:[{speaker:"A",text:"すみません、田中さんはいますか。",translation:"Xin lỗi, anh Tanaka có ở đây không?"},{speaker:"B",text:"田中さんは今、会議室にいます。30分後に戻ります。",translation:"Anh Tanaka đang ở phòng họp. 30 phút nữa về."},{speaker:"A",text:"わかりました。また来ます。",translation:"Tôi hiểu. Tôi sẽ quay lại."}]},commonMistake:{wrong:"ペットがいます → (dùng cho đồ chơi thú nhồi bông)",correct:"ペット(おもちゃ)があります → (đồ chơi nhồi bông là vật, không phải sinh vật)",why:"います chỉ cho sinh vật thật (người, động vật). Thú nhồi bông, robot, búp bê là vật nên dùng あります — trừ khi trong ngữ cảnh tưởng tượng/truyện."},related:["minna-10:NがNにあります","minna-3:NはNにあります/います"],kitsuPrompt:"Hỏi tôi ai đang ở đâu (trong nhà, công ty, trường), tôi trả lời với NはNにいます."},{pattern:"NはNにあります／います",meaning:"N ở / tại N",priority:"core",explanation:"Khi chủ đề đã biết (NはN ở đâu?), dùng は thay vì が. Câu dạng này trả lời câu hỏi 〜はどこにありますか／いますか.",examples:[{sentence:"トイレはどこにありますか。— あちらにあります。",translation:"Nhà vệ sinh ở đâu? — Ở phía kia."},{sentence:"先生は今、研究室にいます。",translation:"Thầy giáo hiện đang ở phòng nghiên cứu."},{sentence:"私の鍵はどこにありますか。",translation:"Chìa khóa của tôi ở đâu nhỉ?"}],note:"NがNにあります = thông báo tồn tại (có N ở đó); NはNにあります = nói về vị trí của N đã biết.",dialogue:{title:"Hỏi đường trong tòa nhà",lines:[{speaker:"Khách",text:"すみません、受付はどこにありますか。",translation:"Xin lỗi, quầy lễ tân ở đâu?"},{speaker:"NV",text:"受付は1階にあります。エレベーターの隣です。",translation:"Quầy lễ tân ở tầng 1. Cạnh thang máy ạ."},{speaker:"Khách",text:"ありがとうございます。",translation:"Cảm ơn."}]},commonMistake:{wrong:"受付はどこがありますか。",correct:"受付はどこにありますか。",why:"Vị trí tồn tại dùng に (không phải が). Câu hỏi vị trí: どこに + あります/います."},related:["minna-10:NがNにあります","minna-3:ここ/そこ/あそこ"],kitsuPrompt:"Bạn hỏi tôi vị trí 5 đồ vật/người trong nhà tôi, tôi trả lời với NはNにあります/います."},{pattern:"NやN（など）",meaning:"N và N (và những thứ khác)",priority:"common",explanation:"や liệt kê danh từ không đầy đủ, ngụ ý còn có những thứ khác (など = vân vân). Khác với と liệt kê đầy đủ.",examples:[{sentence:"机の上に本や雑誌があります。",translation:"Trên bàn có sách, tạp chí (và các thứ khác)."},{sentence:"スーパーで野菜や果物などを買いました。",translation:"Tôi đã mua rau, trái cây, v.v. ở siêu thị."},{sentence:"週末は映画や買い物をします。",translation:"Cuối tuần tôi xem phim, mua sắm (và những thứ khác)."}],note:"や (liệt kê không đầy đủ) khác と (liệt kê đầy đủ): AとBだけ vs AやBなど (còn nhiều hơn).",dialogue:{title:"Kể về siêu thị mới",lines:[{speaker:"A",text:"新しいスーパー、どんなものがありますか。",translation:"Siêu thị mới có những gì?"},{speaker:"B",text:"野菜や果物はもちろん、お惣菜や輸入品などもあります。",translation:"Dĩ nhiên có rau, trái cây, và còn có đồ ăn sẵn, hàng nhập khẩu v.v."},{speaker:"A",text:"便利ですね！",translation:"Tiện quá!"}]},commonMistake:{wrong:"家族は父と母や弟がいます。",correct:"家族は父や母、弟などがいます。",why:'と dùng để liệt kê đầy đủ (chỉ có những người đó), や dùng khi muốn nói "còn có những người khác". Nếu gia đình chỉ có ba người dùng と, nếu muốn nói "bao gồm" dùng や.'},related:["minna-4:Nと (liệt kê đầy đủ)","minna-6:NかN"],kitsuPrompt:"Hỏi tôi trong phòng/nhà có gì, tôi liệt kê bằng NやNなどがあります."}]},{bai:11,level:"N5",kanji:"数",reading:"かず",romaji:"Kazu",titleVi:"Số đếm & trợ số từ",titleJp:"助数詞",descVi:"Đếm vật, người, lần bằng trợ số từ đúng loại và so sánh với どちら.",selfCheckGoals:["Dùng đúng trợ số từ: 個/枚/本/冊/台/回/杯.","Đọc đúng 1人(ひとり)、2人(ふたり)、3人以上(にん).","Nói tần suất với Nに〜回Vます.","Hỏi và trả lời so sánh hai thứ bằng どちら〜のほうが."],readingPassage:{title:"スーパーの買い物",titleVi:"Mua sắm ở siêu thị",japanese:"マリアさんは週に２回スーパーへ買い物に行きます。今日はりんごを３個、ジュースを２本買いました。レジには３人並んでいます。マリアさんは３０歳です。コーヒーは毎日３杯飲みます。健康のために果物もよく食べます。",vietnamese:"Chị Maria mỗi tuần đi siêu thị 2 lần. Hôm nay mua 3 quả táo, 2 chai nước ép. Ở quầy tính tiền có 3 người xếp hàng. Chị Maria 30 tuổi. Mỗi ngày uống 3 ly cà phê. Vì sức khỏe cũng thường ăn trái cây.",highlights:[{excerpt:"週に２回スーパーへ買い物に行きます",label:"Nに〜回Vます"},{excerpt:"りんごを３個",label:"〜個"},{excerpt:"ジュースを２本",label:"〜本"},{excerpt:"マリアさんは３０歳です",label:"〜歳"},{excerpt:"コーヒーは毎日３杯飲みます",label:"〜杯"}],questions:[{q:"マリアさんは週に何回スーパーへ行きますか。",options:["１回","２回","３回","４回"],answer:1},{q:"マリアさんは今日りんごをいくつ買いましたか。",options:["１個","２個","３個","４個"],answer:2}]},patterns:[{pattern:"〜個／〜枚／〜本／〜回／〜杯",meaning:"counter cho vật tròn / tờ mỏng / vật dài / lần / cốc",priority:"core",explanation:"Tiếng Nhật dùng trợ số từ (助数詞) khác nhau tùy loại vật đếm: 個(こ) vật nhỏ tròn, 枚(まい) vật mỏng phẳng, 本(ほん) vật dài hình trụ, 回(かい) lần, 杯(はい) cốc/bát.",examples:[{sentence:"りんごを3個ください。",translation:"Cho tôi 3 quả táo."},{sentence:"紙を2枚使いました。",translation:"Tôi đã dùng 2 tờ giấy."},{sentence:"ビールを1杯飲みました。",translation:"Tôi đã uống 1 ly bia."},{sentence:"先週、3回映画を見ました。",translation:"Tuần trước tôi đã xem phim 3 lần."}],note:"Trợ số từ quan trọng N5: 〜枚(まい)tờ, 〜本(ほん)chai/cây, 〜冊(さつ)cuốn sách, 〜台(だい)máy móc, 〜匹(ひき)thú nhỏ.",dialogue:{title:"Mua sắm ở siêu thị",lines:[{speaker:"Khách",text:"すみません、このケーキを2個と牛乳を1本ください。",translation:"Xin lỗi, cho tôi 2 cái bánh và 1 chai sữa."},{speaker:"NV",text:"はい、他にはよろしいですか。",translation:"Vâng ạ. Còn cần thêm gì không?"},{speaker:"Khách",text:"えーと、コーヒーを3杯分のカップもお願いします。",translation:"À ừm, tôi cần thêm cốc cho 3 ly cà phê."}]},commonMistake:{wrong:"ビールを1本飲みました。(khi uống lon/chai nhỏ)",correct:"ビールを1缶(かん)飲みました。/ 1杯飲みました。",why:"本 dùng cho vật dài hình trụ như chai lớn, ống. Lon bia = 缶(かん). Ly/cốc = 杯(はい). Cần chọn counter phù hợp với hình dạng/loại vật."},related:["minna-11:〜人/〜歳","minna-11:Nに〜回Vます"],kitsuPrompt:'Quiz tôi về trợ số từ: hỏi tôi "dùng counter gì" cho 5 đồ vật khác nhau.'},{pattern:"〜人／〜歳",meaning:"counter người / tuổi",priority:"core",explanation:"人(にん) đếm người (1人=ひとり, 2人=ふたり, 3人以上=〜にん). 歳(さい) đếm tuổi. Cả hai có cách đọc đặc biệt cần nhớ.",examples:[{sentence:"家族は5人います。",translation:"Gia đình có 5 người."},{sentence:"私は25歳です。",translation:"Tôi 25 tuổi."},{sentence:"何人で来ましたか。— 3人です。",translation:"Bạn đến mấy người? — 3 người."},{sentence:"クラスに外国人が10人います。",translation:"Trong lớp có 10 người nước ngoài."}],note:"1人=ひとり, 2人=ふたり (đặc biệt!), 3人=さんにん, 4人=よにん, 何人=なんにん.",dialogue:{title:"Đặt bàn ăn",lines:[{speaker:"NV",text:"何名様ですか。",translation:"Quý khách có mấy người ạ?"},{speaker:"Khách",text:"4人です。子どもが2人います。",translation:"4 người. Trong đó có 2 trẻ em."},{speaker:"NV",text:"かしこまりました。お席にご案内します。",translation:"Vâng ạ. Tôi xin dẫn quý khách vào bàn."}]},commonMistake:{wrong:"私の家族は4にんいます。",correct:"私の家族は4人(よにん)います。",why:'4人 đọc là よにん (không phải しにん — đó là cách đọc của "死人" = người chết). Luôn đọc 4人=よにん.'},related:["minna-11:〜個/枚/本/回/杯","minna-1:NはNです（giới thiệu）"],kitsuPrompt:"Hỏi tôi về gia đình, lớp học và nơi làm (có bao nhiêu người), tôi trả lời với 〜人."},{pattern:"Nに〜回Vます",meaning:"làm ~ lần trong / mỗi N",priority:"common",explanation:"Diễn tả tần suất: に chỉ đơn vị thời gian (tuần/tháng/ngày), 〜回 chỉ số lần. Cấu trúc: [đơn vị thời gian]に[số]回 [động từ].",examples:[{sentence:"1週間に3回ジムに行きます。",translation:"Tôi đến phòng gym 3 lần một tuần."},{sentence:"1ヶ月に1回、歯医者に行きます。",translation:"Tôi đi nha sĩ 1 lần một tháng."},{sentence:"1日に2回薬を飲んでください。",translation:"Hãy uống thuốc 2 lần mỗi ngày."},{sentence:"1年に何回旅行しますか。",translation:"Bạn đi du lịch mấy lần một năm?"}],note:"に ở đây không phải chỉ địa điểm mà chỉ khoảng thời gian: 一週間に (trong một tuần).",dialogue:{title:"Hỏi về thói quen tập thể thao",lines:[{speaker:"A",text:"どのくらいジムに行きますか。",translation:"Bạn đi gym bao nhiêu?"},{speaker:"B",text:"1週間に3回行きます。毎週月水金です。",translation:"3 lần một tuần. Các tuần vào thứ Hai, Tư, Sáu."},{speaker:"A",text:"すごい！私は1ヶ月に1回ぐらいです。",translation:"Ghê thật! Tôi chỉ khoảng 1 lần một tháng thôi."}]},commonMistake:{wrong:"1週間に3回ジムを行きます。",correct:"1週間に3回ジムに行きます。",why:"行きます (đi) dùng に cho địa điểm đích, không phải を. を đi với tha động từ, còn 行く là tự động từ."},related:["minna-11:〜個/枚/本/回/杯","minna-4:NからNまで"],kitsuPrompt:"Hỏi tôi tần suất 5 thói quen hàng ngày/tuần, tôi trả lời với Nに〜回Vます."},{pattern:"NとNとどちらが〜ですか",meaning:"A và B, cái nào ~ hơn?",priority:"common",explanation:"Câu hỏi so sánh hai lựa chọn. Cấu trúc: [A]と[B]とどちらが〜ですか → Trả lời: [A/B]のほうが〜です.",examples:[{sentence:"夏と冬とどちらが好きですか。— 夏のほうが好きです。",translation:"Bạn thích mùa hè hay mùa đông? — Tôi thích mùa hè hơn."},{sentence:"電車とバスとどちらが早いですか。",translation:"Tàu điện và xe buýt, cái nào nhanh hơn?"},{sentence:"日本語と英語とどちらが難しいですか。",translation:"Tiếng Nhật và tiếng Anh, cái nào khó hơn?"}],note:"どちら là dạng lịch sự; どっち là dạng thân mật. Trả lời dùng 〜のほうが (hơn).",dialogue:{title:"Chọn nhà hàng ăn tối",lines:[{speaker:"A",text:"中華料理と和食とどちらがいいですか。",translation:"Đồ Trung Hoa và đồ Nhật, bạn thích cái nào hơn?"},{speaker:"B",text:"今日は和食のほうがいいです。すし屋はどうですか。",translation:"Hôm nay tôi thích đồ Nhật hơn. Quán sushi thế nào?"},{speaker:"A",text:"いいですね！近くにおいしいすし屋があります。",translation:"Tốt đấy! Gần đây có quán sushi ngon."}]},commonMistake:{wrong:"A: AとBとどちらが好きですか。B: はい、Aが好きです。",correct:"A: AとBとどちらが好きですか。B: Aのほうが好きです。",why:"Câu hỏi どちら không trả lời はい/いいえ. Phải dùng 〜のほうが để chỉ rõ lựa chọn so sánh."},related:["minna-12:NはNより〜です","minna-3:NはAですか、Bですか"],kitsuPrompt:"Hỏi tôi 5 cặp so sánh (A và B, cái nào tốt hơn?) bằng どちらが、tôi trả lời với のほうが."}]},{bai:12,level:"N5",kanji:"比",reading:"ひかく",romaji:"Hikaku",titleVi:"So sánh",titleJp:"比較表現",descVi:"Dùng より・のほうが・一番 để so sánh hai hoặc nhiều thứ với nhau.",selfCheckGoals:["So sánh hai thứ bằng AはBより〜です.","Trả lời câu hỏi どちら bằng 〜のほうが〜です.",'Nói "... nhất" trong nhóm bằng Nの中で〜が一番〜.',"Dùng 同じです và 違います để nói giống/khác."],readingPassage:{title:"どちらがいいですか",titleVi:"Cái nào tốt hơn?",japanese:"田中さんと山田さん、どちらが背が高いですか。田中さんのほうが山田さんより背が高いです。三人の中で田中さんが一番背が高いです。マリアさんとキムさんはどちらが日本語が上手ですか。二人は同じぐらいです。でも、キムさんのほうがマリアさんより漢字が得意です。",vietnamese:"Anh Tanaka và anh Yamada, ai cao hơn? Anh Tanaka cao hơn anh Yamada. Trong ba người, anh Tanaka cao nhất. Chị Maria và chị Kim, ai giỏi tiếng Nhật hơn? Hai người giỏi như nhau. Nhưng chị Kim giỏi kanji hơn chị Maria.",highlights:[{excerpt:"どちらが背が高いですか",label:"どちらが〜ですか"},{excerpt:"田中さんのほうが山田さんより背が高いです",label:"NよりNのほうが〜"},{excerpt:"一番背が高いです",label:"Nの中で〜が一番〜"},{excerpt:"二人は同じぐらいです",label:"NはNと同じです"}],questions:[{q:"三人の中で誰が一番背が高いですか。",options:["山田さん","マリアさん","田中さん","キムさん"],answer:2},{q:"マリアさんとキムさんの日本語はどうですか。",options:["マリアさんが上手","キムさんが上手","同じぐらい","どちらも下手"],answer:2}]},patterns:[{pattern:"NはNより〜です",meaning:"N thì ~ hơn N",priority:"core",explanation:'より đứng sau đối tượng bị so sánh (chuẩn so sánh), tính từ đứng sau. Dịch: "N1 thì ~ hơn N2" hay "N1 ~ hơn so với N2".',examples:[{sentence:"東京は大阪より大きいです。",translation:"Tokyo lớn hơn Osaka."},{sentence:"電車はバスより速いです。",translation:"Tàu điện nhanh hơn xe buýt."},{sentence:"今日は昨日より涼しいです。",translation:"Hôm nay mát hơn hôm qua."},{sentence:"日本語は思ったより難しくないです。",translation:"Tiếng Nhật không khó như tôi nghĩ."}],note:'より = "hơn so với". Câu hỏi: 〜より〜のほうがいいですか hay どちらのほうがいいですか.',dialogue:{title:"So sánh hai thành phố",lines:[{speaker:"A",text:"東京と大阪、どちらが好きですか。",translation:"Tokyo và Osaka, bạn thích thành phố nào hơn?"},{speaker:"B",text:"大阪のほうが好きです。東京より物価が安いし、食べ物がおいしいです。",translation:"Tôi thích Osaka hơn. Giá cả rẻ hơn Tokyo và đồ ăn ngon hơn."},{speaker:"A",text:"そうですか。私は東京のほうが便利だと思います。",translation:"Vậy à. Tôi nghĩ Tokyo tiện hơn."}]},commonMistake:{wrong:"東京は大阪よりも大きいです。(không sai, nhưng)",correct:"東京は大阪より大きいです。",why:"よりも (thêm も) nghe mạnh hơn/nhấn mạnh hơn よりだけ. Cả hai đều đúng nhưng より đơn giản hơn cho N5."},related:["minna-12:NよりNのほうが〜","minna-11:NとNとどちらが〜"],kitsuPrompt:"Hỏi tôi so sánh Tokyo vs Osaka, hè vs đông, tiếng Nhật vs tiếng Anh... bằng AはBより〜。"},{pattern:"NよりNのほうが〜です",meaning:"N hơn N về mặt ~",priority:"core",explanation:"のほうが nhấn mạnh vào thứ được chọn/nổi bật hơn. Cấu trúc phổ biến khi trả lời câu hỏi so sánh どちらが.",examples:[{sentence:"りんごよりみかんのほうが好きです。",translation:"Tôi thích quýt hơn táo."},{sentence:"バスより電車のほうが便利です。",translation:"Tàu điện tiện hơn xe buýt."},{sentence:"東京より京都のほうが静かです。",translation:"Kyoto yên tĩnh hơn Tokyo."},{sentence:"どちらのほうが安いですか。",translation:"Cái nào rẻ hơn?"}],note:"AよりBのほうが〜 = B hơn A (B được chọn, A là chuẩn so sánh).",dialogue:{title:"Tư vấn mua điện thoại",lines:[{speaker:"A",text:"このスマホとあのスマホ、どちらがいいですか。",translation:"Điện thoại này và điện thoại kia, cái nào tốt hơn?"},{speaker:"B",text:"バッテリーはこちらのほうが長いですが、あちらのほうがカメラが良いです。",translation:"Pin cái này tốt hơn, nhưng camera cái kia tốt hơn."},{speaker:"A",text:"じゃあ、カメラのほうが大事ですから、あちらにします。",translation:"Vậy vì camera quan trọng hơn, tôi chọn cái kia."}]},commonMistake:{wrong:"りんごよりみかんは好きです。",correct:"りんごよりみかんのほうが好きです。",why:"Cấu trúc cố định: AよりBのほうが〜. Không thay のほうが bằng は — ý nghĩa sẽ thay đổi."},related:["minna-12:NはNより〜","minna-11:NとNとどちらが〜"],kitsuPrompt:"Cho tôi hai lựa chọn, tôi sẽ so sánh và trả lời bằng 〜よりNのほうが〜です."},{pattern:"Nの中で〜が一番〜です",meaning:"~ nhất trong N",priority:"core",explanation:"So sánh bậc nhất: chỉ thứ đứng đầu trong một nhóm. Cấu trúc: [nhóm]の中で / [nhóm]で + [chủ thể]が一番〜.",examples:[{sentence:"クラスの中で田中さんが一番背が高いです。",translation:"Trong lớp, anh Tanaka cao nhất."},{sentence:"日本の食べ物の中で、寿司が一番好きです。",translation:"Trong các món Nhật, tôi thích sushi nhất."},{sentence:"一年で一番寒い月はいつですか。",translation:"Tháng lạnh nhất trong năm là tháng nào?"},{sentence:"この店で一番人気のメニューは何ですか。",translation:"Món phổ biến nhất ở quán này là gì?"}],note:"Câu hỏi bậc nhất: 〜の中で何が一番〜ですか (cái gì ~ nhất?) / 誰が一番〜ですか (ai ~ nhất?).",dialogue:{title:"Hỏi về sở thích nhất",lines:[{speaker:"A",text:"日本の食べ物の中で何が一番好きですか。",translation:"Trong đồ ăn Nhật, bạn thích nhất cái gì?"},{speaker:"B",text:"一番好きなのはラーメンです！特に醤油ラーメン。",translation:"Thứ tôi thích nhất là ramen! Đặc biệt là ramen xì dầu."},{speaker:"A",text:"おすすめのお店はありますか。",translation:"Bạn có quán nào hay không?"}]},commonMistake:{wrong:"クラスで田中さんが一番です高いです。",correct:"クラスで田中さんが一番背が高いです。",why:"一番 đứng trước tính từ, không ngắt câu. Cấu trúc: 一番 + [tính từ] (không thêm です ở giữa)."},related:["minna-12:NはNより〜","minna-12:NよりNのほうが〜"],kitsuPrompt:'Hỏi tôi "〜の中で何が一番〜ですか" về 4 chủ đề, tôi trả lời với 一番〜なのは〜です.'},{pattern:"NはNと同じです",meaning:"N giống N / N giống với N",priority:"common",explanation:"と同じ diễn tả sự giống nhau. Ngược lại là 違います (khác nhau) hoặc 〜と違います (khác với 〜).",examples:[{sentence:"私のかばんはあなたのと同じです。",translation:"Túi của tôi giống túi của bạn."},{sentence:"今日の宿題は昨日と同じですか。",translation:"Bài tập hôm nay có giống hôm qua không?"},{sentence:"これとこれは同じですか、違いますか。",translation:"Cái này và cái này giống hay khác nhau?"}],note:"同じ là tính từ na-adj nhưng đặc biệt: không thêm な khi đứng trước danh từ: 同じ値段 (không phải 同じな値段).",dialogue:{title:"Nhận ra cùng sở thích",lines:[{speaker:"A",text:"私はK-POPが好きです。",translation:"Tôi thích K-POP."},{speaker:"B",text:"あ、私も！趣味が同じですね。",translation:"Ồ tôi cũng vậy! Sở thích giống nhau nhỉ."},{speaker:"A",text:"でも好きなグループは違いますか。",translation:"Nhưng nhóm yêu thích thì có khác không?"}]},commonMistake:{wrong:"同じな趣味ですね。",correct:"同じ趣味ですね。",why:"同じ là tính từ đặc biệt — không dùng な khi đứng trước danh từ, dù nó thuộc nhóm な-adj."},related:["minna-12:NはNより〜","minna-1:NはNです"],kitsuPrompt:"So sánh tôi và bạn về sở thích, tôi sẽ dùng 同じです hoặc 違います để trả lời."}]},{bai:13,level:"N5",kanji:"欲",reading:"ほしい",romaji:"Hoshii",titleVi:"Mong muốn",titleJp:"希望表現",descVi:"Nói muốn sở hữu vật gì (欲しい) và muốn làm gì (〜たいです).",selfCheckGoals:["Nói muốn sở hữu gì bằng 〜が欲しいです.","Nói muốn làm gì bằng Vたいです và chia đúng dạng phủ định/quá khứ.","Nói mục đích di chuyển bằng NへVに行きます.","Phân biệt たい (muốn làm) và 欲しい (muốn có)."],readingPassage:{title:"将来の夢",titleVi:"Ước mơ tương lai",japanese:"ミラーさんは将来日本へ仕事に行きたいです。日本語が上手になりたいです。日本料理も作れるようになりたいです。新しいパソコンも欲しいです。来年、日本語能力試験を受けに行きたいです。夢に向かってがんばります。",vietnamese:"Anh Miller tương lai muốn đi Nhật làm việc. Muốn giỏi tiếng Nhật. Cũng muốn biết nấu ẩm thực Nhật. Cũng muốn có máy tính mới. Sang năm muốn đi thi năng lực tiếng Nhật. Sẽ cố gắng hướng đến ước mơ.",highlights:[{excerpt:"日本へ仕事に行きたいです",label:"NへNにVます / Vたいです"},{excerpt:"日本語が上手になりたいです",label:"NがVたいです"},{excerpt:"パソコンも欲しいです",label:"NはNが欲しいです"}],questions:[{q:"ミラーさんは将来どこへ行きたいですか。",options:["アメリカ","中国","日本","フランス"],answer:2},{q:"ミラーさんは何が欲しいですか。",options:["新しい本","新しいパソコン","日本語の辞書","カメラ"],answer:1}]},patterns:[{pattern:"NはNが欲しいです",meaning:"N muốn (có được) N",priority:"core",explanation:"欲しい là tính từ い, diễn tả mong muốn sở hữu vật gì. Đối tượng mong muốn dùng が. Chú ý: chỉ nói về mong muốn của mình, không dùng để nói mong muốn của người khác (dùng ほしがっています).",examples:[{sentence:"新しいスマートフォンが欲しいです。",translation:"Tôi muốn có điện thoại thông minh mới."},{sentence:"今、お金が欲しいです。",translation:"Bây giờ tôi muốn có tiền."},{sentence:"何か欲しいものはありますか。",translation:"Bạn có muốn thứ gì không?"},{sentence:"休みが欲しいです。",translation:"Tôi muốn được nghỉ ngơi."}],note:"Nói về người khác: 彼は新しい車を欲しがっています (anh ấy đang muốn xe mới). Không nói 彼は〜が欲しいです.",dialogue:{title:"Hỏi muốn quà gì",lines:[{speaker:"A",text:"誕生日に何が欲しいですか。",translation:"Sinh nhật bạn muốn quà gì?"},{speaker:"B",text:"本当は新しいカメラが欲しいです。でも高いですから…",translation:"Thật ra tôi muốn máy ảnh mới. Nhưng vì đắt quá..."},{speaker:"A",text:"じゃあ、一緒に買いに行きましょう！",translation:"Vậy hãy cùng đi mua nhé!"}]},commonMistake:{wrong:"彼は新しい車が欲しいです。",correct:"彼は新しい車を欲しがっています。",why:"Mong muốn là cảm xúc nội tâm — người Nhật tránh phán đoán cảm xúc người khác. Khi nói về người khác dùng 〜ほしがっています (biểu hiện ra ngoài)."},related:["minna-13:Vたいです","minna-9:NはNが好きです"],kitsuPrompt:"Hỏi tôi muốn có gì cho dịp sinh nhật/Giáng sinh, tôi trả lời với 〜が欲しいです."},{pattern:"Vたいです",meaning:"muốn làm V",priority:"core",explanation:'Gắn たい vào động từ dạng ます-stem để nói "muốn làm". たい hoạt động như tính từ い: Vたくないです (không muốn), Vたかったです (đã muốn).',examples:[{sentence:"日本へ行きたいです。",translation:"Tôi muốn đi Nhật."},{sentence:"今日は何もしたくないです。",translation:"Hôm nay tôi không muốn làm gì cả."},{sentence:"子どものころ、医者になりたかったです。",translation:"Hồi nhỏ tôi muốn trở thành bác sĩ."},{sentence:"何が食べたいですか。",translation:"Bạn muốn ăn gì?"}],note:"Tân ngữ của Vたい có thể dùng を hoặc が: ラーメンを食べたい / ラーメンが食べたい (が nhấn mạnh đối tượng hơn).",dialogue:{title:"Lên kế hoạch kỳ nghỉ",lines:[{speaker:"A",text:"夏休みはどこへ行きたいですか。",translation:"Kỳ nghỉ hè bạn muốn đi đâu?"},{speaker:"B",text:"京都へ行きたいです。お寺や神社を見たいです。",translation:"Tôi muốn đi Kyoto. Tôi muốn xem đền chùa và đình miếu."},{speaker:"A",text:"何が食べたいですか。",translation:"Bạn muốn ăn gì?"},{speaker:"B",text:"京都の抹茶スイーツが食べたいです！",translation:"Tôi muốn ăn bánh trà xanh Kyoto!"}]},commonMistake:{wrong:"彼女は日本へ行きたいです。",correct:"彼女は日本へ行きたがっています。",why:"Giống 欲しい, たい cũng chỉ dùng khi nói về mong muốn của bản thân. Với người khác dùng 〜たがっています."},related:["minna-13:NはNが欲しいです","minna-13:NへNにVます"],kitsuPrompt:"Hỏi tôi muốn làm gì trong 5 tình huống khác nhau, tôi trả lời với Vたいです."},{pattern:"NへNにVます",meaning:"đi đến N để làm N",priority:"core",explanation:"Diễn tả mục đích di chuyển. Mục đích đứng trước に, động từ di chuyển đứng sau. Cấu trúc: [nơi đến]へ + [mục đích]に + [đi/đến/về].",examples:[{sentence:"デパートへ買い物に行きます。",translation:"Tôi đi đến trung tâm thương mại để mua sắm."},{sentence:"図書館へ本を借りに行きました。",translation:"Tôi đã đến thư viện để mượn sách."},{sentence:"日本へ日本語を勉強しに来ました。",translation:"Tôi đến Nhật để học tiếng Nhật."},{sentence:"友だちの家へ遊びに行きます。",translation:"Tôi đến nhà bạn để chơi."}],note:"Mục đích là động từ dạng ます-stem + に: 食べに (để ăn), 見に (để xem), 遊びに (để chơi).",dialogue:{title:"Nói lý do đến Nhật",lines:[{speaker:"Người Nhật",text:"日本へ何をしに来ましたか。",translation:"Bạn đến Nhật để làm gì?"},{speaker:"Du học sinh",text:"日本語を勉強しに来ました。日本文化も学びたいです。",translation:"Tôi đến để học tiếng Nhật. Tôi cũng muốn tìm hiểu văn hóa Nhật."},{speaker:"Người Nhật",text:"そうですか。日本を楽しんでください！",translation:"Vậy à. Chúc bạn thích thú với Nhật Bản!"}]},commonMistake:{wrong:"スーパーへ買い物のために行きます。",correct:"スーパーへ買い物に行きます。",why:"Mục đích di chuyển dùng Vます-stem + に, không phải ために (ために = vì, dùng cho mục đích nói chung, học ở bài sau)."},related:["minna-5:NへVます","minna-22:VにNへ行きます"],kitsuPrompt:"Hỏi tôi đi đâu để làm gì (3 địa điểm), tôi trả lời với NへNにVます."},{pattern:"NがVたいです",meaning:"muốn ~ N (tân ngữ dùng が)",priority:"common",explanation:'Khi tân ngữ của Vたい được nhấn mạnh hoặc trong câu hỏi "cái gì muốn làm", tân ngữ có thể dùng が thay vì を.',examples:[{sentence:"日本料理が食べたいです。",translation:"Tôi muốn ăn món Nhật."},{sentence:"何が見たいですか。— 富士山が見たいです。",translation:"Bạn muốn nhìn gì? — Tôi muốn nhìn thấy núi Fuji."},{sentence:"冷たい水が飲みたいです。",translation:"Tôi muốn uống nước lạnh."}],note:"を vs が với たい: を = bình thường, が = nhấn mạnh đối tượng. Cả hai đều đúng, が tự nhiên hơn trong câu hỏi.",dialogue:{title:"Hỏi muốn ăn gì hôm nay",lines:[{speaker:"A",text:"今日は何が食べたいですか。",translation:"Hôm nay bạn muốn ăn gì?"},{speaker:"B",text:"辛いものが食べたいです！タイ料理はどうですか。",translation:"Tôi muốn ăn gì đó cay! Đồ ăn Thái thế nào?"},{speaker:"A",text:"いいですね。近くにおいしいお店があります。",translation:"Hay đấy. Gần đây có quán ngon."}]},commonMistake:{wrong:"何をが食べたいですか。",correct:"何が食べたいですか。",why:"Không dùng をが cùng lúc. Khi tân ngữ là から hỏi (何), dùng が: 何が食べたいですか. Khi tân ngữ cụ thể, dùng を hoặc が: ラーメンを/が食べたい."},related:["minna-13:Vたいです","minna-9:NはNがわかります"],kitsuPrompt:"Hỏi tôi 何が〜たいですか về 4 hoạt động, tôi trả lời nhấn mạnh đối tượng."}]},{bai:14,level:"N5",kanji:"進",reading:"すすむ",romaji:"Susumu",titleVi:"Thể て & đang làm",titleJp:"て形と現在進行",descVi:"Học て-form — yêu cầu lịch sự, nối câu và diễn tả đang làm gì.",selfCheckGoals:["Chia động từ sang て-form đúng cho cả 3 nhóm.","Dùng Vてください để yêu cầu lịch sự.","Nói đang làm gì bằng Vています.","Đề nghị giúp đỡ bằng Vましょうか và trả lời.","Phân biệt Vています hành động (đang) vs trạng thái."],readingPassage:{title:"日本語の授業",titleVi:"Giờ học tiếng Nhật",japanese:"先生は「教科書を開いてください」と言います。学生たちはみんな静かに勉強しています。田中さんはノートに漢字を書いています。マリアさんは先生の話を聞いています。先生は「説明しましょうか。」と言います。",vietnamese:'Giáo viên nói "Hãy mở sách giáo khoa ra". Các học sinh đang học yên lặng. Anh Tanaka đang viết chữ kanji vào vở. Chị Maria đang lắng nghe giáo viên nói. Giáo viên nói "Tôi giải thích cho nhé?".',highlights:[{excerpt:"教科書を開いてください",label:"Vてください"},{excerpt:"みんな静かに勉強しています",label:"Vています (進行)"},{excerpt:"ノートに漢字を書いています",label:"NでVています"},{excerpt:"説明しましょうか",label:"Vましょうか"}],questions:[{q:"田中さんは今何をしていますか。",options:["話しています","聞いています","ノートに漢字を書いています","寝ています"],answer:2},{q:"先生は何と言いましたか。",options:["本を閉じてください","教科書を開いてください","宿題をしてください","帰ってください"],answer:1}]},patterns:[{pattern:"Vてください",meaning:"xin hãy làm (yêu cầu lịch sự)",priority:"core",explanation:'て-form + ください = yêu cầu lịch sự "xin hãy làm". Phủ định: Vないでください (xin đừng làm). Đây là ứng dụng đầu tiên của て-form quan trọng nhất.',examples:[{sentence:"ちょっと待ってください。",translation:"Xin đợi một chút."},{sentence:"ここに名前を書いてください。",translation:"Xin hãy viết tên vào đây."},{sentence:"もう一度言ってください。",translation:"Xin hãy nói lại một lần nữa."},{sentence:"ドアを閉めてください。",translation:"Xin hãy đóng cửa lại."}],note:"Lịch sự hơn: 〜ていただけますか / 〜ていただけませんか. Thân mật: 〜て (bỏ ください).",dialogue:{title:"Yêu cầu ở lớp học",lines:[{speaker:"Thầy",text:"テキストの10ページを開いてください。",translation:"Hãy mở sách giáo khoa trang 10."},{speaker:"Thầy",text:"田中さん、この文を読んでください。",translation:"Tanaka, hãy đọc câu này."},{speaker:"Học sinh",text:"すみません、もう一度言ってください。",translation:"Xin lỗi, thầy nói lại được không?"}]},commonMistake:{wrong:"名前を書いてくださいます。",correct:"名前を書いてください。",why:"ください là dạng mệnh lệnh lịch sự của くれる, không chia tiếp. Không thêm ます sau ください."},related:["minna-17:Vないでください","minna-6:いっしょにVませんか"],kitsuPrompt:"Đóng vai giáo viên và yêu cầu tôi làm 5 việc trong lớp bằng 〜てください."},{pattern:"Vています (進行)",meaning:"đang làm V (tiến hành)",priority:"core",explanation:"て-form + います diễn tả hành động đang diễn ra tại thời điểm nói. Đây là một trong hai nghĩa chính của Vています (nghĩa kia = trạng thái, học sau).",examples:[{sentence:"今、ご飯を食べています。",translation:"Tôi đang ăn cơm."},{sentence:"今、何をしていますか。",translation:"Bây giờ bạn đang làm gì?"},{sentence:"子どもたちが公園で遊んでいます。",translation:"Các em đang chơi ở công viên."},{sentence:"田中さんは今、電話しています。",translation:"Anh Tanaka đang gọi điện thoại."}],note:'います trong Vています là bổ trợ (補助動詞), không phải います "có mặt". Khẩu ngữ hay rút gọn: 〜てる (食べてる).',dialogue:{title:"Gọi điện thoại",lines:[{speaker:"A",text:"もしもし、今、何をしていますか。",translation:"Alo, bây giờ bạn đang làm gì?"},{speaker:"B",text:"今、料理をしています。ちょっと待ってください。",translation:"Tôi đang nấu ăn. Chờ tôi một chút."},{speaker:"A",text:"わかりました。あとでかけ直します。",translation:"Tôi hiểu. Tôi sẽ gọi lại sau."}]},commonMistake:{wrong:"今、ご飯を食べいます。",correct:"今、ご飯を食べています。",why:"Cần đầy đủ て-form trước います. 食べ + て + います = 食べています. Thiếu て là sai ngữ pháp."},related:["minna-15:Vています（trạng thái）","minna-15:Nを知っています"],kitsuPrompt:"Hỏi tôi đang làm gì tại các thời điểm khác nhau trong ngày, tôi trả lời với Vています."},{pattern:"Vましょうか",meaning:"Để tôi làm cho nhé? / Chúng ta làm nhé?",priority:"common",explanation:"Vましょうか = đề nghị giúp đỡ hoặc cùng làm. Khác với Vましょう (cùng làm thôi!) ở chỗ có か — hỏi ý kiến trước.",examples:[{sentence:"荷物を持ちましょうか。",translation:"Để tôi xách đồ cho nhé?"},{sentence:"窓を開けましょうか。",translation:"Để tôi mở cửa sổ nhé?"},{sentence:"そろそろ帰りましょうか。",translation:"Chúng ta về thôi nhỉ?"},{sentence:"タクシーを呼びましょうか。",translation:"Để tôi gọi taxi cho nhé?"}],note:"Trả lời đề nghị giúp: はい、お願いします (vâng, phiền bạn nhé) / いいえ、大丈夫です (không cần, tôi ổn).",dialogue:{title:"Giúp đỡ người mang đồ nặng",lines:[{speaker:"A",text:"荷物が多いですね。持ちましょうか。",translation:"Đồ nhiều nhỉ. Để tôi xách giúp nhé?"},{speaker:"B",text:"あ、ありがとうございます。お願いします。",translation:"Ồ, cảm ơn. Phiền bạn nhé."},{speaker:"A",text:"どこへ行きますか。いっしょに行きましょう。",translation:"Bạn đi đâu? Hãy cùng đi nhé."}]},commonMistake:{wrong:"Vましょうか vs Vましょう bị dùng lẫn lộn.",correct:"行きましょうか (hỏi ý kiến) vs 行きましょう (cùng làm thôi).",why:"ましょうか nghe nhẹ nhàng hơn, hỏi ý kiến người kia. ましょう mạnh hơn, giả định cả hai cùng đồng ý. Trong tình huống lịch sự nên dùng ましょうか."},related:["minna-6:いっしょにVませんか","minna-14:Vてください"],kitsuPrompt:"Tôi sẽ mô tả tình huống khó khăn, bạn đề nghị giúp bằng 〜ましょうか, tôi chấp nhận hoặc từ chối."},{pattern:"NでVています (nghề nghiệp/thói quen)",meaning:"làm nghề / có thói quen làm",priority:"common",explanation:'Vています cũng diễn tả nghề nghiệp hoặc trạng thái kéo dài. で chỉ nơi làm việc. Đây là nghĩa "trạng thái" của Vています.',examples:[{sentence:"銀行で働いています。",translation:"Tôi làm việc ở ngân hàng."},{sentence:"田中さんは東京に住んでいます。",translation:"Anh Tanaka đang sống ở Tokyo."},{sentence:"私は結婚しています。",translation:"Tôi đã kết hôn (đang trong trạng thái đã cưới)."},{sentence:"今、日本語を勉強しています。",translation:"Hiện tôi đang học tiếng Nhật (thói quen)."}],note:"住んでいます (đang ở/sống), 結婚しています (đã lập gia đình), 知っています (đang biết) = trạng thái, không phải hành động.",dialogue:{title:"Giới thiệu bản thân tại tiệc",lines:[{speaker:"A",text:"お仕事は何をされていますか。",translation:"Anh làm nghề gì?"},{speaker:"B",text:"IT会社でエンジニアをしています。最近はAIの開発をしています。",translation:"Tôi làm kỹ sư ở công ty IT. Gần đây đang phát triển AI."},{speaker:"A",text:"すごいですね。東京に住んでいますか。",translation:"Ghê nhỉ. Anh sống ở Tokyo à?"}]},commonMistake:{wrong:"東京に住んでいますか → Tôi biết bạn sống ở Tokyo (khi hỏi người lạ)",correct:"どこに住んでいますか。",why:'住んでいますか hỏi đúng thì: "bạn đang sống ở đâu?". Nhưng khi hỏi người lạ, có thể hỏi どこに住んでいますか cho tự nhiên hơn.'},related:["minna-14:Vています（進行）","minna-1:NはNです（nghề nghiệp）"],kitsuPrompt:"Hỏi tôi về công việc, nơi ở và tình trạng hôn nhân, tôi trả lời với 〜でVています."}]},{bai:15,level:"N5",kanji:"許",reading:"ゆるす",romaji:"Yurusu",titleVi:"Cho phép & cấm đoán",titleJp:"てもいい・てはいけない",descVi:'Hỏi "được phép làm không?" và nói "không được làm" với てはいけない.',selfCheckGoals:["Hỏi xin phép bằng 〜てもいいですか và nhận/từ chối.","Nói cấm bằng 〜てはいけません trong ngữ cảnh nội quy.","Phân biệt Vています hành động vs trạng thái.","Dùng đúng 知っています/知りません."],readingPassage:{title:"図書館のルール",titleVi:"Nội quy thư viện",japanese:"図書館では携帯電話を使ってはいけません。飲食もしてはいけません。静かにしてください。本をコピーしてもいいですか。はい、一階のコピー機を使ってもいいです。田中さんはこの図書館のルールをよく知っています。毎日ここで勉強しています。",vietnamese:"Trong thư viện không được dùng điện thoại di động. Cũng không được ăn uống. Hãy giữ yên lặng. Tôi có được photo sách không? Vâng, được dùng máy photo ở tầng 1. Anh Tanaka biết rõ nội quy thư viện này. Mỗi ngày học ở đây.",highlights:[{excerpt:"携帯電話を使ってはいけません",label:"Vてはいけません"},{excerpt:"コピーしてもいいですか",label:"Vてもいいですか"},{excerpt:"コピー機を使ってもいいです",label:"Vてもいいです"},{excerpt:"ルールをよく知っています",label:"Nを知っています"},{excerpt:"毎日ここで勉強しています",label:"Vています (trạng thái/thói quen)"}],questions:[{q:"図書館で何をしてはいけませんか。",options:["本を読む","携帯電話を使う","ノートを取る","コピーをする"],answer:1},{q:"本をコピーしてもいいですか。",options:["いいえ、だめです","はい、１階で","はい、どこでも","館長に聞いてください"],answer:1}]},patterns:[{pattern:"Vてもいいですか",meaning:"Tôi có thể làm được không? (xin phép)",priority:"core",explanation:"て-form + もいいですか = hỏi xin phép. Phép tắc: も (= cũng) + いい (= tốt/được). Trả lời: はい、どうぞ (vâng, mời) / いいえ、〜てはいけません (không, không được).",examples:[{sentence:"ここで写真を撮ってもいいですか。",translation:"Tôi có thể chụp ảnh ở đây không?"},{sentence:"エアコンをつけてもいいですか。",translation:"Tôi bật điều hòa được không?"},{sentence:"トイレを使ってもいいですか。",translation:"Tôi có thể dùng nhà vệ sinh không?"},{sentence:"ちょっと早く帰ってもいいですか。",translation:"Tôi có thể về sớm một chút không?"}],note:"Lịch sự hơn: 〜てもよろしいですか. Thân mật: 〜ていい? Trả lời cho phép: いいですよ / もちろん / どうぞ.",dialogue:{title:"Xin phép trong văn phòng",lines:[{speaker:"Nhân viên",text:"部長、少し早く帰ってもいいですか。子どもが熱を出して。",translation:"Trưởng phòng, tôi có thể về sớm một chút không? Con tôi bị sốt."},{speaker:"Trưởng phòng",text:"もちろんです。お大事にしてください。",translation:"Dĩ nhiên rồi. Chăm sóc con nhé."},{speaker:"Nhân viên",text:"ありがとうございます。明日ちゃんと来ます。",translation:"Cảm ơn anh. Ngày mai tôi sẽ đến đúng giờ."}]},commonMistake:{wrong:"ここで写真を撮りてもいいですか。",correct:"ここで写真を撮ってもいいですか。",why:"てもいいですか cần て-form đúng: 撮る → 撮って (nhóm 1). Không chia trực tiếp ます-stem + てもいいですか."},related:["minna-15:Vてはいけません","minna-17:Vなくてもいいです"],kitsuPrompt:"Tôi sẽ hỏi xin phép 5 lần trong các tình huống khác nhau, bạn cho phép hoặc từ chối."},{pattern:"Vてはいけません",meaning:"không được làm (cấm đoán)",priority:"core",explanation:"て-form + はいけません = cấm hoặc không được phép. Dùng trong bảng nội quy, quy định. Thân mật: Vてはだめです / Vてはいけない.",examples:[{sentence:"ここでタバコを吸ってはいけません。",translation:"Không được hút thuốc ở đây."},{sentence:"試験中に話してはいけません。",translation:"Không được nói chuyện trong khi thi."},{sentence:"この部屋に入ってはいけません。",translation:"Không được vào phòng này."},{sentence:"子どもはお酒を飲んではいけません。",translation:"Trẻ em không được uống rượu."}],note:"てはいけません (cấm tuyệt đối) mạnh hơn ないほうがいいです (không nên). Dùng đúng ngữ cảnh quan trọng.",dialogue:{title:"Nội quy thư viện",lines:[{speaker:"NV",text:"こちらの図書館では、飲食をしてはいけません。",translation:"Trong thư viện này, không được ăn uống."},{speaker:"Khách",text:"スマホで写真を撮ってもいいですか。",translation:"Tôi có thể chụp ảnh bằng điện thoại không?"},{speaker:"NV",text:"はい、いいですが、フラッシュは使ってはいけません。",translation:"Được, nhưng không được dùng đèn flash."}]},commonMistake:{wrong:"タバコをすってはいけない。(với người lớn tuổi hơn)",correct:"タバコを吸わないでください。/ タバコはご遠慮ください。",why:"てはいけない nghe mạnh/trực tiếp, phù hợp với nội quy hoặc khi nói với trẻ em. Với người lớn hơn dùng Vないでください lịch sự hơn."},related:["minna-15:Vてもいいですか","minna-17:Vないでください"],kitsuPrompt:"Đóng vai nhân viên bảo tàng, giải thích nội quy bằng てはいけません và đáp lại câu hỏi xin phép của tôi."},{pattern:"Vています (trạng thái)",meaning:"đang ở trạng thái V",priority:"core",explanation:'Vています không chỉ là "đang làm" mà còn là trạng thái kéo dài sau khi hoàn tất hành động. Đây là nghĩa thứ hai quan trọng.',examples:[{sentence:"田中さんは結婚しています。",translation:"Anh Tanaka đã (và đang trong trạng thái) kết hôn."},{sentence:"窓が開いています。",translation:"Cửa sổ đang ở trạng thái mở."},{sentence:"電気がついています。",translation:"Đèn đang bật."},{sentence:"道が込んでいます。",translation:"Đường đang tắc."}],note:"結婚する→結婚している (trạng thái đã cưới), 死ぬ→死んでいる (trạng thái đã chết), 知る→知っている (trạng thái biết).",dialogue:{title:"Hỏi thăm phòng",lines:[{speaker:"A",text:"部屋の電気がついていますよ。",translation:"Đèn phòng đang bật đấy."},{speaker:"B",text:"あ、本当だ。窓も開いていますね。",translation:"À, đúng rồi. Cửa sổ cũng đang mở nhỉ."},{speaker:"A",text:"誰かいますか。田中さんは結婚していますか。",translation:"Có ai trong đó không? Anh Tanaka đã có gia đình chưa?"}]},commonMistake:{wrong:"窓は開きました。(để mô tả trạng thái cửa sổ đang mở)",correct:"窓が開いています。",why:"開きました = hành động đã mở (quá khứ hoàn thành). 開いています = trạng thái đang mở (hiện tại). Để mô tả trạng thái hiện tại dùng Vています."},related:["minna-14:Vています（進行）","minna-15:Nを知っています"],kitsuPrompt:"Hỏi tôi về trạng thái các đồ vật trong phòng (đèn/cửa sổ/TV), tôi trả lời với 〜ています."},{pattern:"Nを知っています／知りません",meaning:"biết / không biết N",priority:"common",explanation:'知る (biết) chỉ dùng ở dạng Vています/Vていません khi muốn diễn tả trạng thái "biết". Không nói 知ります để chỉ "đang biết" — đó là một quy tắc đặc biệt.',examples:[{sentence:"田中さんの電話番号を知っていますか。",translation:"Bạn có biết số điện thoại của anh Tanaka không?"},{sentence:"すみません、この道を知りません。",translation:"Xin lỗi, tôi không biết đường này."},{sentence:"あの人の名前を知っていますか。— いいえ、知りません。",translation:"Bạn có biết tên người đó không? — Không, tôi không biết."},{sentence:"このレストランを知っていますか。",translation:"Bạn có biết nhà hàng này không?"}],note:'知っています (đang ở trạng thái biết) ≠ 知ります (hành động "biết được" → dùng khi học/nghe được thông tin mới).',dialogue:{title:"Hỏi thông tin về người quen",lines:[{speaker:"A",text:"ねえ、田中さんの新しいアドレスを知っていますか。",translation:"Này, bạn có biết địa chỉ mới của anh Tanaka không?"},{speaker:"B",text:"いいえ、知りません。山田さんなら知っているかもしれません。",translation:"Không, tôi không biết. Anh Yamada có thể biết."},{speaker:"A",text:"そうですか。山田さんに聞いてみます。",translation:"Vậy à. Để tôi hỏi anh Yamada thử."}]},commonMistake:{wrong:"あの映画を知りますか。",correct:"あの映画を知っていますか。",why:'知る không dùng ở dạng ます trực tiếp để hỏi "biết không". Phải dùng 知っていますか (trạng thái biết hiện tại). 知りません (phủ định) là ngoại lệ được chấp nhận.'},related:["minna-15:Vています（trạng thái）","minna-9:NはNがわかります"],kitsuPrompt:"Hỏi tôi 知っていますか về các địa điểm/người nổi tiếng ở Nhật, tôi trả lời với 知っています/知りません."}]},{bai:16,level:"N5",kanji:"順",reading:"じゅんじょ",romaji:"Junjo",titleVi:"Nối câu & thứ tự",titleJp:"て形の接続",descVi:"Dùng て-form để nối động từ, tính từ và diễn tả thứ tự việc.",selfCheckGoals:["Nối động từ theo thứ tự với V1てV2.","Nối tính từ い → くて và な → で.","Nhấn mạnh thứ tự bắt buộc bằng Vてから.","Mô tả đặc điểm nổi bật của chủ đề với NはNが〜."],readingPassage:{title:"マリアさんの朝",titleVi:"Buổi sáng của Maria",japanese:"マリアさんは毎朝シャワーを浴びてから、朝ごはんを食べます。朝ごはんを食べてから、歯を磨きます。マリアさんの部屋は広くて、明るいです。マリアさんはコーヒーが好きで、毎朝一杯飲みます。この生活はシンプルですが、マリアさんはとても幸せです。",vietnamese:"Mỗi sáng Maria tắm xong rồi mới ăn sáng. Ăn sáng xong rồi đánh răng. Phòng của Maria rộng và sáng. Maria thích cà phê nên mỗi sáng uống một ly. Cuộc sống này đơn giản nhưng Maria rất hạnh phúc.",highlights:[{excerpt:"シャワーを浴びてから、朝ごはんを食べます",label:"Vてから"},{excerpt:"朝ごはんを食べてから、歯を磨きます",label:"V1てV2"},{excerpt:"広くて、明るいです",label:"Aくて (nối adj)"},{excerpt:"コーヒーが好きで",label:"NAで (nối adj)"}],questions:[{q:"マリアさんは朝何をしてから朝ごはんを食べますか。",options:["歯を磨く","シャワーを浴びる","コーヒーを飲む","運動する"],answer:1},{q:"マリアさんの部屋はどんな部屋ですか。",options:["狭くて暗い","広くて明るい","静かで新しい","古くて暗い"],answer:1}]},patterns:[{pattern:"V1てV2",meaning:"làm V1 rồi (tiếp tục) làm V2",priority:"core",explanation:"て-form nối câu theo thứ tự thời gian hoặc diễn tả nhiều hành động liên tiếp. Thứ tự hành động quan trọng: V1 xảy ra trước V2.",examples:[{sentence:"朝起きて、シャワーを浴びて、朝ごはんを食べます。",translation:"Buổi sáng tôi dậy, tắm, rồi ăn sáng."},{sentence:"宿題をして、寝ました。",translation:"Tôi đã làm bài tập về nhà rồi đi ngủ."},{sentence:"電車に乗って、会社へ行きます。",translation:"Tôi đi tàu điện đến công ty."},{sentence:"スーパーに寄って、帰ります。",translation:"Tôi ghé siêu thị rồi về."}],note:"Chủ ngữ có thể khác nhau trong V1 và V2: 先生が来て、授業が始まりました (thầy đến rồi lớp bắt đầu).",dialogue:{title:"Kể lại buổi sáng",lines:[{speaker:"A",text:"毎朝何をしますか。",translation:"Mỗi sáng bạn làm gì?"},{speaker:"B",text:"6時に起きて、シャワーを浴びて、朝ごはんを食べます。それから電車で会社へ行きます。",translation:"Tôi dậy lúc 6 giờ, tắm, ăn sáng. Sau đó đi tàu đến công ty."},{speaker:"A",text:"忙しいですね！",translation:"Bận nhỉ!"}]},commonMistake:{wrong:"ご飯を食べてから、シャワーを浴びます。(đối với thứ tự đúng là tắm → ăn)",correct:"シャワーを浴びて、ご飯を食べます。",why:"V1てV2 quyết định thứ tự: V1 xảy ra TRƯỚC V2. Hãy chú ý thứ tự thực tế của các hành động."},related:["minna-16:Vてから","minna-4:Vました（thứ tự quá khứ）"],kitsuPrompt:"Hỏi tôi về routine buổi sáng/tối, tôi kể lại bằng V1てV2 (3-4 hành động liên tiếp)."},{pattern:"Aくて / NAで (nối tính từ)",meaning:"vừa ~ vừa ~ / ~ và ~",priority:"core",explanation:"Nối tính từ để mô tả nhiều đặc điểm của cùng một đối tượng: い-adj → くて; な-adj → で. Không thể nối hai tính từ trái nghĩa bằng cách này.",examples:[{sentence:"この部屋は広くて、きれいです。",translation:"Phòng này rộng và đẹp."},{sentence:"彼は親切で、おもしろい人です。",translation:"Anh ấy là người tốt bụng và thú vị."},{sentence:"日本語は難しくて、おもしろいです。",translation:"Tiếng Nhật khó nhưng thú vị."},{sentence:"この店は安くておいしいです。",translation:"Quán này rẻ và ngon."}],note:"くて và で cũng diễn tả lý do: 忙しくて、行けません (vì bận nên không đi được).",dialogue:{title:"Mô tả nhà hàng mới",lines:[{speaker:"A",text:"昨日行ったお店はどうでしたか。",translation:"Nhà hàng hôm qua bạn đến thế nào?"},{speaker:"B",text:"料理がおいしくて、値段も安くて、最高でした！",translation:"Đồ ăn ngon, giá lại rẻ, tuyệt vời luôn!"},{speaker:"A",text:"お店の雰囲気はどうでしたか。",translation:"Không khí quán thế nào?"},{speaker:"B",text:"静かで、きれいでした。",translation:"Yên tĩnh và đẹp."}]},commonMistake:{wrong:"この部屋は広いくてきれいです。",correct:"この部屋は広くてきれいです。",why:"Chia い-adj sang て-form: bỏ い, thêm くて (広い → 広くて). Không giữ い rồi mới thêm くて."},related:["minna-8:NはAいです","minna-16:V1てV2"],kitsuPrompt:"Hỏi tôi mô tả 3 nơi/người bằng 2 tính từ nối với くて/で."},{pattern:"Vてから",meaning:"sau khi làm V (rồi mới)",priority:"core",explanation:'Vてから nhấn mạnh thứ tự: hành động V phải hoàn thành trước mới làm việc tiếp theo. Khác với V1てV2 ở chỗ từ から nhấn mạnh "sau khi xong".',examples:[{sentence:"宿題をしてから、ゲームをします。",translation:"Sau khi làm xong bài tập thì mới chơi game."},{sentence:"日本語を勉強してから、日本へ行きます。",translation:"Sau khi học tiếng Nhật xong tôi sẽ đi Nhật."},{sentence:"シャワーを浴びてから、寝ます。",translation:"Tắm xong rồi mới ngủ."},{sentence:"よく考えてから、決めてください。",translation:"Hãy suy nghĩ kỹ rồi mới quyết định."}],note:'Vてから vs Vた後で (bài 34): cả hai đều nghĩa "sau khi", てから nhấn mạnh thứ tự bắt buộc hơn.',dialogue:{title:"Bàn về kế hoạch tương lai",lines:[{speaker:"A",text:"卒業してから、何をしますか。",translation:"Sau khi tốt nghiệp bạn sẽ làm gì?"},{speaker:"B",text:"日本語を上手になってから、日本の会社に就職したいです。",translation:"Sau khi giỏi tiếng Nhật hơn, tôi muốn xin việc ở công ty Nhật."},{speaker:"A",text:"いい計画ですね。頑張ってください。",translation:"Kế hoạch hay đấy. Cố gắng nhé."}]},commonMistake:{wrong:"食べてから後で行きます。",correct:"食べてから行きます。/ 食べた後で行きます。",why:'Không kết hợp てから và 後で cùng lúc — chúng cùng nghĩa "sau khi". Dùng một trong hai là đủ.'},related:["minna-16:V1てV2","minna-34:Vた後で"],kitsuPrompt:'Hỏi tôi kế hoạch tương lai "〜してから何をしますか", tôi trả lời với Vてから.'},{pattern:"N1はN2が〜",meaning:"N1 thì N2 thì ~ (mô tả đặc điểm của một bộ phận)",priority:"common",explanation:"Cấu trúc NはNが〜 dùng khi mô tả đặc điểm của một phần của N1, hoặc N1 có N2 nổi bật về một điểm nào đó. Khác với NはNが好き ở ý nghĩa.",examples:[{sentence:"富士山は景色がきれいです。",translation:"Núi Fuji có cảnh đẹp."},{sentence:"象は鼻が長いです。",translation:"Con voi có cái vòi dài."},{sentence:"この料理は野菜が多いです。",translation:"Món này có nhiều rau."},{sentence:"東京は物価が高いです。",translation:"Tokyo có giá sinh hoạt đắt đỏ."}],note:"Cấu trúc này rất phổ biến: chủ đề (は) → đặc điểm nổi bật (が) → tính từ mô tả.",dialogue:{title:"Giới thiệu Việt Nam",lines:[{speaker:"Người Nhật",text:"ベトナムはどんな国ですか。",translation:"Việt Nam là đất nước như thế nào?"},{speaker:"Du học sinh",text:"ベトナムは食べ物がおいしくて、物価が安いです。特にフォーが有名です。",translation:"Việt Nam đồ ăn ngon và giá sinh hoạt rẻ. Đặc biệt phở rất nổi tiếng."},{speaker:"Người Nhật",text:"フォーを食べてみたいです。",translation:"Tôi muốn thử ăn phở."}]},commonMistake:{wrong:"ベトナムは食べ物がおいしい。(bình thường, nhưng thiếu です khi nói lịch sự)",correct:"ベトナムは食べ物がおいしいです。",why:"Câu hoàn chỉnh cần đuôi lịch sự です. Trong hội thoại bình thường có thể bỏ です, nhưng trong ngữ cảnh học thuật/lịch sự cần giữ."},related:["minna-9:NはNが好きです","minna-12:NはNより〜"],kitsuPrompt:"Hỏi tôi mô tả 3 địa điểm hoặc con vật bằng N1はN2が〜 (bộ phận/đặc điểm nổi bật)."}]},{bai:17,level:"N5",kanji:"禁",reading:"きんし",romaji:"Kinshi",titleVi:"Nghĩa vụ & phủ định",titleJp:"義務と禁止",descVi:'Nói "phải làm" với なければ và "không cần làm" với なくてもいい.',selfCheckGoals:["Yêu cầu phủ định lịch sự với Vないでください.","Nói nghĩa vụ bằng Vなければなりません và dạng thân mật なきゃ.",'Nói "không cần làm" bằng Vなくてもいいです.',"Phân biệt まで (liên tục đến) và までに (trước deadline)."],readingPassage:{title:"試験の前日",titleVi:"Ngày trước kỳ thi",japanese:"明日は日本語の試験があります。今夜は一生懸命勉強しなければなりません。夜更かしはしないでください。無理して全部覚えなくてもいいです。試験は9時からなので、8時30分までに学校に来なければなりません。頑張ってください。",vietnamese:"Ngày mai có kỳ thi tiếng Nhật. Tối nay phải học thật chăm chỉ. Đừng thức khuya. Không cần cố nhồi nhét tất cả. Vì thi từ 9 giờ nên phải đến trường trước 8 giờ 30. Cố lên nhé.",highlights:[{excerpt:"一生懸命勉強しなければなりません",label:"Vなければなりません"},{excerpt:"夜更かしはしないでください",label:"Vないでください"},{excerpt:"全部覚えなくてもいいです",label:"Vなくてもいいです"},{excerpt:"8時30分までに学校に来なければなりません",label:"Nまでに"}],questions:[{q:"試験は何時から始まりますか。",options:["８時","８時半","９時","10時"],answer:2},{q:"学校には何時までに来なければなりませんか。",options:["８時","８時30分","９時","８時15分"],answer:1}]},patterns:[{pattern:"Vないでください",meaning:"xin đừng làm (yêu cầu phủ định)",priority:"core",explanation:"ない-form + でください = yêu cầu lịch sự không làm điều gì. Đây là phủ định của Vてください. Lịch sự hơn: Vないでいただけますか.",examples:[{sentence:"ここでタバコを吸わないでください。",translation:"Xin đừng hút thuốc ở đây."},{sentence:"写真を撮らないでください。",translation:"Xin đừng chụp ảnh."},{sentence:"心配しないでください。",translation:"Xin đừng lo lắng."},{sentence:"ドアを閉めないでください。",translation:"Xin đừng đóng cửa."}],note:"Vないで (bỏ ください) dùng khi thân mật hoặc ra lệnh nhẹ: 走らないで (đừng chạy).",dialogue:{title:"Đề nghị trong bệnh viện",lines:[{speaker:"Y tá",text:"この部屋では携帯電話を使わないでください。",translation:"Xin đừng dùng điện thoại trong phòng này."},{speaker:"Bệnh nhân",text:"わかりました。食事はしてもいいですか。",translation:"Tôi hiểu. Tôi có thể ăn không?"},{speaker:"Y tá",text:"今は食べないでください。検査の前ですから。",translation:"Bây giờ xin đừng ăn. Vì trước khi xét nghiệm."}]},commonMistake:{wrong:"使わなくてください。",correct:"使わないでください。",why:"Phủ định yêu cầu là Vないでください (dùng ない-form + でください). Không nhầm với Vなくてもいいです (không cần làm)."},related:["minna-14:Vてください","minna-15:Vてはいけません"],kitsuPrompt:"Đóng vai người hướng dẫn ở bảo tàng/thư viện, yêu cầu tôi không làm 5 việc bằng Vないでください."},{pattern:"Vなければなりません",meaning:"phải làm V (nghĩa vụ)",priority:"core",explanation:'ない-form → なければ + なりません = "phải làm". Cấu trúc dài, trong hội thoại thường rút gọn thành Vなきゃ hoặc Vなければ。 (bỏ なりません).',examples:[{sentence:"毎日薬を飲まなければなりません。",translation:"Tôi phải uống thuốc mỗi ngày."},{sentence:"明日までにレポートを出さなければなりません。",translation:"Tôi phải nộp báo cáo trước ngày mai."},{sentence:"早く起きなければなりません。",translation:"Tôi phải dậy sớm."},{sentence:"宿題をしなきゃ。",translation:"Phải làm bài tập thôi. (thân mật)"}],note:"Dạng thân mật: なければ → なきゃ hoặc なくちゃ. Ví dụ: 行かなきゃ (phải đi thôi).",dialogue:{title:"Deadline công việc",lines:[{speaker:"A",text:"今日残業しますか。",translation:"Hôm nay bạn làm thêm giờ không?"},{speaker:"B",text:"はい、明日の朝までにこの報告書を提出しなければなりません。",translation:"Có, tôi phải nộp bản báo cáo này trước sáng mai."},{speaker:"A",text:"大変ですね。頑張って！",translation:"Vất vả nhỉ. Cố lên!"}]},commonMistake:{wrong:"行かなければいけません vs 行かなければなりません",correct:"行かなければなりません (sách giáo khoa) = 行かなければいけません (tự nhiên hơn trong hội thoại)",why:"Cả hai đúng. なりません phổ biến trong văn viết/sách GK. いけません tự nhiên hơn trong hội thoại. なきゃ là dạng thân mật nhất."},related:["minna-17:Vなくてもいいです","minna-15:Vてもいいですか"],kitsuPrompt:"Hỏi tôi về quy định ở trường/công ty, tôi trả lời với Vなければなりません."},{pattern:"Vなくてもいいです",meaning:"không cần làm cũng được",priority:"core",explanation:"ない-form → なくて + もいいです = không cần thiết phải làm. Phủ định của Vなければなりません. Dùng để cho phép ai không làm việc gì.",examples:[{sentence:"明日は来なくてもいいですよ。",translation:"Ngày mai bạn không cần đến cũng được đấy."},{sentence:"全部食べなくてもいいです。",translation:"Không cần ăn hết cũng được."},{sentence:"スーツを着なくてもいいですか。",translation:"Tôi không cần mặc suit được không?"},{sentence:"急がなくてもいいですよ。",translation:"Bạn không cần vội đâu."}],note:"なくてもいい = không cần; なくていい (bỏ も) cũng đúng nhưng ít trang trọng hơn.",dialogue:{title:"Trước ngày nghỉ",lines:[{speaker:"Sếp",text:"明日は休みだから、スーツを着なくてもいいですよ。",translation:"Ngày mai là ngày nghỉ nên bạn không cần mặc suit đâu."},{speaker:"NV",text:"えっ、本当ですか。じゃあ、早く来なくてもいいですか。",translation:"Ồ thật à. Vậy tôi không cần đến sớm không?"},{speaker:"Sếp",text:"そうですね、でも10時までには来てください。",translation:"Ừ, nhưng hãy đến trước 10 giờ nhé."}]},commonMistake:{wrong:"Vなくてもいいです vs Vなければなりません (nhầm hướng)",correct:"来なくてもいいです = không cần đến. 来なければなりません = phải đến.",why:"Hai cấu trúc đối lập nhau: なくてもいい = cho phép không làm. なければならない = bắt buộc phải làm. Học song song để không nhầm."},related:["minna-17:Vなければなりません","minna-15:Vてもいいですか"],kitsuPrompt:"Đóng vai sếp, giải phóng tôi khỏi 5 nghĩa vụ bằng Vなくてもいいです."},{pattern:"Nまでに",meaning:"trước thời hạn N / không muộn hơn N",priority:"common",explanation:'まで = "đến tận/cho đến"; までに = "trước (deadline)". Phân biệt: まで (đến tận N, dùng với hành động liên tục) vs までに (trước hạn N, dùng với hành động hoàn thành).',examples:[{sentence:"5時までに帰ってください。",translation:"Xin hãy về trước 5 giờ."},{sentence:"来週の月曜日までにレポートを出してください。",translation:"Hãy nộp báo cáo trước thứ Hai tuần sau."},{sentence:"試験が始まるまでに着いてください。",translation:"Hãy đến trước khi thi bắt đầu."},{sentence:"5時まで図書館で勉強します。",translation:"Tôi học ở thư viện đến tận 5 giờ. (không phải までに)"}],note:"まで (cho đến, liên tục): 5時まで勉強する. までに (trước hạn, kết thúc): 5時までに終わらせる.",dialogue:{title:"Deadline nộp bài",lines:[{speaker:"Thầy",text:"レポートは金曜日までに提出してください。",translation:"Hãy nộp báo cáo trước thứ Sáu."},{speaker:"SV",text:"先生、土曜日までに出してもいいですか。",translation:"Thầy ơi, con nộp đến thứ Bảy có được không?"},{speaker:"Thầy",text:"だめです。金曜日の5時までに必ず出してください。",translation:"Không được. Nhất định nộp trước 5 giờ thứ Sáu."}]},commonMistake:{wrong:"5時まで提出してください。(khi muốn nói deadline là 5 giờ)",correct:"5時までに提出してください。",why:"まで = liên tục đến 5 giờ (ví dụ: làm việc đến 5 giờ). までに = phải hoàn thành trước 5 giờ (deadline). Thêm に là bắt buộc khi nói deadline."},related:["minna-4:NからNまで","minna-17:Vなければなりません"],kitsuPrompt:"Hỏi tôi deadline của 3 việc khác nhau, tôi trả lời với Nまでに."}]},{bai:18,level:"N5",kanji:"能",reading:"のうりょく",romaji:"Nouryoku",titleVi:"Khả năng & sở thích",titleJp:"可能と趣味",descVi:"Dùng こと danh từ hóa — nói có thể làm và sở thích là...",selfCheckGoals:["Nói khả năng bằng Vることができます.","Danh từ hóa động từ với こと để nói sở thích/ước mơ.",'Nói "trước khi làm" với Vるまえに đúng dạng động từ.',"Phân biệt Vるまえに vs Nのまえに."],readingPassage:{title:"私の趣味と習慣",titleVi:"Sở thích và thói quen của tôi",japanese:"私の趣味は料理をすることです。夕ご飯を作るまえに、スーパーへ買い物に行きます。料理のまえに手を洗います。私は日本料理を作ることができます。でも、まだラーメンを上手に作ることができません。",vietnamese:"Sở thích của tôi là nấu ăn. Trước khi nấu bữa tối, tôi đi siêu thị mua đồ. Trước khi nấu ăn tôi rửa tay. Tôi có thể nấu ẩm thực Nhật. Nhưng vẫn chưa nấu được mỳ ramen ngon.",highlights:[{excerpt:"趣味は料理をすることです",label:"NはVることです"},{excerpt:"夕ご飯を作るまえに",label:"Vるまえに"},{excerpt:"料理のまえに手を洗います",label:"Nのまえに"},{excerpt:"日本料理を作ることができます",label:"Vることができます"},{excerpt:"ラーメンを上手に作ることができません",label:"Vることができません"}],questions:[{q:"この人の趣味は何ですか。",options:["スポーツ","料理","音楽","読書"],answer:1},{q:"この人は何ができませんか。",options:["日本料理を作ること","買い物に行くこと","ラーメンを上手に作ること","手を洗うこと"],answer:2}]},patterns:[{pattern:"Vることができます",meaning:"có thể làm V (khả năng)",priority:"core",explanation:"Cấu trúc diễn tả khả năng: động từ dạng từ điển (る-form) + ことができます. Đây là cách nói khả năng dài hơn nhưng lịch sự hơn dạng V可能形 (học ở bài 27).",examples:[{sentence:"私は日本語を話すことができます。",translation:"Tôi có thể nói tiếng Nhật."},{sentence:"ここで泳ぐことができますか。",translation:"Có thể bơi ở đây không?"},{sentence:"漢字を書くことができません。",translation:"Tôi không thể viết chữ Hán."},{sentence:"子どものころ、ピアノを弾くことができました。",translation:"Hồi nhỏ tôi có thể chơi đàn piano."}],note:"Ngắn hơn: Vることができる → V可能形 (話せる). Cả hai đúng; ことができる lịch sự và rõ nghĩa hơn.",dialogue:{title:"Phỏng vấn xin việc",lines:[{speaker:"HRm",text:"どんな言語を話すことができますか。",translation:"Bạn có thể nói ngôn ngữ gì?"},{speaker:"Ứng viên",text:"日本語と英語を話すことができます。中国語も少し話すことができます。",translation:"Tôi có thể nói tiếng Nhật và tiếng Anh. Tiếng Trung thì được một chút."},{speaker:"HR",text:"プログラミングはできますか。",translation:"Bạn có biết lập trình không?"}]},commonMistake:{wrong:"日本語を話せることができます。",correct:"日本語を話すことができます。/ 日本語が話せます。",why:"Không kết hợp V可能形 (話せる) và ことができる cùng lúc — chọn một trong hai cách nói."},related:["minna-9:NはNが上手です","minna-27:V可能形"],kitsuPrompt:"Hỏi tôi về 5 kỹ năng (ngôn ngữ, nấu ăn, thể thao...) và tôi trả lời với Vることができます/できません."},{pattern:"NはVることです (sở thích)",meaning:"sở thích / nghề là (việc) làm V",priority:"core",explanation:"こと biến động từ thành danh từ. Cấu trúc: Chủ đề (は) + (N/Vること) + です. Thường dùng để nói về sở thích, nghề nghiệp, mục tiêu.",examples:[{sentence:"私の趣味は写真を撮ることです。",translation:"Sở thích của tôi là chụp ảnh."},{sentence:"私の夢は日本に住むことです。",translation:"Ước mơ của tôi là sống ở Nhật."},{sentence:"仕事は学生に日本語を教えることです。",translation:"Công việc của tôi là dạy tiếng Nhật cho học sinh."},{sentence:"好きなことは旅行することです。",translation:"Thứ tôi thích là đi du lịch."}],note:'Vること = danh từ hóa động từ. Khác với Vのこと (về chuyện V) — の có thêm sắc thái "về, liên quan đến".',dialogue:{title:"Kể về sở thích",lines:[{speaker:"A",text:"趣味は何ですか。",translation:"Sở thích của bạn là gì?"},{speaker:"B",text:"私の趣味は写真を撮ることと、料理することです。",translation:"Sở thích của tôi là chụp ảnh và nấu ăn."},{speaker:"A",text:"夢は何ですか。",translation:"Ước mơ của bạn là gì?"},{speaker:"B",text:"夢はプロカメラマンになることです。",translation:"Ước mơ là trở thành nhiếp ảnh gia chuyên nghiệp."}]},commonMistake:{wrong:"趣味は写真を撮るです。",correct:"趣味は写真を撮ることです。",why:"Không thể dùng động từ trực tiếp làm vị ngữ danh từ. Cần こと để danh từ hóa: 撮ること (việc chụp ảnh)."},related:["minna-18:Vることができます","minna-26:Vること（N3）"],kitsuPrompt:"Hỏi tôi sở thích, ước mơ và mục tiêu bằng 〜は何ですか, tôi trả lời với Vることです."},{pattern:"Vるまえに",meaning:"trước khi làm V",priority:"core",explanation:'Động từ dạng từ điển (る-form) + まえに = "trước khi làm". Động từ ở dạng hiện tại dù hành động chưa xảy ra — đây là đặc điểm quan trọng.',examples:[{sentence:"寝るまえに歯を磨きます。",translation:"Trước khi ngủ tôi đánh răng."},{sentence:"出かけるまえに、天気を確認します。",translation:"Trước khi ra ngoài, tôi kiểm tra thời tiết."},{sentence:"食事するまえに手を洗いましょう。",translation:"Hãy rửa tay trước khi ăn."},{sentence:"旅行に行くまえに、パスポートを確認してください。",translation:"Trước khi đi du lịch, hãy kiểm tra hộ chiếu."}],note:"Luôn dùng Vる (dạng từ điển) + まえに, dù câu là quá khứ: 寝るまえに食べました (đã ăn trước khi ngủ).",dialogue:{title:"Chuẩn bị đi du lịch",lines:[{speaker:"A",text:"旅行前に何を準備しますか。",translation:"Trước khi đi du lịch bạn chuẩn bị gì?"},{speaker:"B",text:"出発するまえに、パスポートと保険を確認します。",translation:"Trước khi khởi hành, tôi kiểm tra hộ chiếu và bảo hiểm."},{speaker:"A",text:"ホテルは予約しましたか。",translation:"Bạn đã đặt khách sạn chưa?"}]},commonMistake:{wrong:"寝たまえに歯を磨きます。",correct:"寝るまえに歯を磨きます。",why:"まえに luôn dùng Vる (từ điển/hiện tại), không dùng Vた (quá khứ). Hành động chưa xảy ra nên dùng dạng hiện tại."},related:["minna-16:Vてから","minna-18:Nのまえに"],kitsuPrompt:"Hỏi tôi làm gì trước 3 việc quan trọng (ngủ, ăn, đi làm), tôi trả lời với Vるまえに."},{pattern:"Nのまえに",meaning:"trước N (danh từ)",priority:"common",explanation:'Danh từ + のまえに = "trước N". Dùng khi N là danh từ chỉ sự kiện, thời điểm. Cấu trúc đối: Nのあとで (sau N).',examples:[{sentence:"食事のまえに手を洗います。",translation:"Trước bữa ăn tôi rửa tay."},{sentence:"試験のまえに、よく勉強しました。",translation:"Trước kỳ thi, tôi đã học kỹ."},{sentence:"会議のまえにコピーを取ってください。",translation:"Trước cuộc họp, hãy photo tài liệu."},{sentence:"出発のまえに、荷物を確認しました。",translation:"Trước khi khởi hành, tôi đã kiểm tra hành lý."}],note:"Nのまえに (trước N danh từ) vs Vるまえに (trước khi V động từ) — logic giống nhau, chỉ khác dạng từ đứng trước.",dialogue:{title:"Chuẩn bị trước kỳ thi",lines:[{speaker:"A",text:"試験のまえに何をしますか。",translation:"Trước kỳ thi bạn làm gì?"},{speaker:"B",text:"試験のまえに必ず過去問を解きます。それと授業のノートを復習します。",translation:"Trước kỳ thi tôi nhất định làm đề cũ. Và ôn lại vở ghi."},{speaker:"A",text:"いい方法ですね。",translation:"Phương pháp hay đấy."}]},commonMistake:{wrong:"試験まえに勉強しました。",correct:"試験のまえに勉強しました。",why:"Khi N là danh từ sự kiện (試験, 会議...) phải có の: Nのまえに. Không bỏ の."},related:["minna-18:Vるまえに","minna-34:Nのあとで"],kitsuPrompt:"Hỏi tôi làm gì trước 3 sự kiện quan trọng (bữa ăn, họp, ngủ), tôi trả lời với Nのまえに."}]},{bai:19,level:"N5",kanji:"経",reading:"けいけん",romaji:"Keiken",titleVi:"Kinh nghiệm & thay đổi",titleJp:"経験と並列",descVi:"Nói đã từng trải qua (〜たことがある) và trở nên thế nào (〜なります).",selfCheckGoals:["Kể kinh nghiệm cuộc đời bằng Vたことがあります / ありません.","Liệt kê nhiều hoạt động một cách tự nhiên với V1たりV2たりします.","Mô tả sự thay đổi trạng thái bằng くなります (い-adj) và になります (な-adj/N).","Phân biệt になる (tự thay đổi) vs にする (chủ động làm cho thay đổi)."],readingPassage:{title:"日本での経験",titleVi:"Những trải nghiệm ở Nhật",japanese:"マリアさんは日本へ行ったことがあります。京都でお寺を見たり、温泉に入ったりしました。日本に来てから、日本語がだいぶ上手になりました。料理も好きになりました。最初は漢字が難しくて大変でしたが、今は読めるようになりました。",vietnamese:"Chị Maria đã từng đến Nhật. Ở Kyoto đã xem chùa, ngâm suối nước nóng. Từ khi đến Nhật, tiếng Nhật đã giỏi lên nhiều. Cũng đã thích nấu ăn hơn. Lúc đầu chữ kanji khó và vất vả nhưng bây giờ đã đọc được rồi.",highlights:[{excerpt:"日本へ行ったことがあります",label:"Vたことがあります"},{excerpt:"お寺を見たり、温泉に入ったりしました",label:"V1たりV2たりします"},{excerpt:"日本語がだいぶ上手になりました",label:"Aくなります"},{excerpt:"料理も好きになりました",label:"NAになります"}],questions:[{q:"マリアさんは日本で何をしましたか。（２つ）",options:["買い物と料理","お寺見学と温泉","映画と観劇","勉強と仕事"],answer:1},{q:"マリアさんの日本語は今どうですか。",options:["まだ上手じゃない","だいぶ上手になった","全然わからない","少し難しい"],answer:1}]},patterns:[{pattern:"Vたことがあります",meaning:"đã từng làm V (kinh nghiệm)",priority:"core",explanation:"た-form + ことがあります = diễn tả kinh nghiệm đã từng có trong cuộc đời. Phủ định: Vたことがありません / Vたことはありません.",examples:[{sentence:"日本へ行ったことがあります。",translation:"Tôi đã từng đến Nhật."},{sentence:"富士山に登ったことがありますか。",translation:"Bạn đã từng leo núi Fuji chưa?"},{sentence:"生ものを食べたことがありません。",translation:"Tôi chưa từng ăn đồ sống."},{sentence:"外国に住んだことがあります。",translation:"Tôi đã từng sống ở nước ngoài."}],note:"Hỏi kinh nghiệm: 〜たことがありますか (Bạn đã từng ~ chưa?). Trả lời: はい、あります / いいえ、ありません.",dialogue:{title:"Nói chuyện về trải nghiệm du lịch",lines:[{speaker:"A",text:"外国へ行ったことがありますか。",translation:"Bạn đã từng đi nước ngoài chưa?"},{speaker:"B",text:"はい、タイへ行ったことがあります。食べ物がおいしかったです。",translation:"Rồi, tôi đã từng đến Thái Lan. Đồ ăn rất ngon."},{speaker:"A",text:"いいですね！日本へ行ったことは？",translation:"Tốt quá! Còn Nhật Bản thì sao?"}]},commonMistake:{wrong:"日本へ行くことがあります。(muốn nói đã từng đi)",correct:"日本へ行ったことがあります。",why:'Phải dùng た-form (quá khứ) trước ことがあります để diễn tả kinh nghiệm. Vることがあります có nghĩa khác: "đôi khi có lúc làm V".'},related:["minna-14:Vたことがあります","minna-19:V1たりV2たりします","minna-21:〜と思います"],kitsuPrompt:"Hỏi tôi về những trải nghiệm du lịch hay ẩm thực tôi đã từng có. Tôi sẽ trả lời bằng Vたことがあります."},{pattern:"V1たりV2たりします",meaning:"làm khi thì V1 khi thì V2 (liệt kê hoạt động)",priority:"core",explanation:'た-form + り liệt kê các hoạt động không đầy đủ (còn nhiều việc khác). Cuối câu dùng します/しました. Ngụ ý "vừa cái này vừa cái kia (và những thứ khác)".',examples:[{sentence:"休みの日は本を読んだり、音楽を聞いたりします。",translation:"Ngày nghỉ tôi đọc sách, nghe nhạc (và các thứ khác)."},{sentence:"子どもたちは公園で走ったり、遊んだりしています。",translation:"Các em đang chạy và chơi ở công viên."},{sentence:"旅行で写真を撮ったり、ショッピングをしたりしました。",translation:"Trong chuyến du lịch tôi đã chụp ảnh, mua sắm (và nhiều thứ khác)."}],note:"Luôn phải có ít nhất 2 động từ + り, và kết thúc bằng します/しました. Không dùng chỉ 1 動詞たり.",dialogue:{title:"Hỏi cuối tuần làm gì",lines:[{speaker:"A",text:"週末は何をしましたか。",translation:"Cuối tuần bạn làm gì vậy?"},{speaker:"B",text:"友だちと映画を見たり、カラオケをしたりしました。楽しかったです。",translation:"Tôi xem phim, hát karaoke với bạn bè. Vui lắm."},{speaker:"A",text:"いいなあ。私はずっと家で勉強したり、寝たりしていました。",translation:"Thích quá. Tôi thì ở nhà học bài với ngủ suốt."}]},commonMistake:{wrong:"映画を見たり、音楽を聞きます。(quên たり ở động từ thứ hai và quên します ở cuối)",correct:"映画を見たり、音楽を聞いたりします。",why:"Cả hai động từ đều phải chia dạng たり, và câu phải kết thúc bằng します/しました. Thiếu một trong hai sẽ làm câu sai ngữ pháp."},related:["minna-19:Vたことがあります","minna-14:V1たりV2たりします"],kitsuPrompt:"Hỏi tôi thường làm gì vào cuối tuần hoặc kỳ nghỉ. Tôi sẽ dùng V1たりV2たりします để kể nhiều hoạt động."},{pattern:"Aくなります／NAになります",meaning:"trở nên ~ (thay đổi trạng thái)",priority:"core",explanation:"なる (trở thành/trở nên) chỉ sự thay đổi. い-adj → くなる; な-adj → になる. Dùng để nói về sự biến đổi dần dần hoặc đột ngột.",examples:[{sentence:"日本語が上手になりました。",translation:"Tiếng Nhật của tôi đã giỏi lên."},{sentence:"秋になって、寒くなりました。",translation:"Vào mùa thu, trời trở nên lạnh."},{sentence:"田中さんは有名になりました。",translation:"Anh Tanaka đã trở nên nổi tiếng."},{sentence:"子どもが大きくなりましたね。",translation:"Con bạn lớn rồi nhỉ."}],note:"い-adj + くなる: 寒い→寒くなる, 大きい→大きくなる. な-adj/N + になる: 元気→元気になる, 医者→医者になる.",dialogue:{title:"Nhận xét về sự tiến bộ",lines:[{speaker:"先生",text:"最近、日本語がとても上手になりましたね。",translation:"Dạo này tiếng Nhật của bạn giỏi lên nhiều nhỉ."},{speaker:"B",text:"ありがとうございます。毎日練習したら、少し上手になりました。",translation:"Cảm ơn thầy. Nhờ luyện tập mỗi ngày mà giỏi lên một chút."},{speaker:"先生",text:"これからも頑張れば、もっと上手になりますよ。",translation:"Nếu tiếp tục cố gắng, bạn sẽ còn giỏi hơn nữa đấy."}]},commonMistake:{wrong:"元気くなりました。(áp dụng くなる cho な-adj)",correct:"元気になりました。",why:"くなる chỉ dùng cho い-adj (寒い→寒くなる). な-adj và danh từ dùng になる (元気→元気になる, 医者→医者になる). Phải phân biệt loại tính từ."},related:["minna-19:Nになります","minna-12:AくてB","minna-9:Aくするします"],kitsuPrompt:"Hỏi tôi về những thay đổi gần đây trong cuộc sống — thời tiết, sức khỏe, kỹ năng. Tôi sẽ dùng くなります hoặc になります."},{pattern:"Nになります",meaning:"trở thành N (danh từ)",priority:"common",explanation:"Danh từ + になります = trở thành một vai trò, nghề nghiệp, trạng thái mới. Thể hiện mục tiêu hoặc sự thay đổi.",examples:[{sentence:"将来、医者になりたいです。",translation:"Tôi muốn trở thành bác sĩ trong tương lai."},{sentence:"田中さんは部長になりました。",translation:"Anh Tanaka đã trở thành trưởng phòng."},{sentence:"来月から、新しい仕事になります。",translation:"Từ tháng sau, tôi sẽ chuyển sang công việc mới."},{sentence:"春になりました。",translation:"Mùa xuân đã đến."}],note:"になる (trở thành — có chủ ý hoặc biến đổi) khác にする (làm cho trở thành — chủ động quyết định): 先生になる vs 先生にする.",dialogue:{title:"Nói về ước mơ tương lai",lines:[{speaker:"A",text:"将来、何になりたいですか。",translation:"Bạn muốn trở thành gì trong tương lai?"},{speaker:"B",text:"日本語の先生になりたいです。子どもに日本語を教えたいです。",translation:"Tôi muốn trở thành giáo viên tiếng Nhật. Muốn dạy tiếng Nhật cho trẻ em."},{speaker:"A",text:"すてきですね。きっとなれますよ。",translation:"Tuyệt quá nhỉ. Chắc chắn bạn sẽ làm được thôi."}]},commonMistake:{wrong:"先生になりたいです。→ 先生にしたいです。(nhầm にする cho bản thân)",correct:"先生になりたいです。",why:"になる = tự thân trở thành (mục tiêu cá nhân). にする = chủ động biến cái gì/ai thành cái gì. Không thể dùng にする cho ước mơ của bản thân."},related:["minna-19:Aくなります／NAになります","minna-13:VたいNです"],kitsuPrompt:"Hỏi tôi muốn trở thành gì trong tương lai và tại sao. Tôi sẽ trả lời bằng Nになりたいです."}]},{bai:20,level:"N5",kanji:"常",reading:"ふつう",romaji:"Futsuu",titleVi:"Thể thông thường",titleJp:"普通形",descVi:"Dùng thể phổ thông để nói chuyện thân mật tự nhiên với bạn bè.",selfCheckGoals:["Chia đủ 4 dạng thể thông thường: hiện tại (+/−) và quá khứ (+/−) cho V, い-adj, な-adj, N.","Dùng うん / ううん thay はい / いいえ trong hội thoại thân mật.","Thêm よ và ね đúng chỗ để nghe tự nhiên hơn.","Dùng Vないと như rút gọn tự nhiên của Vなければなりません."],readingPassage:{title:"友達との会話",titleVi:"Nói chuyện với bạn",japanese:"「明日のパーティー、来る？」「うん、行くよ。何を持って行けばいい？」「飲み物を持ってきてくれると嬉しいな。」「わかった。ジュースを買って行く。遅れないと思うけど、もし遅れたら先に始めてて。」「大丈夫、待ってるよ。」",vietnamese:'"Bữa tiệc ngày mai, bạn đến không?" "Ừ, mình đến. Nên mang gì đến?" "Nếu mang đồ uống thì vui lắm." "Hiểu rồi. Mình sẽ mua nước ép đến. Mình nghĩ không trễ đâu nhưng nếu trễ thì cứ bắt đầu trước nhé." "Không sao, tao đợi mày."',highlights:[{excerpt:"来る？",label:"Casual form (plain question)"},{excerpt:"行くよ",label:"Plain form + よ"},{excerpt:"遅れないと思うけど",label:"〜と思います / Vないと"}],questions:[{q:"この人は明日パーティーに行きますか。",options:["行かない","行く","まだわからない","仕事がある"],answer:1},{q:"何を持って行きますか。",options:["食べ物","お菓子","ジュース","ケーキ"],answer:2}]},patterns:[{pattern:"V/A/NAの普通形",meaning:"thể thông thường (chia đủ 4 dạng)",priority:"core",explanation:"Thể thông thường (普通形) là nền tảng để ghép vào nhiều cấu trúc ngữ pháp. 4 dạng: hiện tại khẳng định, hiện tại phủ định, quá khứ khẳng định, quá khứ phủ định.",examples:[{sentence:"行く／行かない／行った／行かなかった",translation:"đi / không đi / đã đi / đã không đi"},{sentence:"寒い／寒くない／寒かった／寒くなかった",translation:"lạnh / không lạnh / đã lạnh / đã không lạnh"},{sentence:"元気だ／元気じゃない／元気だった／元気じゃなかった",translation:"khỏe / không khỏe / đã khỏe / đã không khỏe"},{sentence:"学生だ／学生じゃない／学生だった／学生じゃなかった",translation:"là SV / không phải SV / đã là SV / đã không phải SV"}],note:"Thể thông thường = cơ sở để xây dựng: 〜と思います, 〜んです, 〜かもしれない, 〜らしい và nhiều cấu trúc N3-N2.",dialogue:{title:"Nói chuyện thân mật với bạn",lines:[{speaker:"A",text:"昨日のパーティー、楽しかった？",translation:"Bữa tiệc hôm qua vui không?"},{speaker:"B",text:"うん、すごく楽しかった！田中さんも来てたよ。",translation:"Ừ, vui lắm! Tanaka cũng có mặt đấy."},{speaker:"A",text:"えっ、知らなかった。もっと早く言ってよ。",translation:"Ủa, tôi không biết. Nói sớm hơn chứ!"}]},commonMistake:{wrong:"元気じゃないだった。(sai chia phủ định quá khứ của な-adj)",correct:"元気じゃなかった。",why:"Phủ định quá khứ của な-adj: じゃない → じゃなかった (không thêm だ). Tương tự: 静かじゃなかった, 好きじゃなかった."},related:["minna-21:〜と思います","minna-21:〜と言いました","minna-20:Casual conversation markers"],kitsuPrompt:"Hãy nói chuyện với tôi như bạn thân — dùng thể thông thường, うん/ううん, và よ/ね. Tôi sẽ cố gắng trả lời tự nhiên."},{pattern:"Casual conversation markers",meaning:"hội thoại thân mật — うん、ううん、〜よ、〜ね",priority:"core",explanation:"Trong hội thoại thân mật, người Nhật thay はい→うん (ừ), いいえ→ううん (không), thêm よ (nhấn mạnh), ね (cầu đồng thuận) vào cuối câu.",examples:[{sentence:"明日、暇？— うん、暇だよ。",translation:"Ngày mai rảnh không? — Ừ, rảnh đấy."},{sentence:"もう食べた？— ううん、まだ。",translation:"Ăn chưa? — Chưa."},{sentence:"これ、おいしいね！",translation:"Cái này ngon nhỉ!"},{sentence:"早く行かないと！",translation:"Phải đi nhanh thôi!"}],note:"よ = khẳng định/nhấn mạnh thông tin mới; ね = xác nhận đồng thuận (cả hai cùng biết/cùng cảm nhận).",dialogue:{title:"Hẹn đi ăn cùng nhau",lines:[{speaker:"A",text:"ねえ、お昼、一緒に食べない？",translation:"Này, trưa ăn cùng nhau không?"},{speaker:"B",text:"うん、いいよ。どこ行く？",translation:"Ừ, được đấy. Đi đâu?"},{speaker:"A",text:"駅の近くにおいしいラーメン屋があるよ。安いしね。",translation:"Gần ga có tiệm mì ramen ngon đấy. Lại còn rẻ nữa."}]},commonMistake:{wrong:"うん、そうですよ。(pha trộn thể thân mật và lịch sự)",correct:"うん、そうだよ。(thân mật) hoặc はい、そうですよ。(lịch sự)",why:"うん là thân mật, phải đi kèm với thể thông thường (だよ, じゃない, など). Đừng pha trộn うん với ます/です trong cùng một câu."},related:["minna-20:V/A/NAの普通形","minna-20:Vないと (ngắn)"],kitsuPrompt:"Nói chuyện bạn bè với tôi về kế hoạch cuối tuần. Dùng うん/ううん, よ, ね tự nhiên."},{pattern:"Vないと (ngắn)",meaning:"phải làm (rút gọn)",priority:"common",explanation:'Rút gọn của Vなければなりません. Vないと (nếu không làm thì không được) → ngụ ý "phải làm". Cuối thường để lửng 〜 hoặc thêm いけない.',examples:[{sentence:"早く帰らないと。",translation:"Phải về sớm thôi. (ngụ ý: không thì trễ)"},{sentence:"宿題、やらないといけない。",translation:"Phải làm bài tập thôi."},{sentence:"もう寝ないと。",translation:"Phải ngủ thôi."},{sentence:"ダイエットしないとなあ。",translation:"Phải ăn kiêng thôi nhỉ..."}],note:"Vないと (bỏ いけない) là dạng rất thông dụng trong khẩu ngữ. Bạn sẽ nghe rất nhiều trong phim, anime.",dialogue:{title:"Bận rộn trước kỳ thi",lines:[{speaker:"A",text:"明日、テストだよ。勉強した？",translation:"Ngày mai thi rồi. Học chưa?"},{speaker:"B",text:"ううん、まだ。今夜ちゃんとやらないと。",translation:"Chưa. Tối nay phải học nghiêm túc thôi."},{speaker:"A",text:"早く寝ないと体がもたないよ。",translation:"Phải ngủ sớm thôi, không thì cơ thể không chịu được đâu."}]},commonMistake:{wrong:"行かないとです。(thêm です vào dạng rút gọn thân mật)",correct:"行かないと。(để lửng) hoặc 行かなければなりません。(lịch sự)",why:"Vないと là dạng thân mật, không thêm です. Nếu muốn nói lịch sự thì phải dùng đầy đủ: Vなければなりません hoặc Vないといけません."},related:["minna-17:Vなければなりません","minna-20:Casual conversation markers"],kitsuPrompt:"Hỏi tôi điều gì đang áp lực hoặc việc gì tôi phải làm hôm nay. Tôi sẽ dùng Vないと để nói."}]},{bai:21,level:"N5",kanji:"思",reading:"おもう",romaji:"Omou",titleVi:"Suy nghĩ & trích dẫn",titleJp:"思考と引用",descVi:'Nói "tôi nghĩ rằng..." với 〜と思います và dẫn lời ai đó đã nói.',selfCheckGoals:["Dùng thể thông thường + と思います để đưa ra ý kiến cá nhân.","Dẫn lời ai đó bằng 〜と言いました (quá khứ) và 〜と言っています (hiện tại).","Phỏng đoán nhẹ nhàng với でしょう và phân biệt giọng lên (hỏi) vs giọng xuống (khẳng định).","Nêu chủ đề bằng Nについて đi với các động từ nói/viết/suy nghĩ."],readingPassage:{title:"ニュースを見て",titleVi:"Xem tin tức",japanese:"先生は「明日は雨が降るでしょう」と言いました。天気予報について話しています。私は明日は雨じゃないと思います。でも、傘を持って行ったほうがいいでしょう。環境問題について、いろいろな意見があると思います。",vietnamese:'Giáo viên nói "Ngày mai có thể trời sẽ mưa". Đang nói về dự báo thời tiết. Tôi nghĩ ngày mai không mưa. Nhưng tốt hơn nên mang ô đi. Tôi nghĩ về vấn đề môi trường có nhiều ý kiến khác nhau.',highlights:[{excerpt:"明日は雨が降るでしょう",label:"〜でしょう"},{excerpt:"と言いました",label:"〜と言いました"},{excerpt:"天気予報について",label:"Nについて"},{excerpt:"雨じゃないと思います",label:"〜と思います"}],questions:[{q:"先生は何と言いましたか。",options:["今日は晴れ","明日は雨が降るでしょう","明日は晴れでしょう","台風が来る"],answer:1},{q:"この人は明日の天気についてどう思いますか。",options:["雨だと思う","雨じゃないと思う","雪だと思う","わからない"],answer:1}]},patterns:[{pattern:"〜と思います",meaning:"tôi nghĩ rằng ~",priority:"core",explanation:"Dùng thể thông thường (普通形) + と思います để diễn tả ý kiến, phỏng đoán. Không dùng dạng lịch sự trước と: sai: 寒いですと思います → đúng: 寒いと思います.",examples:[{sentence:"あした雨が降ると思います。",translation:"Tôi nghĩ ngày mai trời sẽ mưa."},{sentence:"田中さんはもう帰ったと思います。",translation:"Tôi nghĩ anh Tanaka đã về rồi."},{sentence:"この映画はおもしろいと思います。",translation:"Tôi nghĩ bộ phim này thú vị."},{sentence:"日本語は難しいと思いますか。",translation:"Bạn có nghĩ tiếng Nhật khó không?"}],note:"と思っています (đang nghĩ = quan điểm kéo dài) vs と思います (nghĩ ngay lúc nói). Cả hai thường dùng được.",dialogue:{title:"Thảo luận về bộ phim",lines:[{speaker:"A",text:"あの映画、おもしろいと思いますか。",translation:"Bạn nghĩ bộ phim đó thú vị không?"},{speaker:"B",text:"うーん、私はちょっと長いと思います。でも、映像はきれいだと思います。",translation:"Ừm, tôi nghĩ hơi dài. Nhưng hình ảnh thì tôi nghĩ đẹp."},{speaker:"A",text:"そうですね。主人公の演技はすばらしいと思いますよ。",translation:"Đúng nhỉ. Diễn xuất của nhân vật chính tôi nghĩ tuyệt vời đấy."}]},commonMistake:{wrong:"面白いですと思います。(dùng dạng lịch sự trước と)",correct:"面白いと思います。",why:"Trước と思います phải dùng thể thông thường (普通形). い-adj: おもしろい (không có です), な-adj: 便利だ, Danh từ: 学生だ. Đây là lỗi phổ biến nhất của người học N5."},related:["minna-20:V/A/NAの普通形","minna-21:〜でしょう","minna-21:〜と言いました"],kitsuPrompt:"Đưa ra nhận xét về một chủ đề (phim, thức ăn, thời tiết) và hỏi tôi ý kiến. Tôi sẽ trả lời bằng 〜と思います."},{pattern:"〜と言いました",meaning:"nói rằng ~ / bảo rằng ~",priority:"core",explanation:"Dẫn lời nói trực tiếp hoặc gián tiếp: [nội dung] + と言いました. Nội dung dùng thể thông thường. と là dấu hiệu trích dẫn.",examples:[{sentence:"田中さんはあした来ると言いました。",translation:"Anh Tanaka nói (rằng) ngày mai anh sẽ đến."},{sentence:"先生は明日テストがあると言いました。",translation:"Thầy nói ngày mai có bài kiểm tra."},{sentence:"彼女は「疲れた」と言いました。",translation:'Cô ấy nói "Mệt quá".'},{sentence:"何と言いましたか。",translation:"Anh/chị ấy nói gì vậy?"}],note:"Dẫn lời hiện tại: 〜と言っています. Dẫn lời quá khứ: 〜と言いました.",dialogue:{title:"Truyền đạt lại tin tức",lines:[{speaker:"A",text:"田中さんから電話があったよ。",translation:"Vừa có điện thoại của Tanaka đó."},{speaker:"B",text:"え、何と言いましたか。",translation:"Ồ, anh ấy nói gì vậy?"},{speaker:"A",text:"明日のパーティーに行けないと言いました。仕事が忙しいって。",translation:"Anh ấy nói không đến bữa tiệc ngày mai được. Bảo là công việc bận lắm."}]},commonMistake:{wrong:"田中さんは「明日来ます」と言いました。(dùng thể lịch sự trong trích dẫn gián tiếp)",correct:"田中さんは明日来ると言いました。",why:"Khi dẫn lời gián tiếp, nội dung trong と cần dùng thể thông thường. Chỉ dùng dấu「」và thể lịch sự khi trích dẫn trực tiếp nguyên văn."},related:["minna-21:〜と思います","minna-20:V/A/NAの普通形"],kitsuPrompt:"Hỏi tôi ai đó đã nói gì về một tình huống (ví dụ: bạn nói thời tiết thế nào, thầy nói bài thi thế nào). Tôi sẽ dùng 〜と言いました."},{pattern:"〜でしょう",meaning:"có lẽ ~ (phỏng đoán với tự tin)",priority:"common",explanation:'でしょう diễn tả phỏng đoán, suy luận có độ chắc nhất định. Giọng lên ở cuối → câu hỏi "... phải không?". Giọng xuống → khẳng định "hẳn là...".',examples:[{sentence:"あした、雨が降るでしょう。",translation:"Ngày mai có lẽ trời mưa."},{sentence:"田中さんは忙しいでしょう。",translation:"Anh Tanaka chắc là bận."},{sentence:"もう知っているでしょう？",translation:"Bạn đã biết rồi phải không?"},{sentence:"この問題は難しいでしょう。",translation:"Bài này hẳn là khó."}],note:"でしょう (lịch sự) = だろう (thân mật). Trong dự báo thời tiết, でしょう rất phổ biến.",dialogue:{title:"Đoán thời tiết cho chuyến đi",lines:[{speaker:"A",text:"来週、京都に行きます。天気はどうでしょうか。",translation:"Tuần sau tôi đi Kyoto. Thời tiết sẽ thế nào nhỉ?"},{speaker:"B",text:"11月ですから、少し寒いでしょう。でも雨は降らないでしょう。",translation:"Vì là tháng 11 nên có lẽ hơi lạnh. Nhưng chắc không mưa đâu."},{speaker:"A",text:"そうですね。コートを持って行ったほうがいいでしょうね。",translation:"Đúng nhỉ. Có lẽ nên mang áo khoác theo nhỉ."}]},commonMistake:{wrong:"明日は雨でしょうです。(thêm です sau でしょう)",correct:"明日は雨でしょう。",why:"でしょう đã là dạng lịch sự, không thêm です. Tương tự: おいしいでしょう (không phải おいしいですでしょう)."},related:["minna-21:〜と思います","minna-32:〜かもしれません"],kitsuPrompt:"Hỏi tôi phỏng đoán về thời tiết, tình huống, hoặc cảm nghĩ của ai đó. Tôi sẽ trả lời bằng でしょう."},{pattern:"Nについて",meaning:"về N / liên quan đến N",priority:"common",explanation:"について đứng sau danh từ để chỉ chủ đề, nội dung đang nói đến. Dùng với 話す, 書く, 教える, 考える, 知っている, v.v.",examples:[{sentence:"日本の文化について話します。",translation:"Tôi nói về văn hóa Nhật Bản."},{sentence:"日本語の勉強方法について教えてください。",translation:"Hãy cho tôi biết về phương pháp học tiếng Nhật."},{sentence:"環境問題について考えています。",translation:"Tôi đang suy nghĩ về vấn đề môi trường."},{sentence:"何についてレポートを書きましたか。",translation:"Bạn đã viết báo cáo về chủ đề gì?"}],note:'について vs に関して(にかんして): cả hai đều là "về". に関して trang trọng hơn, dùng trong văn viết.',dialogue:{title:"Chuẩn bị bài thuyết trình",lines:[{speaker:"A",text:"レポートは何について書きますか。",translation:"Bạn viết báo cáo về chủ đề gì?"},{speaker:"B",text:"日本の伝統的な祭りについて書こうと思っています。",translation:"Tôi đang nghĩ sẽ viết về lễ hội truyền thống Nhật Bản."},{speaker:"A",text:"おもしろそうですね。どんなお祭りについて調べましたか。",translation:"Nghe hay đấy nhỉ. Bạn đã tìm hiểu về lễ hội nào vậy?"}]},commonMistake:{wrong:"日本についての文化を話します。(nhầm cấu trúc)",correct:"日本の文化について話します。",why:"Cấu trúc đúng: [danh từ chủ đề] について + động từ. Không thêm の giữa について và động từ. についての có thể dùng nhưng tiếp theo phải là danh từ: 日本文化についての本 (cuốn sách về văn hóa Nhật)."},related:["minna-21:〜と思います","minna-21:〜と言いました"],kitsuPrompt:"Hỏi tôi muốn nói/học/biết về chủ đề gì. Tôi sẽ dùng Nについて để trả lời."}]},{bai:22,level:"N5",kanji:"修",reading:"しゅうしょく",romaji:"Shuushoku",titleVi:"Bổ nghĩa danh từ",titleJp:"名詞修飾節",descVi:"Dùng mệnh đề V/A để bổ nghĩa cho danh từ như relative clause.",selfCheckGoals:["Tạo relative clause bằng cách đặt mệnh đề động từ trước danh từ (Vた/Vる/Vない + N).","Nhớ dùng が thay は trong mệnh đề bổ nghĩa khi chỉ người thực hiện hành động.","Kết hợp mệnh đề bổ nghĩa với danh từ trừu tượng: 時間, 約束, 機会, こと.","Thêm tính từ い và な trước danh từ để mô tả chính xác hơn."],readingPassage:{title:"お気に入りのカフェ",titleVi:"Quán cà phê yêu thích",japanese:"昨日行ったカフェはとても素敵でした。窓から見える景色がきれいでした。私が注文したケーキはとても美味しかったです。飲めないコーヒーの代わりに、紅茶を頼みました。また行きたいお店です。",vietnamese:"Quán cà phê hôm qua đến rất xinh đẹp. Phong cảnh nhìn qua cửa sổ đẹp lắm. Bánh ngọt tôi đặt ngon lắm. Thay vì cà phê không uống được, tôi gọi trà. Là quán muốn đến lại.",highlights:[{excerpt:"昨日行ったカフェ",label:"Vた + N"},{excerpt:"窓から見える景色",label:"Vる + N"},{excerpt:"私が注文したケーキ",label:"Vた + N (N2)"},{excerpt:"飲めないコーヒー",label:"Vない + N"},{excerpt:"また行きたいお店",label:"Vたい + N"}],questions:[{q:"このカフェで何を食べましたか。",options:["サンドイッチ","ケーキ","アイスクリーム","クッキー"],answer:1},{q:"どうしてコーヒーを飲みませんでしたか。",options:["嫌いだから","高いから","飲めないから","売り切れだから"],answer:2}]},patterns:[{pattern:"Vる／Vた／Vない + N",meaning:"N mà / N đã / N chưa V (mệnh đề bổ nghĩa danh từ)",priority:"core",explanation:"Mệnh đề động từ đứng trước danh từ để bổ nghĩa, giống relative clause trong tiếng Anh. Thứ tự: [mệnh đề bổ nghĩa] + [danh từ]. Không cần pronoun (that/who/which).",examples:[{sentence:"これは私が昨日買った本です。",translation:"Đây là cuốn sách mà tôi đã mua hôm qua."},{sentence:"あそこに座っている人は田中さんです。",translation:"Người đang ngồi kia là anh Tanaka."},{sentence:"日本語が話せる人を探しています。",translation:"Tôi đang tìm người có thể nói tiếng Nhật."},{sentence:"まだ食べていない料理がたくさんあります。",translation:"Vẫn còn nhiều món tôi chưa ăn."}],note:"Người thực hiện hành động trong mệnh đề bổ nghĩa dùng が (không phải は): 私が買った本 (không phải 私は買った本).",dialogue:{title:"Mô tả đồ vật và người",lines:[{speaker:"A",text:"あのテーブルの上にある赤いかばんは誰のですか。",translation:"Cái túi đỏ ở trên bàn kia là của ai vậy?"},{speaker:"B",text:"ああ、それは昨日田中さんが忘れていったかばんです。",translation:"À, đó là cái túi mà Tanaka để quên hôm qua."},{speaker:"A",text:"そうですか。田中さんに連絡したほうがいいですね。",translation:"Thế à. Nên liên lạc với Tanaka thì hơn nhỉ."}]},commonMistake:{wrong:"私は買った本 (dùng は thay vì が trong mệnh đề bổ nghĩa)",correct:"私が買った本",why:"Trong mệnh đề bổ nghĩa danh từ, chủ thể thực hiện hành động phải dùng が, không phải は. は chỉ được dùng ở mệnh đề chính. Đây là quy tắc quan trọng nhất của cấu trúc này."},related:["minna-22:Vる + 時間／約束／機会など","minna-22:Aい N / NAな N","minna-23:V/Aとき"],kitsuPrompt:"Hỏi tôi mô tả đồ vật hoặc người nào đó. Tôi sẽ dùng mệnh đề bổ nghĩa để trả lời."},{pattern:"Vる + 時間／約束／機会など",meaning:"thời gian / hẹn / cơ hội để làm ~",priority:"core",explanation:"Mệnh đề bổ nghĩa trước danh từ trừu tượng như 時間 (thời gian), 約束 (lời hẹn), 機会 (cơ hội). Rất phổ biến trong giao tiếp hàng ngày.",examples:[{sentence:"昼ごはんを食べる時間がありません。",translation:"Tôi không có thời gian ăn trưa."},{sentence:"明日、会う約束をしました。",translation:"Tôi đã hẹn gặp vào ngày mai."},{sentence:"日本に行く機会がありますか。",translation:"Bạn có cơ hội đi Nhật không?"},{sentence:"話したいことがあります。",translation:"Có chuyện tôi muốn nói với bạn."}],note:"〜する予定 (kế hoạch) / 〜する機会 (cơ hội) / 〜する時間 (thời gian) — những collocation phổ biến.",dialogue:{title:"Lên kế hoạch gặp nhau",lines:[{speaker:"A",text:"最近、忙しいですか。",translation:"Dạo này bạn có bận không?"},{speaker:"B",text:"はい、昼ごはんを食べる時間もないくらいです。",translation:"Có, bận đến mức không có thời gian ăn trưa nữa."},{speaker:"A",text:"大変ですね。今週末、ゆっくり話せる機会がありますか。",translation:"Vất vả nhỉ. Cuối tuần này bạn có cơ hội nói chuyện thoải mái không?"}]},commonMistake:{wrong:"食べるの時間がありません。(thêm の không cần thiết trước danh từ)",correct:"食べる時間がありません。",why:"Mệnh đề bổ nghĩa + danh từ không cần の ở giữa. の chỉ dùng để danh từ hóa (食べるのは好きです) hoặc trong cấu trúc の where clause."},related:["minna-22:Vる／Vた／Vない + N","minna-18:Vることができます"],kitsuPrompt:"Hỏi tôi về thời gian, cơ hội hoặc kế hoạch. Tôi sẽ trả lời bằng các cụm như 〜する時間、〜する機会、〜する約束."},{pattern:"Aい N / NAな N",meaning:"N mà có tính chất ~ (tính từ bổ nghĩa danh từ)",priority:"common",explanation:"Tính từ đứng trước danh từ: い-adj giữ nguyên; な-adj thêm な. Đây là cách tạo cụm danh từ mô tả.",examples:[{sentence:"大きい荷物を持っています。",translation:"Tôi đang mang hành lý to."},{sentence:"静かなレストランで食べたいです。",translation:"Tôi muốn ăn ở nhà hàng yên tĩnh."},{sentence:"新しいスマホが欲しいです。",translation:"Tôi muốn có điện thoại mới."},{sentence:"有名な俳優に会いたいです。",translation:"Tôi muốn gặp diễn viên nổi tiếng."}],note:"Tính từ bổ nghĩa + N tạo cụm danh từ dùng làm chủ ngữ, tân ngữ hoặc bổ ngữ trong câu dài hơn.",dialogue:{title:"Mô tả nơi muốn đến",lines:[{speaker:"A",text:"今度の旅行、どんなホテルに泊まりたいですか。",translation:"Chuyến đi tới bạn muốn ở khách sạn như thế nào?"},{speaker:"B",text:"静かできれいな部屋がいいです。できれば海が見える場所がいいな。",translation:"Tôi muốn phòng yên tĩnh và sạch sẽ. Nếu được thì ở nơi nhìn thấy biển."},{speaker:"A",text:"いいですね。安くておいしいレストランも近くにあるといいですよね。",translation:"Nghe hay đấy. Nếu gần có nhà hàng ngon và rẻ nữa thì tốt nhỉ."}]},commonMistake:{wrong:"静かいレストラン (áp dụng い-adj cho な-adj)",correct:"静かなレストラン",why:"な-adj khi bổ nghĩa danh từ phải thêm な: 静かな, 有名な, 便利な. い-adj giữ nguyên: 大きい, 新しい, 安い. Phải phân biệt loại tính từ."},related:["minna-22:Vる／Vた／Vない + N","minna-9:AくてB/NAで"],kitsuPrompt:"Hỏi tôi muốn có đồ vật hay đi nơi như thế nào. Tôi sẽ mô tả bằng tính từ bổ nghĩa danh từ."}]},{bai:23,level:"N5",kanji:"条",reading:"じょうけん",romaji:"Jouken",titleVi:"Thời điểm & điều kiện",titleJp:"とき・と",descVi:'Nói "khi nào" với とき và điều kiện tự nhiên với 〜と.',selfCheckGoals:["Phân biệt Vるとき (trước khi V) và Vたとき (sau khi đã V) — đây là điểm khó nhất của bài.","Dùng と cho điều kiện tự nhiên, quy luật, chỉ đường — không dùng với lời mời/yêu cầu ở V2.",'Diễn tả cách thức "mà không làm V" bằng Vないで.',"Phân biệt Vないで (cách thức) và Vなくて (lý do)."],readingPassage:{title:"困ったときに",titleVi:"Khi gặp khó khăn",japanese:"道に迷ったとき、スマホで地図を見ます。傘を持っていないとき、コンビニで買います。ボタンを押すと、ドアが開きます。電車に乗るとき、スマホを見ないで外を見ます。困ったときは、すぐ友達に連絡します。",vietnamese:"Khi lạc đường, tôi xem bản đồ trên điện thoại. Khi không có ô, tôi mua ở cửa hàng tiện lợi. Khi bấm nút, cửa mở ra. Khi đi tàu, tôi không nhìn điện thoại mà nhìn ra ngoài. Khi gặp khó khăn, tôi liên lạc ngay với bạn.",highlights:[{excerpt:"道に迷ったとき",label:"Vたとき"},{excerpt:"傘を持っていないとき",label:"Vないとき"},{excerpt:"ボタンを押すと、ドアが開きます",label:"V1とV2"},{excerpt:"スマホを見ないで外を見ます",label:"Vないで"}],questions:[{q:"道に迷ったとき何をしますか。",options:["警察に電話する","スマホで地図を見る","友達を呼ぶ","タクシーに乗る"],answer:1},{q:"電車に乗るとき、どうしますか。",options:["スマホを見る","音楽を聞く","スマホを見ないで外を見る","寝る"],answer:2}]},patterns:[{pattern:"V/Aとき",meaning:"khi ~ / lúc ~",priority:"core",explanation:"とき chỉ thời điểm xảy ra hành động. Dạng động từ trước とき quan trọng: Vる-とき (trước khi V), Vた-とき (sau khi đã V). Sự khác biệt này rất quan trọng.",examples:[{sentence:"日本へ行ったとき、富士山を見ました。",translation:"Khi (đã) đến Nhật, tôi đã nhìn thấy núi Fuji."},{sentence:"子どものとき、よく泳ぎました。",translation:"Lúc còn nhỏ, tôi hay bơi lội."},{sentence:"困ったとき、電話してください。",translation:"Khi gặp khó khăn, hãy gọi điện cho tôi."},{sentence:"暇なとき、映画を見ます。",translation:"Khi rảnh, tôi xem phim."}],note:"日本へ行くとき (trước khi đến Nhật, còn đang chuẩn bị) khác 日本へ行ったとき (đã đến Nhật rồi).",dialogue:{title:"Nhớ lại kỷ niệm thời thơ ấu",lines:[{speaker:"A",text:"子どものとき、よく何をしましたか。",translation:"Hồi nhỏ bạn thường làm gì?"},{speaker:"B",text:"川の近くで育ったので、夏になると毎日泳ぎました。",translation:"Vì lớn lên gần sông nên hè nào tôi cũng bơi mỗi ngày."},{speaker:"A",text:"いいですね。私は学校から帰ったとき、いつも公園で遊びました。",translation:"Tốt nhỉ. Còn tôi, mỗi lần tan học về là hay chơi ở công viên."}]},commonMistake:{wrong:"日本へ行くとき、富士山を見ました。(muốn nói đã đến Nhật rồi mới thấy Fuji)",correct:"日本へ行ったとき、富士山を見ました。",why:'Hành động "thấy Fuji" xảy ra sau khi đã đến Nhật → phải dùng Vたとき. Vるとき = hành động chính chưa hoàn thành (đang trên đường đi). Ví dụ đúng: 日本へ行くとき、荷物を準備しました (chuẩn bị trước khi đi).'},related:["minna-23:V1とV2 (điều kiện tự nhiên)","minna-25:V/Aたら","minna-22:Vる／Vた／Vない + N"],kitsuPrompt:"Hỏi tôi về kỷ niệm thời thơ ấu hoặc thói quen khi còn học. Tôi sẽ dùng 〜とき để kể."},{pattern:"V1とV2 (điều kiện tự nhiên)",meaning:"khi V1 thì (tự nhiên) V2",priority:"core",explanation:"と chỉ điều kiện tự nhiên, quy luật, hoặc chỉ dẫn: khi/nếu V1 thì tất yếu V2. Không dùng với mệnh đề biểu đạt ý chí, mong muốn, lời mời ở V2.",examples:[{sentence:"このボタンを押すと、ドアが開きます。",translation:"Khi nhấn nút này, cửa sẽ mở ra."},{sentence:"春になると、桜が咲きます。",translation:"Khi mùa xuân đến, hoa anh đào nở."},{sentence:"右に曲がると、コンビニがあります。",translation:"Rẽ phải là thấy cửa hàng tiện lợi."},{sentence:"お湯を入れると、3分で食べられます。",translation:"Khi cho nước sôi vào, 3 phút là ăn được."}],note:"Không dùng と khi V2 là ý chí/lời mời: sai: 右に曲がると、見てください → dùng たら hoặc ば thay thế.",dialogue:{title:"Chỉ đường đến nơi",lines:[{speaker:"A",text:"すみません、郵便局はどこですか。",translation:"Xin lỗi, bưu điện ở đâu vậy ạ?"},{speaker:"B",text:"この道をまっすぐ行くと、信号があります。そこを左に曲がると、右手に見えますよ。",translation:"Đi thẳng theo con đường này thì có đèn giao thông. Rẽ trái ở đó rồi sẽ thấy ở bên phải."},{speaker:"A",text:"ありがとうございます。歩くと何分くらいですか。",translation:"Cảm ơn bạn. Nếu đi bộ thì mất khoảng bao nhiêu phút?"}]},commonMistake:{wrong:"駅に着くと、電話してください。(V2 là yêu cầu/mệnh lệnh)",correct:"駅に着いたら、電話してください。",why:"と không dùng khi V2 là ý chí, yêu cầu, lời mời, lời khuyên. Phải dùng たら hoặc ば trong những trường hợp đó. と chỉ dùng cho kết quả tự nhiên/tất yếu."},related:["minna-23:V/Aとき","minna-25:V/Aたら"],kitsuPrompt:"Chỉ đường cho tôi từ ga đến một địa điểm nổi tiếng. Dùng 〜と để nói điều kiện tự nhiên."},{pattern:"Vないで",meaning:"mà không làm V / không làm V rồi (làm gì khác)",priority:"core",explanation:'ない-form + で = "không làm V (và làm V2 thay)". Khác với Vなくて (nối tính từ hoặc chỉ lý do).',examples:[{sentence:"朝ごはんを食べないで学校へ行きました。",translation:"Tôi đã đến trường mà không ăn sáng."},{sentence:"傘を持たないで出かけました。",translation:"Tôi ra ngoài mà không mang ô."},{sentence:"日本語で話してください。英語を使わないで。",translation:"Hãy nói tiếng Nhật. Đừng dùng tiếng Anh."},{sentence:"何も言わないで行ってしまいました。",translation:"Anh ấy đã đi mà không nói gì cả."}],note:"Vないで (cách thức — không làm V) vs Vなくて (lý do — vì không làm V nên): 病気で来ないで vs 病気で来なくて困った.",dialogue:{title:"Giải thích lý do đến muộn",lines:[{speaker:"先生",text:"今日はどうして遅れましたか。",translation:"Hôm nay tại sao em trễ vậy?"},{speaker:"B",text:"朝、寝坊して、ごはんも食べないで急いで来ました。",translation:"Sáng em ngủ quên, rồi không ăn sáng, vội vàng đến luôn ạ."},{speaker:"先生",text:"次からは準備してから来てください。急がないでゆっくり来ていいですよ。",translation:"Lần sau chuẩn bị rồi hãy đến. Không cần vội, đến từ từ cũng được."}]},commonMistake:{wrong:"朝ごはんを食べなくて学校へ行きました。(dùng なくて thay vì ないで cho cách thức)",correct:"朝ごはんを食べないで学校へ行きました。",why:"ないで chỉ cách thức (đi mà không ăn). なくて chỉ lý do/nguyên nhân (vì không ăn nên...). Nhầm hai cấu trúc này là lỗi rất phổ biến."},related:["minna-23:V/Aとき","minna-17:Vなければなりません","minna-16:VてもいいですかVてはいけません"],kitsuPrompt:"Hỏi tôi về điều tôi đã làm theo cách không thông thường hôm nay. Tôi sẽ dùng Vないで để mô tả."}]},{bai:24,level:"N5",kanji:"贈",reading:"おくる",romaji:"Okuru",titleVi:"Cho & nhận hành động",titleJp:"やりもらい (行為)",descVi:"Phân biệt てあげる・てもらう・てくれる khi nói về hành động trao/nhận.",selfCheckGoals:["Xác định đúng hướng hành động: あげる (cho đi), もらう (nhận được), くれる (được cho — từ góc mình).","Dùng てもらいますか / てもらえませんか để nhờ vả lịch sự.","Biết khi nào nên tránh てあげます (nghe như ban ơn) và thay bằng 〜ましょうか.","Mô tả ai đó làm điều tốt cho mình bằng てくれました với cảm xúc biết ơn tự nhiên."],readingPassage:{title:"引っ越しの手伝い",titleVi:"Giúp dọn nhà",japanese:"先月、田中さんが引っ越しました。ミラーさんは田中さんに荷物を運んであげました。マリアさんも手伝ってあげました。田中さんはミラーさんに棚を組み立ててもらいました。山田さんが車を出してくれました。みんなに助けてもらって、田中さんはとても感謝しています。",vietnamese:"Tháng trước anh Tanaka chuyển nhà. Anh Miller đã giúp vận chuyển đồ đạc cho anh Tanaka. Chị Maria cũng giúp. Anh Tanaka nhờ anh Miller lắp giá kệ. Anh Yamada cho mượn xe. Nhờ mọi người giúp đỡ, anh Tanaka rất biết ơn.",highlights:[{excerpt:"田中さんに荷物を運んであげました",label:"VてあげますNに"},{excerpt:"棚を組み立ててもらいました",label:"VてもらいますNに"},{excerpt:"山田さんが車を出してくれました",label:"VてくれますNが"}],questions:[{q:"ミラーさんは田中さんに何をしてあげましたか。",options:["料理を作った","荷物を運んだ","棚を組み立てた","車を出した"],answer:1},{q:"誰が車を出してくれましたか。",options:["ミラーさん","マリアさん","田中さん","山田さん"],answer:3}]},patterns:[{pattern:"VてあげますNに",meaning:"làm cho ai (mình/người khác → người kia)",priority:"core",explanation:"てあげます = làm ơn/giúp đỡ cho ai. Hướng: người cho (chủ ngữ) → người nhận (に). Khi làm cho người bề trên, dùng てさしあげます (trang trọng hơn).",examples:[{sentence:"友だちの荷物を持ってあげました。",translation:"Tôi đã xách đồ giúp bạn."},{sentence:"道に迷っている人に道を教えてあげました。",translation:"Tôi đã chỉ đường cho người bị lạc."},{sentence:"弟に宿題を教えてあげます。",translation:"Tôi sẽ dạy bài tập cho em trai."},{sentence:"先生に資料をコピーしてさしあげました。",translation:"Tôi đã photo tài liệu giúp thầy."}],note:'Cẩn thận khi dùng てあげる — đôi khi nghe như "ban ơn". Tốt hơn: 〜ましょうか (để tôi giúp nhé?) thay vì てあげます.',dialogue:{title:"Giúp đỡ người bạn đang khó khăn",lines:[{speaker:"A",text:"田中さん、荷物が多いですね。手伝いましょうか。",translation:"Tanaka, hành lý nhiều nhỉ. Để tôi giúp nhé?"},{speaker:"B",text:"ありがとうございます。じゃあ、この袋を持ってもらえますか。",translation:"Cảm ơn bạn. Vậy bạn có thể cầm cái túi này giúp tôi không?"},{speaker:"A",text:"はい、もちろん。弟にも手伝ってもらいましょう。",translation:"Được chứ. Nhờ em tôi giúp thêm nữa nhé."}]},commonMistake:{wrong:"私は先生に本を教えてあげました。(dùng あげる với người bề trên một cách tự nhiên)",correct:"私は先生に本をお見せしました。hoặc 先生に本を見てさしあげました。",why:"てあげる với người bề trên (thầy, sếp) nghe thiếu lịch sự. Nên dùng てさしあげます hoặc đổi sang cách nói khiêm nhường hơn. てあげる dùng tự nhiên nhất với người thân, bạn bè, em nhỏ."},related:["minna-24:VてもらいますNに","minna-24:VてくれますNが","minna-7:あげます／もらいます／くれます"],kitsuPrompt:"Kể cho tôi nghe điều bạn đã làm giúp ai đó gần đây. Tôi sẽ phản hồi và chia sẻ lại bằng てあげました."},{pattern:"VてもらいますNに",meaning:"được / nhờ ai làm cho",priority:"core",explanation:"てもらいます = nhờ vả hoặc được hưởng lợi từ hành động của người khác. Hướng: người làm (に) → mình (chủ ngữ). Quan trọng: nhấn mạnh rằng người nói được lợi.",examples:[{sentence:"田中さんに荷物を持ってもらいました。",translation:"Tôi đã nhờ anh Tanaka xách đồ (và anh ấy đã xách)."},{sentence:"先生に日本語を教えてもらっています。",translation:"Tôi đang được thầy dạy tiếng Nhật."},{sentence:"友だちに車で駅まで送ってもらいました。",translation:"Bạn đã chở tôi đến ga bằng xe."},{sentence:"医者に薬を出してもらいました。",translation:"Tôi đã được bác sĩ kê đơn thuốc."}],note:"てもらえますか / てもらえませんか = nhờ vả lịch sự. Trang trọng hơn: ていただけますか.",dialogue:{title:"Nhờ bạn giúp sửa tiếng Nhật",lines:[{speaker:"A",text:"すみません、この作文を見てもらえませんか。",translation:"Xin lỗi, bạn có thể xem giúp bài văn này không?"},{speaker:"B",text:"もちろん。どこが心配ですか。",translation:"Được chứ. Bạn lo phần nào vậy?"},{speaker:"A",text:"敬語の部分をチェックしてもらいたいんです。",translation:"Tôi muốn nhờ bạn kiểm tra phần kính ngữ."}]},commonMistake:{wrong:"田中さんが荷物を持ってもらいました。(dùng が thay vì に cho người làm)",correct:"田中さんに荷物を持ってもらいました。",why:"Người thực hiện hành động trong てもらう phải dùng に (không phải が). Nhớ: もらう = mình nhận, người làm = に. Ngược lại, くれる dùng が cho người làm."},related:["minna-24:VてあげますNに","minna-24:VてくれますNが"],kitsuPrompt:"Hỏi tôi gần đây được ai giúp điều gì. Tôi sẽ kể bằng 〜てもらいました."},{pattern:"VてくれますNが",meaning:"ai đó làm cho mình (cảm ơn)",priority:"core",explanation:"てくれます = ai đó chủ động làm cho mình (người nói), mang cảm xúc biết ơn. Hướng: người làm (が) → mình. Khác てもらいます ở chỗ không cần nhờ — người kia tự làm.",examples:[{sentence:"母が毎日お弁当を作ってくれます。",translation:"Mẹ mỗi ngày làm cơm hộp cho tôi."},{sentence:"田中さんが道を教えてくれました。",translation:"Anh Tanaka đã chỉ đường cho tôi (và tôi biết ơn)."},{sentence:"友だちが空港まで迎えに来てくれました。",translation:"Bạn đã đến sân bay đón tôi."},{sentence:"誰かドアを開けてくれますか。",translation:"Ai có thể mở cửa giúp tôi không?"}],note:"Ba cặp: あげる(cho), もらう(nhận), くれる(được cho — từ góc nhìn người nhận). くれる luôn hướng đến người nói hoặc gia đình/người thân của người nói.",dialogue:{title:"Kể về lòng tốt của bạn bè",lines:[{speaker:"A",text:"先週、病気で大変でしたね。",translation:"Tuần trước bạn ốm, vất vả quá nhỉ."},{speaker:"B",text:"でも、山田さんが料理を作ってきてくれたり、薬を買ってきてくれたりして、助かりました。",translation:"Nhưng Yamada đã nấu đồ ăn mang đến, lại còn mua thuốc cho tôi nữa, nhờ vậy mà đỡ lắm."},{speaker:"A",text:"いい友だちですね。大切にしてくださいね。",translation:"Bạn bè tốt thật. Hãy trân trọng nhau nhé."}]},commonMistake:{wrong:"田中さんにくれました。(dùng に thay vì が cho người làm trong くれる)",correct:"田中さんがくれました。",why:"くれる: người làm là が (chủ ngữ), không phải に. Ngược lại với もらう (người làm = に). Nhớ: くれる = người ngoài tự chủ động cho mình → chủ ngữ が."},related:["minna-24:VてあげますNに","minna-24:VてもらいますNに","minna-7:あげます／もらいます／くれます"],kitsuPrompt:"Hỏi tôi về điều ai đó đã làm cho tôi mà không cần nhờ. Tôi sẽ kể bằng 〜てくれました với lòng biết ơn."}]},{bai:25,level:"N5",kanji:"仮",reading:"かてい",romaji:"Katei",titleVi:"Giả định & nhượng bộ",titleJp:"たら・ても",descVi:'Nói "nếu / khi ... thì" với たら và "dù ... vẫn" với ても.',selfCheckGoals:["Chia đúng dạng たら từ tất cả loại động từ, tính từ và danh từ.","Phân biệt たら (điều kiện linh hoạt) với と (điều kiện tự nhiên/quy luật).",'Diễn đạt "dù... vẫn" bằng ても một cách tự nhiên trong hội thoại.',"Dùng もし〜たら để nói điều kiện giả định viễn tưởng."],readingPassage:{title:"旅行の計画",titleVi:"Kế hoạch du lịch",japanese:"もし時間があったら、北海道へ旅行したいです。お金があれば、ホテルに泊まります。たとえ雨が降っても、旅行はやめません。天気が悪くても、楽しい思い出が作れると思います。来年の春になったら、必ず行きます。",vietnamese:"Nếu có thời gian, tôi muốn đi du lịch Hokkaido. Nếu có tiền, tôi sẽ ở khách sạn. Dù trời có mưa, tôi cũng không bỏ du lịch. Tôi nghĩ dù thời tiết xấu cũng có thể tạo kỷ niệm vui. Khi mùa xuân năm tới đến, nhất định tôi sẽ đi.",highlights:[{excerpt:"もし時間があったら、北海道へ旅行したいです",label:"もし〜たら"},{excerpt:"たとえ雨が降っても、旅行はやめません",label:"たとえ〜ても"},{excerpt:"天気が悪くても、楽しい思い出が作れる",label:"V/Aても"},{excerpt:"来年の春になったら",label:"V/Aたら"}],questions:[{q:"この人はどこへ旅行したいですか。",options:["東京","大阪","北海道","沖縄"],answer:2},{q:"雨が降ったらどうしますか。",options:["旅行をやめる","家にいる","旅行はやめない","別の日にする"],answer:2}]},patterns:[{pattern:"V/Aたら",meaning:"nếu / khi ~ (điều kiện hoặc thời điểm)",priority:"core",explanation:'た-form + ら tạo điều kiện. Hai nghĩa: (1) điều kiện "nếu": giả định chưa xảy ra; (2) thời điểm "khi": hoàn thành V1 rồi làm V2. Đây là dạng điều kiện linh hoạt nhất.',examples:[{sentence:"雨が降ったら、行きません。",translation:"Nếu trời mưa thì tôi không đi."},{sentence:"家に帰ったら、電話してください。",translation:"Khi về nhà rồi hãy gọi điện cho tôi."},{sentence:"春になったら、花見をしましょう。",translation:"Khi mùa xuân đến, hãy đi ngắm hoa nhé."},{sentence:"安かったら、買います。",translation:"Nếu rẻ thì tôi sẽ mua."}],note:"たら có thể dùng với mọi loại V2 (ý chí, lời mời, yêu cầu) — linh hoạt hơn と và ば. Câu hỏi lịch sự: 〜たら、どうですか (Nếu ~ thì sao?).",dialogue:{title:"Lên kế hoạch nếu được nghỉ dài",lines:[{speaker:"A",text:"長い休みが取れたら、どこへ行きたいですか。",translation:"Nếu được nghỉ dài, bạn muốn đi đâu?"},{speaker:"B",text:"北海道へ行ったことがないので、行ってみたいです。雪が積もったら、スキーもしたいです。",translation:"Vì chưa từng đến Hokkaido nên tôi muốn thử. Nếu tuyết đổ thì tôi cũng muốn trượt tuyết."},{speaker:"A",text:"いいですね。計画が決まったら、一緒に行きましょうよ。",translation:"Hay đấy. Khi kế hoạch xong rồi, cùng đi nhé."}]},commonMistake:{wrong:"家に帰ったら、テレビを見ていました。(V2 quá khứ trong câu điều kiện một lần)",correct:"家に帰ったら、テレビを見ました。",why:"たら diễn tả điều kiện: khi V1 hoàn thành thì V2 xảy ra. V2 nên ở hiện tại hoặc tương lai (未来), hoặc quá khứ đơn (ました). Tránh dùng ていました vì nó gợi trạng thái đang kéo dài."},related:["minna-23:V1とV2 (điều kiện tự nhiên)","minna-25:もし〜たら","minna-25:V/Aても"],kitsuPrompt:"Hỏi tôi sẽ làm gì trong một tình huống giả định vui (ví dụ: nếu trúng xổ số, nếu biết nói tiếng Nhật hoàn hảo). Tôi sẽ dùng たら để trả lời."},{pattern:"もし〜たら",meaning:"nếu giả sử ~ (điều kiện khó xảy ra)",priority:"common",explanation:"もし nhấn mạnh tính giả định, thường dùng cho điều kiện khó có khả năng xảy ra. もし đứng đầu câu, たら ở cuối mệnh đề điều kiện.",examples:[{sentence:"もし宝くじが当たったら、世界旅行をします。",translation:"Nếu giả sử trúng xổ số, tôi sẽ đi du lịch vòng quanh thế giới."},{sentence:"もし時間があったら、手伝います。",translation:"Nếu có thời gian thì tôi sẽ giúp."},{sentence:"もし日本語が上手になったら、通訳になりたいです。",translation:"Nếu tiếng Nhật giỏi lên, tôi muốn làm phiên dịch."}],note:"もし tăng tính giả định; câu vẫn đúng khi không có もし, nhưng もし giúp báo hiệu điều kiện sắp tới.",dialogue:{title:"Ước mơ viễn vông",lines:[{speaker:"A",text:"もし何でも一つ欲しいものが手に入るとしたら、何が欲しいですか。",translation:"Nếu giả sử được có bất kỳ thứ gì bạn muốn, bạn muốn gì?"},{speaker:"B",text:"もし時間を自由に使えたら、毎日旅行したいです。お金より時間の方が大切ですから。",translation:"Nếu được tự do dùng thời gian, tôi muốn đi du lịch mỗi ngày. Vì thời gian quan trọng hơn tiền bạc."},{speaker:"A",text:"いい考えですね。もし私が一億円あったら、まず親に家を買ってあげたいです。",translation:"Ý hay đấy. Còn nếu tôi có 100 triệu yên thì trước tiên tôi muốn mua nhà cho bố mẹ."}]},commonMistake:{wrong:"もし雨が降ると、行きません。(dùng と thay vì たら sau もし)",correct:"もし雨が降ったら、行きません。",why:"もし phải đi với たら (hoặc ば), không dùng với と. と là điều kiện tự nhiên/quy luật, không phù hợp với giả định chủ quan của もし."},related:["minna-25:V/Aたら","minna-23:V1とV2 (điều kiện tự nhiên)"],kitsuPrompt:'Hỏi tôi câu "もし〜たら、どうしますか" về tình huống vui hay viễn tưởng. Tôi sẽ trả lời sáng tạo.'},{pattern:"V/Aても",meaning:"dù ~ vẫn ~ (nhượng bộ)",priority:"core",explanation:'て-form + も diễn tả "dù hoặc dù có ~ thì kết quả vẫn vậy". Ngược với điều kiện thông thường — nhấn mạnh không có ngoại lệ.',examples:[{sentence:"雨が降っても、行きます。",translation:"Dù trời mưa, tôi vẫn đi."},{sentence:"忙しくても、毎日運動します。",translation:"Dù bận, tôi vẫn tập thể dục mỗi ngày."},{sentence:"何度聞いても、わかりません。",translation:"Dù hỏi bao nhiêu lần cũng không hiểu."},{sentence:"高くても、買います。",translation:"Dù đắt, tôi vẫn mua."}],note:"Cấu trúc mở rộng: 何V-ても (dù làm bao nhiêu): 何度食べても飽きない (ăn mãi không chán).",dialogue:{title:"Bàn về quyết tâm học tiếng Nhật",lines:[{speaker:"A",text:"日本語の勉強、つらくないですか。",translation:"Học tiếng Nhật không vất vả sao?"},{speaker:"B",text:"難しくても、楽しいので続けます。漢字は何度見ても忘れてしまいますが...",translation:"Dù khó nhưng vì vui nên tôi tiếp tục. Tuy nhiên chữ Hán dù nhìn bao nhiêu lần cũng quên..."},{speaker:"A",text:"私もです。でも、諦めなければ絶対に上手になりますよ。",translation:"Tôi cũng vậy. Nhưng nếu không bỏ cuộc chắc chắn sẽ giỏi lên thôi."}]},commonMistake:{wrong:'雨が降っても行きません。(nhầm nghĩa — thực ra nói "dù mưa cũng không đi")',correct:"雨が降っても、行きます。(dù mưa vẫn đi)",why:"ても + phủ định = dù X thì vẫn không Y. ても + khẳng định = dù X thì vẫn Y. Phải chú ý phần V2 là khẳng định hay phủ định để không nhầm nghĩa."},related:["minna-25:たとえ〜ても","minna-25:V/Aたら"],kitsuPrompt:"Hỏi tôi về điều tôi vẫn làm dù có trở ngại. Tôi sẽ dùng 〜ても để thể hiện quyết tâm."},{pattern:"たとえ〜ても",meaning:"dù cho ~ (nhấn mạnh mạnh hơn)",priority:"optional",explanation:"たとえ (= dù cho, dù rằng) kết hợp với ても để nhấn mạnh hơn về tính nhượng bộ. Thường dùng trong ngữ cảnh trang trọng, quyết tâm, hoặc văn học.",examples:[{sentence:"たとえ難しくても、諦めません。",translation:"Dù cho khó đến đâu, tôi sẽ không bỏ cuộc."},{sentence:"たとえ失敗しても、また挑戦します。",translation:"Dù cho có thất bại, tôi sẽ thử lại."},{sentence:"たとえ雨が降っても、試合は続けます。",translation:"Dù cho trời mưa, trận đấu vẫn tiếp tục."}],note:"たとえ〜ても mạnh hơn và trang trọng hơn 〜ても bình thường. Thường thấy trong diễn văn, quyết tâm cá nhân.",dialogue:{title:"Thể hiện quyết tâm trước kỳ thi",lines:[{speaker:"A",text:"明日、日本語能力試験ですね。緊張していますか。",translation:"Ngày mai thi năng lực tiếng Nhật nhỉ. Bạn có hồi hộp không?"},{speaker:"B",text:"はい、でもたとえ合格できなくても、また来年挑戦します。",translation:"Có, nhưng dù cho không đậu thì năm sau tôi sẽ thử lại."},{speaker:"A",text:"その気持ちが大切ですよ。たとえ結果が悪くても、努力は無駄じゃないです。",translation:"Tinh thần đó mới quan trọng. Dù cho kết quả không tốt thì công sức không bao giờ uổng phí."}]},commonMistake:{wrong:"たとえ〜たら (dùng たら sau たとえ)",correct:"たとえ〜ても",why:'たとえ phải đi với ても, không đi với たら. たとえ〜ても là cặp cố định biểu đạt "dù cho ~ đi nữa".'},related:["minna-25:V/Aても","minna-25:V/Aたら"],kitsuPrompt:"Hỏi tôi về điều tôi quyết tâm làm dù hoàn cảnh khó khăn. Tôi sẽ dùng たとえ〜ても để diễn đạt mạnh mẽ."}]},{bai:26,level:"N4",kanji:"説",reading:"せつめい",romaji:"Setsumei",titleVi:"Giải thích & lý do",titleJp:"んです",descVi:"Dùng 〜んです để giải thích lý do, bộc lộ cảm xúc và xác nhận.",selfCheckGoals:["Dùng 〜んです để giải thích lý do một cách tự nhiên, không cứng nhắc.","Hỏi lý do/tình huống bằng V/Aんですか với giọng điệu quan tâm.","Phân biệt 〜んです (có dụng ý giải thích) vs 〜です (trần thuật đơn).","Dùng Nなんです khi giải thích bằng danh từ hoặc tính từ な."],readingPassage:{title:"体の調子が悪い",titleVi:"Cảm thấy không khỏe",japanese:"「顔色が悪いですね。大丈夫ですか。」「実は昨日から熱があるんです。」「それは大変ですね。病院へ行ったんですか。」「いいえ、薬を飲んでいるんですが、なかなか治らなくて。」「今日は大切な会議があるんですよね。無理しないでください。」",vietnamese:'"Sắc mặt bạn tệ nhỉ. Ổn không?" "Thực ra từ hôm qua tôi bị sốt." "Vất vả quá. Đi bệnh viện rồi à?" "Không, đang uống thuốc nhưng mãi không khỏi." "Hôm nay có cuộc họp quan trọng phải không. Đừng cố quá nhé."',highlights:[{excerpt:"熱があるんです",label:"〜んです (giải thích)"},{excerpt:"病院へ行ったんですか",label:"Vたんですか (hỏi tình huống)"},{excerpt:"薬を飲んでいるんですが",label:"Vているんですが"},{excerpt:"大切な会議があるんですよね",label:"Nがあるんですね (xác nhận)"}],questions:[{q:"どうして顔色が悪いですか。",options:["眠れなかったから","昨日から熱があるから","食べすぎたから","仕事が多いから"],answer:1},{q:"今、何をしていますか。",options:["病院へ行っています","会議をしています","薬を飲んでいます","家で寝ています"],answer:2}]},patterns:[{pattern:"〜んです",meaning:"giải thích lý do / bộc lộ cảm xúc",priority:"core",explanation:'〜んです (= 〜のです) thêm sắc thái "giải thích, tâm sự" vào câu. Dùng khi muốn truyền đạt lý do hoặc cảm xúc đằng sau thông tin — khác với 〜です đơn thuần chỉ trần thuật.',examples:[{sentence:"頭が痛いんです。だから、今日は早く帰ります。",translation:"Tôi bị đau đầu. Vì thế hôm nay về sớm."},{sentence:"実は、日本語を勉強しているんです。",translation:"Thực ra, tôi đang học tiếng Nhật đấy."},{sentence:"このケーキ、おいしいんですよ！ぜひ食べてみてください。",translation:"Bánh này ngon lắm đấy! Nhất định phải thử đi."}],note:"V/いAdj → んです. なAdj/N → なんです. Thân mật: 〜んだ (nam), 〜の (nữ). Câu nghi vấn: 〜んですか.",dialogue:{title:"Giải thích tại sao đến muộn",lines:[{speaker:"A",text:"遅いですね。どうしたんですか。",translation:"Muộn nhỉ. Có chuyện gì vậy?"},{speaker:"B",text:"すみません。電車が止まったんです。",translation:"Xin lỗi. Tàu điện bị dừng ạ."},{speaker:"A",text:"そうなんですか。大変でしたね。",translation:"Vậy à. Vất vả nhỉ."}]},commonMistake:{wrong:"どうして休みましたですか。",correct:"どうして休んだんですか。",why:'Khi hỏi lý do, tiếng Nhật tự nhiên dùng 〜んですか. Câu hỏi 〜んですか mang sắc thái "tôi muốn hiểu tình huống của bạn", nghe quan tâm hơn nhiều.'},related:["minna-9:〜から (lý do)","minna-39:〜ので"],kitsuPrompt:"Hỏi tôi vì sao trông có vẻ mệt/vui/buồn hôm nay. Tôi sẽ dùng 〜んです để giải thích tình huống."},{pattern:"V／Aんですか",meaning:"hỏi lý do / tình huống (quan tâm)",priority:"core",explanation:'Câu hỏi với 〜んですか mang sắc thái "Tôi chú ý thấy điều gì đó — có chuyện gì vậy?". Thân thiện và quan tâm hơn câu hỏi trực tiếp, tạo cảm giác muốn hiểu tình huống của đối phương.',examples:[{sentence:"荷物が多いんですか。どこへ行くんですか。",translation:"Hành lý nhiều nhỉ. Bạn đi đâu vậy?"},{sentence:"泣いているんですか。どうしたんですか。",translation:"Bạn đang khóc à. Có chuyện gì vậy?"},{sentence:"日本語が上手なんですね。どこで勉強したんですか。",translation:"Tiếng Nhật giỏi nhỉ. Học ở đâu vậy?"}],note:'〜んですか thường đi kèm quan sát: "Tôi thấy X → tại sao/có phải Y?". Nghe tự nhiên hơn câu hỏi trực tiếp lạnh lùng.',dialogue:{title:"Quan tâm đến đồng nghiệp",lines:[{speaker:"A",text:"元気がないんですか。疲れているんですか。",translation:"Bạn có vẻ không khỏe. Mệt à?"},{speaker:"B",text:"ええ、昨日ほとんど眠れなかったんです。",translation:"Vâng, hôm qua gần như không ngủ được."},{speaker:"A",text:"今日は早く帰ったほうがいいんじゃないですか。",translation:"Hôm nay về sớm thôi nhỉ."}]},commonMistake:{wrong:"田中さんは元気んですか。",correct:"田中さんは元気なんですか。",why:"Danh từ và tính từ な phải thêm な trước んです: 元気なんです, 学生なんです (tính từ い và động từ nối trực tiếp: 忙しいんです, 行くんです). Ngoài ra chỉ dùng 〜んですか khi có điều quan sát được muốn hỏi — dùng cho câu hỏi thông tin thường (お名前は何ですか) sẽ nghe như tra khảo."},related:["minna-26:〜んです","minna-9:どうして〜か"],kitsuPrompt:"Mô tả một tình huống rõ ràng (ví dụ: tôi đang cầm nhiều túi, trông lo lắng...). Tôi sẽ dùng 〜んですか để hỏi."},{pattern:"Nなんです",meaning:"là N đấy — giải thích bằng danh từ",priority:"common",explanation:"Khi phần giải thích là danh từ hoặc tính từ な, phải thêm な trước んです → なんです. Dùng khi giải thích đặc trưng, tình huống hoặc danh tính của bản thân.",examples:[{sentence:"今日は私の誕生日なんです。",translation:"Hôm nay là sinh nhật của tôi đấy."},{sentence:"彼女は日本人なんですよ。",translation:"Cô ấy là người Nhật đấy nhé."},{sentence:"あの店、有名なんですか。",translation:"Quán đó nổi tiếng à?"}],note:"Quy tắc: V → んです ／ いAdj → いんです ／ なAdj → なんです ／ N → なんです. Chỉ な-adj và N mới cần thêm な.",dialogue:{title:"Giới thiệu về bản thân",lines:[{speaker:"A",text:"どこから来たんですか。",translation:"Bạn từ đâu đến vậy?"},{speaker:"B",text:"ベトナム人なんです。ハノイ出身です。",translation:"Tôi là người Việt Nam. Quê ở Hà Nội."},{speaker:"A",text:"そうなんですね。日本語が本当に上手なんですね。",translation:"Vậy à. Tiếng Nhật giỏi thật nhỉ."}]},commonMistake:{wrong:"学生んです。",correct:"学生なんです。",why:"Danh từ và tính từ な phải thêm な trước んです. Nhớ quy tắc: V-ん, いAdj-ん, なAdj-なん, N-なん."},related:["minna-26:〜んです","minna-1:NはNです"],kitsuPrompt:"Giả vờ bạn không biết tôi là ai. Hỏi về quốc tịch, nghề nghiệp. Tôi sẽ giải thích bằng 〜なんです."}]},{bai:27,level:"N4",kanji:"可",reading:"かのう",romaji:"Kanou",titleVi:"Dạng khả năng",titleJp:"可能動詞・〜が見える／聞こえる",descVi:'Chia động từ sang dạng khả năng để nói "có thể" làm gì.',selfCheckGoals:["Chia động từ nhóm 1, 2, 3 sang dạng khả năng đúng quy tắc.","Phân biệt が見えます/聞こえます (khả năng tự nhiên) vs 見ることができます (nỗ lực).",'Dùng NしかVません để diễn đạt "chỉ có N, không có gì khác".',"Nói được cả khả năng (できます) và không thể (できません) trong ngữ cảnh thực tế."],readingPassage:{title:"私にできること",titleVi:"Những điều tôi có thể làm",japanese:"私は日本語が少し話せます。でも、漢字はひらがなしか読めません。料理は好きで、和食なら作れます。ここからは富士山が見えますか。晴れた日なら見えますよ。水泳は全然できません。",vietnamese:"Tôi có thể nói tiếng Nhật một chút. Nhưng chữ kanji chỉ đọc được hiragana. Thích nấu ăn, nếu là ẩm thực Nhật thì làm được. Từ đây có thể nhìn thấy núi Phú Sĩ không? Nếu trời nắng thì thấy được đấy. Bơi lội thì không làm được tí nào.",highlights:[{excerpt:"日本語が少し話せます",label:"V可能形"},{excerpt:"ひらがなしか読めません",label:"Nしか〜ない"},{excerpt:"和食なら作れます",label:"V可能形 (điều kiện)"},{excerpt:"富士山が見えますか",label:"NがVえます (tự nhiên)"}],questions:[{q:"漢字はどのくらい読めますか。",options:["全部読める","半分読める","ひらがなしか読めない","全然読めない"],answer:2},{q:"富士山はいつ見えますか。",options:["いつでも見える","晴れた日なら見える","曇った日に見える","夜だけ見える"],answer:1}]},patterns:[{pattern:"V可能形",meaning:"có thể V",priority:"core",explanation:"Dạng khả năng diễn đạt khả năng hoặc sự cho phép. Nhóm 1: える→ える (書く→書ける). Nhóm 2: る→られる (食べる→食べられる). Nhóm 3: する→できる, くる→こられる. Trợ từ を thường đổi thành が.",examples:[{sentence:"日本語が話せますが、漢字はあまり読めません。",translation:"Có thể nói tiếng Nhật nhưng không đọc được kanji lắm."},{sentence:"子どものころ、ピアノが弾けました。",translation:"Hồi nhỏ tôi chơi được đàn piano."},{sentence:"このホテルではペットが飼えません。",translation:"Khách sạn này không được nuôi thú cưng."}],note:"Nhóm 2 口語: 食べれる (thay食べられる) — được chấp nhận trong văn nói thân mật nhưng tránh trong văn viết.",dialogue:{title:"Phỏng vấn xin việc",lines:[{speaker:"A",text:"パソコンは使えますか。",translation:"Bạn có dùng được máy tính không?"},{speaker:"B",text:"はい、エクセルとワードなら問題なく使えます。",translation:"Vâng, Excel và Word thì dùng được không vấn đề gì."},{speaker:"A",text:"英語での会議に参加できますか。",translation:"Bạn có thể tham gia cuộc họp bằng tiếng Anh không?"}]},commonMistake:{wrong:"日本語を話せます。",correct:"日本語が話せます。",why:"Với dạng khả năng, trợ từ を thường đổi thành が. Đây là quy tắc quan trọng mà người học hay quên: 日本語を話す → 日本語が話せる."},related:["minna-18:Vることができます","minna-27:NがVできます"],kitsuPrompt:"Hỏi tôi những điều tôi có thể và không thể làm (nấu ăn, chơi nhạc cụ, thể thao...). Tôi sẽ trả lời bằng dạng 可能形."},{pattern:"NがVえます／聞こえます",meaning:"thấy / nghe được (tự nhiên, không cố ý)",priority:"common",explanation:"見えます và 聞こえます diễn đạt khả năng tự nhiên — mắt/tai tiếp nhận thông tin mà không cần cố gắng. Khác với 見られます/聞けます (có thể cố ý nhìn/nghe).",examples:[{sentence:"部屋から海が見えます。",translation:"Từ phòng có thể nhìn thấy biển."},{sentence:"隣の部屋から音楽が聞こえます。",translation:"Nghe thấy tiếng nhạc từ phòng bên."},{sentence:"霧で山が見えません。",translation:"Sương mù nên không thấy núi."}],note:"見える ≠ 見られる: 窓から富士山が見える (tự nhiên thấy) vs 映画が見られる (có thể/được xem). Tương tự: 聞こえる ≠ 聞ける.",dialogue:{title:"Tìm chỗ ở",lines:[{speaker:"A",text:"この部屋から何が見えますか。",translation:"Từ phòng này có thể thấy gì?"},{speaker:"B",text:"晴れた日は富士山が見えますよ。夜は夜景がきれいです。",translation:"Ngày nắng thấy được núi Phú Sĩ đấy. Ban đêm cảnh đêm đẹp lắm."},{speaker:"A",text:"道路の音は聞こえますか。",translation:"Có nghe thấy tiếng ồn từ đường không?"}]},commonMistake:{wrong:'富士山が見られます。(khi nói "từ đây trông thấy Phú Sĩ")',correct:"富士山が見えます。",why:"見えます = tự nhiên nhìn thấy (không chủ đích). 見られます = có thể xem (có chủ đích, ví dụ: xem phim, xem biểu diễn)."},related:["minna-27:V可能形","minna-18:Vることができます"],kitsuPrompt:"Hỏi tôi về những điều có thể thấy/nghe từ nơi tôi đang ở (nhà, lớp học). Tôi sẽ dùng 見えます/聞こえます."},{pattern:"Nしか〜ない",meaning:"chỉ có N (hàm ý ít, thiếu)",priority:"core",explanation:'しか + phủ định diễn tả "chỉ có N mà thôi" — mang hàm ý tiêu cực hoặc nuối tiếc. Khác với だけ (trung tính): 100円しかない (chỉ có 100 yên — thấy ít) vs 100円だけある (chỉ có 100 yên — trung tính).',examples:[{sentence:"お金が100円しかありません。",translation:"Chỉ còn có 100 yên thôi."},{sentence:"ひらがなしか読めません。",translation:"Chỉ đọc được hiragana thôi."},{sentence:"残り時間は5分しかない。",translation:"Thời gian còn lại chỉ có 5 phút thôi."}],note:"しか luôn đi với động từ phủ định (ない/ません). しか thay thế trợ từ が/を nhưng giữ に/で/と.",dialogue:{title:"Thiếu tiền",lines:[{speaker:"A",text:"夕食はどこで食べましょうか。",translation:"Ăn tối ở đâu nhỉ?"},{speaker:"B",text:"今日はお金が500円しかないんです。コンビニしか行けません。",translation:"Hôm nay tôi chỉ còn 500 yên thôi. Chỉ đi được cửa hàng tiện lợi thôi."},{speaker:"A",text:"そうですか。じゃあ、今日は私がおごります。",translation:"Vậy à. Vậy hôm nay để tôi đãi nhé."}]},commonMistake:{wrong:"日本語しかわかります。",correct:"日本語しかわかりません。",why:"しか PHẢI đi với phủ định (ない/ません). Không bao giờ dùng しか với khẳng định. Nếu thấy しか mà không có phủ định → sai."},related:["minna-6:NかN","minna-27:V可能形"],kitsuPrompt:"Tạo tình huống tôi bị hạn chế (ít tiền, ít thời gian, chỉ biết một thứ). Tôi sẽ dùng 〜しかありません để diễn đạt."}]},{bai:28,level:"N4",kanji:"並",reading:"なみ",romaji:"Nami",titleVi:"Hai việc đồng thời",titleJp:"〜ながら・〜ています (習慣)",descVi:"Dùng 〜ながら để mô tả hai hành động diễn ra cùng lúc.",selfCheckGoals:["Dùng V1ながらV2 với V2 là hành động chính, V1 là hành động phụ đồng thời.","Phân biệt Vています (thói quen) vs Vています (đang làm dở tại lúc nói).","Dùng Vやすい / Vにくい để nhận xét tính dễ/khó của một hành động.","Nhớ: chủ thể của V1 và V2 trong ながら phải là cùng một người."],readingPassage:{title:"田中さんの生活習慣",titleVi:"Thói quen sinh hoạt của Tanaka",japanese:"田中さんは毎朝音楽を聞きながらジョギングをしています。仕事では、コーヒーを飲みながらメールをチェックします。この会社に入ってから、早起きをするようにしています。この本は専門用語が多くて読みにくいです。でも、内容はわかりやすいです。",vietnamese:"Anh Tanaka mỗi sáng vừa nghe nhạc vừa chạy bộ. Trong công việc, vừa uống cà phê vừa kiểm tra email. Từ khi vào công ty này, anh cố gắng dậy sớm. Cuốn sách này có nhiều thuật ngữ chuyên môn nên khó đọc. Nhưng nội dung dễ hiểu.",highlights:[{excerpt:"音楽を聞きながらジョギングをしています",label:"V1ながらV2 / Vています (thói quen)"},{excerpt:"コーヒーを飲みながらメールをチェックします",label:"V1ながらV2"},{excerpt:"読みにくいです",label:"Vにくい"},{excerpt:"わかりやすいです",label:"Vやすい"}],questions:[{q:"田中さんは朝、何をしながらジョギングしますか。",options:["コーヒーを飲みながら","音楽を聞きながら","メールをチェックしながら","ニュースを見ながら"],answer:1},{q:"この本はどうですか。",options:["読みやすいが内容が難しい","読みにくいが内容はわかりやすい","読みやすくて内容もわかりやすい","全部難しい"],answer:1}]},patterns:[{pattern:"V1stemながらV2",meaning:"vừa V1 vừa V2 (đồng thời)",priority:"core",explanation:"V1のmasu-stem + ながら + V2 diễn tả hai hành động xảy ra cùng lúc của cùng một người. V2 là hành động chính, V1 là hành động phụ/nền. V1 thường là hành động nhỏ hơn, ít quan trọng hơn.",examples:[{sentence:"音楽を聞きながら料理します。",translation:"Vừa nghe nhạc vừa nấu ăn."},{sentence:"歩きながらスマホを見るのは危ないです。",translation:"Vừa đi vừa xem điện thoại rất nguy hiểm."},{sentence:"先生の話を聞きながら、ノートを取ります。",translation:"Vừa nghe giáo viên nói vừa ghi chép."}],note:"V1 và V2 phải có cùng chủ thể. Sai: 私が歩きながら、彼が話しました. Đúng: 彼は話しながら歩きました.",dialogue:{title:"Tán gẫu giờ nghỉ trưa",lines:[{speaker:"A",text:"いつも昼ごはんを食べながら何をしていますか。",translation:"Bạn thường làm gì trong khi ăn trưa?"},{speaker:"B",text:"ニュースを見ながら食べることが多いです。",translation:"Thường vừa xem tin tức vừa ăn."},{speaker:"A",text:"私はYouTubeを見ながら食べています。",translation:"Tôi vừa xem YouTube vừa ăn."}]},commonMistake:{wrong:"彼と話しながら、私は歩きました。(hai chủ thể khác nhau)",correct:"彼と話しながら歩きました。(cùng chủ thể)",why:"ながら yêu cầu cùng một chủ thể thực hiện cả hai hành động. Không thể dùng ながら khi V1 và V2 do hai người khác nhau thực hiện."},related:["minna-14:Vています (進行)","minna-28:Vています (習慣)"],kitsuPrompt:"Hỏi tôi về thói quen đa nhiệm (làm gì trong khi ăn, đi học, nấu ăn...). Tôi sẽ dùng 〜ながら."},{pattern:"Vています (習慣)",meaning:"thói quen / trạng thái kéo dài",priority:"core",explanation:"Vています có ba nghĩa: (1) đang làm (tiến hành), (2) thói quen/nghề nghiệp/tình trạng kéo dài, (3) kết quả còn lưu lại. Nghĩa thói quen thường kèm 毎日/毎朝... hoặc context nghề nghiệp.",examples:[{sentence:"毎朝6時に起きています。",translation:"Tôi có thói quen dậy lúc 6 giờ sáng."},{sentence:"銀行で働いています。",translation:"Tôi làm việc ở ngân hàng."},{sentence:"3年間日本語を勉強しています。",translation:"Tôi đang học tiếng Nhật 3 năm rồi."}],note:"Phân biệt: 電車に乗っています (đang trên tàu — tiến hành) vs 毎日電車に乗っています (thói quen dùng tàu). Context là chìa khóa.",dialogue:{title:"Làm quen tại buổi networking",lines:[{speaker:"A",text:"お仕事は何をしていらっしゃいますか。",translation:"Bạn đang làm công việc gì ạ?"},{speaker:"B",text:"IT会社でプログラマーをしています。",translation:"Tôi làm lập trình viên ở công ty IT."},{speaker:"A",text:"趣味は何かされていますか。",translation:"Bạn có sở thích gì không?"}]},commonMistake:{wrong:'毎日運動しています。(khi muốn nói "hôm nay đang tập")',correct:"今、運動しています。(đang tập) vs 毎日運動しています。(thói quen)",why:"毎日 + Vています → thói quen. 今 + Vています → đang làm ngay bây giờ. Dấu hiệu thời gian quyết định nghĩa."},related:["minna-14:Vています (進行)","minna-15:Vています (trạng thái)"],kitsuPrompt:"Hỏi tôi về thói quen hàng ngày và nghề nghiệp. Tôi sẽ dùng Vています để mô tả."},{pattern:"Vやすい／Vにくい",meaning:"dễ / khó V",priority:"common",explanation:'Vのmasu-stem + やすい (dễ V) / にくい (khó V). Dùng để nhận xét tính chất của đồ vật, sách, thức ăn... theo góc độ "dễ/khó sử dụng/thực hiện".',examples:[{sentence:"この靴は歩きやすいです。",translation:"Đôi giày này dễ đi lắm."},{sentence:"先生の字は読みにくいです。",translation:"Chữ của giáo viên khó đọc."},{sentence:"このアプリは使いやすくて、気に入っています。",translation:"App này dễ dùng nên tôi thích."}],note:"やすい/にくい chia như い-adjective: やすい → やすくない, やすかった. Thường nói về thiết kế, tính năng của vật — không nói về người.",dialogue:{title:"Mua giày mới",lines:[{speaker:"A",text:"この靴、履きやすいですか。",translation:"Đôi giày này có dễ mang không?"},{speaker:"B",text:"うーん、少し大きくて脱ぎにくいです。",translation:"Ừm, hơi to một chút nên khó cởi."},{speaker:"A",text:"では、こちらはいかがですか。歩きやすいですよ。",translation:"Vậy đôi này thì sao? Đi bộ dễ lắm đấy."}]},commonMistake:{wrong:'彼はわかりにくいです。(muốn nói "anh ấy khó hiểu")',correct:"彼の説明はわかりにくいです。(lời giải thích của anh ấy khó hiểu)",why:"やすい/にくい thường gắn với đồ vật/hành động, không phải người. Thay vì nói người, hãy nói về hành động/thuộc tính cụ thể."},related:["minna-44:Vすぎます","minna-44:V方"],kitsuPrompt:"Cho tôi đánh giá về các đồ vật xung quanh (sách, app, quần áo). Tôi sẽ dùng やすい/にくい."}]},{bai:29,level:"N4",kanji:"結",reading:"けっか",romaji:"Kekka",titleVi:"Tự động từ & kết quả",titleJp:"自動詞と結果状態",descVi:'Phân biệt tự/tha động từ và nói "đã lỡ làm" với てしまいました.',selfCheckGoals:["Phân biệt tự động từ (intransitive) và tha động từ (transitive) — cặp quan trọng nhất N4.","Dùng Vています để diễn đạt trạng thái kết quả (kết quả còn lưu lại).","Dùng Vてしまいました để nói về hành động đã hoàn tất không thể đảo ngược / lỡ tay.","Phân biệt 電気をつけます (hành động) vs 電気がついています (trạng thái kết quả)."],readingPassage:{title:"うっかりミス",titleVi:"Lỡ tay sơ ý",japanese:"今朝、会社に財布を忘れてしまいました。それに、大事なファイルも消えてしまいました。会議の資料を印刷しようとしたら、プリンターが壊れています。窓が開いているので、部屋が寒いです。電気もついたままです。今日は最悪の日です。",vietnamese:"Sáng nay tôi để quên ví ở công ty. Thêm vào đó, file quan trọng cũng bị xóa mất. Khi định in tài liệu họp thì máy in bị hỏng. Cửa sổ đang mở nên phòng lạnh. Đèn cũng đang bật. Hôm nay là ngày tệ nhất.",highlights:[{excerpt:"財布を忘れてしまいました",label:"Vてしまいました (lỡ tay)"},{excerpt:"大事なファイルも消えてしまいました",label:"Vてしまいました (đáng tiếc)"},{excerpt:"プリンターが壊れています",label:"Vています (kết quả)"},{excerpt:"窓が開いているので",label:"自動詞 + ています (trạng thái)"}],questions:[{q:"今朝、何を忘れましたか。",options:["鍵","ファイル","財布","プリンター"],answer:2},{q:"プリンターはどうなっていますか。",options:["使っています","壊れています","動いています","印刷しています"],answer:1}]},patterns:[{pattern:"自動詞 vs 他動詞",meaning:"tự động từ vs tha động từ",priority:"core",explanation:"Tự động từ (自動詞) không cần tân ngữ: ドアが開く. Tha động từ (他動詞) cần tân ngữ với を: ドアを開ける. Nhiều cặp tự/tha tồn tại song song và rất quan trọng.",examples:[{sentence:"ドアが開きます。vs ドアを開けます。",translation:"Cửa mở. vs Tôi mở cửa."},{sentence:"電気がつきます。vs 電気をつけます。",translation:"Đèn bật. vs Tôi bật đèn."},{sentence:"窓が閉まります。vs 窓を閉めます。",translation:"Cửa sổ đóng. vs Tôi đóng cửa sổ."}],note:"Cặp hay gặp: 開く/開ける, 閉まる/閉める, つく/つける, 消える/消す, 起きる/起こす, 落ちる/落とす.",dialogue:{title:"Ai làm vỡ bình hoa?",lines:[{speaker:"A",text:"花瓶が割れています。どうしたんですか。",translation:"Bình hoa bị vỡ rồi. Sao vậy?"},{speaker:"B",text:"ネコが落としてしまったんです。",translation:"Con mèo làm rơi đấy ạ."},{speaker:"A",text:"ネコが花瓶を割ったんですね。困りましたね。",translation:"Mèo làm vỡ bình hoa rồi. Phiền quá nhỉ."}]},commonMistake:{wrong:"ドアが開けています。",correct:"ドアが開いています。(tự động từ + ています = trạng thái)",why:"Tự động từ + ています diễn đạt trạng thái kết quả: 開く(自) → 開いている(đang ở trạng thái mở). Tha động từ + ています: 開ける(他) → 開けている(đang thực hiện hành động mở)."},related:["minna-29:Vています (結果)","minna-15:Vています (trạng thái)"],kitsuPrompt:"Đưa ra tình huống trong nhà (đèn, cửa, máy móc) và hỏi tôi ai làm gì. Tôi sẽ phân biệt tự/tha động từ."},{pattern:"Vています (結果状態)",meaning:"đang trong trạng thái kết quả",priority:"core",explanation:'Tự động từ + ています diễn đạt trạng thái hiện tại là kết quả của hành động trước đó. Hành động đã hoàn tất nhưng trạng thái còn đó. Trả lời câu hỏi "bây giờ đang thế nào?"',examples:[{sentence:"電気がついています。",translation:"Đèn đang sáng (đã được bật)."},{sentence:"財布の中にお金が入っています。",translation:"Trong ví có tiền (đã được bỏ vào)."},{sentence:"もう知っています。",translation:"Tôi đã biết rồi (hiện tại đang ở trạng thái biết)."}],note:"知っています, 住んでいます, 持っています, 結婚しています → đây là những động từ đặc biệt chỉ dùng ています để diễn đạt trạng thái (không dùng ます đơn).",dialogue:{title:"Kiểm tra trước khi ra ngoài",lines:[{speaker:"A",text:"電気が消えていますか。",translation:"Đèn đã tắt chưa?"},{speaker:"B",text:"はい、全部消えています。窓も閉まっています。",translation:"Vâng, tất cả đã tắt rồi. Cửa sổ cũng đã đóng."},{speaker:"A",text:"じゃあ、出かけましょう。",translation:"Vậy thì đi thôi."}]},commonMistake:{wrong:'結婚します。(khi muốn nói "đã kết hôn")',correct:"結婚しています。",why:"結婚します = sẽ kết hôn (tương lai). 結婚しています = đã kết hôn (trạng thái hiện tại). Tương tự: 住みます → 住んでいます, 知ります → 知っています."},related:["minna-15:Vています (trạng thái)","minna-29:自動詞 vs 他動詞"],kitsuPrompt:"Hỏi tôi về trạng thái hiện tại của các đồ vật xung quanh (cửa, đèn, v.v.). Tôi sẽ dùng 〜ています."},{pattern:"Vてしまいました",meaning:"đã lỡ làm / đã trót làm (đáng tiếc hoặc nhẹ nhõm)",priority:"core",explanation:"Vてしまいます diễn đạt: (1) hành động hoàn tất không thể đảo ngược, thường kèm cảm giác tiếc nuối; (2) hoàn thành hoàn toàn (nghĩa nhẹ hơn). Văn nói: 〜ちゃった (ngắn gọn).",examples:[{sentence:"財布を忘れてしまいました。",translation:"Tôi đã lỡ quên ví mất rồi."},{sentence:"ケーキを全部食べてしまいました。",translation:"Đã ăn hết cái bánh rồi."},{sentence:"宿題を全部終わらせてしまいました。",translation:"Đã làm xong hết bài tập rồi (nhẹ nhõm)."}],note:"Văn nói thân mật: 食べてしまった → 食べちゃった, してしまった → しちゃった. Nghĩa tiêu cực hay tích cực phụ thuộc ngữ cảnh.",dialogue:{title:"Lỡ gửi email sai",lines:[{speaker:"A",text:"大変！間違ったメールを送ってしまいました。",translation:"Ớ trời! Tôi đã lỡ gửi email nhầm rồi."},{speaker:"B",text:"えー！誰に送ったんですか。",translation:"Ôi! Gửi cho ai vậy?"},{speaker:"A",text:"お客様に内部のメールを送ってしまいました...",translation:"Tôi đã gửi email nội bộ cho khách hàng mất rồi..."}]},commonMistake:{wrong:"財布を忘れました。(đúng nhưng thiếu sắc thái)",correct:"財布を忘れてしまいました。(đáng tiếc, không thể hoàn tác)",why:'〜ました đơn thuần chỉ thông báo. 〜てしまいました thêm sắc thái "ôi thôi, không thể làm lại được" — chọn cái nào tùy theo ý định biểu đạt.'},related:["minna-29:Vています (結果)","minna-20:Vてしまいました"],kitsuPrompt:"Tạo tình huống tôi lỡ tay làm điều gì đó (phá vỡ đồ, quên hẹn, gửi nhầm). Tôi sẽ dùng 〜てしまいました."}]},{bai:30,level:"N4",kanji:"備",reading:"そなえる",romaji:"Sonaeru",titleVi:"Làm sẵn & chuẩn bị",titleJp:"準備と状態",descVi:"Dùng てあります (đã làm sẵn) và ておきます (làm để chuẩn bị).",selfCheckGoals:["Dùng Vてあります để nói về kết quả của việc ai đó đã cố ý làm sẵn.","Dùng Vておきます để nói mình sẽ làm trước để chuẩn bị cho việc sau.","Phân biệt 窓が開いている (tự 自動詞+ている) vs 窓が開けてある (tha他動詞+てある, có chủ đích).","Biết khi nào dùng ておく và khi nào dùng てある trong hội thoại thực tế."],readingPassage:{title:"旅行の準備",titleVi:"Chuẩn bị cho chuyến đi",japanese:"来週、大阪へ出張があります。ホテルはもう予約してあります。電車のチケットも買っておきました。会議の資料は印刷しておきます。地図はスマホにダウンロードしてあります。忘れ物がないように、リストを作っておきましょう。",vietnamese:"Tuần tới có công tác ở Osaka. Khách sạn đã được đặt rồi. Vé tàu cũng đã mua trước rồi. Tài liệu họp sẽ in trước. Bản đồ đã được tải về điện thoại rồi. Để không quên đồ, hãy lập danh sách trước nhé.",highlights:[{excerpt:"ホテルはもう予約してあります",label:"Vてあります (đã làm sẵn)"},{excerpt:"チケットも買っておきました",label:"Vておきます (làm trước)"},{excerpt:"資料は印刷しておきます",label:"Vておきます (kế hoạch)"},{excerpt:"地図はスマホにダウンロードしてあります",label:"Vてあります (kết quả)"}],questions:[{q:"ホテルについて、どうなっていますか。",options:["これから予約します","もう予約してあります","予約が必要です","キャンセルしました"],answer:1},{q:"会議の資料はどうしますか。",options:["もう印刷してあります","印刷しておきます","印刷しなくていいです","誰かが印刷します"],answer:1}]},patterns:[{pattern:"Vてあります",meaning:"(ai đó) đã làm sẵn — kết quả còn đó",priority:"core",explanation:"Tha động từ + てあります diễn đạt trạng thái hiện tại là kết quả của hành động ai đó đã cố ý thực hiện trước đó. Nhấn mạnh: có người đã chuẩn bị, kết quả còn đó, thường là có lý do.",examples:[{sentence:"黒板に予定が書いてあります。",translation:"Lịch trình đã được viết trên bảng đen rồi."},{sentence:"ビールが冷蔵庫に冷やしてあります。",translation:"Bia đã được để lạnh trong tủ lạnh rồi."},{sentence:"部屋の予約がしてあります。",translation:"Phòng đã được đặt rồi."}],note:"Phân biệt: 窓が開いている(自動詞) = cửa đang mở (không rõ chủ đích) vs 窓が開けてある(他動詞) = cửa đã được mở có chủ đích (để thông khí chẳng hạn).",dialogue:{title:"Chuẩn bị bữa tiệc",lines:[{speaker:"A",text:"料理の準備はできていますか。",translation:"Chuẩn bị đồ ăn xong chưa?"},{speaker:"B",text:"はい、サラダは作ってあります。飲み物も冷やしてあります。",translation:"Vâng, salad đã làm xong rồi. Đồ uống cũng đã làm lạnh rồi."},{speaker:"A",text:"お皿は並べてありますか。",translation:"Đĩa đã bày ra chưa?"}]},commonMistake:{wrong:"窓が開いてあります。(tự động từ + てある)",correct:"窓が開けてあります。(tha動詞 + てある)",why:"てあります chỉ dùng với tha động từ. Nếu muốn dùng tự động từ + kết quả, hãy dùng 〜ています: 窓が開いています."},related:["minna-30:Vておきます","minna-29:Vています (結果)"],kitsuPrompt:"Hỏi tôi xem nhà tôi đã chuẩn bị gì cho khách (đồ ăn, phòng, v.v.). Tôi sẽ dùng 〜てあります."},{pattern:"Vておきます",meaning:"làm trước / làm sẵn để dùng sau",priority:"core",explanation:"Vておきます diễn đạt hành động thực hiện trước để chuẩn bị cho điều gì sẽ xảy ra sau. Nhấn mạnh ý thức chuẩn bị, lên kế hoạch từ trước. Văn nói: 〜とく / 〜ておく.",examples:[{sentence:"旅行の前にホテルを予約しておきます。",translation:"Trước chuyến đi tôi sẽ đặt khách sạn trước."},{sentence:"試験のために単語を覚えておいてください。",translation:"Hãy ghi nhớ từ vựng trước để chuẩn bị cho kỳ thi."},{sentence:"会議の前に資料を読んでおいた方がいいです。",translation:"Nên đọc tài liệu trước khi họp."}],note:"Văn nói: 読んでおく → 読んどく. 調べておきます → 調べとく. Nghĩa vẫn giữ nguyên — chỉ là rút gọn.",dialogue:{title:"Chuẩn bị cho kỳ thi",lines:[{speaker:"A",text:"試験まで何をしておくべきですか。",translation:"Trước kỳ thi nên chuẩn bị gì?"},{speaker:"B",text:"文法を復習しておいて、単語も全部覚えておいてください。",translation:"Hãy ôn lại ngữ pháp và ghi nhớ hết từ vựng trước nhé."},{speaker:"A",text:"わかりました。辞書も持ってきておきます。",translation:"Vâng. Tôi cũng sẽ mang từ điển theo trước."}]},commonMistake:{wrong:"会議のために資料をしておきました。(動詞なし)",correct:"会議のために資料を準備しておきました。",why:'Vておきます cần động từ cụ thể đứng trước おきます. "資料をしておく" thiếu động từ rõ ràng — phải nói "準備する/印刷する/読む...".'},related:["minna-30:Vてあります","minna-17:Vなければなりません"],kitsuPrompt:"Hỏi tôi cần chuẩn bị gì cho một sự kiện sắp tới (kỳ thi, du lịch, phỏng vấn). Tôi sẽ dùng 〜ておきます."}]},{bai:31,level:"N4",kanji:"志",reading:"こころざし",romaji:"Kokorozashi",titleVi:"Dự định & kế hoạch",titleJp:"意向と予定",descVi:"Nói có ý định làm (つもり), có lịch làm (予定) và chưa làm (まだ).",selfCheckGoals:["Chia được V意向形 của 5 động từ nhóm I, II, III","Phân biệt つもりです (ý định cá nhân) và 予定です (lịch đã lên)","Dùng まだ〜ていません để nói điều chưa hoàn thành","Nói kế hoạch tháng tới bằng 予定 một cách tự nhiên"],readingPassage:{title:"来年の計画",titleVi:"Kế hoạch năm sau",japanese:"来年、私は日本語能力試験のN3を受けるつもりです。そのために、毎日二時間練習する予定です。友だちのマリアさんも一緒に受験する予定だと言っていました。今はまだ模擬試験を受けていませんが、来月から始めようと思っています。二人で頑張ろうと話し合いました。",vietnamese:"Năm sau, tôi dự định thi N3 kỳ thi năng lực tiếng Nhật. Để đó, tôi có kế hoạch luyện tập hai tiếng mỗi ngày. Bạn tôi là Maria cũng nói rằng cô ấy có kế hoạch thi cùng. Hiện tại tôi chưa thi thử lần nào, nhưng tôi đang nghĩ sẽ bắt đầu từ tháng sau. Hai người đã nói chuyện với nhau rằng cùng cố gắng nào.",highlights:[{excerpt:"受けるつもりです",label:"ý định cá nhân"},{excerpt:"練習する予定です",label:"kế hoạch cụ thể"},{excerpt:"まだ模擬試験を受けていません",label:"chưa làm"},{excerpt:"始めようと思っています",label:"V意向形+と思う"}],questions:[{q:"筆者は来年何をするつもりですか。",options:["N3の試験を受ける","N2の試験を受ける","日本へ旅行する","仕事を変える"],answer:0},{q:"筆者はまだ何をしていませんか。",options:["模擬試験を受けること","友だちと話すこと","予定を立てること","練習すること"],answer:0}]},patterns:[{pattern:"V意向形",meaning:"ý chí / đề nghị cùng làm (dạng thể ý chí)",priority:"high",explanation:"Thể ý chí (volitional form) biểu thị ý định hoặc lời mời cùng làm. Nhóm I: い→お+う (書く→書こう). Nhóm II: bỏ る+よう (食べる→食べよう). Nhóm III: する→しよう, くる→こよう.",examples:[{sentence:"明日早く起きよう。",translation:"Ngày mai dậy sớm thôi."},{sentence:"一緒に勉強しよう！",translation:"Cùng nhau học nào!"},{sentence:"もう帰ろうか。",translation:"Về thôi nhỉ?"}],note:'〜ようと思っています = "đang nghĩ sẽ ~" (kế hoạch của bản thân, chưa quyết chắc)',dialogue:{jp:"A：週末、映画を見ようか。\nB：いいね、行こう！",vi:"A: Cuối tuần xem phim không?\nB: Hay đấy, đi thôi!"},commonMistake:{wrong:"明日は早く起きようです。",correct:"明日は早く起きようと思います。",why:"V意向形(thể ý chí, vd 起きよう)là dạng kết thúc câu riêng, không được ghép trực tiếp です phía sau. Muốn nói lịch sự về ý định thì phải dùng cấu trúc V意向形+と思います, không phải thêm です ngay sau 意向形."},related:["Vるつもりです","Vようと思っています"],kitsuPrompt:"Hỏi tôi về một kế hoạch tôi muốn thực hiện. Tôi sẽ trả lời bằng V意向形+と思っています."},{pattern:"Vるつもりです",meaning:"dự định / có ý định làm",priority:"high",explanation:"〜つもりです theo sau V thể từ điển biểu thị ý định cá nhân, đã quyết định nhưng chưa hẳn là lịch cụ thể. Phủ định: Vないつもりです (dự định không làm).",examples:[{sentence:"夏休みに沖縄へ行くつもりです。",translation:"Kỳ nghỉ hè tôi dự định đi Okinawa."},{sentence:"今年は結婚しないつもりです。",translation:"Năm nay tôi không có ý định kết hôn."},{sentence:"大学を卒業したら、働くつもりです。",translation:"Sau khi tốt nghiệp đại học tôi dự định đi làm."}],note:"Khác với 予定: つもり là ý định cá nhân (có thể thay đổi), 予定 là lịch đã lên (thường có tính cố định hơn).",dialogue:{jp:"A：将来何をするつもりですか。\nB：医者になるつもりです。",vi:"A: Tương lai bạn dự định làm gì?\nB: Tôi dự định trở thành bác sĩ."},commonMistake:{wrong:"来年、日本へ行くつもりをしています。",correct:"来年、日本へ行くつもりです。",why:"つもり là danh từ hình thức đi kèm です (Vるつもりです), không phải động từ để chia thành 〜をしています. Học viên hay nhầm với mẫu 練習をしています nên gắn thêm をしています vào sau つもり, đây là sai cấu trúc."},related:["Vる予定です","Vようと思っています"],kitsuPrompt:"Hỏi tôi có kế hoạch gì trong tương lai gần. Tôi sẽ dùng 〜つもりです."},{pattern:"Vる予定です",meaning:"có lịch / dự kiến (theo lịch trình)",priority:"high",explanation:"〜予定です theo sau V thể từ điển biểu thị lịch đã lên, thường có tính xác định cao hơn つもり. Dùng trong công việc, sự kiện đã đặt trước.",examples:[{sentence:"来月、出張の予定があります。",translation:"Tháng sau tôi có lịch công tác."},{sentence:"会議は３時に始まる予定です。",translation:"Cuộc họp dự kiến bắt đầu lúc 3 giờ."},{sentence:"今年の夏、友だちの結婚式に出席する予定です。",translation:"Mùa hè năm nay tôi dự kiến dự đám cưới của bạn."}],note:"Cũng dùng được với danh từ: 出張の予定です。Phủ định: 予定はありません / 予定がありません.",dialogue:{jp:"A：来週の土曜日は何か予定がありますか。\nB：友だちと映画を見る予定です。",vi:"A: Thứ Bảy tuần sau bạn có kế hoạch gì không?\nB: Tôi có kế hoạch đi xem phim với bạn."},commonMistake:{wrong:"来月、出張に行く予定をしています。",correct:"来月、出張に行く予定です。",why:"Tương tự つもり, 予定 cũng là danh từ hình thức dùng với です (Vる予定です), không chia thành 〜をしています. Nhầm lẫn phổ biến là coi 予定 như một hành động đang diễn ra thay vì một trạng thái lịch trình đã định."},related:["Vるつもりです","Nがあります"],kitsuPrompt:"Hỏi tôi lịch công tác hay kế hoạch cuối tuần. Tôi sẽ dùng 〜予定です."},{pattern:"まだVていません",meaning:"chưa ~ (hành động chưa hoàn thành)",priority:"medium",explanation:"まだ + Vていません biểu thị hành động chưa xảy ra mặc dù dự kiến hoặc đáng lẽ đã xảy ra. Khác với 〜ていません đơn thuần (chỉ trạng thái hiện tại không làm).",examples:[{sentence:"まだ宿題をやっていません。",translation:"Tôi chưa làm bài tập về nhà."},{sentence:"まだ昼ごはんを食べていません。",translation:"Tôi chưa ăn trưa."},{sentence:"映画はまだ見ていません。",translation:"Bộ phim đó tôi chưa xem."}],note:"もう〜ましたか（rồi chưa?）→ まだ〜ていません（chưa）là cặp hỏi-đáp phổ biến.",dialogue:{jp:"A：もうレポートを出しましたか。\nB：いいえ、まだ出していません。明日出す予定です。",vi:"A: Bạn đã nộp báo cáo chưa?\nB: Chưa ạ, tôi chưa nộp. Dự kiến nộp ngày mai."},commonMistake:{wrong:"今朝からまだ何も食べませんでした。",correct:"今朝からまだ何も食べていません。",why:"まだ diễn tả một việc tính đến hiện tại vẫn chưa xảy ra dù đáng lẽ đã xảy ra, nên phải dùng thể tiếp diễn phủ định 〜ていません để nối kết quá khứ với hiện tại. 〜ませんでした chỉ một sự việc đã hoàn toàn kết thúc trong quá khứ, không phù hợp khi đi cùng まだ."},related:["もうVました","Vていません"],kitsuPrompt:"Hỏi tôi về những việc tôi chưa làm xong. Tôi sẽ dùng まだ〜ていません."}]},{bai:32,level:"N4",kanji:"勧",reading:"すすめる",romaji:"Susumeru",titleVi:"Lời khuyên & dự đoán",titleJp:"助言と推量",descVi:'Khuyên "nên làm" với たほうがいい và dự đoán với でしょう・かもしれない.',selfCheckGoals:["Đưa ra lời khuyên bằng たほうがいい và ないほうがいい trong 3 tình huống","Phân biệt でしょう (đoán chắc hơn) và かもしれない (đoán không chắc)","Dùng のではないでしょうか để đưa ra dự đoán lịch sự",'Trả lời khi được hỏi "どうしたらいいですか" một cách tự nhiên'],readingPassage:{title:"健康アドバイス",titleVi:"Lời khuyên về sức khỏe",japanese:"最近、田中さんはあまり眠れていないようです。毎日夜遅くまでゲームをしているので、体に良くないでしょう。早めに寝たほうがいいと思います。また、コーヒーを飲みすぎないほうがいいかもしれません。ストレスが原因かもしれませんから、週末に散歩してみてはどうでしょうか。",vietnamese:"Dạo này có vẻ như Tanaka-san không ngủ đủ giấc. Vì chơi game đến khuya mỗi ngày nên chắc không tốt cho cơ thể. Tôi nghĩ nên đi ngủ sớm hơn. Ngoài ra, có lẽ không nên uống quá nhiều cà phê. Vì có thể là do căng thẳng, nên sao không thử đi dạo vào cuối tuần nhỉ?",highlights:[{excerpt:"良くないでしょう",label:"dự đoán でしょう"},{excerpt:"寝たほうがいい",label:"lời khuyên"},{excerpt:"ないほうがいいかもしれません",label:"không nên + có thể"},{excerpt:"ストレスが原因かもしれません",label:"đoán không chắc"}],questions:[{q:"筆者は田中さんに何をすすめていますか。",options:["早く寝ること","もっとゲームをすること","コーヒーを飲むこと","仕事を休むこと"],answer:0},{q:"田中さんがよく眠れない原因として、何が考えられますか。",options:["ストレス","運動不足","食べ過ぎ","寒さ"],answer:0}]},patterns:[{pattern:"Vたほうがいいです",meaning:"nên làm (lời khuyên)",priority:"high",explanation:'V thể た + ほうがいい biểu thị lời khuyên nhẹ nhàng "nên làm thì tốt hơn". Thường đi kèm với よ để nhấn mạnh sự quan tâm.',examples:[{sentence:"熱があるなら、病院へ行ったほうがいいですよ。",translation:"Nếu có sốt thì nên đi bệnh viện đó."},{sentence:"雨が降るから、傘を持ったほうがいいです。",translation:"Trời mưa nên mang ô theo thì tốt hơn."},{sentence:"もっと野菜を食べたほうがいいと思います。",translation:"Tôi nghĩ bạn nên ăn nhiều rau hơn."}],note:"Thể た ở đây không có nghĩa là quá khứ — đây là dạng đặc biệt của ngữ pháp ほうがいい.",dialogue:{jp:"A：最近、頭が痛いんです。\nB：それは大変ですね。病院へ行ったほうがいいですよ。",vi:"A: Dạo này đầu tôi hay đau.\nB: Vậy thì vất vả nhỉ. Nên đi bệnh viện đó."},commonMistake:{wrong:"もっと野菜を食べるほうがいいです。",correct:"もっと野菜を食べたほうがいいです。",why:'Khi đưa lời khuyên trực tiếp "nên làm gì", tiếng Nhật dùng V thể た + ほうがいい (thể た ở đây không mang nghĩa quá khứ mà là quy tắc cố định của mẫu này). V thể từ điển + ほうがいい chỉ tự nhiên khi so sánh giữa hai lựa chọn, không dùng để khuyên bảo trực tiếp như câu này.'},related:["Vないほうがいいです","Vたらどうですか"],kitsuPrompt:"Nói tôi đang mệt, ít ngủ. Hãy đưa ra 2-3 lời khuyên bằng たほうがいいですよ."},{pattern:"Vないほうがいいです",meaning:"không nên làm (lời khuyên tránh)",priority:"high",explanation:'V thể ない + ほうがいい biểu thị lời khuyên "không nên làm ~ thì tốt hơn". Thường mang nghĩa cảnh báo nhẹ.',examples:[{sentence:"体が悪いから、タバコを吸わないほうがいいです。",translation:"Vì sức khỏe xấu nên không hút thuốc thì tốt hơn."},{sentence:"試験前にゲームをしないほうがいいよ。",translation:"Trước khi thi không nên chơi game đâu nhé."},{sentence:"風邪がうつるから、人と会わないほうがいいと思います。",translation:"Vì lây cảm nên tôi nghĩ không nên gặp người khác."}],note:"Cặp たほうがいい / ないほうがいい rất thực dụng trong hội thoại hàng ngày khi khuyên bảo.",dialogue:{jp:"A：夜、一人で歩いても大丈夫ですか。\nB：あのエリアは暗いから、一人で歩かないほうがいいですよ。",vi:"A: Tối đi một mình được không?\nB: Khu đó tối lắm, không nên đi một mình đâu."},commonMistake:{wrong:"お酒を飲まないほうがいくないです。",correct:"お酒を飲まないほうがいいです。",why:'ほうがいい đã mang nghĩa khẳng định trọn vẹn "tốt hơn"; ý phủ định của câu đã nằm ở động từ đứng trước (飲まない), nên không cần và không được phủ định thêm いい. Ngoài ra いい là tính từ bất quy tắc, nếu phủ định phải chia thành よくない chứ không phải いくない — nhưng ở mẫu ないほうがいい thì hoàn toàn không phủ định いい nữa.'},related:["Vたほうがいいです","Vてはいけません"],kitsuPrompt:"Hỏi tôi có thói quen gì xấu không. Sau đó khuyên bằng ないほうがいい."},{pattern:"〜でしょう",meaning:"chắc là ~ / có lẽ ~ (đoán khá chắc)",priority:"medium",explanation:"でしょう theo sau V/A/N thể bình thường biểu thị phỏng đoán với độ tự tin cao hơn かもしれない. Thường nghe trong dự báo thời tiết và nhận định.",examples:[{sentence:"明日は晴れるでしょう。",translation:"Ngày mai chắc trời sẽ nắng."},{sentence:"田中さんはもう知っているでしょう。",translation:"Tanaka-san chắc đã biết rồi."},{sentence:"この問題は難しいでしょう。",translation:"Bài toán này chắc khó đấy."}],note:"Lịch sự hóa: でしょう. Thân mật: だろう. Câu hỏi: 〜でしょうか (lịch sự hơn ですか).",dialogue:{jp:"A：山田さんは来るでしょうか。\nB：メッセージを送ったから、来るでしょう。",vi:"A: Yamada-san có đến không nhỉ?\nB: Đã nhắn tin rồi nên chắc đến thôi."},commonMistake:{wrong:"明日は雨が降るでしょうです。",correct:"明日は雨が降るでしょう。",why:"でしょう bản thân đã là dạng lịch sự hoàn chỉnh để đưa ra phỏng đoán (tương đương だろう đã được lịch sự hóa), nên không được thêm です phía sau — việc thêm です là dư thừa và sai ngữ pháp vì でしょう không cần trợ động từ lịch sự nào khác đi kèm."},related:["〜かもしれません","〜と思います"],kitsuPrompt:"Hỏi tôi dự đoán về thời tiết hoặc kết quả thi. Tôi sẽ dùng でしょう để đoán."},{pattern:"〜かもしれません",meaning:"có thể ~ (đoán không chắc, 50%)",priority:"high",explanation:"かもしれない / かもしれません theo sau V/A/N thể bình thường biểu thị khả năng xảy ra khoảng 50%, không chắc chắn.",examples:[{sentence:"田中さんは今日来ないかもしれません。",translation:"Tanaka-san hôm nay có thể không đến."},{sentence:"試験に合格したかもしれない。",translation:"Có thể tôi đã đậu kỳ thi."},{sentence:"この店はもう閉まっているかもしれませんね。",translation:"Cửa hàng này có thể đã đóng cửa rồi nhỉ."}],note:"かもしれない < でしょう < に違いない (theo thứ tự tự tin tăng dần)",dialogue:{jp:"A：あれ、鍵がない。\nB：車の中に置いてきたかもしれないよ。",vi:"A: Ơ, không thấy chìa khóa.\nB: Có thể để quên trong xe rồi đấy."},commonMistake:{wrong:"田中さんは今日来るかもしれないです。",correct:"田中さんは今日来るかもしれません。",why:"かもしれない ghép thêm です (かもしれないです) không sai hẳn về ngữ pháp nhưng nghe kém tự nhiên và ít dùng trong văn viết/nói lịch sự chuẩn mực. Dạng chuẩn, tự nhiên và phổ biến hơn là chia trực tiếp thành かもしれません thay vì gắn ない+です."},related:["〜でしょう","〜らしい"],kitsuPrompt:"Hỏi tôi điều gì đó không chắc, như kết quả thi hay thời tiết. Tôi sẽ đoán bằng かもしれません."}]},{bai:33,level:"N4",kanji:"命",reading:"めいれい",romaji:"Meirei",titleVi:"Mệnh lệnh & cấm chỉ",titleJp:"命令形・禁止形",descVi:"Dùng thể mệnh lệnh mạnh và cấm tuyệt đối trong ngữ cảnh thực tế.",selfCheckGoals:["Chia được V命令形 của 5 động từ nhóm I, II, III","Nhận ra ngữ cảnh dùng mệnh lệnh (biển báo, thể thao, khẩn cấp)","Dùng という để giải thích tên/khái niệm lạ","Đọc câu có N と読みます một cách tự nhiên"],readingPassage:{title:"緊急避難の案内",titleVi:"Hướng dẫn thoát hiểm khẩn cấp",japanese:"火事や地震が起きたとき、まず落ち着け。パニックになるな。「非常口」という表示を探して、その方向へ走れ。エレベーターは使うな。階段を使え。外に出たら、「集合場所」と書いてある場所に集まること。係員の指示に従え。",vietnamese:'Khi xảy ra hỏa hoạn hay động đất, trước tiên hãy bình tĩnh. Đừng hoảng loạn. Tìm biển hiệu gọi là "Lối thoát hiểm" rồi chạy theo hướng đó. Đừng dùng thang máy. Hãy dùng cầu thang. Ra ngoài rồi, hãy tập trung ở nơi có ghi "Điểm tập kết". Hãy tuân theo chỉ dẫn của nhân viên.',highlights:[{excerpt:"落ち着け",label:"V命令形"},{excerpt:"パニックになるな",label:"Vるな cấm"},{excerpt:"「非常口」という表示",label:"という説明"},{excerpt:"エレベーターは使うな",label:"cấm dùng"}],questions:[{q:"火事のとき、エレベーターを使ってもいいですか。",options:["いいえ、使ってはいけません","はい、使ってもいいです","場合によります","わかりません"],answer:0},{q:"外に出たら、どこへ行きますか。",options:["集合場所","非常口","階段","エレベーター"],answer:0}]},patterns:[{pattern:"V命令形",meaning:"Hãy làm! (mệnh lệnh mạnh)",priority:"medium",explanation:"Thể mệnh lệnh (imperative) rất thô, mạnh. Nhóm I: âm cuối い→え (書く→書け, 話す→話せ). Nhóm II: bỏ る+ろ (食べる→食べろ). Nhóm III: しろ／来い. Dùng trong biển báo, thể thao, tình huống khẩn cấp.",examples:[{sentence:"早く起きろ！",translation:"Dậy mau lên!"},{sentence:"止まれ！（道路標識）",translation:"Dừng lại! (biển báo)"},{sentence:"頑張れ！",translation:"Cố lên!"}],note:"Không dùng trong hội thoại lịch sự thông thường. Thay bằng 〜てください hoặc 〜なさい (dịu hơn).",dialogue:{jp:"（コーチ）：もっと走れ！諦めるな！\n（選手）：はい！",vi:"(Huấn luyện viên): Chạy thêm nào! Đừng bỏ cuộc!\n(Vận động viên): Vâng!"},commonMistake:{wrong:"毎朝五時に起きますろ。",correct:"毎朝五時に起きろ。",why:"Thể mệnh lệnh (V命令形) không được tạo bằng cách chia từ dạng ます rồi thêm ろ. Với động từ nhóm II (bỏ る, thêm ろ): 起きる→起きろ, 食べる→食べろ. Nhiều học viên nhầm lẫn ghép ますれ hoặc ますろ vào sau thể ます, nhưng thể mệnh lệnh phải chia trực tiếp từ thể từ điển, không qua thể ます."},related:["Vてください","Vなさい","Vるな"],kitsuPrompt:"Đóng vai huấn luyện viên thể thao, dùng V命令形 để chỉ đạo tôi trong buổi tập."},{pattern:"Vるな (禁止)",meaning:"Cấm làm! (cấm tuyệt đối, mạnh)",priority:"medium",explanation:"V thể từ điển + な biểu thị lệnh cấm rất mạnh. Dùng trong biển báo, tình huống nguy hiểm, hoặc giữa bạn bè thân mật (nửa đùa). Không dùng với người trên.",examples:[{sentence:"立入禁止：入るな。",translation:"Cấm vào! (biển báo)"},{sentence:"危ないから、触るな！",translation:"Nguy hiểm đó, đừng chạm vào!"},{sentence:"嘘をつくな！",translation:"Đừng nói dối!"}],note:"Trong văn nói thân mật: 走るなよ (nhẹ hơn). Lịch sự hơn: 走らないでください.",dialogue:{jp:"A：（工事現場）危ないから、ここに入るな！\nB：すみません、知りませんでした。",vi:"A: (Công trường xây dựng) Nguy hiểm lắm, đừng vào đây!\nB: Xin lỗi, tôi không biết."},commonMistake:{wrong:"そこに入るなです。",correct:"そこに入るな。",why:"な trong Vるな (禁止) là trợ từ chỉ mệnh lệnh cấm đặt cuối câu, bản thân nó đã mang tính kết thúc câu và sắc thái mạnh/thô, nên không thể thêm です phía sau như một danh từ hay tính từ. Nếu muốn lịch sự hơn thì phải đổi hẳn cấu trúc, dùng 〜ないでください chứ không phải gắn です vào Vるな."},related:["V命令形","Vないでください","Vてはいけません"],kitsuPrompt:"Mô tả một công trường xây dựng. Hãy đặt 3 biển cấm khác nhau bằng Vるな."},{pattern:"Nと読みます／書きます",meaning:"đọc là ~ / viết là ~ (giải thích ký tự)",priority:"low",explanation:"Dùng と để trích dẫn cách đọc hoặc cách viết của một từ/ký tự. Rất hữu ích khi giới thiệu từ mới hoặc giải thích chữ Hán.",examples:[{sentence:"この漢字は「やま」と読みます。",translation:'Chữ Hán này đọc là "yama".'},{sentence:"名前は漢字で「山田」と書きます。",translation:'Tên viết bằng chữ Hán là "Yamada".'},{sentence:"「寿司」は「すし」と読みます。",translation:'"寿司" đọc là "sushi".'}],note:"Cũng dùng: 〜と言います（gọi là, nói là）cho từ vựng/tên gọi.",dialogue:{jp:"A：この字、何と読みますか。\nB：「いずみ」と読みます。私の名前です。",vi:'A: Chữ này đọc là gì?\nB: Đọc là "Izumi". Đó là tên tôi.'},commonMistake:{wrong:"この字を「やま」と読みます。",correct:"この字は「やま」と読みます。",why:"Trong mẫu Nと読みます／書きます, danh từ chỉ chủ đề đang được giải thích cách đọc/viết phải đi với trợ từ は (hoặc lược bỏ trợ từ trong văn nói: この字、「やま」と読みます), không dùng を vì đây không phải là tân ngữ của hành động 読む mà là chủ đề đang được nói đến."},related:["〜という N","〜と言います"],kitsuPrompt:"Hỏi tôi tên tiếng Nhật của một thứ gì đó. Tôi sẽ trả lời bằng 〜と読みます / と書きます."},{pattern:"〜というN",meaning:"N gọi là ~ / N có tên là ~",priority:"high",explanation:"〜という + N dùng để giải thích hoặc giới thiệu một khái niệm, tên gọi, hoặc thông tin chưa biết với người nghe. Rất phổ biến trong văn nói.",examples:[{sentence:"「居酒屋」というお店に行ってみたいです。",translation:'Tôi muốn thử đến cửa hàng gọi là "izakaya".'},{sentence:"「わびさび」という考え方は日本独特です。",translation:'Khái niệm gọi là "wabi-sabi" là nét riêng của Nhật Bản.'},{sentence:"キムさんという友だちがいます。",translation:"Tôi có người bạn tên là Kim."}],note:"Dùng để giải thích tên người, địa danh, khái niệm lạ. こと/の có thể thêm: 〜ということ (việc được gọi là ~).",dialogue:{jp:"A：「花見」って何ですか。\nB：「花見」というのは、桜の木の下でお酒を飲んだり、食事をしたりすることです。",vi:'A: "Hanami" là gì vậy?\nB: "Hanami" là việc uống rượu, ăn uống dưới cây anh đào.'},commonMistake:{wrong:"「居酒屋」というな店に行きたいです。",correct:"「居酒屋」というお店に行きたいです。",why:"Trong mẫu 〜というN, sau という phải là danh từ (N) đi ngay liền, không được chèn thêm な vào giữa という và danh từ. な chỉ dùng sau tính từ na-keiyoushi (như 静かな), còn という là một cụm cố định đóng vai trò định ngữ cho danh từ theo sau, cấu trúc đúng luôn là 「〜」という + N."},related:["〜と言います","Nと読みます"],kitsuPrompt:"Hỏi tôi về một từ tiếng Việt thú vị. Tôi sẽ dùng 〜というのは〜ことです để giải thích."}]},{bai:34,level:"N4",kanji:"通",reading:"とおり",romaji:"Toori",titleVi:"Theo như & để nguyên",titleJp:"とおり・あと・まま",descVi:"Dùng とおりに, あとで và まま để diễn tả thứ tự và trạng thái duy trì.",selfCheckGoals:["Dùng とおりに với cả V た và N の một cách chính xác","Phân biệt あとで (sau khi, thứ tự) và から (nên vì, nguyên nhân)","Mô tả trạng thái để nguyên bằng まま trong 3 câu","Nhận biết まま trong văn bản và hiểu đúng nghĩa"],readingPassage:{title:"料理のレシピ通りに",titleVi:"Nấu theo công thức",japanese:"今日、母のレシピ通りにカレーを作ってみました。材料を切ったあとで、鍋に入れて煮ます。蓋を開けたまま、弱火で30分煮てください。火を止めたあとで、カレールーを入れます。食べてみたら、母が作ったのと同じ味でした。レシピ通りに作るのは大切だと思いました。",vietnamese:"Hôm nay tôi thử nấu cà ri theo công thức của mẹ. Sau khi cắt nguyên liệu, cho vào nồi rồi nấu. Hãy nấu ở lửa nhỏ 30 phút với nắp để mở. Sau khi tắt bếp, cho khối cà ri vào. Ăn thử thì vị giống hệt cái mẹ nấu. Tôi nghĩ việc nấu đúng theo công thức rất quan trọng.",highlights:[{excerpt:"レシピ通りに",label:"theo như ~ (Nのとおりに)"},{excerpt:"切ったあとで",label:"sau khi ~"},{excerpt:"蓋を開けたまま",label:"để nguyên trạng thái"},{excerpt:"火を止めたあとで",label:"sau khi ~"}],questions:[{q:"カレーを作るとき、蓋をどうしますか。",options:["開けたまま煮る","閉めたまま煮る","途中で取る","どちらでもいい"],answer:0},{q:"カレールーはいつ入れますか。",options:["火を止めたあと","材料を切ったあと","最初に","蓋を閉める前"],answer:0}]},patterns:[{pattern:"V／Nのとおりに",meaning:"theo như ~ / đúng như ~",priority:"medium",explanation:"〜とおりに biểu thị hành động được thực hiện đúng theo khuôn mẫu, hướng dẫn, hoặc sự mong đợi. Theo sau: V た + とおりに, N + のとおりに.",examples:[{sentence:"先生が言ったとおりに書いてください。",translation:"Hãy viết đúng như thầy đã nói."},{sentence:"地図のとおりに行ったら、すぐ着きました。",translation:"Đi đúng theo bản đồ thì đến ngay."},{sentence:"計画通りに仕事が進んでいます。",translation:"Công việc đang tiến hành đúng theo kế hoạch."}],note:"通り / とおり cũng dùng như danh từ độc lập: 計画通り (đúng theo kế hoạch), 予想通り (đúng như dự đoán).",dialogue:{jp:"A：薬の飲み方がわかりますか。\nB：はい、説明書に書いてあるとおりに飲みます。",vi:"A: Bạn biết cách uống thuốc chưa?\nB: Vâng, tôi uống đúng theo hướng dẫn ghi trong tờ giấy."},commonMistake:{wrong:"先生が言うとおりに書きました。",correct:"先生が言ったとおりに書きました。",why:"Khi nói về việc đã làm theo lời/hướng dẫn đã xảy ra rồi (quá khứ), động từ đứng trước とおりに nên chia ở thể た (言った) chứ không phải thể từ điển (言う), vì とおりに mô tả hành động được thực hiện đúng theo điều đã được nói/chỉ dẫn trước đó. Ngoài ra khi dùng với danh từ, phải có の: 地図のとおりに, không được bỏ の thành 地図とおりに."},related:["〜ように","〜にしたがって"],kitsuPrompt:"Hỏi tôi về một hướng dẫn tôi cần làm theo. Tôi sẽ dùng 〜とおりに."},{pattern:"Vたあとで",meaning:"sau khi V (thứ tự hành động)",priority:"high",explanation:"V thể た + あとで biểu thị hành động thứ hai xảy ra sau khi hành động thứ nhất hoàn thành. Khác với てから ở chỗ あとで không nhấn mạnh quan hệ nhân quả.",examples:[{sentence:"食事のあとで、薬を飲んでください。",translation:"Sau bữa ăn hãy uống thuốc."},{sentence:"宿題をしたあとで、テレビを見ます。",translation:"Sau khi làm bài tập tôi xem TV."},{sentence:"仕事が終わったあとで、飲みに行きましょう。",translation:"Sau khi xong việc hãy đi uống nhé."}],note:"N + のあとで: 食事のあとで. Khác với 〜てから: てから nhấn mạnh thứ tự nhân quả, あとで thuần túy về thời gian.",dialogue:{jp:"A：いつ返事を書きますか。\nB：会議が終わったあとで、すぐ書きます。",vi:"A: Khi nào bạn viết thư trả lời?\nB: Sau khi cuộc họp kết thúc tôi sẽ viết ngay."},commonMistake:{wrong:"薬を食べるあとで、少し休みます。",correct:"薬を食べたあとで、少し休みます。",why:"Vたあとで bắt buộc động từ phía trước phải chia ở thể た (quá khứ) để thể hiện hành động đã hoàn thành trước, không được dùng thể từ điển (食べる). Ngoài ra cũng tránh lỗi thừa て: không viết 食べてのあとで, vì あとで chỉ cần theo sau trực tiếp thể た, không cần thêm の hay て."},related:["Vてから","Vるまえに"],kitsuPrompt:"Hỏi tôi thói quen hàng ngày sau giờ làm. Tôi sẽ dùng 〜たあとで để mô tả."},{pattern:"V／Aいまま",meaning:"để nguyên trạng thái ~ (không thay đổi)",priority:"high",explanation:"〜まま biểu thị trạng thái tiếp tục từ hành động trước mà không có thay đổi. Dùng với: V た まま (trạng thái sau khi V), V ない まま (trạng thái không V).",examples:[{sentence:"電気をつけたまま、寝てしまいました。",translation:"Tôi để đèn bật rồi ngủ quên."},{sentence:"靴を履いたまま、家に入らないでください。",translation:"Xin đừng vào nhà mà vẫn mang giày."},{sentence:"財布を忘れたまま、出かけてしまいました。",translation:"Tôi đi ra ngoài mà quên mang ví."}],note:"V ない まま: 何も言わないまま、帰ってしまった (Ra về mà không nói gì). A い まま: 熱いまま食べないで (Đừng ăn khi còn nóng).",dialogue:{jp:"A：コートを着たまま、入ってもいいですか。\nB：ここは暖かいから、脱いでください。",vi:"A: Tôi vào mà vẫn mặc áo khoác có được không?\nB: Ở đây ấm lắm, hãy cởi ra."},commonMistake:{wrong:"窓を開けているまま、寝てしまいました。",correct:"窓を開けたまま、寝てしまいました。",why:"〜まま diễn tả trạng thái được giữ nguyên sau một hành động đã hoàn tất, nên phải dùng V thể た (開けた) chứ không dùng thể ている (開けている) vì ている nhấn mạnh hành động đang tiếp diễn chứ không phải trạng thái để nguyên sau khi làm xong. Cũng lưu ý dạng phủ định 開けないまま không cần thêm で phía sau, chỉ cần ないまま là đủ."},related:["〜ている","〜にしたまま"],kitsuPrompt:"Hỏi tôi về những lần tôi vô tình để nguyên gì đó. Tôi sẽ kể bằng 〜たまま."}]},{bai:35,level:"N4",kanji:"仮",reading:"かてい",romaji:"Katei",titleVi:"Điều kiện ば & なら",titleJp:"条件形",descVi:"Thêm hai dạng điều kiện: ば-form và なら cho các ngữ cảnh khác nhau.",selfCheckGoals:["Chia đúng V/Aば-form của 5 từ khác nhau (nhóm I, II, III và tính từ)","Phân biệt たら (kết quả cụ thể) và ば (điều kiện giả định)","Dùng なら khi phản hồi thông tin của người khác","Hỏi lời khuyên bằng 疑問詞+たらいい một cách tự nhiên"],readingPassage:{title:"旅行の相談",titleVi:"Tư vấn du lịch",japanese:"A：来月、日本へ旅行するんですが、どこへ行ったらいいでしょうか。\nB：日本へ行くなら、ぜひ京都がいいですよ。古い建物がたくさんあります。\nA：予算が少なければ、安い宿泊先はありますか。\nB：予算が少ないなら、ゲストハウスがお勧めです。一泊三千円ぐらいで泊まれますよ。\nA：そうですか。ありがとうございます！",vietnamese:"A: Tháng sau tôi đi du lịch Nhật Bản, nên đến đâu thì tốt nhỉ?\nB: Nếu đi Nhật thì nhất định nên đến Kyoto. Ở đó có nhiều công trình cổ lắm.\nA: Nếu ngân sách ít thì có chỗ ở rẻ không?\nB: Nếu ngân sách ít thì tôi khuyên nên ở nhà khách. Có thể ở với giá khoảng 3000 yên một đêm đó.",highlights:[{excerpt:"どこへ行ったらいいでしょうか",label:"疑問詞+たらいい"},{excerpt:"日本へ行くなら",label:"なら điều kiện"},{excerpt:"予算が少なければ",label:"Aば điều kiện"},{excerpt:"予算が少ないなら",label:"なら phản hồi"}],questions:[{q:"Bに聞くと、日本のどこへ行くといいと言いましたか。",options:["京都","東京","大阪","北海道"],answer:0},{q:"予算が少ない場合、Bは何を勧めましたか。",options:["ゲストハウス","ホテル","旅館","ユースホステル"],answer:0}]},patterns:[{pattern:"V／Aば",meaning:"nếu ~ (điều kiện giả định)",priority:"high",explanation:"Thể ば (provisional conditional) biểu thị điều kiện giả định. V nhóm I: âm cuối い→えば (書く→書けば). V nhóm II: bỏ る+れば. A い: bỏ い+ければ. Không dùng với hành động ý chí/yêu cầu ở vế sau.",examples:[{sentence:"安ければ、買います。",translation:"Nếu rẻ thì tôi mua."},{sentence:"早く来れば、間に合います。",translation:"Nếu đến sớm thì kịp."},{sentence:"天気が良ければ、ピクニックに行きましょう。",translation:"Nếu thời tiết đẹp hãy đi dã ngoại."}],note:"ば thường dùng cho điều kiện tự nhiên/khách quan. たら thường dùng cho điều kiện cụ thể hơn, kết quả sau khi xảy ra.",dialogue:{jp:"A：この薬を飲めば、すぐ良くなりますか。\nB：はい、ちゃんと飲めば、3日で治りますよ。",vi:"A: Nếu uống thuốc này thì hết ngay không?\nB: Vâng, nếu uống đúng giờ thì 3 ngày là khỏi."},commonMistake:{wrong:"安ければ、買ってください。",correct:"安かったら、買ってください。",why:"Thể ば không được dùng khi vế sau là câu yêu cầu, mệnh lệnh hay ý chí của người nói (như てください, ましょう, たい). Trong trường hợp đó phải chuyển sang dùng たら (安かったら) vì たら có thể kết hợp tự nhiên với các vế sau mang tính yêu cầu/ý chí, còn ば chỉ hợp với điều kiện khách quan, tự nhiên, không kèm mệnh lệnh."},related:["Vたら","Vなら","Vと"],kitsuPrompt:'Đặt câu hỏi điều kiện "nếu... thì sao?" về cuộc sống hàng ngày. Tôi sẽ dùng ば.'},{pattern:"Nなら／V普通形なら",meaning:"nếu là ~ thì (phản hồi chủ đề, gợi ý)",priority:"high",explanation:"なら dùng khi phản hồi với thông tin vừa nhận được từ người khác hoặc giả định về chủ đề vừa đề cập. Thường mang hàm ý tư vấn, gợi ý.",examples:[{sentence:"日本語を学ぶなら、この教科書がいいですよ。",translation:"Nếu học tiếng Nhật thì cuốn giáo trình này tốt đó."},{sentence:"寿司が食べたいなら、あそこのお店がおいしいよ。",translation:"Nếu muốn ăn sushi thì tiệm đó ngon đấy."},{sentence:"A：明日、大阪へ行くんです。B：大阪へ行くなら、たこ焼きを食べてね。",translation:"A: Ngày mai tôi đi Osaka. B: Nếu đi Osaka thì nhớ ăn takoyaki nhé."}],note:'なら nhấn mạnh rằng "giả sử điều bạn nói là đúng, thì...". Thường theo sau thông tin người khác vừa chia sẻ.',dialogue:{jp:"A：パソコンを買いたいんですが。\nB：パソコンを買うなら、あのお店が安いですよ。",vi:"A: Tôi muốn mua máy tính.\nB: Nếu mua máy tính thì cửa hàng kia rẻ đó."},commonMistake:{wrong:"A：明日、大阪へ行くんです。B：大阪へ行くのなら、たこ焼きを食べてね。",correct:"A：明日、大阪へ行くんです。B：大阪へ行くなら、たこ焼きを食べてね。",why:"Sau động từ ở thể thường (行く), thêm の trước なら (行くのなら) tuy không sai ngữ pháp nhưng nghe hơi sách vở, trang trọng thái quá cho văn nói thông thường. Trong hội thoại tự nhiên hàng ngày, người Nhật thường bỏ の và nói thẳng 行くなら. の chỉ hay xuất hiện khi muốn nhấn mạnh giải thích lý do (thường đi với んです/のです)."},related:["Vば","Vたら","Vと"],kitsuPrompt:"Hỏi tôi về dự định học tiếng Nhật. Sau đó tư vấn phương pháp bằng 〜なら."},{pattern:"疑問詞＋V／Aたらいい",meaning:"nên ~ cái gì/ở đâu/thế nào? (xin lời khuyên)",priority:"high",explanation:"疑問詞 (何, どこ, どう, いつ...) + V たらいい = cấu trúc xin lời khuyên về hành động nên làm. Thường kết thúc bằng ですか hoặc でしょうか.",examples:[{sentence:"日本語を勉強するには、何をしたらいいですか。",translation:"Để học tiếng Nhật thì nên làm gì?"},{sentence:"この荷物、どこに置いたらいいですか。",translation:"Đồ vật này tôi nên để ở đâu?"},{sentence:"道が込んでいます。どう行ったらいいでしょうか。",translation:"Đường tắc nghẽn. Nên đi thế nào nhỉ?"}],note:"Trả lời bằng 〜たほうがいいですよ hoặc 〜するといいですよ.",dialogue:{jp:"A：日本語がうまくなるには、どうしたらいいですか。\nB：毎日少しずつ練習したらいいですよ。",vi:"A: Để giỏi tiếng Nhật thì nên làm thế nào?\nB: Nên luyện tập mỗi ngày một chút là được."},commonMistake:{wrong:"道が込んでいます。どう行けばいいでしょうか。",correct:"道が込んでいます。どう行ったらいいでしょうか。",why:"Cả 〜ばいい và 〜たらいい đều dùng để xin lời khuyên và về mặt ngữ pháp không sai, nhưng trong văn nói tự nhiên của người Nhật, mẫu 疑問詞+Vたらいいですか phổ biến và tự nhiên hơn hẳn 疑問詞+Vばいいですか khi hỏi ý kiến trực tiếp. Học viên hay chọn ば vì quen mẫu điều kiện, nhưng nên ưu tiên たら trong ngữ cảnh xin lời khuyên."},related:["Vたほうがいいです","Vたら（どうですか）"],kitsuPrompt:"Tôi sẽ hỏi bạn lời khuyên bằng 何をしたらいいですか. Bạn hãy trả lời bằng 〜たほうがいいですよ."}]},{bai:36,level:"N4",kanji:"為",reading:"ため",romaji:"Tame",titleVi:"Mục tiêu & thay đổi",titleJp:"目標と変化",descVi:"Nói cố gắng để (〜ように) và trở nên có thể (〜ようになる).",selfCheckGoals:['Dùng ように sau V可能形 để nói mục tiêu "để có thể làm được"',"Phân biệt ようになる (thay đổi tự nhiên) và ようにする (cố ý)","Kể về sự thay đổi tích cực của bản thân bằng ようになりました","Nói quyết tâm mới bằng ようにしています trong 2 câu"],readingPassage:{title:"日本語の上達",titleVi:"Tiến bộ trong tiếng Nhật",japanese:"一年前、私は日本語が全然話せませんでした。でも、毎日練習するようにしてから、だんだん話せるようになりました。今は簡単な会話なら、できるようになりました。単語を忘れないように、毎日手帳に書くようにしています。来年はN3に合格できるように、もっと頑張ります。",vietnamese:"Một năm trước tôi không nói được tiếng Nhật chút nào. Nhưng từ khi cố gắng luyện tập mỗi ngày, dần dần tôi đã có thể nói được. Bây giờ với hội thoại đơn giản thì tôi đã làm được rồi. Để không quên từ vựng, tôi đang cố gắng ghi vào sổ tay mỗi ngày. Năm sau tôi sẽ cố hơn nữa để có thể đậu N3.",highlights:[{excerpt:"毎日練習するようにしてから",label:"cố ý thay đổi hành vi"},{excerpt:"話せるようになりました",label:"thay đổi tự nhiên"},{excerpt:"単語を忘れないように",label:"ように mục tiêu"},{excerpt:"N3に合格できるように",label:"ように mục đích"}],questions:[{q:"筆者は今、日本語について何ができるようになりましたか。",options:["簡単な会話","ビジネス敬語","専門用語","スピーチ"],answer:0},{q:"筆者は単語を忘れないために何をしていますか。",options:["手帳に書く","アプリを使う","友だちと話す","先生に聞く"],answer:0}]},patterns:[{pattern:"Vる／Vないように",meaning:"để ~ / để không ~ (hướng đến mục tiêu)",priority:"high",explanation:"〜ように biểu thị mục đích hoặc nỗ lực hướng đến trạng thái mong muốn. Thường theo sau V 可能形 (để có thể ~) hoặc V ない (để không ~). Khác với ために: ように dùng với V可能 và V ない, ために dùng với V ý chí.",examples:[{sentence:"遅刻しないように、早く起きます。",translation:"Để không đi muộn tôi dậy sớm."},{sentence:"漢字が書けるように、毎日練習しています。",translation:"Để có thể viết kanji tôi luyện tập mỗi ngày."},{sentence:"健康のために、運動するようにしています。",translation:"Vì sức khỏe tôi đang cố gắng tập thể dục."}],note:"ように + 言います/頼みます = gián tiếp truyền đạt yêu cầu: 静かにするように言ってください (nhờ nói hãy yên lặng).",dialogue:{jp:"A：どうして毎朝ジョギングするんですか。\nB：健康でいられるように、走るようにしているんです。",vi:"A: Sao mỗi sáng bạn đi chạy bộ vậy?\nB: Tôi đang cố chạy để giữ sức khỏe."},commonMistake:{wrong:"太らないために、食べすぎないようにしています。",correct:"太らないように、食べすぎないようにしています。",why:"Học viên hay lẫn ために và ように: ために đi theo sau động từ Ý CHÍ (thể từ điển mang tính chủ động rõ ràng như 勉強するために), còn ように bắt buộc dùng khi vế trước là động từ khả năng (V可能形) hoặc động từ phủ định (Vない) diễn tả mục tiêu/mong muốn không hoàn toàn kiểm soát được, ví dụ 太らないように, 食べられるように. Ở đây 太らない (phủ định) phải đi với ように, không được dùng ために."},related:["Vるようになる","Vるために"],kitsuPrompt:"Hỏi tôi về mục tiêu học tập. Tôi sẽ dùng 〜できるように〜ています."},{pattern:"Vるようになります",meaning:"trở nên có thể làm ~ (thay đổi tự nhiên)",priority:"high",explanation:"ようになる biểu thị sự thay đổi tự nhiên theo thời gian — từ trạng thái A sang trạng thái B. Thường đi với V可能形 hoặc V普通形 biểu thị thay đổi khả năng/thói quen.",examples:[{sentence:"練習したら、泳げるようになりました。",translation:"Sau khi luyện tập tôi đã bơi được rồi."},{sentence:"日本に住んでから、箸が使えるようになりました。",translation:"Từ khi sống ở Nhật tôi đã dùng được đũa."},{sentence:"毎日読んでいたら、速く読めるようになりました。",translation:"Đọc mỗi ngày thì tôi đọc nhanh hơn rồi."}],note:"ようになった = kết quả thay đổi đã hoàn tất. Phủ định: Vないようになった (trở nên không còn làm).",dialogue:{jp:"A：日本語、上手になりましたね。\nB：ありがとうございます。毎日聞いていたら、少し聞き取れるようになりました。",vi:"A: Tiếng Nhật bạn giỏi hơn nhỉ.\nB: Cảm ơn. Nghe mỗi ngày thì tôi đã nghe hiểu được một chút."},commonMistake:{wrong:"毎日練習したら、上手になるようになりました。",correct:"毎日練習したら、上手になりました。",why:"Lỗi phổ biến là thừa ようになる khi đã có になる rồi (danh từ/tính từ + になる đã tự mang nghĩa 'trở nên'), thêm ようになった nữa thành lặp nghĩa dư thừa, đúng ra chỉ cần 上手になりました. Ngoài ra một lỗi khác hay gặp là quên よう khi chia động từ khả năng: できるになりました (sai) phải là できるようになりました (đủ よう)."},related:["Vるように","Vるようにする"],kitsuPrompt:"Hỏi tôi về điều gì đó tôi đã học được sau nhiều tháng cố gắng. Tôi sẽ kể bằng ようになりました."},{pattern:"Vるようにします",meaning:"cố gắng làm ~ (quyết tâm/nỗ lực)",priority:"high",explanation:"ようにする biểu thị sự cố ý, nỗ lực để duy trì hoặc bắt đầu một hành vi. Khác với ようになる (thay đổi tự nhiên), ようにする là ý chí chủ động.",examples:[{sentence:"毎朝ニュースを見るようにしています。",translation:"Tôi đang cố gắng xem tin tức mỗi sáng."},{sentence:"野菜をたくさん食べるようにしています。",translation:"Tôi đang cố ăn nhiều rau hơn."},{sentence:"夜は早く寝るようにします。",translation:"Tôi sẽ cố gắng ngủ sớm vào buổi tối."}],note:"〜ようにしています = đang duy trì thói quen. 〜ようにします = quyết tâm làm từ nay trở đi.",dialogue:{jp:"A：健康のために何かしていますか。\nB：毎日30分歩くようにしています。",vi:"A: Bạn làm gì để giữ sức khỏe không?\nB: Tôi đang cố gắng đi bộ 30 phút mỗi ngày."},commonMistake:{wrong:"太らないように、野菜をたくさん食べないようにしている。",correct:"太らないように、野菜をたくさん食べるようにしています。",why:"Mẫu 〜ようにしている (thể thường, không có です) tuy không sai về ngữ pháp nhưng khi nói về thói quen đang duy trì ở hiện tại trong văn nói lịch sự tự nhiên, người Nhật thường dùng 〜ようにしています (có です/ます) hơn là dùng thể thường 〜ようにしている, đặc biệt khi giao tiếp với người ngoài hoặc trong câu trả lời phỏng vấn."},related:["Vるようになる","Vるように"],kitsuPrompt:"Hỏi tôi về các thói quen tốt tôi đang cố gắng duy trì. Tôi sẽ dùng 〜ようにしています."}]},{bai:37,level:"N4",kanji:"受",reading:"うける",romaji:"Ukeru",titleVi:"Thể bị động",titleJp:"受身",descVi:"Chia động từ sang thể bị động — bị/được ai làm gì cho mình.",selfCheckGoals:["Chia được V受身形 của 8 động từ thông dụng (nhóm I, II, III)","Phân biệt bị động trực tiếp và bị động gián tiếp (迷惑)",'Dùng に để chỉ "tác nhân" (người làm) trong câu bị động',"Diễn đạt sự kiện lịch sử bằng bị động khách quan"],readingPassage:{title:"ほめられた日",titleVi:"Ngày được khen",japanese:"今日、会社でプレゼンをしました。発表が終わったあと、部長に「よくできた」と褒められました。同僚にも「わかりやすかった」と言われて、とてもうれしかったです。でも、電車の中で足を踏まれたり、急に雨に降られたりして、少し大変でした。良いことも悪いこともある一日でした。",vietnamese:'Hôm nay tôi thuyết trình ở công ty. Sau khi thuyết trình xong, tôi được trưởng phòng khen "làm tốt lắm". Đồng nghiệp cũng nói "dễ hiểu lắm" nên tôi rất vui. Nhưng trong tàu điện ngầm tôi bị giẫm chân, lại bị mưa bất ngờ nữa, nên khá vất vả. Đó là một ngày có cả chuyện tốt lẫn chuyện xấu.',highlights:[{excerpt:"部長に褒められました",label:"bị động tích cực"},{excerpt:"わかりやすかったと言われて",label:"bị động gián tiếp"},{excerpt:"足を踏まれたり",label:"迷惑の受身"},{excerpt:"雨に降られたり",label:"迷惑の受身 (thiên nhiên)"}],questions:[{q:"部長は筆者に何と言いましたか。",options:["よくできた","もっと練習して","発表は短くして","わかりにくかった"],answer:0},{q:"電車の中で何が起きましたか。",options:["足を踏まれた","かばんを盗まれた","席を取られた","電話が鳴った"],answer:0}]},patterns:[{pattern:"V受身形",meaning:"thể bị động (bị/được ai làm gì)",priority:"high",explanation:"Thể bị động (passive voice): Nhóm I: âm cuối い→あ+れる (書く→書かれる, 飲む→飲まれる). Nhóm II: bỏ る+られる (食べる→食べられる). Nhóm III: される, 来られる. Tác nhân dùng に (người) hoặc によって (trong văn viết).",examples:[{sentence:"先生に名前を呼ばれました。",translation:"Tôi được thầy gọi tên."},{sentence:"犬に手を噛まれました。",translation:"Tay tôi bị chó cắn."},{sentence:"この映画は多くの人に見られています。",translation:"Bộ phim này được nhiều người xem."}],note:'Tiếng Nhật không chia rõ "bị" (tiêu cực) và "được" (tích cực) trong cấu trúc — ngữ cảnh quyết định.',dialogue:{jp:"A：どうしたんですか、その傷は？\nB：自転車に乗っていたとき、車にぶつけられました。",vi:"A: Vết thương đó sao vậy?\nB: Khi đang đi xe đạp tôi bị xe hơi đâm vào."},commonMistake:{wrong:"このケーキ、子どもに全部食べれるました。",correct:"このケーキ、子どもに全部食べられました。",why:"Động từ nhóm II khi chia thể bị động phải giữ nguyên ら trong られる (食べる→食べられる), không được bỏ ら thành 食べれる (đó là dạng rút gọn ら抜き言葉 dùng cho thể khả năng, không phải bị động). Ngoài ra cần phân biệt: nhóm I chia bằng đổi âm cuối い→あ+れる (飲む→飲まれる là đúng), còn nhóm II luôn thêm られる chứ không rút gọn."},related:["V使役形","V使役受身形"],kitsuPrompt:"Hỏi tôi về những lần bị ai đó làm phiền hoặc làm điều gì đó. Tôi sẽ dùng bị động."},{pattern:"Nが／はVられます (社会・歴史)",meaning:"được ~ (bị động khách quan / lịch sử)",priority:"medium",explanation:"Bị động khách quan dùng khi tác nhân không quan trọng hoặc không xác định — phổ biến trong văn viết, tin tức, lịch sử. Tương đương passive voice trong tiếng Anh.",examples:[{sentence:"この建物は1900年に建てられました。",translation:"Tòa nhà này được xây năm 1900."},{sentence:"毎年、多くの観光客がこの祭りに招待されます。",translation:"Mỗi năm nhiều khách du lịch được mời đến lễ hội này."},{sentence:"新しいルールが発表されました。",translation:"Quy tắc mới đã được công bố."}],note:"によって thay cho に khi tác nhân là tổ chức/sự kiện lớn: 政府によって発表された (được chính phủ công bố).",dialogue:{jp:"A：あの建物はいつ建てられましたか。\nB：明治時代に建てられたと書いてあります。",vi:"A: Tòa nhà đó được xây khi nào?\nB: Có ghi là được xây vào thời Meiji."},commonMistake:{wrong:"先生によって漢字の書き方を教えられました。",correct:"先生に漢字の書き方を教えられました。",why:"Học viên hay nhầm lẫn giữa に và によって khi chỉ tác nhân trong câu bị động: に dùng cho tác nhân là NGƯỜI cụ thể trong quan hệ gần gũi, đời thường (先生に教えられた), còn によって chỉ dùng khi tác nhân là tổ chức lớn, tác giả tác phẩm, hoặc trong văn phong trang trọng/học thuật (例：この本は有名な作家によって書かれた). Dùng によって cho một việc đơn giản như thầy giáo dạy học trò nghe quá trang trọng, không tự nhiên."},related:["V受身形","によって"],kitsuPrompt:"Hỏi tôi về một di tích lịch sử. Tôi sẽ mô tả bằng bị động khách quan."},{pattern:"迷惑の受身",meaning:'bị động "phiền" (chịu hậu quả không mong muốn)',priority:"high",explanation:"迷惑受身: Chủ thể bị ảnh hưởng tiêu cực bởi hành động của người/vật khác. Đặc biệt: có thể dùng với cả nội động từ (雨に降られる — bị mưa). Không có trong tiếng Anh/Việt.",examples:[{sentence:"隣の人にピアノを弾かれて、眠れませんでした。",translation:"Người hàng xóm đánh đàn piano làm tôi không ngủ được."},{sentence:"子どもに泣かれて、困りました。",translation:"Đứa trẻ khóc làm tôi bối rối."},{sentence:"急に友だちに来られて、部屋が片付いていなかった。",translation:"Bạn bất ngờ đến làm tôi bối rối vì phòng chưa dọn."}],note:"Cấu trúc: (Chủ thể) は (tác nhân) に (hành động gây phiền) られる. Hành động không nhất thiết nhắm vào chủ thể.",dialogue:{jp:"A：昨日、どうして眠そうですか。\nB：夜中に赤ちゃんに泣かれて、全然眠れませんでした。",vi:"A: Hôm qua sao trông buồn ngủ vậy?\nB: Đêm hôm qua em bé khóc suốt nên tôi không ngủ được chút nào."},commonMistake:{wrong:"傘を忘れて、雨が降られて、びしょ濡れになりました。",correct:"傘を忘れて、雨に降られて、びしょ濡れになりました。",why:"迷惑の受身 (bị động chịu ảnh hưởng) với động từ tự nhiên như 降る (mưa rơi) không thể lấy chính hiện tượng đó (雨) làm chủ ngữ với trợ từ が, vì chủ ngữ của câu bị động phải là NGƯỜI CHỊU ẢNH HƯỞNG, còn tác nhân gây phiền (雨) phải đứng sau với trợ từ に. Vì vậy phải nói 私は雨に降られた chứ không được nói 雨が降られた."},related:["V受身形","Vて困ります"],kitsuPrompt:"Hỏi tôi về những tình huống tôi bị phiền hà bởi người khác hoặc thời tiết. Tôi sẽ dùng 迷惑受身."}]},{bai:38,level:"N4",kanji:"化",reading:"か",romaji:"Ka",titleVi:"Danh từ hóa",titleJp:"名詞化",descVi:"Dùng の và こと để biến mệnh đề thành danh từ trong câu phức.",selfCheckGoals:["Dùng のは/のが/のを chính xác với ít nhất 5 động từ khác nhau","Phân biệt の (cảm giác/tình huống cụ thể) và こと (khái niệm trừu tượng)",'Tạo câu "thích/giỏi/dở" bằng のが好き/上手/下手',"Dùng のを忘れる và のを知っている tự nhiên"],readingPassage:{title:"趣味について",titleVi:"Về sở thích",japanese:"私は写真を撮るのが好きです。特に、夕日の写真を撮るのが楽しいです。カメラを買う前は、スマホで撮るのは難しいと思っていました。でも、練習するのは思ったより簡単でした。友だちは絵を描くのが得意ですが、私には難しいです。人それぞれ得意なことが違いますね。",vietnamese:"Tôi thích chụp ảnh. Đặc biệt, chụp ảnh hoàng hôn thì rất vui. Trước khi mua máy ảnh tôi nghĩ chụp bằng điện thoại khó. Nhưng việc luyện tập dễ hơn tôi tưởng. Bạn tôi giỏi vẽ tranh, nhưng với tôi thì khó. Mỗi người giỏi điều khác nhau nhỉ.",highlights:[{excerpt:"写真を撮るのが好きです",label:"のが好き"},{excerpt:"スマホで撮るのは難しい",label:"のは〜だ"},{excerpt:"練習するのは思ったより",label:"のは評価"},{excerpt:"絵を描くのが得意",label:"のが得意"}],questions:[{q:"筆者が特に好きな写真はどんな写真ですか。",options:["夕日の写真","動物の写真","風景の写真","人物の写真"],answer:0},{q:"筆者の友だちは何が得意ですか。",options:["絵を描くこと","写真を撮ること","音楽を弾くこと","料理を作ること"],answer:0}]},patterns:[{pattern:"Vるのは〜です",meaning:"việc V là ~ (danh từ hóa mệnh đề)",priority:"high",explanation:'の sau V thể từ điển biến mệnh đề thành danh từ. のは = "việc ~" làm chủ ngữ. Dùng khi muốn nói về trải nghiệm/hành động như một thực thể.',examples:[{sentence:"日本語を話すのは難しいです。",translation:"Việc nói tiếng Nhật thì khó."},{sentence:"山に登るのは大変ですが、楽しいです。",translation:"Việc leo núi thì vất vả nhưng vui."},{sentence:"毎日早起きするのは辛いです。",translation:"Việc dậy sớm mỗi ngày thật khổ."}],note:"こと và の có thể thay thế nhau với のは/のが trong nhiều trường hợp, nhưng の gợi cảm giác trực quan/cụ thể hơn.",dialogue:{jp:"A：日本語を勉強するのはどうですか。\nB：難しいですが、楽しいです！話せるようになるのが目標です。",vi:"A: Học tiếng Nhật thế nào?\nB: Khó nhưng vui! Mục tiêu là trở nên nói được."},commonMistake:{wrong:"日本語を話しますのは難しいです。",correct:"日本語を話すのは難しいです。",why:"の danh từ hóa mệnh đề chỉ ghép được với động từ ở THỂ TỪ ĐIỂN (辞書形), không ghép được với thể ます lịch sự. Vì vậy 話しますの là sai, phải nói 話すの. Quy tắc: Vる (từ điển) + のは/のが, không bao giờ Vます + の."},related:["Vるのが","Vることは"],kitsuPrompt:"Hỏi tôi về điều gì đó tôi thấy khó hoặc thú vị. Tôi sẽ dùng 〜のは〜です."},{pattern:"Vるのが好きです／上手です",meaning:"thích / giỏi việc ~",priority:"high",explanation:"V thể từ điển + の + が好き/嫌い/上手/下手/得意/苦手 — biểu thị thái độ, sở thích hoặc kỹ năng đối với một hành động.",examples:[{sentence:"歌を歌うのが好きです。",translation:"Tôi thích hát."},{sentence:"料理を作るのが得意です。",translation:"Tôi giỏi nấu ăn."},{sentence:"人前で話すのが苦手です。",translation:"Tôi kém nói trước đám đông."}],note:"好き/嫌い/上手/下手/得意/苦手 đều theo mẫu này. Chú ý: 上手 thường nói về kỹ năng của người khác (lịch sự), 得意 nói về bản thân.",dialogue:{jp:"A：何か趣味はありますか。\nB：写真を撮るのが好きです。休みのたびに出かけます。",vi:"A: Bạn có sở thích gì không?\nB: Tôi thích chụp ảnh. Mỗi kỳ nghỉ là tôi đi ngay."},commonMistake:{wrong:"料理することが好きですが、この文はちょっと硬いです。",correct:"料理するのが好きです。",why:"こと và の đều danh từ hóa được động từ và về ngữ pháp こと không sai, nhưng khi nói về một hành động cụ thể, sống động (đặc biệt trong văn nói/hội thoại) người Nhật tự nhiên dùng の hơn là こと. こと nghe trang trọng, trừu tượng hơn nên hợp với văn viết/khái niệm chung, còn の hợp với trải nghiệm/cảm giác cụ thể như sở thích cá nhân."},related:["Vるのは","Nが好きです"],kitsuPrompt:"Hỏi tôi về sở thích và điểm mạnh/yếu của tôi. Tôi sẽ dùng のが好き/得意/苦手."},{pattern:"Vるのを忘れました／知っています",meaning:"quên / biết việc ~ (の làm tân ngữ)",priority:"medium",explanation:"の danh từ hóa làm tân ngữ (を) cho các động từ tri giác/nhận thức: 忘れる, 知る, 見る, 聞く, 手伝う, やめる...",examples:[{sentence:"薬を飲むのを忘れました。",translation:"Tôi quên uống thuốc."},{sentence:"彼女が来るのを知っていましたか。",translation:"Bạn có biết cô ấy sẽ đến không?"},{sentence:"子どもが転ぶのを見ました。",translation:"Tôi thấy đứa trẻ ngã."}],note:"こと cũng dùng với 知る, 忘れる nhưng thường trừu tượng hơn. の gợi cảm giác đang thấy/trải nghiệm sự việc đó.",dialogue:{jp:"A：会議の時間、変わったの知ってた？\nB：えっ、知らなかった！メールを確認するのを忘れてた。",vi:"A: Giờ họp đổi rồi bạn biết không?\nB: Ơ, không biết! Tôi quên kiểm tra email."},commonMistake:{wrong:"薬を飲みましたのを忘れました。",correct:"薬を飲むのを忘れました。",why:"の (danh từ hóa) làm tân ngữ đứng trước を phải đi sau động từ ở THỂ TỪ ĐIỂN, không chia thì (không dùng thể ました). Thì quá khứ chỉ nằm ở động từ chính phía sau (忘れました), còn mệnh đề bị danh từ hóa luôn giữ nguyên thể từ điển: 飲むのを忘れました, không phải 飲みましたのを."},related:["Vるのが","Vることを"],kitsuPrompt:"Hỏi tôi về những việc tôi hay quên làm. Tôi sẽ dùng 〜のを忘れました."}]},{bai:39,level:"N4",kanji:"原",reading:"げんいん",romaji:"Genin",titleVi:"Nguyên nhân & lý do",titleJp:"原因・理由",descVi:"Phân biệt 〜て (nguyên nhân cảm xúc) và 〜ので (lý do lịch sự).",selfCheckGoals:["Phân biệt 〜て (cảm xúc/kết quả tự nhiên) và 〜ので (lý do lịch sự) qua 4 câu ví dụ","Phân biệt ので và から (ので lịch sự/khách quan, から chủ quan/thân mật)","Dùng 〜ために (nguyên nhân tiêu cực/vì lý do) trong câu viết","Giải thích lý do xin phép nghỉ bằng ので một cách lịch sự"],readingPassage:{title:"遅刻の理由",titleVi:"Lý do đến muộn",japanese:"今朝、電車が事故のために遅れたので、会議に遅刻してしまいました。上司に「すみません、電車が遅れたので遅くなりました」と謝りました。上司は「事故があったのか、それは仕方がない」と言ってくれました。ニュースを見て、事故の大きさにびっくりしました。今日は早めに帰るので、明日の準備を家でするつもりです。",vietnamese:'Sáng nay tàu điện bị trễ vì tai nạn nên tôi đã đến muộn cuộc họp. Tôi xin lỗi cấp trên rằng "Xin lỗi, tàu điện trễ nên tôi đến muộn". Cấp trên nói "Có tai nạn à, thế thì không có cách nào". Xem tin tức thấy quy mô tai nạn tôi giật mình. Hôm nay tôi về sớm nên định chuẩn bị cho ngày mai ở nhà.',highlights:[{excerpt:"事故のために遅れたので",label:"ため+ので nguyên nhân"},{excerpt:"電車が遅れたので",label:"ので lý do lịch sự"},{excerpt:"ニュースを見て、びっくりしました",label:"Vて cảm xúc"},{excerpt:"早めに帰るので",label:"ので tiếp nối"}],questions:[{q:"筆者はなぜ会議に遅刻しましたか。",options:["電車が事故で遅れたから","寝坊したから","道が込んでいたから","電車を乗り間違えたから"],answer:0},{q:"上司はどんな反応をしましたか。",options:["仕方がないと言った","怒った","何も言わなかった","早く帰るよう言った"],answer:0}]},patterns:[{pattern:"V／Aて、〜 (原因・感情)",meaning:"vì ~ (nguyên nhân cảm xúc/kết quả tự nhiên)",priority:"high",explanation:"V/A thể て + vế sau biểu thị nguyên nhân dẫn đến cảm xúc hoặc kết quả tự nhiên. Dùng với động từ trạng thái hoặc kết quả khách quan — không dùng với câu yêu cầu/mệnh lệnh.",examples:[{sentence:"嬉しいニュースを聞いて、泣いてしまいました。",translation:"Nghe tin vui tôi khóc mất."},{sentence:"道に迷って、遅れました。",translation:"Vì lạc đường nên tôi đến muộn."},{sentence:"財布を忘れて、困りました。",translation:"Quên ví nên tôi bối rối."}],note:"Vế sau KHÔNG thể là mệnh lệnh, yêu cầu, hay ý chí: ❌ 急いで、早く来てください (dùng ので/から thay).",dialogue:{jp:"A：どうして泣いているんですか。\nB：映画を見て、感動して泣いてしまいました。",vi:"A: Sao bạn khóc vậy?\nB: Xem phim cảm động quá nên khóc mất."},commonMistake:{wrong:"熱があって、休んでください。",correct:"熱があるので、休んでください。",why:"Vế sau của 〜て (nguyên nhân) chỉ diễn tả cảm xúc hoặc kết quả tự nhiên, KHÔNG được là câu mệnh lệnh, yêu cầu hay ý chí như 〜てください/〜ましょう/〜たい. Khi vế sau là yêu cầu như 休んでください, phải dùng 〜ので hoặc 〜から thay cho 〜て."},related:["〜ので","〜から"],kitsuPrompt:"Hỏi tôi về một kỷ niệm cảm động hay bất ngờ. Tôi sẽ kể bằng 〜て感動しました/びっくりしました."},{pattern:"〜ので",meaning:"vì ~ nên ~ (lý do lịch sự/khách quan)",priority:"high",explanation:"ので sau V/A/N thể bình thường (Na adj + な, N + な trước ので) biểu thị lý do theo cách khách quan, lịch sự. Dùng khi xin phép, giải thích, hoặc văn viết trang trọng.",examples:[{sentence:"熱があるので、今日は休みます。",translation:"Vì có sốt nên hôm nay tôi nghỉ."},{sentence:"雨が降るので、傘を持ってきました。",translation:"Vì trời mưa nên tôi mang ô."},{sentence:"静かなので、ここで勉強しやすいです。",translation:"Vì yên tĩnh nên học ở đây dễ chịu."}],note:"ので lịch sự, khách quan hơn から. Trong văn nói thân mật dùng から. Trong email/xin phép chính thức dùng ので.",dialogue:{jp:"A：明日の会議、欠席できますか。\nB：出張があるので、欠席させていただきます。",vi:"A: Cuộc họp ngày mai bạn có thể vắng mặt không?\nB: Vì có chuyến công tác nên tôi xin phép vắng."},commonMistake:{wrong:"静かだので、ここで勉強しやすいです。",correct:"静かなので、ここで勉強しやすいです。",why:"Trước ので, tính từ đuôi な (na-keiyoushi) phải chia thành 「な」+ ので (không phải だ + ので), và danh từ cũng phải thêm な trước ので (N + なので), ví dụ 学生なので chứ không phải 学生だので. Đây là lỗi rất phổ biến vì học viên nhầm quy tắc chia の trước こと/です sang ので."},related:["〜から","〜て(原因)","〜ため"],kitsuPrompt:"Tôi muốn xin nghỉ làm. Hãy giúp tôi viết email ngắn dùng 〜ので."},{pattern:"Nのために / Vるために",meaning:"vì ~ (nguyên nhân tiêu cực) / để ~ (mục đích)",priority:"medium",explanation:"ために có hai nghĩa: (1) nguyên nhân tiêu cực/trung lập trong văn viết (事故のために = vì tai nạn); (2) mục đích (試験のために = để thi). Ngữ cảnh quyết định.",examples:[{sentence:"台風のために、電車が止まりました。",translation:"Vì bão nên tàu điện dừng hoạt động."},{sentence:"試験に合格するために、毎日勉強しています。",translation:"Để đậu kỳ thi tôi học mỗi ngày."},{sentence:"病気のために、仕事を休みました。",translation:"Vì bệnh nên tôi nghỉ làm."}],note:"ため là văn viết/trang trọng. Văn nói thân mật dùng から hoặc ので thay thế.",dialogue:{jp:"A：どうして電車が遅れているんですか。\nB：事故のため、しばらくお待ちください。（アナウンス）",vi:"A: Sao tàu điện bị trễ vậy?\nB: Vì tai nạn, xin quý khách chờ một lúc. (Thông báo)"},commonMistake:{wrong:"日本語が話せるために、毎日勉強しています。",correct:"日本語が話せるように、毎日勉強しています。",why:"ために diễn đạt mục đích chỉ dùng được với động từ Ý CHÍ (hành động chủ động có thể kiểm soát, như 合格するために); còn với động từ khả năng/trạng thái không chủ động điều khiển được (話せる - thể khả năng) phải dùng ように. Ngoài ra cần phân biệt hai nghĩa của ために: (1) nguyên nhân trung lập/tiêu cực trong văn viết (事故のために), (2) mục đích (試験のために) — ngữ cảnh quyết định nghĩa nào đang được dùng."},related:["〜ので","〜Vるように"],kitsuPrompt:"Hỏi tôi về lý do tại sao tôi học tiếng Nhật. Tôi sẽ dùng 〜ために (mục đích)."}]},{bai:40,level:"N4",kanji:"問",reading:"もんだい",romaji:"Mondai",titleVi:"Câu hỏi gián tiếp",titleJp:"埋め込み疑問",descVi:"Lồng câu hỏi vào mệnh đề chính với 〜かどうか; nói thử làm với てみる.",selfCheckGoals:["Chuyển câu hỏi trực tiếp thành gián tiếp bằng か và かどうか","Phân biệt 疑問詞+か (ai/gì/đâu) và かどうか (có hay không)",'Dùng Vてみます để nói "thử ~ xem sao" trong 3 tình huống','Nói "không biết có ~ không" bằng かどうかわかりません'],readingPassage:{title:"新しいレストランを試してみた",titleVi:"Thử nhà hàng mới",japanese:"先週、駅の近くに新しいレストランができたと聞いたので、行ってみました。メニューを見て、何を頼んだらいいかわかりませんでした。店員さんにおすすめかどうか聞いたら、パスタが人気だと教えてくれました。食べてみたら、とてもおいしかったです。また来るかどうか迷いましたが、きっとまた来ると思います。",vietnamese:"Tuần trước nghe nói có nhà hàng mới gần ga nên tôi đã thử đến. Xem menu thì không biết nên gọi gì. Hỏi nhân viên có phải món nào được gợi ý không thì được cho biết pasta rất được ưa chuộng. Ăn thử thì ngon lắm. Tôi do dự không biết có đến lần nữa không, nhưng chắc chắn sẽ đến nữa tôi nghĩ vậy.",highlights:[{excerpt:"行ってみました",label:"Vてみる thử"},{excerpt:"何を頼んだらいいかわかりません",label:"疑問詞+か không biết"},{excerpt:"おすすめかどうか聞いた",label:"かどうか hỏi"},{excerpt:"また来るかどうか迷いました",label:"かどうか phân vân"}],questions:[{q:"筆者はなぜこのレストランに行きましたか。",options:["新しくできたと聞いたから","友だちに誘われたから","前から知っていたから","看板を見たから"],answer:0},{q:"筆者は店員さんに何を聞きましたか。",options:["おすすめかどうか","値段はいくらか","何時に閉まるか","予約できるかどうか"],answer:0}]},patterns:[{pattern:"疑問詞＋か〜",meaning:"câu hỏi gián tiếp với từ nghi vấn",priority:"high",explanation:"疑問詞 (何, どこ, いつ, だれ...) + か biến câu hỏi trực tiếp thành mệnh đề phụ (câu hỏi gián tiếp). Vế sau thường là 知っていますか, わかりますか, 教えてください.",examples:[{sentence:"どこに財布を置いたか、覚えていません。",translation:"Tôi không nhớ đã để ví ở đâu."},{sentence:"何時に始まるか、知っていますか。",translation:"Bạn có biết bắt đầu lúc mấy giờ không?"},{sentence:"誰が来るか、教えてください。",translation:"Hãy cho tôi biết ai sẽ đến."}],note:"Câu hỏi gián tiếp dùng thể bình thường (không dùng ですか). ❌ 何時に始まりますか、知っていますか → Dùng: 何時に始まるか",dialogue:{jp:"A：この漢字、どう読むか知っていますか。\nB：すみません、私もわかりません。",vi:"A: Bạn có biết chữ Hán này đọc thế nào không?\nB: Xin lỗi, tôi cũng không biết."},commonMistake:{wrong:"何時に始まりますかがわかりません。",correct:"何時に始まるかわかりません。",why:"Câu hỏi gián tiếp (埋め込み疑問) dùng thể bình thường (từ điển), không dùng thể ですか/ますか lịch sự, và cũng không cần trợ từ が sau か. Vì vậy 始まりますかが là sai kép: vừa sai thể động từ, vừa thừa trợ từ. Đúng là 始まるかわかりません."},related:["〜かどうか","〜と思います"],kitsuPrompt:"Hỏi tôi về điều gì đó không chắc. Tôi sẽ trả lời bằng 〜かわかりません."},{pattern:"V／Aかどうか〜",meaning:"có ~ hay không (câu hỏi có/không gián tiếp)",priority:"high",explanation:"かどうか theo sau V/A thể bình thường biểu thị câu hỏi có-hay-không được lồng vào câu. Khác với 疑問詞+か (ai/gì/đâu), かどうか dùng khi không có từ nghi vấn.",examples:[{sentence:"明日、雨が降るかどうかわかりません。",translation:"Tôi không biết ngày mai có mưa không."},{sentence:"試験に合格できるかどうか、心配です。",translation:"Tôi lo không biết có đậu kỳ thi không."},{sentence:"彼が来るかどうか、確認してみます。",translation:"Tôi sẽ thử xác nhận xem anh ấy có đến không."}],note:"かどうか + 聞く/確認する/迷う... Dùng để diễn đạt sự không chắc chắn hoặc phân vân.",dialogue:{jp:"A：パーティーに行くかどうか、まだ決めていないんです。\nB：ぜひ来てください！楽しいですよ。",vi:"A: Tôi chưa quyết định có đi bữa tiệc không.\nB: Hãy đến đi! Vui lắm."},commonMistake:{wrong:"彼が行くかどうかかわかりません。",correct:"彼が行くかどうかわかりません。",why:"かどうか đã tự nó là một cụm hoàn chỉnh biểu thị câu hỏi có/không gián tiếp, không cần thêm か lần nữa phía sau. Thêm か thừa (かどうかか) là lỗi lặp từ phổ biến khi học viên nhầm lẫn với cấu trúc 疑問詞+か."},related:["疑問詞+か","〜か〜かどちら"],kitsuPrompt:"Hỏi tôi về một quyết định đang phân vân. Tôi sẽ dùng かどうか để nói."},{pattern:"Vてみます",meaning:"thử làm ~ (xem kết quả thế nào)",priority:"high",explanation:"V thể て + みる biểu thị thử thực hiện một hành động để xem kết quả. Gợi ý tinh thần khám phá, trải nghiệm.",examples:[{sentence:"初めて日本料理を食べてみました。",translation:"Tôi đã thử ăn món Nhật lần đầu."},{sentence:"この薬を飲んでみてください。",translation:"Hãy thử uống thuốc này xem."},{sentence:"難しそうですが、やってみます。",translation:"Có vẻ khó nhưng tôi sẽ thử làm xem."}],note:'てみる gợi hành động có chủ ý "thử xem sao". Kết quả thường được nói tiếp: 〜てみたら、おいしかったです.',dialogue:{jp:"A：日本のお正月料理、食べてみましたか。\nB：まだです。今年ぜひ食べてみたいと思っています。",vi:"A: Bạn đã thử món ăn Tết Nhật chưa?\nB: Chưa. Năm nay tôi rất muốn thử."},commonMistake:{wrong:"初めて日本料理を食べをみました。",correct:"初めて日本料理を食べてみました。",why:"てみる (thử làm) phải gắn vào thể て của động từ (食べて + みる), không được nối trực tiếp bằng を. Học viên hay nhầm vì nghĩ みる là động từ riêng nên chêm trợ từ を vào giữa, nhưng đúng ra phải giữ nguyên khối Vて + みる: 食べてみます, không phải 食べをみます hay 食べますをみます."},related:["Vたことがあります","Vてください"],kitsuPrompt:"Đề xuất tôi thử làm điều gì đó liên quan đến tiếng Nhật. Tôi sẽ nói sẽ 〜てみます."}]},{bai:41,level:"N4",kanji:"恩",reading:"おん",romaji:"On",titleVi:"Ân huệ & nhờ vả",titleJp:"行為のやりもらい",descVi:"Dùng てあげる・てもらう・てくれる và dạng kính ngữ ていただく.",selfCheckGoals:["Chọn đúng てあげる/てもらう/てくれる theo góc nhìn người nói","Phân biệt てもらいます (nhờ) và ていただきます (kính ngữ)","Kể lại một việc người khác làm cho mình bằng てくれました","Dùng ていただけませんか để nhờ vả lịch sự"],readingPassage:{title:"引越しのお礼",titleVi:"Lời cảm ơn khi chuyển nhà",japanese:"先月、引越しをしたとき、友だちが手伝ってくれました。重い荷物を運んでもらったり、掃除を手伝ってもらったりしました。私も友だちにお礼に食事をごちそうしてあげました。田中さんには、新しい住所を知らせていただいたおかげで、すぐ連絡が取れました。みなさんのおかげで、無事に引越しができました。",vietnamese:"Tháng trước khi chuyển nhà, bạn bè đã giúp tôi. Tôi được họ giúp vác đồ nặng và dọn dẹp. Tôi cũng đãi bữa ăn để cảm ơn bạn bè. Nhờ được Tanaka-san cho biết địa chỉ mới nên tôi liên lạc được ngay. Nhờ mọi người mà tôi chuyển nhà thành công.",highlights:[{excerpt:"手伝ってくれました",label:"てくれる: ai làm cho mình"},{excerpt:"運んでもらったり",label:"てもらう: được nhờ"},{excerpt:"食事をごちそうしてあげました",label:"てあげる: làm cho người khác"},{excerpt:"知らせていただいた",label:"ていただく kính ngữ"}],questions:[{q:"友だちは筆者のために何をしてくれましたか。",options:["荷物を運んだり、掃除を手伝ったりした","引越し先を探してくれた","お金を貸してくれた","食事をごちそうしてくれた"],answer:0},{q:"筆者は友だちへのお礼に何をしましたか。",options:["食事をごちそうした","プレゼントを贈った","旅行に誘った","お金を渡した"],answer:0}]},patterns:[{pattern:"Vてあげます",meaning:"làm (giúp) cho ai đó (góc độ người cho)",priority:"high",explanation:'てあげる: Người nói (hoặc đối tượng mà người nói có cảm tình) làm gì đó vì lợi ích của người khác. Nhấn mạnh việc "tôi làm cho anh/cô ấy".',examples:[{sentence:"道に迷っている人に地図を見せてあげました。",translation:"Tôi đã chỉ bản đồ cho người đang lạc đường."},{sentence:"子どもに本を読んであげます。",translation:"Tôi đọc sách cho đứa trẻ nghe."},{sentence:"友だちの荷物を持ってあげました。",translation:"Tôi đã xách hộ đồ cho bạn."}],note:'Cẩn thận: nói てあげる với người trên có thể nghe "ban ơn" — thay bằng おVしました (kính ngữ). Đừng dùng てあげる khi nói về hành động của người khác làm cho mình.',dialogue:{jp:"A：子ども、泣いているよ。\nB：絵本を読んであげたら、泣きやむかもしれないよ。",vi:"A: Đứa bé đang khóc kìa.\nB: Đọc truyện tranh cho nó nghe thì có thể hết khóc đó."},commonMistake:{wrong:"先生に日本語を教えてあげました。",correct:"先生に日本語を教えました。",why:'てあげる mang sắc thái người nói "ban ơn" cho người khác, nên dùng với người ngang hàng hoặc dưới thì tự nhiên, nhưng dùng với người trên (先生, 上司, khách hàng) nghe rất thất lễ như thể mình ban ơn cho họ. Với người trên nên bỏ てあげる, chỉ dùng động từ thường (教えました) hoặc kính ngữ khiêm nhường (お教えしました).'},related:["Vてもらいます","Vてくれます"],kitsuPrompt:"Kể cho tôi nghe về lần bạn giúp đỡ ai đó. Tôi sẽ kể lại bằng てあげました."},{pattern:"Vてもらいます",meaning:"nhờ/được ai làm cho (góc độ người nhận)",priority:"high",explanation:'てもらう: Người nói nhờ (hoặc nhận) ai đó làm gì vì lợi ích của mình. Nhấn mạnh "tôi nhận được/nhờ được". Người làm dùng に.',examples:[{sentence:"先生に作文を直してもらいました。",translation:"Tôi đã nhờ thầy sửa bài văn."},{sentence:"友だちに駅まで送ってもらいました。",translation:"Tôi được bạn chở đến ga."},{sentence:"医者に薬を出してもらいました。",translation:"Tôi được bác sĩ kê đơn thuốc."}],note:"てもらえますか / てもらえませんか = nhờ vả lịch sự: 写真を撮ってもらえますか。(Bạn chụp ảnh giúp tôi được không?)",dialogue:{jp:"A：日本語の作文、難しかった？\nB：うん。先生に一緒に確認してもらったから、なんとかなったよ。",vi:"A: Bài văn tiếng Nhật có khó không?\nB: Có. Nhưng nhờ thầy kiểm tra cùng nên cũng xong được."},commonMistake:{wrong:"先生に作文をもらいます。",correct:"先生に作文を直してもらいます。",why:'てもらう phải luôn đi kèm một động từ chỉ hành động ở thể て đứng trước (V-て + もらう) để diễn tả "được ai đó làm gì cho mình"; nếu chỉ nói AにNをもらいます thì đó lại là câu "nhận được vật N từ A" (nghĩa khác hẳn, giống もらう đơn thuần), không phải "nhờ/được làm giúp". Cần thêm động từ hành động + て: 先生に作文を直してもらいます (được thầy sửa giúp bài văn).'},related:["Vてくれます","Vていただきます"],kitsuPrompt:"Hỏi tôi về lần tôi nhờ ai giúp đỡ. Tôi sẽ kể bằng 〜てもらいました."},{pattern:"Vてくれます",meaning:"ai đó làm cho mình (góc độ người nhận, tự nguyện)",priority:"high",explanation:'てくれる: Người khác tự nguyện làm gì đó vì lợi ích của người nói. Nhấn mạnh sự "tử tế/ân cần" của người làm — không phải do yêu cầu.',examples:[{sentence:"母が毎朝お弁当を作ってくれます。",translation:"Mỗi sáng mẹ làm cơm hộp cho tôi."},{sentence:"友だちが病院まで連れて行ってくれました。",translation:"Bạn đã đưa tôi đến bệnh viện."},{sentence:"先生が丁寧に説明してくれました。",translation:"Thầy đã giải thích cẩn thận cho tôi."}],note:"くれる dùng khi người nhận là người nói hoặc gia đình người nói. Nếu người nhận là người khác → てあげる.",dialogue:{jp:"A：引越しのとき、大変じゃなかった？\nB：友だちが手伝ってくれたから、思ったより楽だったよ。",vi:"A: Lúc chuyển nhà có vất vả không?\nB: Bạn bè giúp nên dễ hơn tôi nghĩ."},commonMistake:{wrong:"先生が私に日本語の文法を教えてくれました。それで、私はよく理解できました。",correct:"先生が日本語の文法を教えてくれました。それで、よく理解できました。",why:'てくれる vốn đã ngầm hiểu người nhận lợi ích là người nói (hoặc người thân của người nói), nên khi ngữ cảnh đã rõ, việc thêm 私に (cho tôi) và chủ ngữ 私は ở câu sau là thừa, không tự nhiên trong văn nói/viết tiếng Nhật. Câu đúng tự nhiên hơn khi lược bỏ 私に/私は vì てくれる tự nó đã hàm ý "làm cho tôi".'},related:["Vてもらいます","Vてあげます"],kitsuPrompt:"Hỏi tôi về điều ai đó đã làm cho tôi mà khiến tôi cảm động. Tôi sẽ kể bằng てくれました."},{pattern:"Vていただきます (謙譲)",meaning:"(kính ngữ) được/nhờ người trên làm cho",priority:"medium",explanation:"ていただく là kính ngữ của てもらう. Dùng khi người làm là người có địa vị cao hơn (thầy giáo, cấp trên, khách hàng). Rất phổ biến trong ngữ cảnh kinh doanh.",examples:[{sentence:"部長に報告書を確認していただきました。",translation:"Tôi đã được trưởng phòng xem lại báo cáo."},{sentence:"先生にご意見をいただきました。",translation:"Tôi đã được thầy cho ý kiến."},{sentence:"よろしければ、こちらにサインしていただけますか。",translation:"Nếu được, bạn có thể ký vào đây không?"}],note:"ていただけませんか / ていただけますか = nhờ vả lịch sự cao nhất. Dùng nhiều trong email và công sở.",dialogue:{jp:"A：こちらの書類を確認していただけますか。\nB：はい、少し時間をいただければ確認します。",vi:"A: Bạn có thể xem tài liệu này cho tôi không?\nB: Được, nếu cho tôi chút thời gian tôi sẽ kiểm tra."},commonMistake:{wrong:"お客様に資料を確認してあげました。",correct:"お客様に資料を確認していただきました。",why:'てあげる nghe như người nói "ban ơn" cho khách hàng — rất thất lễ trong tiếng Nhật kính ngữ. Khi khách hàng (người trên) làm gì đó cho mình, phải dùng kính ngữ ていただく (お客様に確認していただきました = được khách hàng xem giúp); còn khi mình làm gì đó cho khách thì dùng khiêm nhường ngữ いたします/させていただきます (確認いたしました), tuyệt đối không dùng てあげる với khách hàng.'},related:["Vてもらいます","Vてくださいます"],kitsuPrompt:"Đóng vai nhân viên văn phòng nhờ cấp trên duyệt tài liệu. Dùng 〜ていただけますか."}]},{bai:42,level:"N4",kanji:"目",reading:"もくてき",romaji:"Mokuteki",titleVi:"Mục đích & tốn phí",titleJp:"目的",descVi:'Nói "để làm gì" với ために / のに và "tốn bao lâu/tiền" với かかる.',selfCheckGoals:["Phân biệt ために (mục đích ý chí) và ように (mục tiêu thay đổi)","Dùng Vるのに để giải thích công cụ/phương tiện dùng làm gì","Nói thời gian/tiền tốn cho việc gì bằng かかります","Tạo câu với ために về mục tiêu dài hạn của bản thân"],readingPassage:{title:"資格取得のための準備",titleVi:"Chuẩn bị lấy chứng chỉ",japanese:"日本語能力試験に合格するために、毎日２時間勉強しています。参考書を買うために、先月から少しずつお金をためてきました。この辞書は意味を調べるのに便利です。試験会場まで電車で行くと１時間かかります。準備に時間もお金もかかりますが、絶対に合格したいです。",vietnamese:"Để đậu kỳ thi năng lực tiếng Nhật tôi học 2 tiếng mỗi ngày. Để mua sách tham khảo, tháng trước tôi đã bắt đầu tiết kiệm dần. Cuốn từ điển này tiện để tra nghĩa. Đi tàu điện đến nơi thi mất 1 tiếng. Chuẩn bị tốn cả thời gian lẫn tiền bạc, nhưng tôi nhất định muốn đậu.",highlights:[{excerpt:"合格するために",label:"ために mục đích"},{excerpt:"参考書を買うために",label:"ために lý do"},{excerpt:"意味を調べるのに便利",label:"Vるのに công dụng"},{excerpt:"１時間かかります",label:"かかる tốn thời gian"}],questions:[{q:"筆者はなぜ毎日勉強していますか。",options:["日本語能力試験に合格するため","仕事に必要だから","先生に言われたから","趣味だから"],answer:0},{q:"試験会場までどのくらいかかりますか。",options:["電車で1時間","電車で30分","バスで1時間","歩いて30分"],answer:0}]},patterns:[{pattern:"Vる／Nのために",meaning:"để ~ (mục đích có ý chí)",priority:"high",explanation:"ために theo sau V thể từ điển hoặc N + の biểu thị mục đích của hành động. Phân biệt với ように: ために dùng với V ý chí (動詞意志形), ように dùng với V可能 và V ない.",examples:[{sentence:"日本語が上手になるために、毎日練習します。",translation:"Để giỏi tiếng Nhật tôi luyện tập mỗi ngày."},{sentence:"健康のために、野菜をたくさん食べています。",translation:"Vì sức khỏe tôi ăn nhiều rau."},{sentence:"試験のために、友だちと勉強しました。",translation:"Để thi, tôi học cùng bạn bè."}],note:"❌ 起きられるように → ✓ (V可能+ように). ❌ 起きるために = có thể nhưng ために thường ít dùng với V khả năng.",dialogue:{jp:"A：なぜ毎朝走るんですか。\nB：マラソンに出るために、体を鍛えているんです。",vi:"A: Sao mỗi sáng bạn chạy bộ vậy?\nB: Tôi đang rèn thể lực để thi marathon."},commonMistake:{wrong:"朝早く起きられるために、目覚まし時計を二つセットしました。",correct:"朝早く起きられるように、目覚まし時計を二つセットしました。",why:'ために dùng sau động từ ý chí (意志動詞: 食べる, 勉強する...) để diễn đạt mục đích mà bản thân chủ động làm được; còn ように dùng sau động từ khả năng (可能形: 起きられる, 食べられる...) hoặc động từ vô ý chí vì bản thân không thể chủ động kiểm soát việc "có làm được hay không". Do đó 起きられるために là sai, phải dùng 起きられるように.'},related:["Vるように","〜のために"],kitsuPrompt:"Hỏi tôi về mục tiêu lớn nhất của tôi hiện nay. Tôi sẽ trả lời bằng 〜ために〜ています."},{pattern:"Vるのに〜",meaning:"để làm ~ / dùng cho việc ~ (chức năng/phương tiện)",priority:"medium",explanation:"Vるのに sau đó là tính từ/động từ chức năng biểu thị công dụng hoặc tình huống cần thiết. Thường đi với: 便利だ, 使う, 必要だ, 時間がかかる.",examples:[{sentence:"この道具は魚をさばくのに使います。",translation:"Dụng cụ này dùng để làm cá."},{sentence:"日本語の勉強に辞書は必要なのに、忘れてきた。",translation:"Từ điển cần thiết để học tiếng Nhật mà tôi lại quên mang."},{sentence:"駅まで歩いて行くのに15分かかります。",translation:"Đi bộ đến ga mất 15 phút."}],note:"Vるのに + かかる = tốn thời gian/tiền để làm. Vるのに + 便利 = tiện để làm. Vるのに + 必要 = cần để làm.",dialogue:{jp:"A：このアプリ、何に使うんですか。\nB：発音を練習するのに使っています。とても便利ですよ。",vi:"A: App này dùng để làm gì vậy?\nB: Tôi dùng để luyện phát âm. Tiện lắm."},commonMistake:{wrong:"日本語の勉強のに、この辞書を使います。",correct:"日本語の勉強のために、この辞書を使います。",why:"Vるのに (dùng để làm gì / công dụng) chỉ theo sau ĐỘNG TỪ ở thể từ điển (V る), không thể gắn trực tiếp sau danh từ như 勉強. Khi muốn nói mục đích với danh từ, phải dùng Nのために (không phải Nのに): 日本語の勉強のために辞書を使います. Nếu muốn dùng dạng のに thì phải chuyển thành động từ: 日本語を勉強するのに、この辞書を使います。"},related:["Vるために","Nに使います"],kitsuPrompt:"Hỏi tôi công cụ hay ứng dụng nào tôi dùng để học tiếng Nhật. Tôi sẽ dùng のに."},{pattern:"Nに〜時間／お金がかかります",meaning:"tốn ~ thời gian / tiền cho N",priority:"high",explanation:"かかる (tốn) dùng với thời gian và tiền bạc. Cấu trúc: [hoạt động/nơi] に [lượng thời gian/tiền] がかかります.",examples:[{sentence:"東京から大阪まで新幹線で２時間かかります。",translation:"Từ Tokyo đến Osaka bằng shinkansen mất 2 tiếng."},{sentence:"この修理に10万円かかりました。",translation:"Sửa chữa này tốn 100,000 yên."},{sentence:"料理を作るのに30分かかります。",translation:"Nấu ăn mất 30 phút."}],note:"かかる ≠ 要る (いる). 要る = cần có (物が要る). かかる = tốn (時間・お金がかかる). Cũng dùng: Vるのにかかります.",dialogue:{jp:"A：免許を取るのに、どのくらいお金がかかりましたか。\nB：学校の費用が30万円くらいかかりました。",vi:"A: Lấy bằng lái tốn bao nhiêu tiền vậy?\nB: Chi phí trường học khoảng 300,000 yên."},commonMistake:{wrong:"この作業は時間がかかります。",correct:"この作業に3時間かかります。",why:"Cấu trúc かかる cần chỉ rõ LƯỢNG thời gian/tiền cụ thể đi kèm trợ từ に trước đối tượng tốn kém: [việc] に [số lượng thời gian/tiền] がかかります. Nói chung chung 時間がかかります (không có con số, dùng は thay vì に) làm mất đi thông tin định lượng cần thiết của mẫu câu — câu đúng và đầy đủ phải nêu rõ số lượng: この作業に3時間かかります (công việc này tốn 3 tiếng)."},related:["Vるのに","時間がかかる"],kitsuPrompt:"Hỏi tôi mất bao lâu/tốn bao nhiêu để làm điều gì đó. Tôi sẽ dùng かかります."}]},{bai:43,level:"N4",kanji:"様",reading:"ようす",romaji:"Yousu",titleVi:"Vẻ ngoài & trạng thái",titleJp:"様態のそうだ",descVi:"Dùng 〜そうです để nói về vẻ bề ngoài và những gì sắp xảy ra.",selfCheckGoals:["Phân biệt そうです(様態) và そうです(伝聞) qua 4 câu ví dụ","Chia đúng A い → A (bỏ い) + そうだ và A な → A + そうだ","Dùng Vそうにありません để nói dự báo tiêu cực","Dùng てきます/ていきます đúng hướng di chuyển"],readingPassage:{title:"空模様と旅の準備",titleVi:"Bầu trời và chuẩn bị chuyến đi",japanese:"明日、友だちと山に登る予定ですが、空が曇っていて雨が降りそうです。天気予報によると、午後から晴れるそうですが、傘を持って行きます。出発前に、コンビニで食べ物を買って来ます。山の上は寒そうなので、ジャケットも持って行きます。今日は早めに寝て、明日に備えます。",vietnamese:"Ngày mai tôi có kế hoạch leo núi với bạn, nhưng trời u ám có vẻ sắp mưa. Theo dự báo thời tiết thì chiều sẽ nắng, nhưng tôi sẽ mang ô theo. Trước khi xuất phát tôi sẽ ghé cửa hàng tiện lợi mua đồ ăn rồi quay lại. Vì trên núi có vẻ lạnh nên tôi cũng mang áo khoác theo. Hôm nay tôi ngủ sớm để chuẩn bị cho ngày mai.",highlights:[{excerpt:"雨が降りそうです",label:"そうだ様態 dự đoán"},{excerpt:"晴れるそうですが",label:"そうだ伝聞 nghe nói"},{excerpt:"買って来ます",label:"てくる: đi rồi quay lại"},{excerpt:"寒そうなので",label:"そうだ様態 tính từ"}],questions:[{q:"筆者はなぜ傘を持って行きますか。",options:["雨が降りそうだから","晴れるから","山が寒いから","天気予報が外れるから"],answer:0},{q:"出発前に筆者は何をしますか。",options:["コンビニで食べ物を買う","荷物を確認する","友だちと待ち合わせる","地図を印刷する"],answer:0}]},patterns:[{pattern:"V／Aそうです (様態)",meaning:"có vẻ ~ / trông như sắp ~ (phán đoán từ vẻ ngoài)",priority:"high",explanation:"そうだ (様態) biểu thị phán đoán dựa trên quan sát trực tiếp (vẻ ngoài, cảm giác). Chia: V stem + そう, A い bỏ い + そう, A な bỏ だ + そう. Chú ý: いい→よさそう, ない→なさそう.",examples:[{sentence:"雨が降りそうです。空が暗い。",translation:"Có vẻ trời sắp mưa. Bầu trời tối."},{sentence:"この料理、とてもおいしそうですね！",translation:"Món này trông ngon quá!"},{sentence:"彼は疲れそうな顔をしています。",translation:"Anh ấy trông mặt mệt mỏi."}],note:"Phân biệt với そうです (伝聞 = nghe nói): 様態 → quan sát trực tiếp. 伝聞 → nghe từ nguồn khác.",dialogue:{jp:"A：あのケーキ、おいしそうですね。\nB：そうですね。甘そうだから、コーヒーと一緒に食べたいですね。",vi:"A: Cái bánh kia trông ngon nhỉ.\nB: Nhỉ. Trông ngọt nên muốn ăn cùng cà phê quá."},commonMistake:{wrong:"このケーキはおいしいそうです。",correct:"このケーキはおいしそうです。",why:"そうだ (様態 - phán đoán từ vẻ ngoài) khi ghép với tính từ đuôi い phải bỏ い rồi mới thêm そう: おいしい→おいし+そう=おいしそう. Giữ nguyên おいしい rồi thêm そうです là sai. Lưu ý ngoại lệ đặc biệt: いい→よさそう (không phải いいそう), ない→なさそう."},related:["〜そうです(伝聞)","〜らしいです","〜ようです"],kitsuPrompt:"Cho tôi xem một hình ảnh (bằng chữ mô tả). Tôi sẽ nhận xét bằng 〜そうですね."},{pattern:"Vそうにありません／なさそうです",meaning:"có vẻ sẽ không ~ (dự đoán tiêu cực)",priority:"medium",explanation:"Phủ định của 様態 そうです: Vそうにありません = trông không có vẻ sẽ ~. Thường dùng khi tình hình không thuận lợi. Cũng dùng: Vそうもありません (nhấn mạnh hơn).",examples:[{sentence:"この仕事、今日中に終わりそうにありません。",translation:"Công việc này có vẻ không xong được trong hôm nay."},{sentence:"雨が止みそうにありませんね。",translation:"Mưa có vẻ không tạnh nhỉ."},{sentence:"彼は来そうもないですね。",translation:"Anh ấy có vẻ không đến đâu nhỉ."}],note:"なさそうです = A/N không có vẻ ~ (ない → なさそう). Vそうにない / Vそうもない đều tự nhiên.",dialogue:{jp:"A：電車、まだ来ない？\nB：まだだね。しばらく来そうにないから、座って待とう。",vi:"A: Tàu chưa đến à?\nB: Chưa. Có vẻ chưa đến lâu nên ngồi chờ thôi."},commonMistake:{wrong:"電車がまだ来るそうじゃありませんね。",correct:"電車がまだ来そうにありませんね。",why:"Phủ định của そうだ様態 không chia theo kiểu thông thường N/Aだ→じゃありません. Đúng ra phải dùng mẫu riêng: Vそうにありません hoặc Vそうもありません (V stem + そうに/そうも + ありません). Trong văn nói thân mật, 来なさそうです cũng được chấp nhận (đổi từ dạng phủ định 来ない→来なさそう), nhưng 来そうにありません là cách trang trọng, tự nhiên và phổ biến hơn."},related:["〜そうです(様態)","〜そうもない"],kitsuPrompt:"Tôi đang ở trong tình huống không thuận lợi. Hãy hỏi và tôi sẽ dùng 〜そうにありません."},{pattern:"Vて来ます／Vて行きます",meaning:"đi V rồi quay lại / V rồi đi (hướng di chuyển)",priority:"high",explanation:"てくる: làm gì đó rồi quay lại chỗ nói chuyện (hướng vào). ていく: làm gì đó rồi rời đi khỏi (hướng ra). Cũng biểu thị quá trình thay đổi: 変わってきた (đã bắt đầu thay đổi).",examples:[{sentence:"ちょっとコンビニで買って来ます。",translation:"Tôi ghé cửa hàng tiện lợi mua rồi về ngay."},{sentence:"傘を持って行ってください。",translation:"Hãy mang ô đi nhé."},{sentence:"最近、日本語が上手になって来ましたね。",translation:"Dạo này tiếng Nhật của bạn đã tiến bộ hơn nhỉ."}],note:"てくる cũng biểu thị sự bắt đầu hoặc tiến triển theo hướng người nói: 雨が降ってきた (bắt đầu mưa). ていく: 変わっていく (tiếp tục thay đổi về phía trước).",dialogue:{jp:"A：どこ行くの？\nB：ちょっと郵便局で荷物を送って来るよ。すぐ戻るから待ってて。",vi:"A: Bạn đi đâu vậy?\nB: Ghé bưu điện gửi hàng rồi về ngay. Chờ mình với."},commonMistake:{wrong:"コンビニで飲み物を買いて来ます。",correct:"コンビニで飲み物を買って来ます。",why:"Động từ nhóm I kết thúc bằng う khi chia thể て phải đổi thành って (う→って), không phải いて: 買う→買って (không phải 買いて). Quy tắc âm tiện tương tự áp dụng cho các động từ khác như 持つ→持って来ます, 立つ→立って."},related:["〜てある","〜ておく"],kitsuPrompt:"Hỏi tôi đang đi đâu. Tôi sẽ dùng てきます hoặc ていきます để trả lời."}]},{bai:44,level:"N4",kanji:"過",reading:"すぎる",romaji:"Sugiru",titleVi:"Quá mức & cách làm",titleJp:"程度と方法",descVi:"Dùng 〜すぎます cho mức độ vượt quá và V方 để nói cách làm việc gì.",selfCheckGoals:["Tạo câu với すぎます cho cả V và A trong 5 ví dụ","Dùng やすい/にくい với V stem để mô tả tính dễ/khó",'Hỏi "cách làm" bằng Vる方はどうですか / V方を教えてください',"Phân biệt すぎます (quá mức xấu) và とても (mức cao, trung tính)"],readingPassage:{title:"新しいスマホの使い方",titleVi:"Cách dùng điện thoại mới",japanese:"新しいスマホを買いました。画面が大きくて見やすいですが、少し重くて持ちにくいです。使い方がわからなくて、説明書を読みましたが、説明が難しすぎて困りました。友だちに設定の仕方を教えてもらいました。アプリが多すぎて、どれを使えばいいか迷っています。でも、写真がきれいに撮れるので、気に入っています。",vietnamese:"Tôi mua điện thoại mới. Màn hình lớn nhìn dễ nhưng hơi nặng khó cầm. Không biết cách dùng nên đọc sách hướng dẫn nhưng hướng dẫn khó quá tôi bối rối. Tôi nhờ bạn chỉ cách cài đặt. Có quá nhiều ứng dụng nên tôi đang phân vân không biết dùng cái nào. Nhưng vì chụp ảnh đẹp nên tôi thích.",highlights:[{excerpt:"見やすいですが",label:"やすい dễ"},{excerpt:"持ちにくいです",label:"にくい khó"},{excerpt:"難しすぎて困りました",label:"すぎて kết quả xấu"},{excerpt:"設定の仕方を教えてもらいました",label:"V方 cách làm"}],questions:[{q:"スマホについて、見やすい理由は何ですか。",options:["画面が大きいから","軽いから","説明書があるから","カメラが良いから"],answer:0},{q:"筆者はスマホの設定をどうしましたか。",options:["友だちに教えてもらった","説明書を読んだ","自分で調べた","お店に行った"],answer:0}]},patterns:[{pattern:"Vすぎます／Aすぎます",meaning:"~ quá (vượt mức bình thường, thường tiêu cực)",priority:"high",explanation:"V stem + すぎる hoặc A (bỏ い/だ) + すぎる biểu thị mức độ vượt quá ngưỡng bình thường, thường mang nghĩa tiêu cực. すぎて + kết quả xấu rất phổ biến.",examples:[{sentence:"昨日、飲みすぎて、頭が痛いです。",translation:"Hôm qua uống quá nhiều nên đau đầu."},{sentence:"この荷物は重すぎて、一人では持てません。",translation:"Cái này nặng quá, một mình tôi không mang được."},{sentence:"部屋が暑すぎて、眠れませんでした。",translation:"Phòng nóng quá nên không ngủ được."}],note:"Danh từ hóa: 食べすぎ (ăn quá nhiều), 飲みすぎ (uống quá nhiều) — dùng như danh từ độc lập.",dialogue:{jp:"A：最近、疲れているね。\nB：仕事が忙しすぎて、全然休めていないんです。",vi:"A: Dạo này trông mệt nhỉ.\nB: Công việc bận quá nên không nghỉ ngơi được gì."},commonMistake:{wrong:"昨日、食べますすぎて、お腹が痛かったです。それに、このドレスはきれいすぎです。",correct:"昨日、食べすぎて、お腹が痛かったです。それに、このドレスはきれいすぎます。",why:"すぎる luôn ghép vào V stem (bỏ hẳn đuôi ます), không giữ nguyên dạng ます rồi thêm すぎます: 食べます→食べすぎます (không phải 食べますすぎます). Với tính từ (kể cả な-tính từ như きれい), すぎる là một động từ hoàn chỉnh nên phải chia đủ ます: きれいすぎます, không được bỏ lửng thành きれいすぎです."},related:["〜すぎる→すぎて","とても〜"],kitsuPrompt:"Hỏi tôi về những thói quen không tốt cho sức khỏe. Tôi sẽ dùng すぎます."},{pattern:"Vやすい／にくいです",meaning:"dễ làm ~ / khó làm ~ (tính chất của đối tượng)",priority:"high",explanation:"V stem + やすい/にくい: やすい = dễ/có xu hướng ~, にくい = khó/không dễ ~. Nói về tính chất của vật hoặc hành động, không phải về khả năng của người.",examples:[{sentence:"この説明書は読みやすいです。",translation:"Tờ hướng dẫn này dễ đọc."},{sentence:"あの先生の話は聞き取りにくいです。",translation:"Giáo viên đó nói khó nghe."},{sentence:"このペンは書きやすいですね。",translation:"Cái bút này viết dễ nhỉ."}],note:"やすい ≠ 簡単だ. やすい nói về đặc tính của vật (dễ dùng), 簡単 nói về độ phức tạp của nhiệm vụ.",dialogue:{jp:"A：このアプリ、使いやすいですか。\nB：最初は少し慣れにくいですが、慣れると使いやすいですよ。",vi:"A: App này dễ dùng không?\nB: Lúc đầu hơi khó quen, nhưng quen rồi thì dễ dùng."},commonMistake:{wrong:"この料理は食べるやすいです。それに、この部屋はきれいやすいです。",correct:"この料理は食べやすいです。それに、この部屋は片付けやすいです。",why:"やすい／にくい phải ghép trực tiếp vào V stem (bỏ đuôi る/ます), không giữ nguyên thể từ điển: 食べる→食べやすい (không phải 食べるやすい). Ngoài ra やすい／にくい chỉ dùng với ĐỘNG TỪ để nói về đặc tính dễ/khó thực hiện hành động, KHÔNG gắn trực tiếp vào tính từ như きれい — muốn diễn đạt phải chuyển sang động từ tương ứng, ví dụ 片付けやすい (dễ dọn dẹp)."},related:["〜すぎます","V方"],kitsuPrompt:"Hỏi tôi về điện thoại/sách/ứng dụng nào đó. Tôi sẽ dùng やすい/にくい để mô tả."},{pattern:"V方",meaning:"cách V / phương pháp V",priority:"high",explanation:"V stem + 方 (かた) = cách làm gì đó. Dùng khi hỏi hoặc giải thích phương pháp thực hiện hành động. 方 đọc là かた.",examples:[{sentence:"この機械の使い方を教えてください。",translation:"Hãy dạy tôi cách dùng máy này."},{sentence:"漢字の読み方を調べました。",translation:"Tôi đã tra cách đọc chữ Hán."},{sentence:"作り方は簡単です。材料を混ぜるだけです。",translation:"Cách làm đơn giản. Chỉ cần trộn nguyên liệu lại."}],note:"行き方 (cách đi đến), 食べ方 (cách ăn), 書き方 (cách viết)... Tất cả đều theo mẫu V stem + 方.",dialogue:{jp:"A：この料理の作り方を教えてもらえますか。\nB：まず、野菜を切ります。それから…",vi:"A: Bạn có thể chỉ cách làm món này không?\nB: Trước tiên cắt rau. Sau đó..."},commonMistake:{wrong:"この料理の食べる方を教えてください。",correct:"この料理の食べ方を教えてください。",why:"方 (かた, nghĩa cách làm) phải ghép với V stem (bỏ đuôi ます/る): 食べ+方=食べ方. Nếu dùng nguyên thể động từ như 食べる方 thì ý nghĩa lại chuyển sang cách nói kính trọng chỉ NGƯỜI làm hành động đó (vd 食べる方はどなたですか = Vị nào là người ăn?), không còn là cách làm nữa — dễ gây hiểu nhầm nếu nhầm hai mẫu này."},related:["Vやすい/にくい","〜方法"],kitsuPrompt:"Hỏi tôi cách làm một việc gì đó bằng 〜方はどうやりますか. Tôi sẽ giải thích."}]},{bai:45,level:"N4",kanji:"場",reading:"ばあい",romaji:"Baai",titleVi:"Trường hợp & đối lập",titleJp:"場合と逆接",descVi:'Nói "trong trường hợp..." với ばあいは và "mặc dù... nhưng" với のに.',selfCheckGoals:["Dùng 場合は trong hướng dẫn/quy tắc với 3 tình huống khác nhau","Phân biệt のに (đối lập bực bội) và けれど (đối lập trung tính)","Tạo câu のに thể hiện sự bất ngờ, thất vọng","Đọc bảng hướng dẫn khẩn cấp có chứa 場合は"],readingPassage:{title:"緊急時のマニュアル",titleVi:"Hướng dẫn khẩn cấp",japanese:"地震が起きた場合は、まず机の下に隠れてください。火事が起きた場合は、エレベーターを使わないでください。停電の場合は、非常口の表示を探して避難してください。せっかく練習したのに、本番では忘れてしまいそうで心配です。こんなに準備したのに、うまくいかないかもしれないと思うと不安です。",vietnamese:"Trong trường hợp xảy ra động đất, trước tiên hãy trốn dưới bàn. Trong trường hợp hỏa hoạn, đừng dùng thang máy. Trong trường hợp mất điện, hãy tìm biển hiệu lối thoát hiểm rồi sơ tán. Tôi lo lắng vì dù đã luyện tập công phu nhưng sợ lúc thật sẽ quên. Nghĩ rằng dù đã chuẩn bị nhiều như vậy nhưng có thể không suôn sẻ thì thấy lo.",highlights:[{excerpt:"地震が起きた場合は",label:"場合は tình huống"},{excerpt:"停電の場合は",label:"N の場合は"},{excerpt:"練習したのに、忘れてしまいそう",label:"のに bực bội"},{excerpt:"こんなに準備したのに",label:"のに thất vọng"}],questions:[{q:"火事が起きた場合は何をしてはいけませんか。",options:["エレベーターを使う","階段を使う","外に出る","窓を開ける"],answer:0},{q:"筆者はなぜ心配していますか。",options:["練習したのに本番で忘れそうだから","準備が足りないから","仲間がいないから","時間がないから"],answer:0}]},patterns:[{pattern:"V／A／Nのばあいは",meaning:"trong trường hợp ~ (điều kiện giả định)",priority:"high",explanation:'〜場合は biểu thị "trong trường hợp ~" — điều kiện giả định hoặc hướng dẫn cho tình huống cụ thể. Thường dùng trong văn bản hành chính, hướng dẫn an toàn, quy tắc.',examples:[{sentence:"遅刻する場合は、事前に連絡してください。",translation:"Trong trường hợp đến muộn hãy liên lạc trước."},{sentence:"急病の場合は、すぐに119番に電話してください。",translation:"Trong trường hợp bệnh đột ngột hãy gọi ngay 119."},{sentence:"不合格の場合は、もう一度受けられます。",translation:"Trong trường hợp trượt có thể thi lại một lần nữa."}],note:"Khác với たら (điều kiện thực tế): 場合は thường dùng cho tình huống giả định, quy tắc. Cũng dùng: 〜ばあいでも (ngay cả trong trường hợp).",dialogue:{jp:"A：パスワードを忘れた場合は、どうすればいいですか。\nB：このボタンを押して、メールアドレスを入力してください。",vi:"A: Trong trường hợp quên mật khẩu thì làm thế nào?\nB: Hãy nhấn nút này rồi nhập địa chỉ email."},commonMistake:{wrong:"遅刻する場合、連絡してください。",correct:"遅刻する場合は、連絡してください。",why:"Mẫu 〜場合は cần trợ từ は để nhấn mạnh đây là chủ đề của tình huống/điều kiện đang nói tới. Bỏ は câu vẫn hiểu được nhưng trở nên nhạt và không tự nhiên, đặc biệt trong văn bản hướng dẫn, quy tắc, thông báo hành chính nơi 〜場合は, 〜してください là cấu trúc chuẩn."},related:["〜たら","〜ば","〜とき"],kitsuPrompt:"Tôi đóng vai nhân viên khách sạn. Hỏi tôi về các quy định phòng cháy. Tôi sẽ dùng 〜場合は."},{pattern:"〜のに (逆接)",meaning:"mặc dù ~ nhưng ~ (bất ngờ, thất vọng)",priority:"high",explanation:"のに (đối lập) biểu thị sự tương phản bất ngờ — thường kèm cảm xúc bực bội, thất vọng, tiếc nuối. Vế trước là mệnh đề bình thường, のに là liên từ giữa hai vế.",examples:[{sentence:"こんなに練習したのに、試験に落ちました。",translation:"Dù đã luyện tập nhiều như vậy nhưng lại trượt thi."},{sentence:"もう9時なのに、彼はまだ来ていません。",translation:"Dù đã 9 giờ rồi nhưng anh ấy vẫn chưa đến."},{sentence:"せっかく作ったのに、食べてくれませんでした。",translation:"Dù đã cất công làm nhưng anh ấy không ăn."}],note:"のに (đối lập) ≠ のに (mục đích = để làm). Phân biệt theo ngữ cảnh. せっかく〜のに = tiếc rằng dù đã cố công ~ nhưng...",dialogue:{jp:"A：あれ、傘を持ってきたのに、雨が降らなかったね。\nB：でも、持ってきて良かったよ。午後から降るかもしれないから。",vi:"A: Ơ, mang ô theo rồi mà trời không mưa nhỉ.\nB: Nhưng may mang theo đấy. Chiều có thể mưa mà."},commonMistake:{wrong:"彼は学生だのに、もう働いています。",correct:"彼は学生なのに、もう働いています。",why:"Khi danh từ đứng trước のに (đối lập), phải thêm な chứ không giữ だ: N + なのに (không phải N + だのに), vì のに vốn nối vào thể ngắn な của Nな/だ giống tính từ đuôi な. Ngoài ra, のに bắt buộc vế sau phải mang tính bất ngờ/trái kỳ vọng so với vế trước — nếu hai vế không có sự tương phản rõ ràng (ví dụ chỉ mô tả trạng thái bình thường nối tiếp nhau) thì dùng のに sẽ nghe khó hiểu hoặc sai ngữ dụng."},related:["〜けれど","〜が(逆接)","〜でも"],kitsuPrompt:"Hỏi tôi về điều gì đó tôi đã cố gắng nhưng không thành. Tôi sẽ dùng のに để thể hiện sự tiếc nuối."}]},{bai:46,level:"N4",kanji:"際",reading:"ところ",romaji:"Tokoro",titleVi:"Thời điểm hành động",titleJp:"ところと最近",descVi:'Nói "sắp làm", "đang làm", "vừa xong" bằng ところ và ばかり.',selfCheckGoals:["Phân biệt 3 dạng ところ: るところ / ているところ / たところ","Phân biệt たところ (vừa xong, khách quan) và たばかり (vừa xong, cảm giác còn mới)","Mô tả đúng giai đoạn hành động đang ở đâu trong 5 tình huống","Dùng ばかり với thói quen mới bắt đầu: 〜始めたばかりです"],readingPassage:{title:"新入社員の一日",titleVi:"Một ngày của nhân viên mới",japanese:"今日から新しい会社で働き始めました。まだ入社したばかりなので、わからないことがたくさんあります。今は、会社のルールを説明してもらっているところです。お昼ごろ、ちょうど上司が部屋から出てきたところに出会いました。午後は書類を整理し終わったところで、先輩に確認してもらいます。まだ仕事に慣れていませんが、頑張ります。",vietnamese:"Hôm nay bắt đầu làm việc ở công ty mới. Vì mới vào công ty nên còn nhiều điều chưa hiểu. Hiện tại đang được giải thích về quy tắc công ty. Buổi trưa tôi tình cờ gặp cấp trên vừa bước ra khỏi phòng. Buổi chiều vừa xong việc sắp xếp tài liệu, tôi nhờ đàn anh kiểm tra. Tôi chưa quen với công việc nhưng sẽ cố gắng.",highlights:[{excerpt:"入社したばかりなので",label:"たばかり vừa mới"},{excerpt:"説明してもらっているところです",label:"ているところ đang làm"},{excerpt:"出てきたところに出会いました",label:"たところ vừa xong"},{excerpt:"整理し終わったところで",label:"たところ thời điểm xong"}],questions:[{q:"今、筆者は何をしているところですか。",options:["会社のルールを説明してもらっている","書類を整理している","上司と話している","昼ごはんを食べている"],answer:0},{q:"筆者はなぜわからないことが多いですか。",options:["まだ入社したばかりだから","日本語が難しいから","仕事が複雑だから","先輩がいないから"],answer:0}]},patterns:[{pattern:"Vるところです",meaning:"sắp ~ (ngay bây giờ, chuẩn bị thực hiện)",priority:"high",explanation:'V thể từ điển + ところ biểu thị thời điểm ngay trước khi hành động bắt đầu. Nhấn mạnh "chuẩn bị làm, chưa làm". Thường kết hợp với 今から, ちょうど.',examples:[{sentence:"ちょうど出かけるところです。",translation:"Tôi đang chuẩn bị ra ngoài đây."},{sentence:"今から昼ごはんを食べるところです。",translation:"Bây giờ tôi chuẩn bị ăn trưa."},{sentence:"電話をするところでした。",translation:"Tôi chuẩn bị gọi điện (nhưng...). "}],note:"Vるところ + でした = chuẩn bị làm nhưng đã bị gián đoạn. Rất thường gặp trong câu chuyện kể.",dialogue:{jp:"A：どこかへ行くんですか。\nB：ええ、ちょうど駅へ行くところです。一緒に行きますか。",vi:"A: Bạn đi đâu à?\nB: Vâng, tôi đang chuẩn bị ra ga đây. Đi cùng không?"},commonMistake:{wrong:"田中さんは今、ご飯を食べるところです。",correct:"田中さんは今、ご飯を食べているところです。",why:'Vるところです (chưa xảy ra, sắp làm) khác hẳn Vているところです (đang diễn ra giữa chừng). Nếu hành động đang thực sự xảy ra ngay lúc nói (đang ăn) thì phải dùng thể ている + ところ, không dùng thể từ điển + ところ vì thể đó chỉ diễn tả "sắp" chứ chưa bắt đầu.'},related:["Vているところ","Vたところ"],kitsuPrompt:'Gọi điện hỏi tôi đang làm gì. Tôi sẽ nói "vừa chuẩn bị ~" bằng るところです.'},{pattern:"Vているところです",meaning:"đang ~ (ngay lúc này, giữa chừng)",priority:"high",explanation:'V thể ている + ところ biểu thị hành động đang tiếp diễn ngay tại thời điểm nói, nhấn mạnh "đang ở giữa chừng". Thường dùng khi được hỏi đột ngột.',examples:[{sentence:"今、調べているところです。",translation:"Tôi đang tra cứu đây."},{sentence:"書類を作っているところですが、少し待ってください。",translation:"Tôi đang làm tài liệu, xin chờ một chút."},{sentence:"今ちょうど話し合っているところです。",translation:"Chúng tôi đang thảo luận đây."}],note:'Vているところ mạnh hơn Vています về nghĩa "đang ở giữa việc đó ngay lúc này".',dialogue:{jp:"A：山田さん、資料できましたか。\nB：今、最終確認をしているところです。あと10分ほどで終わります。",vi:"A: Yamada-san, tài liệu xong chưa?\nB: Tôi đang kiểm tra lần cuối đây. Khoảng 10 phút nữa xong."},commonMistake:{wrong:"今、調べているところします。",correct:"今、調べているところです。",why:"Sau ところ (khi kết câu) phải theo bằng です, không phải します — ところ là danh từ hình thức nên chia như danh từ (ところです / ところでした), không chia theo động từ する. Ngoài ra ところ còn có thể theo sau bằng に気づいた, に電話がかかってきた... nhưng không phải します."},related:["Vるところ","Vたところ"],kitsuPrompt:'Gọi điện hỏi tôi đang làm gì. Tôi sẽ nói "đang ~" bằng ているところです.'},{pattern:"Vたところです",meaning:"vừa mới ~ xong (ngay trước đây, khách quan)",priority:"high",explanation:"V thể た + ところ biểu thị hành động vừa mới hoàn thành ngay trước đó. Mang tính khách quan về thời điểm. Thường kết hợp: たった今〜たところ.",examples:[{sentence:"たった今、着いたところです。",translation:"Tôi vừa mới đến đây."},{sentence:"宿題をやり終えたところです。",translation:"Tôi vừa mới làm xong bài tập."},{sentence:"ちょうど食べ終えたところでした。",translation:"Tôi vừa mới ăn xong đúng lúc."}],note:'たところ nhấn mạnh thời điểm vừa xong. たばかり nhấn mạnh cảm giác "mới mẻ, chưa quen". Thường có thể thay nhau nhưng sắc thái khác.',dialogue:{jp:"A：お待たせしました。\nB：いいえ、私も今来たところです。",vi:"A: Xin lỗi để bạn chờ.\nB: Không sao, tôi cũng vừa mới đến đây."},commonMistake:{wrong:"私も今来たところですから、少し待ってください。",correct:"私も今来たところなので、少し待ってください。",why:"から sau たところです nghe không tự nhiên vì ところです đã mang sắc thái kết câu/miêu tả trạng thái khách quan; khi cần nối lý do nên dùng ので (hoặc tách thành câu riêng rồi giải thích ở câu sau), tránh ghép trực tiếp からsau ところです."},related:["Vたばかり","Vているところ"],kitsuPrompt:"Hỏi tôi vừa làm xong gì. Tôi sẽ trả lời bằng たところです."},{pattern:"Vたばかりです",meaning:"mới ~ (cảm giác còn mới, chưa quen)",priority:"high",explanation:'V thể た + ばかり biểu thị hành động vừa xảy ra với cảm giác "còn mới mẻ". Khoảng thời gian có thể không quá ngắn (vài ngày/tuần) nhưng người nói cảm thấy vẫn còn "mới".',examples:[{sentence:"日本に来たばかりで、まだ慣れていません。",translation:"Tôi mới sang Nhật nên chưa quen."},{sentence:"結婚したばかりなので、新居を探しています。",translation:"Mới cưới xong nên đang tìm nhà mới."},{sentence:"食べたばかりなので、まだおなかがいっぱいです。",translation:"Vừa mới ăn xong nên vẫn còn no."}],note:"ばかり cũng có nghĩa khác: Vてばかり (chỉ làm mỗi việc đó): ゲームばかりしている (chỉ chơi game thôi).",dialogue:{jp:"A：日本語、上手ですね。\nB：ありがとうございます。でも、まだ勉強を始めたばかりです。",vi:"A: Tiếng Nhật bạn giỏi nhỉ.\nB: Cảm ơn. Nhưng tôi mới bắt đầu học thôi."},commonMistake:{wrong:"すみません、来るばかりです。",correct:"すみません、来たばかりです。",why:'たばかり luôn phải đi với động từ thể た (đã xảy ra) vì ý nghĩa là "vừa mới ~ xong"; không thể dùng thể từ điển (るばかり) vì như vậy sẽ mất nghĩa "vừa mới", câu trở nên vô nghĩa. Đúng: 来たばかりです (vừa mới đến).'},related:["Vたところ","まだ〜ていません"],kitsuPrompt:"Hỏi tôi về điều gì đó tôi mới bắt đầu học/làm. Tôi sẽ dùng たばかりです."}]},{bai:47,level:"N4",kanji:"伝",reading:"つたえる",romaji:"Tsutaeru",titleVi:"Truyền đạt & nghe nói",titleJp:"伝聞",descVi:"Dùng 〜そうです (truyền đạt) và 〜らしい để nói nghe đồn / có vẻ.",selfCheckGoals:["Phân biệt そうです(様態) và そうです(伝聞) qua 5 câu ví dụ","Phân biệt らしい (nghe đồn/có vẻ từ bằng chứng) và ようだ (phán đoán từ quan sát)","Dùng によると để trích nguồn thông tin một cách tự nhiên","Viết 2 câu tin tức bằng 〜によると〜そうです"],readingPassage:{title:"うわさ話",titleVi:"Chuyện nghe đồn",japanese:"友だちの話によると、近くのカフェが来月閉店するそうです。あのカフェはいつも混んでいて、人気があるらしいのに、残念ですね。ネットの情報によると、新しい場所に移転するらしいです。でも、まだ確かではないようです。田中さんはもう知っているらしくて、新しい場所も調べていたそうです。",vietnamese:"Theo lời bạn tôi, quán cà phê gần đây nghe nói tháng sau sẽ đóng cửa. Dù nghe nói quán đó lúc nào cũng đông và nổi tiếng mà, tiếc nhỉ. Theo thông tin trên mạng thì hình như sẽ chuyển sang địa điểm mới. Nhưng có vẻ chưa chắc chắn. Nghe nói Tanaka-san đã biết rồi và còn điều tra cả địa điểm mới.",highlights:[{excerpt:"友だちの話によると",label:"によると nguồn tin"},{excerpt:"閉店するそうです",label:"そうです伝聞"},{excerpt:"人気があるらしいのに",label:"らしい nghe nói"},{excerpt:"移転するらしいです",label:"らしい suy đoán"}],questions:[{q:"近くのカフェはどうなるそうですか。",options:["来月閉店する","移転しない","値段が上がる","新しいメニューが増える"],answer:0},{q:"田中さんについて何がわかりますか。",options:["新しい場所を調べていた","閉店を知らなかった","カフェのオーナーだ","新しい場所に行った"],answer:0}]},patterns:[{pattern:"〜そうです (伝聞)",meaning:"nghe nói ~ (truyền đạt thông tin từ nguồn khác)",priority:"high",explanation:"そうです (伝聞/truyền đạt) theo sau V/A/N thể bình thường biểu thị thông tin nghe được từ người khác hoặc nguồn khác. Khác với 様態そうです: 伝聞 dùng thể bình thường đầy đủ (食べるそうだ, 食べたそうだ).",examples:[{sentence:"天気予報によると、明日は雨が降るそうです。",translation:"Theo dự báo thời tiết, nghe nói ngày mai trời mưa."},{sentence:"田中さんは病気で休んでいるそうです。",translation:"Nghe nói Tanaka-san đang nghỉ vì bệnh."},{sentence:"あの店は安くておいしいそうですよ。",translation:"Nghe nói quán đó vừa rẻ vừa ngon đó."}],note:"Phân biệt: 高そうです (trông có vẻ đắt — 様態) vs 高いそうです (nghe nói đắt — 伝聞).",dialogue:{jp:"A：あの映画、面白いですか。\nB：まだ見ていませんが、友だちがとても面白いそうです。",vi:"A: Bộ phim đó có hay không?\nB: Tôi chưa xem nhưng bạn tôi nói rất hay."},commonMistake:{wrong:"友だちの話では、あの映画はとても面白そうです。",correct:"友だちの話では、あの映画はとても面白いそうです。",why:'面白そうです (様態 - thể trạng thái, bỏ い thêm そう) nghĩa là "trông có vẻ hay" dựa trên quan sát trực tiếp của người nói, còn 面白いそうです (伝聞 - truyền đạt, giữ nguyên thể thường + そうだ) nghĩa là "nghe người khác nói là hay". Khi trích lời người khác (友だちの話では) phải dùng 伝聞 nên phải giữ đủ 面白い + そうです, không được bỏ い.'},related:["〜らしいです","〜ようです","〜によると"],kitsuPrompt:"Chia sẻ với tôi tin tức bạn nghe được. Tôi sẽ phản hồi bằng 〜そうですね hoặc 〜そうです."},{pattern:"〜らしいです",meaning:"có vẻ ~ / nghe nói ~ (suy luận từ bằng chứng gián tiếp)",priority:"high",explanation:'らしい theo sau V/A/N thể bình thường biểu thị suy luận từ thông tin gián tiếp (nghe đồn, dấu hiệu quan sát, tình hình chung). Thường mang nghĩa "theo như tôi biết/thấy thì có vẻ...".',examples:[{sentence:"山田さんは転職したらしいです。",translation:"Có vẻ Yamada-san đã đổi việc rồi."},{sentence:"日本の夏はとても暑いらしいですよ。",translation:"Nghe nói mùa hè Nhật Bản nóng lắm đó."},{sentence:"彼は毎日残業しているらしい。顔色が悪い。",translation:"Có vẻ anh ấy làm thêm giờ mỗi ngày. Nhìn trông xấu sắc."}],note:'らしい cũng có nghĩa "mang đặc tính của ~" khi theo sau N: 男らしい (nam tính), 日本らしい (mang phong cách Nhật).',dialogue:{jp:"A：マリアさん、最近見かけないね。\nB：どこかに引っ越したらしいよ。先週から姿が見えないから。",vi:"A: Dạo này không thấy Maria nhỉ.\nB: Nghe nói chuyển đi đâu rồi. Tuần trước từ đó không thấy bóng."},commonMistake:{wrong:"山田さんは明日、東京へ来るらしいです。彼女に会った人から聞きました。",correct:"山田さんは明日、東京へ来るらしいです。彼女に会った人から聞きました。",why:"らしい dùng được với cả V thể hiện tại (るらしい - sắp/sẽ xảy ra theo tin đồn) lẫn thể quá khứ (たらしい - đã xảy ra theo tin đồn); nhiều học viên tưởng らしい chỉ dùng cho việc đã xảy ra nên tránh dùng るらしい cho việc tương lai, nhưng thực ra るらしい hoàn toàn tự nhiên khi nói về việc sắp xảy ra nghe đồn được, còn たらしい tự nhiên hơn khi nói về việc đã xảy ra."},related:["〜そうです(伝聞)","〜ようです","によると"],kitsuPrompt:"Kể cho tôi nghe điều gì đó bạn nghe đồn. Tôi sẽ phản hồi bằng らしいですね."},{pattern:"Nによると",meaning:"theo N / dựa theo N (trích nguồn thông tin)",priority:"high",explanation:'によると theo sau nguồn thông tin (N = người, sách, báo, dự báo...) biểu thị "theo như ~ nói/viết". Thường đi kèm với 〜そうだ hoặc 〜らしい ở cuối câu.',examples:[{sentence:"ニュースによると、大きな地震があったそうです。",translation:"Theo tin tức, nghe nói đã có động đất lớn."},{sentence:"天気予報によると、明日は晴れるらしいです。",translation:"Theo dự báo thời tiết, có vẻ ngày mai nắng."},{sentence:"田中さんの話によると、あの店は安いそうですよ。",translation:"Theo lời Tanaka-san, nghe nói quán đó rẻ lắm."}],note:"によると không dùng khi người nói là nguồn thông tin của chính mình. Chỉ khi trích dẫn nguồn khác.",dialogue:{jp:"A：なんか、うちの会社、合併するって聞いたけど。\nB：本当に？誰の話によると？\nA：山田部長の話によると、来年合併するそうだよ。",vi:"A: Nghe nói công ty mình sẽ sáp nhập.\nB: Thật à? Theo lời ai vậy?\nA: Theo lời trưởng phòng Yamada, nghe nói năm sau sẽ sáp nhập."},commonMistake:{wrong:"私によると、この本はとても面白いです。",correct:"私の意見では、この本はとても面白いです。",why:"によると chỉ dùng để trích dẫn NGUỒN THÔNG TIN BÊN NGOÀI (báo, dự báo, lời người khác), không dùng cho ý kiến/quan điểm của chính người nói. Khi muốn nêu ý kiến bản thân phải dùng 私の意見では hoặc 私は〜と思います, không được ghép 私によると."},related:["〜そうです(伝聞)","〜らしい"],kitsuPrompt:"Chia sẻ tin tức nào đó bằng 〜によると〜そうです. Tôi sẽ hỏi thêm chi tiết."}]},{bai:48,level:"N4",kanji:"使",reading:"しえき",romaji:"Shieki",titleVi:"Thể sai khiến",titleJp:"使役",descVi:"Chia động từ sang sai khiến — bắt hoặc cho phép ai làm gì.",selfCheckGoals:["Chia đúng V使役形 của 5 động từ (nhóm I, II, III)","Phân biệt を + V使役 (bắt làm) và に + V使役 (cho phép/yêu cầu)","Dùng させていただきます để xin phép lịch sự trong 3 tình huống","Nhận biết sai khiến trong câu bị động kép: させられる"],readingPassage:{title:"親の教育方針",titleVi:"Phương châm giáo dục của cha mẹ",japanese:"私の父は厳しくて、毎日ピアノを練習させました。嫌いだったけど、今は感謝しています。子どもに好きなことをさせることも大切ですが、時には無理にでもやらせることが必要だと思います。先生方には、子どもたちに色々な経験をさせてほしいとお願いしています。また、会議を早退させていただきたいのですが、子どもが熱を出したので。",vietnamese:"Bố tôi nghiêm khắc, bắt tôi luyện đàn piano mỗi ngày. Tôi ghét lắm nhưng bây giờ thì biết ơn. Cho trẻ con làm điều mình thích cũng quan trọng, nhưng tôi nghĩ đôi khi cần bắt làm dù không muốn. Tôi đã nhờ các thầy cô cho trẻ trải nghiệm nhiều thứ. Ngoài ra, tôi muốn xin phép về sớm trước khi họp kết thúc, vì con tôi bị sốt.",highlights:[{excerpt:"毎日ピアノを練習させました",label:"V使役形 bắt làm"},{excerpt:"好きなことをさせること",label:"させる cho phép"},{excerpt:"やらせることが必要",label:"させる bắt làm"},{excerpt:"会議を早退させていただきたい",label:"させていただく xin phép"}],questions:[{q:"父は筆者に何をさせましたか。",options:["ピアノを練習させた","勉強させた","早起きさせた","料理させた"],answer:0},{q:"筆者はなぜ早退したいのですか。",options:["子どもが熱を出したから","仕事が終わったから","病院に行くから","用事があるから"],answer:0}]},patterns:[{pattern:"V使役形",meaning:"thể sai khiến (bắt / cho phép ai làm gì)",priority:"high",explanation:"Thể sai khiến (causative form): Nhóm I: âm cuối い→あ+せる (書く→書かせる, 飲む→飲ませる). Nhóm II: bỏ る+させる. Nhóm III: させる, 来させる. Kết hợp: Nを V させる (bắt N làm) hoặc N に V させる (để/cho N làm).",examples:[{sentence:"先生は学生に作文を書かせました。",translation:"Thầy bắt học sinh viết bài văn."},{sentence:"子どもに好きな服を選ばせました。",translation:"Tôi để con chọn quần áo mình thích."},{sentence:"部長は私を早く来させました。",translation:"Trưởng phòng bắt tôi đến sớm."}],note:"を + V使役: bắt làm (không thể từ chối). に + V使役: cho phép / để làm (ít áp lực hơn).",dialogue:{jp:"A：子育てで何が大変ですか。\nB：野菜が嫌いな子どもに野菜を食べさせるのが一番大変です。",vi:"A: Nuôi dạy con cái điều gì vất vả nhất?\nB: Bắt đứa con ghét rau ăn rau là khó nhất."},commonMistake:{wrong:"野菜が嫌いな子どもに野菜を食べれるのが一番大変です。",correct:"野菜が嫌いな子どもに野菜を食べさせるのが一番大変です。",why:'食べれる là thể khả năng (có thể ăn được — năng lực), còn 食べさせる là thể sai khiến (bắt/để ai đó ăn). Hai thể chia hoàn toàn khác nhau (khả năng: bỏ る thêm られる/れる; sai khiến: bỏ る thêm させる) và mang nghĩa khác hẳn — câu muốn nói "bắt con ăn rau" phải dùng thể sai khiến 食べさせる, dùng nhầm 食べれる sẽ thành "con có thể ăn được rau", sai nghĩa.'},related:["V受身形","V使役受身形"],kitsuPrompt:"Hỏi tôi về điều bố mẹ hay thầy cô đã bắt tôi làm khi còn nhỏ. Tôi sẽ dùng させました."},{pattern:"Nを Vさせます",meaning:"bắt N làm ~ (sai khiến với tân ngữ)",priority:"medium",explanation:"Cấu trúc đầy đủ: (Người ra lệnh) は (người làm) を/に (mục tiêu) を V させる. を + V させる = bắt (không có quyền từ chối). に + V させる = để/cho phép.",examples:[{sentence:"監督は選手を走らせました。",translation:"Huấn luyện viên bắt vận động viên chạy."},{sentence:"社長は社員を出張させました。",translation:"Giám đốc cho/phái nhân viên đi công tác."},{sentence:"部下に資料を作らせます。",translation:"Tôi để cấp dưới làm tài liệu."}],note:"Trong thực tế, を vs に thường phụ thuộc vào văn hóa/ngữ cảnh hơn là ngữ pháp cứng nhắc.",dialogue:{jp:"A：どうしてあんなに部下に仕事をさせるんですか。\nB：自分で経験させないと、成長しないんです。",vi:"A: Sao anh cứ để cấp dưới làm việc vậy?\nB: Không để họ tự trải nghiệm thì không lớn được."},commonMistake:{wrong:"上司は部下を仕事にさせました。",correct:"上司は部下に仕事をさせました。",why:"Trong câu sai khiến có tân ngữ, người bị sai khiến phải đi với に (部下に), còn việc/tân ngữ đi với を (仕事を). Học viên hay nhầm gắn を cho người và に cho việc, khiến câu sai ngữ pháp — cấu trúc chuẩn luôn là (người ra lệnh)は(người làm)に(việc)をV させる."},related:["V使役形","V使役受身形"],kitsuPrompt:"Đóng vai quản lý phân công công việc. Dùng させます để nói về việc giao cho cấp dưới."},{pattern:"Vさせていただきます",meaning:"(khiêm nhường) xin phép được ~ / cho tôi ~",priority:"high",explanation:"させていただく = させてもらう (kính ngữ khiêm nhường). Biểu thị xin phép hoặc trân trọng đề xuất hành động của mình. Rất phổ biến trong ngữ cảnh kinh doanh, hội họp.",examples:[{sentence:"少し休ませていただきます。",translation:"Cho tôi nghỉ một chút."},{sentence:"説明させていただいてもよろしいですか。",translation:"Tôi xin phép được giải thích có được không?"},{sentence:"本日はこれで失礼させていただきます。",translation:"Hôm nay tôi xin phép cáo từ ở đây."}],note:"させていただきます rất phổ biến đến mức đôi khi dùng thái quá. Trong văn nói thân mật: させてもらいます hoặc 〜します là đủ.",dialogue:{jp:"A：本日の発表を担当させていただく山田と申します。\nB：よろしくお願いします。",vi:"A: Tôi là Yamada, được phân công phụ trách phần thuyết trình hôm nay.\nB: Vâng, xin hãy chỉ giáo."},commonMistake:{wrong:"少し休ませていただきますです。",correct:"少し休ませていただきます。",why:"させていただきます đã là dạng kính ngữ khiêm nhường hoàn chỉnh, đã chia lịch sự bằng ます nên không được thêm です phía sau — thêm vào là thừa và sai ngữ pháp."},related:["Vていただきます","させてもらいます"],kitsuPrompt:"Đóng vai nhân viên xin phép cấp trên. Dùng させていただきます trong 2 tình huống."}]},{bai:49,level:"N4",kanji:"尊",reading:"そんけい",romaji:"Sonkei",titleVi:"Kính ngữ tôn trọng",titleJp:"尊敬表現",descVi:"Học 尊敬語 — cách nói lịch sự khi đề cập hành động của người trên.",selfCheckGoals:["Nhớ 6 kính ngữ đặc biệt (いらっしゃる, 召し上がる, なさる, おっしゃる, ご覧になる, くださる)","Chia お〜になる của 3 động từ thông dụng","Dùng dạng bị động làm kính ngữ trong văn nói thông thường","Phân biệt khi nào dùng 尊敬語 vs 謙譲語"],readingPassage:{title:"社長のご来店",titleVi:"Giám đốc ghé thăm cửa hàng",japanese:"今日、社長が私たちの店においでになりました。店に入られたとき、「いい雰囲気ですね」とおっしゃいました。試食品を召し上がってから、「おいしいですね」とご覧になりながらにっこりなさいました。社長は「皆さん、よく頑張っていますね」とおっしゃって、帰られました。とても緊張しましたが、褒めていただいて、うれしかったです。",vietnamese:'Hôm nay giám đốc đã ghé thăm cửa hàng của chúng tôi. Khi vào cửa hàng, ngài nói "không khí đẹp nhỉ". Sau khi dùng thử hàng mẫu, ngài mỉm cười vừa nhìn xung quanh và nói "ngon nhỉ". Giám đốc nói "mọi người làm tốt lắm nhỉ" rồi ra về. Tôi rất hồi hộp nhưng được khen thì vui lắm.',highlights:[{excerpt:"においでになりました",label:"いらっしゃる kính ngữ"},{excerpt:"入られたとき",label:"V受身形 kính ngữ"},{excerpt:"おっしゃいました",label:"おっしゃる kính ngữ"},{excerpt:"召し上がってから",label:"召し上がる kính ngữ"}],questions:[{q:"社長は店に入ったとき、何とおっしゃいましたか。",options:["いい雰囲気ですね","おいしいですね","よく頑張っていますね","素晴らしいですね"],answer:0},{q:"筆者はどんな気持ちでしたか。",options:["緊張したが、褒められてうれしかった","楽しかった","怖かった","困った"],answer:0}]},patterns:[{pattern:"V受身形 (尊敬)",meaning:"kính ngữ nhẹ bằng dạng bị động",priority:"medium",explanation:"V bị động (受身形) cũng được dùng làm kính ngữ mức nhẹ — phổ biến trong văn nói công sở. Lịch sự hơn thể thông thường nhưng nhẹ hơn お〜になる.",examples:[{sentence:"部長はもう帰られましたか。",translation:"Trưởng phòng về rồi ạ?"},{sentence:"先生はいつ来られますか。",translation:"Thầy đến lúc nào ạ?"},{sentence:"社長が来られたとき、知らせてください。",translation:"Khi giám đốc đến xin hãy báo cho tôi."}],note:"V受身(尊敬) = kính ngữ. Cách nhận biết: không có tác nhân に, chủ ngữ là người trên.",dialogue:{jp:"A：山田部長はいらっしゃいますか。\nB：先ほど外に出られました。もうすぐ戻られると思います。",vi:"A: Trưởng phòng Yamada có ở đây không?\nB: Ngài vừa ra ngoài. Tôi nghĩ sẽ quay lại ngay."},commonMistake:{wrong:"先生は学生に来られました。",correct:"先生は来られました。",why:"V受身 dùng làm kính ngữ thì KHÔNG có tác nhân đi kèm に; nếu thêm 学生に vào thì câu biến thành bị động thực sự nghĩa là bị học sinh làm gì đó, khác hoàn toàn nghĩa kính ngữ đơn giản là thầy đã đến/về. Cách phân biệt: xem có tác nhân rõ ràng bằng に hay không, và chủ ngữ có phải người trên trong ngữ cảnh lịch sự hay không."},related:["お〜になる","特別な尊敬語"],kitsuPrompt:"Hỏi tôi về cấp trên trong cuộc họp. Tôi sẽ dùng 受身形(尊敬) để mô tả hành động của họ."},{pattern:"おVますになります",meaning:"kính ngữ chuẩn (お〜になる)",priority:"high",explanation:"お + V stem (ます form) + になる = kính ngữ chuẩn cho người trên. Lịch sự hơn V受身. Không dùng được với tất cả động từ (động từ ngắn, thuần Nhật dùng được tốt hơn).",examples:[{sentence:"先生はもうお帰りになりましたか。",translation:"Thầy về rồi ạ?"},{sentence:"社長がお書きになった手紙です。",translation:"Đây là bức thư giám đốc đã viết."},{sentence:"こちらでお待ちになってください。",translation:"Xin vui lòng chờ ở đây ạ."}],note:"Động từ Hán tự → ご〜になる: ご利用になる, ご確認になる. Động từ thuần Nhật → お〜になる: お読みになる.",dialogue:{jp:"A：社長、この書類はもうお読みになりましたか。\nB：はい、先ほど読みました。",vi:"A: Giám đốc, ngài đã đọc tài liệu này chưa ạ?\nB: Rồi, vừa đọc xong."},commonMistake:{wrong:"社長はもうおいるになりますか。",correct:"社長はもういらっしゃいますか。",why:"いる không chia theo mẫu お〜になる vì đã có kính ngữ đặc biệt riêng là いらっしゃる. Tương tự, 食べる không dùng ご食べになる mà phải dùng kính ngữ đặc biệt 召し上がる/お召し上がりになる — một số động từ thông dụng luôn ưu tiên dạng kính ngữ đặc biệt thay vì quy tắc お〜になる."},related:["特別な尊敬語","V受身(尊敬)"],kitsuPrompt:"Đóng vai nhân viên lễ tân. Dùng お〜になる để hỏi khách hàng/cấp trên."},{pattern:"特別な尊敬語",meaning:"kính ngữ đặc biệt (bất quy tắc)",priority:"high",explanation:"Một số động từ thông dụng có kính ngữ đặc biệt, không theo quy tắc. Cần học thuộc: いる/行く/来る→いらっしゃる, 食べる/飲む→召し上がる, 言う→おっしゃる, する→なさる, 見る→ご覧になる, くれる→くださる.",examples:[{sentence:"社長はどこにいらっしゃいますか。",translation:"Giám đốc đang ở đâu ạ?"},{sentence:"何をおっしゃいましたか。",translation:"Ngài đã nói gì ạ?"},{sentence:"この書類をご覧になってください。",translation:"Xin ngài xem tài liệu này ạ."}],note:"Bảng kính ngữ đặc biệt:\nいる/行く/来る → いらっしゃる\n食べる/飲む → 召し上がる\n言う → おっしゃる\nする → なさる\n見る → ご覧になる\nもらう → いただく (謙譲)\nくれる → くださる\nあげる → 差し上げる (謙譲)",dialogue:{jp:"A：部長、コーヒーはいかがですか。\nB：ありがとう。じゃ、いただきます。",vi:"A: Trưởng phòng, cà phê có được không ạ?\nB: Cảm ơn. Vậy tôi nhận."},commonMistake:{wrong:"先生が晩ご飯を食べました。",correct:"先生が晩ご飯を召し上がりました。",why:"Khi nói về hành động của người trên (thầy giáo, giám đốc...) cần dùng kính ngữ đặc biệt thay vì động từ thường: 食べる→召し上がる, 言う→おっしゃる. Dùng động từ thường như 食べました/言いました với người trên bị coi là thiếu lịch sự."},related:["おVますになる","特別な謙譲語"],kitsuPrompt:"Đóng vai học sinh gặp thầy giáo. Dùng ít nhất 3 kính ngữ đặc biệt trong đoạn hội thoại."}]},{bai:50,level:"N4",kanji:"謙",reading:"けんじょう",romaji:"Kenjou",titleVi:"Kính ngữ khiêm nhường",titleJp:"謙譲表現",descVi:"Học 謙譲語 — hạ thấp bản thân khi nói về hành động của chính mình.",selfCheckGoals:["Nhớ 6 khiêm nhường ngữ đặc biệt (参る, 申す, いたす, 伺う, いただく, 差し上げる)","Chia お〜します và ご〜いたします đúng cho 3 động từ","Dùng ていただけませんか để nhờ vả ở mức lịch sự cao nhất","Phân biệt khi nào dùng 尊敬語 (hành động của người trên) và 謙譲語 (hành động của mình)"],readingPassage:{title:"お客様へのご案内",titleVi:"Hướng dẫn cho khách hàng",japanese:"いらっしゃいませ。本日はご来店いただきありがとうございます。私、山田と申します。ご案内いたします。こちらへどうぞ。ご注文はお決まりでしょうか。ご不明な点がございましたら、何でも伺います。後ほど、お会計をお持ちいたします。また、アンケートにお答えいただけませんか。よろしければ、ぜひお願いいたします。",vietnamese:"Xin chào quý khách. Cảm ơn quý khách đã ghé thăm hôm nay. Tôi là Yamada. Tôi xin hướng dẫn. Mời quý khách đi lối này. Quý khách đã chọn món chưa ạ? Nếu có điều gì chưa rõ xin cứ hỏi tôi. Tôi sẽ mang hóa đơn đến sau. Ngoài ra, quý khách có thể trả lời bảng câu hỏi không? Nếu được xin rất mong quý khách.",highlights:[{excerpt:"山田と申します",label:"申す khiêm nhường"},{excerpt:"ご案内いたします",label:"ご〜いたします"},{excerpt:"何でも伺います",label:"伺う khiêm nhường"},{excerpt:"お答えいただけませんか",label:"ていただけませんか nhờ lịch sự"}],questions:[{q:"店員は自分を何と呼んでいますか。",options:["山田","佐藤","田中","鈴木"],answer:0},{q:"店員はお客様に何をお願いしていますか。",options:["アンケートに答えること","注文を決めること","席に座ること","荷物を預けること"],answer:0}]},patterns:[{pattern:"おVますします／いたします",meaning:"khiêm nhường chuẩn (お〜する/いたす)",priority:"high",explanation:"お + V stem + する/いたします = khiêm nhường chuẩn về hành động của mình dành cho người trên. いたします lịch sự hơn します. Động từ Hán tự → ご〜する/いたす: ご案内いたします.",examples:[{sentence:"お荷物をお持ちします。",translation:"Để tôi mang đồ cho ngài."},{sentence:"資料をご用意いたします。",translation:"Tôi xin chuẩn bị tài liệu."},{sentence:"詳しくご説明いたします。",translation:"Tôi xin giải thích chi tiết."}],note:"お〜します (thân mật hơn chút) vs お〜いたします (rất trang trọng). Trong dịch vụ khách hàng, いたします là chuẩn.",dialogue:{jp:"A：すみません、この荷物、重くて…\nB：お持ちいたします。こちらへどうぞ。",vi:"A: Xin lỗi, hành lý này nặng quá...\nB: Để tôi mang cho ạ. Mời đi lối này."},commonMistake:{wrong:"お客様の分もお食べします。",correct:"お客様の分もいただきます。",why:"食べる có khiêm nhường ngữ đặc biệt là いただく nên không chia theo mẫu お〜します thông thường (お食べします là sai). Ngoài ra, động từ thuần Nhật như 持つ chia お持ちします chứ không phải ご持ちします — ご〜する chỉ dùng cho từ gốc Hán."},related:["特別な謙譲語","Vていただきます"],kitsuPrompt:"Đóng vai nhân viên khách sạn chào đón khách. Dùng お〜いたします trong 3 câu."},{pattern:"特別な謙譲語",meaning:"khiêm nhường đặc biệt (bất quy tắc)",priority:"high",explanation:"Khiêm nhường ngữ đặc biệt không theo quy tắc, cần học thuộc: いる/行く→参る(まいる), 言う→申す(もうす), する→いたす, 来る/訪ねる/聞く→伺う(うかがう), もらう/食べる/飲む→いただく, あげる→差し上げる(さしあげる).",examples:[{sentence:"田中と申します。よろしくお願いいたします。",translation:"Tôi là Tanaka. Xin rất mong được chỉ giáo."},{sentence:"明日、御社に伺います。",translation:"Ngày mai tôi xin đến quý công ty."},{sentence:"もう少しお待ちいただけますか。",translation:"Ngài có thể đợi thêm một chút không ạ?"}],note:"Bảng khiêm nhường đặc biệt:\nいる/行く → 参る\n言う → 申す\nする → いたす\n来る/訪ねる/聞く → 伺う\nもらう/食べる/飲む → いただく\nあげる → 差し上げる\n知っている → 存じております\nいる → おります",dialogue:{jp:"A：部長、先日の件ですが、確認いたしました。\nB：そうですか。詳しく教えてください。\nA：はい、明日ご説明に伺ってもよろしいでしょうか。",vi:"A: Trưởng phòng, về vụ hôm trước, tôi đã xác nhận rồi ạ.\nB: Vậy à. Hãy cho tôi biết chi tiết đi.\nA: Vâng ạ. Ngày mai tôi có thể đến để giải thích được không ạ?"},commonMistake:{wrong:"お客様が明日参ります。",correct:"お客様が明日いらっしゃいます。",why:"参る là khiêm nhường ngữ dùng khi nói về hành động CỦA MÌNH để hạ thấp bản thân, không được dùng cho hành động của người trên/khách hàng — trường hợp đó phải dùng kính ngữ いらっしゃる. Tương tự, 申す chỉ dùng khi tự giới thiệu bản thân (私は…と申します), không dùng để nói lời của người khác."},related:["特別な尊敬語","おVますいたします"],kitsuPrompt:"Làm bài kiểm tra nhanh: nói câu bình thường, tôi sẽ đổi sang khiêm nhường ngữ đặc biệt."},{pattern:"Vていただけませんか",meaning:"bạn có thể ~ cho tôi không? (nhờ rất lịch sự)",priority:"high",explanation:"V て + いただけませんか = nhờ vả ở mức trang trọng nhất. Phân cấp lịch sự: てください < てもらえますか < ていただけますか < ていただけませんか (lịch sự nhất).",examples:[{sentence:"もう少しゆっくり話していただけませんか。",translation:"Bạn có thể nói chậm hơn một chút không ạ?"},{sentence:"こちらに署名していただけますか。",translation:"Bạn có thể ký vào đây không ạ?"},{sentence:"ご意見をお聞かせいただけませんか。",translation:"Có thể cho tôi biết ý kiến của ngài không ạ?"}],note:"ていただけますか (có thể ~) và ていただけませんか (không biết có thể ~ không) — cả hai đều lịch sự. ～ませんか nghe khiêm nhường hơn một chút.",dialogue:{jp:"A：すみません、この荷物、ここに置いていただけませんか。\nB：はい、もちろんです。",vi:"A: Xin lỗi, bạn có thể đặt hành lý này vào đây không ạ?\nB: Vâng, tất nhiên rồi ạ."},commonMistake:{wrong:"部長、こちらに署名してくれませんか。",correct:"部長、こちらに署名していただけませんか。",why:"してくれませんか là cách nói thân mật, không phù hợp khi nhờ cấp trên hay người ngoài; cần dùng ていただけませんか trang trọng hơn. ていただけないですか cũng chấp nhận được về ngữ pháp nhưng ていただけませんか mới là dạng chuẩn mực, đặc biệt trong văn viết/công việc."},related:["Vていただきます","Vてくださいませんか"],kitsuPrompt:"Đóng vai khách hàng gọi điện đến ngân hàng. Nhờ 2 việc khác nhau bằng ていただけませんか."}]}]),i=n=>"ALL"===n?t:t.filter(t=>t.level===n),h=await n("b:lib/minna-curriculum.js#KANJI_NUM_50","c3f70e91cd9c9719837d",["一","二","三","四","五","六","七","八","九","十","十一","十二","十三","十四","十五","十六","十七","十八","十九","二十","二十一","二十二","二十三","二十四","二十五","二十六","二十七","二十八","二十九","三十","三十一","三十二","三十三","三十四","三十五","三十六","三十七","三十八","三十九","四十","四十一","四十二","四十三","四十四","四十五","四十六","四十七","四十八","四十九","五十"]);export{t as n,i as r,h as t};